<?php

declare(strict_types=1);

namespace PortLibs\LibSqlite;

final class SQLiteWalHotJournalSavepointCheckpointCurrentSourceNextPlan
{
    public static function next156Plan(
        string $databasePath,
        string $databaseBytes,
        int $pageSize,
        string $savepoint,
        array $hotJournalPages,
        array $currentSourcePages,
        array $currentSavepointWrites,
        array $nextSavepointWrites,
        SQLiteWal $currentWal,
        string $currentWalBytes,
        SQLiteWal $nextWal,
        string $nextWalBytes,
        array $readerPageNumbers,
        int $readerEndFrame,
        int $currentSourceEpoch = 1,
        bool $reservedLock = false,
        bool $superJournalRequired = false,
        bool $superJournalExists = false,
    ): array
    {
        $impl = new class {
                /**
                 * @param array<int,string> $hotJournalPages
                 * @param array<int,string> $currentSourcePages
                 * @param array<int,string> $currentSavepointWrites
                 * @param array<int,string> $nextSavepointWrites
                 * @param list<int> $readerPageNumbers
                 * @return array<string,mixed>
                 */
                public static function plan(
                    string $databasePath,
                    string $databaseBytes,
                    int $pageSize,
                    string $savepoint,
                    array $hotJournalPages,
                    array $currentSourcePages,
                    array $currentSavepointWrites,
                    array $nextSavepointWrites,
                    SQLiteWal $currentWal,
                    string $currentWalBytes,
                    SQLiteWal $nextWal,
                    string $nextWalBytes,
                    array $readerPageNumbers,
                    int $readerEndFrame,
                    int $currentSourceEpoch = 1,
                    bool $reservedLock = false,
                    bool $superJournalRequired = false,
                    bool $superJournalExists = false,
                ): array {
                    $base = SQLitePagerSavepointWalHotJournalCurrentSourceNext148Plan::plan(
                        $databasePath,
                        $databaseBytes,
                        $pageSize,
                        $savepoint,
                        $hotJournalPages,
                        $currentSourcePages,
                        $currentSavepointWrites,
                        $nextSavepointWrites,
                        $currentWal,
                        $currentWalBytes,
                        $nextWal,
                        $nextWalBytes,
                        $readerPageNumbers,
                        $readerEndFrame,
                        $currentSourceEpoch,
                        $reservedLock,
                        $superJournalRequired,
                        $superJournalExists
                    );

                    $walPath = $databasePath . '-wal';
                    $payloads = $base['base_plan']['payloads'];
                    $payloads[$walPath . '#current-source-next156'] = $currentWalBytes;
                    $payloads[$walPath . '#next-source-next156'] = $nextWalBytes;

                    $operations = array_values(array_filter(
                        $base['base_plan']['operations'],
                        static fn (array $operation): bool => isset($operation['path']) && (string) $operation['path'] !== ''
                    ));
                    $operations[] = [
                        'op' => 'sync',
                        'path' => $databasePath,
                        'durable' => true,
                        'reason' => 'sync_hot_journal_savepoint_retry_database_before_wal_source_switch_next156',
                    ];
                    $operations[] = [
                        'op' => 'write',
                        'path' => $walPath,
                        'offset' => 0,
                        'bytes' => strlen($currentWalBytes),
                        'payload_key' => $walPath . '#current-source-next156',
                        'reason' => 'preserve_current_wal_source_for_pinned_reader_before_next_savepoint_retry_next156',
                    ];
                    $operations[] = [
                        'op' => 'truncate',
                        'path' => $walPath,
                        'bytes' => strlen($currentWalBytes),
                        'reason' => 'trim_wal_to_current_source_before_next_savepoint_retry_next156',
                    ];
                    $operations[] = [
                        'op' => 'sync',
                        'path' => $walPath,
                        'durable' => true,
                        'reason' => 'sync_current_wal_source_before_next_savepoint_retry_next156',
                    ];
                    $operations[] = [
                        'op' => 'write',
                        'path' => $walPath,
                        'offset' => 0,
                        'bytes' => strlen($nextWalBytes),
                        'payload_key' => $walPath . '#next-source-next156',
                        'reason' => 'install_next_wal_source_after_hot_journal_savepoint_retry_next156',
                    ];
                    $operations[] = [
                        'op' => 'truncate',
                        'path' => $walPath,
                        'bytes' => strlen($nextWalBytes),
                        'reason' => 'trim_wal_to_next_source_after_hot_journal_savepoint_retry_next156',
                    ];
                    $operations[] = [
                        'op' => 'sync',
                        'path' => $walPath,
                        'durable' => true,
                        'reason' => 'sync_next_wal_source_after_hot_journal_savepoint_retry_next156',
                    ];
                    $operations[] = [
                        'op' => 'sync_directory',
                        'path' => dirname($databasePath),
                        'durable' => true,
                        'reason' => 'persist_hot_journal_savepoint_checkpoint_current_source_sidecars_next156',
                    ];

                    $applyBytes = 0;
                    foreach ($operations as $operation) {
                        if (($operation['op'] ?? '') === 'write' || ($operation['op'] ?? '') === 'truncate') {
                            $applyBytes += (int) ($operation['bytes'] ?? 0);
                        }
                    }

                    return [
                        'status' => $base['status'] === 'pager-savepoint-wal-hot-journal-current-source-next148'
                            ? 'wal-hot-journal-savepoint-checkpoint-current-source-next156'
                            : 'wal-hot-journal-savepoint-checkpoint-current-source-blocked-next156',
                        'reason' => $base['status'] === 'pager-savepoint-wal-hot-journal-current-source-next148'
                            ? 'hot_journal_savepoint_retry_database_synced_current_wal_preserved_next_wal_installed'
                            : 'base_current_source_not_ready_for_vfs_apply',
                        'database_path' => $databasePath,
                        'journal_path' => $base['journal_path'],
                        'wal_path' => $walPath,
                        'savepoint' => $savepoint,
                        'reader_end_frame' => $readerEndFrame,
                        'operation_count' => count($operations),
                        'apply_byte_count' => $applyBytes,
                        'database_sync_count' => count(array_filter(
                            $operations,
                            static fn (array $operation): bool => ($operation['op'] ?? '') === 'sync' && ($operation['path'] ?? '') === $databasePath
                        )),
                        'wal_sync_count' => count(array_filter(
                            $operations,
                            static fn (array $operation): bool => ($operation['op'] ?? '') === 'sync' && ($operation['path'] ?? '') === $walPath
                        )),
                        'directory_sync_count' => count(array_filter(
                            $operations,
                            static fn (array $operation): bool => ($operation['op'] ?? '') === 'sync_directory'
                        )),
                        'current_wal_bytes_length' => strlen($currentWalBytes),
                        'next_wal_bytes_length' => strlen($nextWalBytes),
                        'current_wal_sha256' => hash('sha256', $currentWalBytes),
                        'next_wal_sha256' => hash('sha256', $nextWalBytes),
                        'next_replaces_current_wal' => hash('sha256', $currentWalBytes) !== hash('sha256', $nextWalBytes),
                        'base_status' => $base['status'],
                        'base_reason' => $base['reason'],
                        'base_reader_retry_match' => $base['retry_matches_current_reader'],
                        'base_next_source_separated' => $base['next_source_separated'],
                        'next_separated_page_numbers' => $base['next_separated_page_numbers'],
                        'operation_reasons' => array_column($operations, 'reason'),
                        'operations' => $operations,
                        'payloads' => $payloads,
                        'base_plan' => $base,
                        'dependencies' => array_values(array_unique(array_merge(
                            $base['dependencies'],
                            [
                                'sqlite-wal-hot-journal-savepoint-checkpoint-current-source-next156',
                                'vfs-atomic-wal-source-switch',
                                'sqlite-wal-current-source-durable-apply',
                            ]
                        ))),
                        'dependency_closure' => 'no new support component needed; reuses next148 pager/WAL source validation and existing native PHP VFS atomic operation application',
                        'non_overlap' => 'avoids accepted VFS rollback-journal apply, VFS savepoint rollback apply, WAL byte truncation, checkpoint transaction, and next148 reader-source diagnostics by applying the validated current/next WAL source switch as a durable VFS operation sequence',
                    ];
                }
        };

        return $impl::plan($databasePath, $databaseBytes, $pageSize, $savepoint, $hotJournalPages, $currentSourcePages, $currentSavepointWrites, $nextSavepointWrites, $currentWal, $currentWalBytes, $nextWal, $nextWalBytes, $readerPageNumbers, $readerEndFrame, $currentSourceEpoch, $reservedLock, $superJournalRequired, $superJournalExists);
    }

    public static function next159Plan(
        string $databasePath,
        string $databaseBytes,
        int $pageSize,
        string $savepoint,
        array $hotJournalPages,
        array $currentSourcePages,
        array $currentSavepointWrites,
        array $nextSavepointWrites,
        SQLiteWal $currentWal,
        string $currentWalBytes,
        SQLiteWal $nextWal,
        string $nextWalBytes,
        array $readerPageNumbers,
        int $readerEndFrame,
        string $mode = 'restart',
        int $currentSourceEpoch = 1,
        bool $reservedLock = false,
        bool $superJournalRequired = false,
        bool $superJournalExists = false,
    ): array
    {
        $impl = new class {
                /**
                 * @param array<int,string> $hotJournalPages
                 * @param array<int,string> $currentSourcePages
                 * @param array<int,string> $currentSavepointWrites
                 * @param array<int,string> $nextSavepointWrites
                 * @param list<int> $readerPageNumbers
                 * @return array<string,mixed>
                 */
                public static function plan(
                    string $databasePath,
                    string $databaseBytes,
                    int $pageSize,
                    string $savepoint,
                    array $hotJournalPages,
                    array $currentSourcePages,
                    array $currentSavepointWrites,
                    array $nextSavepointWrites,
                    SQLiteWal $currentWal,
                    string $currentWalBytes,
                    SQLiteWal $nextWal,
                    string $nextWalBytes,
                    array $readerPageNumbers,
                    int $readerEndFrame,
                    string $mode = 'restart',
                    int $currentSourceEpoch = 1,
                    bool $reservedLock = false,
                    bool $superJournalRequired = false,
                    bool $superJournalExists = false,
                ): array {
                    $mode = strtolower(trim($mode));
                    if (!in_array($mode, ['full', 'restart', 'truncate'], true)) {
                        throw new \InvalidArgumentException('SQLite WAL hot-journal savepoint checkpoint current-source next159 requires full, restart, or truncate mode');
                    }
                    if ($readerPageNumbers === []) {
                        throw new \InvalidArgumentException('SQLite WAL hot-journal savepoint checkpoint current-source next159 requires reader pages');
                    }
                    if ($readerEndFrame < 0 || $readerEndFrame > $currentWal->frameCount()) {
                        throw new \InvalidArgumentException('SQLite WAL hot-journal savepoint checkpoint current-source next159 reader frame is outside the current WAL range');
                    }

                    $base = SQLitePagerSavepointWalHotJournalCurrentSourceNext148Plan::plan(
                        $databasePath,
                        $databaseBytes,
                        $pageSize,
                        $savepoint,
                        $hotJournalPages,
                        $currentSourcePages,
                        $currentSavepointWrites,
                        $nextSavepointWrites,
                        $currentWal,
                        $currentWalBytes,
                        $nextWal,
                        $nextWalBytes,
                        $readerPageNumbers,
                        $readerEndFrame,
                        $currentSourceEpoch,
                        $reservedLock,
                        $superJournalRequired,
                        $superJournalExists,
                    );

                    $rolledBackDatabaseBytes = (string) $base['base_plan']['rolled_back_database_bytes'];
                    $checkpoint = $currentWal->checkpointModePlan($rolledBackDatabaseBytes, $mode, $readerEndFrame);
                    $durable = $currentWal->durableCheckpointResult($rolledBackDatabaseBytes, $mode, $readerEndFrame);
                    $nextDurable = $nextWal->durableCheckpointResult($rolledBackDatabaseBytes, 'passive', $nextWal->frameCount());

                    $rows = [];
                    foreach ($readerPageNumbers as $pageNumber) {
                        if (!is_int($pageNumber) || $pageNumber < 1) {
                            throw new \InvalidArgumentException('SQLite WAL hot-journal savepoint checkpoint current-source next159 reader pages must be one-based integers');
                        }

                        $current = $currentWal->readerSnapshotPageImage($rolledBackDatabaseBytes, $pageNumber, $readerEndFrame);
                        $afterCheckpoint = $durable['wal_bytes'] === ''
                            ? self::databasePageVisibility((string) $durable['database_bytes'], $pageSize, $pageNumber)
                            : SQLiteWal::parse((string) $durable['wal_bytes'], $pageSize, true)->readerSnapshotPageImage((string) $durable['database_bytes'], $pageNumber, $readerEndFrame);
                        $next = $nextWal->readerSnapshotPageImage($rolledBackDatabaseBytes, $pageNumber, $nextWal->frameCount());
                        $nextCheckpoint = self::databasePageVisibility((string) $nextDurable['database_bytes'], $pageSize, $pageNumber);

                        $rows[] = [
                            'page_number' => $pageNumber,
                            'current_source' => $current['source'],
                            'current_frame' => $current['frame_index'],
                            'current_label' => self::label((string) $current['image']),
                            'checkpoint_source' => $afterCheckpoint['source'],
                            'checkpoint_frame' => $afterCheckpoint['frame_index'],
                            'checkpoint_label' => self::label((string) $afterCheckpoint['image']),
                            'next_source' => $next['source'],
                            'next_frame' => $next['frame_index'],
                            'next_label' => self::label((string) $next['image']),
                            'next_checkpoint_source' => $nextCheckpoint['source'],
                            'next_checkpoint_label' => self::label((string) $nextCheckpoint['image']),
                            'checkpoint_matches_current' => $afterCheckpoint['image'] === $current['image'],
                            'next_checkpoint_matches_next' => $nextCheckpoint['image'] === $next['image'],
                            'source_transition' => $current['source'] . '>checkpoint>' . $afterCheckpoint['source'] . '>next-wal>' . $next['source'] . '>next-checkpoint>' . $nextCheckpoint['source'],
                        ];
                    }

                    $currentSources = array_column($rows, 'current_source');
                    $checkpointSources = array_column($rows, 'checkpoint_source');
                    $nextSources = array_column($rows, 'next_source');
                    $status = (bool) $base['hot_recovered']
                        && !(bool) $checkpoint['busy']
                        && $base['next_source_separated']
                        && !in_array(false, array_column($rows, 'checkpoint_matches_current'), true)
                        && !in_array(false, array_column($rows, 'next_checkpoint_matches_next'), true)
                        ? 'wal-hot-journal-savepoint-checkpoint-current-source-next159'
                        : 'wal-hot-journal-savepoint-checkpoint-current-source-blocked-next159';

                    $payloads = [
                        $databasePath . '#next159-checkpoint-current' => (string) $durable['database_bytes'],
                        $databasePath . '-wal#next159-checkpoint-current' => (string) $durable['wal_bytes'],
                        $databasePath . '#next159-checkpoint-next' => (string) $nextDurable['database_bytes'],
                        $databasePath . '-wal#next159-checkpoint-next' => (string) $nextDurable['wal_bytes'],
                    ];
                    $operations = self::operations($databasePath, $mode, $durable, $nextDurable, $payloads);

                    return [
                        'status' => $status,
                        'reason' => $status === 'wal-hot-journal-savepoint-checkpoint-current-source-next159'
                            ? 'hot_journal_recovered_savepoint_retry_checkpointed_before_next_wal_source'
                            : 'hot_journal_savepoint_checkpoint_current_source_not_ready',
                        'database_path' => $databasePath,
                        'journal_path' => $base['journal_path'],
                        'wal_path' => $databasePath . '-wal',
                        'page_size' => $pageSize,
                        'savepoint' => $savepoint,
                        'mode' => $mode,
                        'reader_end_frame' => $readerEndFrame,
                        'hot_recovered' => (bool) $base['hot_recovered'],
                        'checkpoint_busy' => (bool) $checkpoint['busy'],
                        'checkpoint_reason' => $checkpoint['reason'],
                        'checkpoint_wal_action' => $durable['wal_action'],
                        'next_checkpoint_wal_action' => $nextDurable['wal_action'],
                        'current_wal_source' => $base['current_wal_source'],
                        'next_wal_source' => $base['next_wal_source'],
                        'current_sources' => $currentSources,
                        'checkpoint_sources' => $checkpointSources,
                        'next_sources' => $nextSources,
                        'next_checkpoint_sources' => array_column($rows, 'next_checkpoint_source'),
                        'current_frame_indexes' => array_column($rows, 'current_frame'),
                        'checkpoint_frame_indexes' => array_column($rows, 'checkpoint_frame'),
                        'next_frame_indexes' => array_column($rows, 'next_frame'),
                        'current_labels' => array_column($rows, 'current_label'),
                        'checkpoint_labels' => array_column($rows, 'checkpoint_label'),
                        'next_labels' => array_column($rows, 'next_label'),
                        'next_checkpoint_labels' => array_column($rows, 'next_checkpoint_label'),
                        'checkpoint_matches_current_reader' => !in_array(false, array_column($rows, 'checkpoint_matches_current'), true),
                        'next_checkpoint_matches_next_reader' => !in_array(false, array_column($rows, 'next_checkpoint_matches_next'), true),
                        'checkpoint_uses_database_pages' => !in_array('wal', $checkpointSources, true),
                        'next_uses_separate_wal_source' => $base['next_source_separated'],
                        'next_checkpoint_uses_database_pages' => !in_array('wal', array_column($rows, 'next_checkpoint_source'), true),
                        'source_transitions' => array_column($rows, 'source_transition'),
                        'source_digest' => hash('sha256', implode('|', array_column($rows, 'source_transition'))),
                        'current_checkpoint' => $checkpoint,
                        'current_durable' => $durable,
                        'next_durable' => $nextDurable,
                        'rows' => $rows,
                        'operations' => $operations,
                        'operation_reasons' => array_column($operations, 'reason'),
                        'payload_keys' => array_keys($payloads),
                        'payloads' => $payloads,
                        'base_plan' => $base,
                        'dependencies' => array_values(array_unique(array_merge(
                            $base['dependencies'],
                            $durable['dependencies'],
                            $nextDurable['dependencies'],
                            [
                                'sqlite-wal-hot-journal-savepoint-checkpoint-current-source-next159',
                                'wordpress-import-hot-journal-savepoint-checkpoint-current-source',
                            ]
                        ))),
                        'dependency_closure' => 'no new support component needed; reuses hot-journal current-source recovery, WAL reader snapshots, savepoint page images, and durable checkpoint helpers',
                        'non_overlap' => 'avoids accepted WAL byte truncation, rollback-journal apply, checkpoint transaction, and next148 WAL source separation by asserting checkpoint materialization on the rolled-back hot-journal current source before the next WAL generation is read',
                    ];
                }

                /**
                 * @param array<string,string> $payloads
                 * @return list<array<string,mixed>>
                 */
                private static function operations(string $databasePath, string $mode, array $current, array $next, array $payloads): array
                {
                    $operations = [
                        [
                            'op' => 'write',
                            'path' => $databasePath,
                            'offset' => 0,
                            'bytes' => strlen($payloads[$databasePath . '#next159-checkpoint-current']),
                            'payload_key' => $databasePath . '#next159-checkpoint-current',
                            'reason' => 'checkpoint_hot_journal_savepoint_current_source_database',
                        ],
                    ];

                    if ((string) $current['wal_bytes'] === '') {
                        $operations[] = [
                            'op' => $mode === 'truncate' ? 'truncate' : 'restart',
                            'path' => $databasePath . '-wal',
                            'bytes' => strlen((string) $current['wal_bytes']),
                            'payload_key' => $databasePath . '-wal#next159-checkpoint-current',
                            'reason' => $mode === 'truncate'
                                ? 'truncate_current_wal_after_hot_journal_savepoint_checkpoint'
                                : 'restart_current_wal_after_hot_journal_savepoint_checkpoint',
                        ];
                    } else {
                        $operations[] = [
                            'op' => 'write',
                            'path' => $databasePath . '-wal',
                            'offset' => 0,
                            'bytes' => strlen((string) $current['wal_bytes']),
                            'payload_key' => $databasePath . '-wal#next159-checkpoint-current',
                            'reason' => 'preserve_current_wal_after_reader_blocked_checkpoint',
                        ];
                    }

                    $operations[] = [
                        'op' => 'write',
                        'path' => $databasePath . '-wal',
                        'offset' => 0,
                        'bytes' => strlen($payloads[$databasePath . '-wal#next159-checkpoint-next']),
                        'payload_key' => $databasePath . '-wal#next159-checkpoint-next',
                        'reason' => 'install_next_wal_generation_after_current_checkpoint',
                    ];
                    $operations[] = [
                        'op' => 'sync',
                        'path' => $databasePath,
                        'durable' => true,
                        'reason' => 'sync_database_after_hot_journal_savepoint_checkpoint',
                    ];
                    $operations[] = [
                        'op' => 'sync',
                        'path' => $databasePath . '-wal',
                        'durable' => true,
                        'reason' => 'sync_next_wal_generation_after_checkpoint',
                    ];

                    if ((string) $next['wal_bytes'] === '') {
                        $operations[] = [
                            'op' => 'delete',
                            'path' => $databasePath . '-wal',
                            'reason' => 'delete_empty_next_wal_after_checkpoint',
                        ];
                    }

                    return $operations;
                }

                /**
                 * @return array{page_number:int,source:string,frame_index:null,database_offset:int,image:string,snapshot_end_frame:int,snapshot_commit_frame:null,database_page_count:int}
                 */
                private static function databasePageVisibility(string $databaseBytes, int $pageSize, int $pageNumber): array
                {
                    if ($pageNumber < 1) {
                        throw new \InvalidArgumentException('SQLite WAL hot-journal savepoint checkpoint current-source next159 page numbers are one-based');
                    }

                    return [
                        'page_number' => $pageNumber,
                        'source' => 'database',
                        'frame_index' => null,
                        'database_offset' => ($pageNumber - 1) * $pageSize,
                        'image' => substr($databaseBytes, ($pageNumber - 1) * $pageSize, $pageSize),
                        'snapshot_end_frame' => 0,
                        'snapshot_commit_frame' => null,
                        'database_page_count' => intdiv(strlen($databaseBytes), $pageSize),
                    ];
                }

                private static function label(string $image): string
                {
                    return rtrim(substr($image, 0, 96), ".\0");
                }
        };

        return $impl::plan($databasePath, $databaseBytes, $pageSize, $savepoint, $hotJournalPages, $currentSourcePages, $currentSavepointWrites, $nextSavepointWrites, $currentWal, $currentWalBytes, $nextWal, $nextWalBytes, $readerPageNumbers, $readerEndFrame, $mode, $currentSourceEpoch, $reservedLock, $superJournalRequired, $superJournalExists);
    }

    public static function next161Plan(
        string $databasePath,
        string $databaseBytes,
        int $pageSize,
        string $savepoint,
        array $hotJournalPages,
        array $savepointBeforePages,
        SQLiteWal $currentWal,
        string $currentWalBytes,
        SQLiteWal $nextWal,
        string $nextWalBytes,
        array $readerCachePages,
        array $checkpointPages,
        string $mode = 'restart',
        int $readerEndFrame = 0,
        int $currentSourceEpoch = 1,
    ): array
    {
        $impl = new class {
                /**
                 * @param array<int,string> $hotJournalPages
                 * @param array<int,string> $savepointBeforePages
                 * @param array<int,array{image:string,source_id?:string,epoch?:int,pinned?:bool,dirty?:bool,label?:string}> $readerCachePages
                 * @param list<int> $checkpointPages
                 * @return array<string,mixed>
                 */
                public static function plan(
                    string $databasePath,
                    string $databaseBytes,
                    int $pageSize,
                    string $savepoint,
                    array $hotJournalPages,
                    array $savepointBeforePages,
                    SQLiteWal $currentWal,
                    string $currentWalBytes,
                    SQLiteWal $nextWal,
                    string $nextWalBytes,
                    array $readerCachePages,
                    array $checkpointPages,
                    string $mode = 'restart',
                    int $readerEndFrame = 0,
                    int $currentSourceEpoch = 1,
                ): array {
                    $mode = strtolower(trim($mode));
                    if ($databasePath === '' || $databaseBytes === '' || $savepoint === '') {
                        throw new \InvalidArgumentException('SQLite WAL hot-journal savepoint checkpoint current-source next161 requires database path, bytes, and savepoint');
                    }
                    if ($pageSize < 512 || ($pageSize & ($pageSize - 1)) !== 0) {
                        throw new \InvalidArgumentException('SQLite WAL hot-journal savepoint checkpoint current-source next161 page size must be a power of two at least 512');
                    }
                    if (strlen($databaseBytes) % $pageSize !== 0) {
                        throw new \InvalidArgumentException('SQLite WAL hot-journal savepoint checkpoint current-source next161 database bytes must be page-size aligned');
                    }
                    if (!in_array($mode, ['full', 'restart', 'truncate'], true)) {
                        throw new \InvalidArgumentException('SQLite WAL hot-journal savepoint checkpoint current-source next161 requires full, restart, or truncate mode');
                    }
                    if ($currentWalBytes === '' || $nextWalBytes === '') {
                        throw new \InvalidArgumentException('SQLite WAL hot-journal savepoint checkpoint current-source next161 requires current and next WAL bytes');
                    }
                    if ($readerEndFrame < 0 || $readerEndFrame > $currentWal->frameCount()) {
                        throw new \InvalidArgumentException('SQLite WAL hot-journal savepoint checkpoint current-source next161 reader frame is outside current WAL range');
                    }
                    if ($currentSourceEpoch < 1) {
                        throw new \InvalidArgumentException('SQLite WAL hot-journal savepoint checkpoint current-source next161 source epoch must be positive');
                    }
                    if ($hotJournalPages === [] || $savepointBeforePages === [] || $readerCachePages === [] || $checkpointPages === []) {
                        throw new \InvalidArgumentException('SQLite WAL hot-journal savepoint checkpoint current-source next161 requires hot-journal, savepoint, reader-cache, and checkpoint pages');
                    }

                    $database = self::sourceMap($databaseBytes, $pageSize);
                    $hotJournalPages = self::normalizeImages($hotJournalPages, $pageSize, 'hot-journal');
                    $savepointBeforePages = self::normalizeImages($savepointBeforePages, $pageSize, 'savepoint before');
                    $readerCachePages = self::normalizeReaderCache($readerCachePages, $pageSize);
                    self::assertPageList($checkpointPages);

                    $operations = [];
                    foreach ($hotJournalPages as $pageNumber => $image) {
                        self::assertDatabasePageExists($database, $pageNumber, 'hot-journal recovery');
                        $database[$pageNumber] = [
                            'image' => $image,
                            'source' => 'hot-journal-recovered-current-source-next161',
                        ];
                        $operations[] = [
                            'op' => 'restore_hot_journal_page_before_savepoint_checkpoint',
                            'page_number' => $pageNumber,
                        ];
                    }

                    foreach ($savepointBeforePages as $pageNumber => $image) {
                        self::assertDatabasePageExists($database, $pageNumber, 'savepoint rollback');
                        $database[$pageNumber] = [
                            'image' => $image,
                            'source' => 'rollback-to-savepoint-before-image-current-source-next161',
                        ];
                        $operations[] = [
                            'op' => 'rollback_savepoint_page_before_checkpoint',
                            'savepoint' => $savepoint,
                            'page_number' => $pageNumber,
                        ];
                    }
                    ksort($database, SORT_NUMERIC);

                    $rolledBackDatabaseBytes = self::sourceBytes($database, $pageSize);
                    $currentCheckpoint = $currentWal->checkpointModePlan($rolledBackDatabaseBytes, $mode, $readerEndFrame);
                    $currentDurable = $currentWal->durableCheckpointResult($rolledBackDatabaseBytes, $mode, $readerEndFrame);
                    $currentSourceId = self::sourceId('current', $databasePath, $savepoint, $currentWalBytes, $rolledBackDatabaseBytes, $mode, $readerEndFrame);
                    $checkpointEpoch = $currentSourceEpoch + 1;
                    $nextSourceId = self::sourceId('next', $databasePath, $savepoint, $nextWalBytes, (string) $currentDurable['database_bytes'], 'passive', $nextWal->frameCount());
                    $nextEpoch = $checkpointEpoch + 1;

                    $retainedCache = [];
                    $invalidatedCache = [];
                    $rows = [];
                    foreach ($checkpointPages as $pageNumber) {
                        self::assertDatabasePageExists($database, $pageNumber, 'checkpoint page');
                        $current = $currentWal->readerSnapshotPageImage($rolledBackDatabaseBytes, $pageNumber, $readerEndFrame);
                        $checkpoint = self::checkpointVisibility((string) $currentDurable['database_bytes'], (string) $currentDurable['wal_bytes'], $pageSize, $pageNumber, $readerEndFrame);
                        $next = $nextWal->readerSnapshotPageImage((string) $currentDurable['database_bytes'], $pageNumber, $nextWal->frameCount());
                        $cache = $readerCachePages[$pageNumber] ?? null;
                        $admission = self::cacheAdmission($cache, (string) $current['image'], $currentSourceId, $checkpointEpoch, (string) $currentDurable['wal_action']);
                        if ($admission['admitted']) {
                            $retainedCache[] = $pageNumber;
                        } else {
                            $invalidatedCache[] = $pageNumber;
                        }

                        $rows[] = [
                            'page_number' => $pageNumber,
                            'current_source' => $current['source'],
                            'current_frame' => $current['frame_index'],
                            'current_label' => self::label((string) $current['image']),
                            'checkpoint_source' => $checkpoint['source'],
                            'checkpoint_frame' => $checkpoint['frame_index'],
                            'checkpoint_label' => self::label((string) $checkpoint['image']),
                            'next_source' => $next['source'],
                            'next_frame' => $next['frame_index'],
                            'next_label' => self::label((string) $next['image']),
                            'cache_admitted' => $admission['admitted'],
                            'cache_reason' => $admission['reason'],
                            'cache_label' => $cache['label'] ?? null,
                            'cache_prefix' => is_array($cache) ? self::label($cache['image']) : null,
                            'current_matches_checkpoint' => $current['image'] === $checkpoint['image'],
                            'next_differs_from_current_source' => $next['image'] !== $current['image'] || $next['source'] !== $current['source'],
                            'source_transition' => $current['source'] . '>checkpoint>' . $checkpoint['source'] . '>next>' . $next['source'],
                        ];
                        $operations[] = [
                            'op' => $admission['admitted'] ? 'retain_reader_cache_for_checkpoint_current_source' : 'invalidate_reader_cache_for_checkpoint_current_source',
                            'page_number' => $pageNumber,
                            'reason' => $admission['reason'],
                        ];
                    }

                    $nextDurable = $nextWal->durableCheckpointResult((string) $currentDurable['database_bytes'], 'passive', $nextWal->frameCount());
                    $operations[] = [
                        'op' => 'publish_checkpoint_current_source_token',
                        'source_id' => $currentSourceId,
                        'epoch' => $checkpointEpoch,
                        'wal_action' => $currentDurable['wal_action'],
                    ];
                    $operations[] = [
                        'op' => 'publish_next_wal_source_token',
                        'source_id' => $nextSourceId,
                        'epoch' => $nextEpoch,
                        'wal_action' => $nextDurable['wal_action'],
                    ];

                    $allCurrentMatchesCheckpoint = !in_array(false, array_column($rows, 'current_matches_checkpoint'), true);
                    $status = $allCurrentMatchesCheckpoint
                        && $retainedCache !== []
                        && $invalidatedCache !== []
                        ? 'wal-hot-journal-savepoint-checkpoint-current-source-next161'
                        : 'wal-hot-journal-savepoint-checkpoint-current-source-blocked-next161';

                    return [
                        'status' => $status,
                        'reason' => $status === 'wal-hot-journal-savepoint-checkpoint-current-source-next161'
                            ? 'reader_cache_rebased_after_hot_journal_savepoint_checkpoint_current_source'
                            : 'checkpoint_current_source_reader_cache_not_rebased',
                        'database_path' => $databasePath,
                        'journal_path' => $databasePath . '-journal',
                        'wal_path' => $databasePath . '-wal',
                        'page_size' => $pageSize,
                        'savepoint' => $savepoint,
                        'mode' => $mode,
                        'reader_end_frame' => $readerEndFrame,
                        'current_checkpoint' => $currentCheckpoint,
                        'current_durable' => $currentDurable,
                        'next_durable' => $nextDurable,
                        'current_source_token' => ['id' => $currentSourceId, 'epoch' => $checkpointEpoch],
                        'next_source_token' => ['id' => $nextSourceId, 'epoch' => $nextEpoch],
                        'hot_journal_page_numbers' => array_keys($hotJournalPages),
                        'savepoint_rollback_page_numbers' => array_keys($savepointBeforePages),
                        'checkpoint_page_numbers' => $checkpointPages,
                        'current_sources' => array_column($rows, 'current_source'),
                        'checkpoint_sources' => array_column($rows, 'checkpoint_source'),
                        'next_sources' => array_column($rows, 'next_source'),
                        'current_frame_indexes' => array_column($rows, 'current_frame'),
                        'checkpoint_frame_indexes' => array_column($rows, 'checkpoint_frame'),
                        'next_frame_indexes' => array_column($rows, 'next_frame'),
                        'current_labels' => array_column($rows, 'current_label'),
                        'checkpoint_labels' => array_column($rows, 'checkpoint_label'),
                        'next_labels' => array_column($rows, 'next_label'),
                        'retained_cache_page_numbers' => $retainedCache,
                        'invalidated_cache_page_numbers' => $invalidatedCache,
                        'requires_reader_reopen' => $invalidatedCache !== [],
                        'current_matches_checkpoint' => $allCurrentMatchesCheckpoint,
                        'next_changes_pages' => in_array(true, array_column($rows, 'next_differs_from_current_source'), true),
                        'rows' => $rows,
                        'operations' => $operations,
                        'operation_names' => array_column($operations, 'op'),
                        'source_digest' => hash('sha256', $currentSourceId . '|' . $nextSourceId . '|' . implode('|', array_column($rows, 'source_transition'))),
                        'dependencies' => [
                            'sqlite-wal-hot-journal-savepoint-checkpoint-current-source-next161',
                            'sqlite-hot-journal-savepoint-checkpoint-reader-cache-token-fence',
                            'sqlite-wal-reader-snapshot-page-image',
                            'sqlite-wal-durable-checkpoint-result',
                        ],
                        'dependency_closure' => 'no new support component needed; reuses WAL parsing, reader snapshots, durable checkpoint result planning, and savepoint before-image materialization',
                        'non_overlap' => 'does not repeat next159 checkpoint payload writes; this slice fences reader-cache source tokens across hot-journal recovery, rollback-to-savepoint, current checkpoint, and next WAL generation',
                    ];
                }

                /**
                 * @return array<int,array{image:string,source:string}>
                 */
                private static function sourceMap(string $bytes, int $pageSize): array
                {
                    $map = [];
                    foreach (str_split($bytes, $pageSize) as $index => $image) {
                        if (strlen($image) !== $pageSize) {
                            throw new \InvalidArgumentException('SQLite WAL hot-journal savepoint checkpoint current-source next161 database image is not page-size aligned');
                        }
                        $map[$index + 1] = [
                            'image' => $image,
                            'source' => 'database-before-hot-journal-next161',
                        ];
                    }

                    return $map;
                }

                /**
                 * @param array<int,string> $images
                 * @return array<int,string>
                 */
                private static function normalizeImages(array $images, int $pageSize, string $label): array
                {
                    $normalized = [];
                    foreach ($images as $pageNumber => $image) {
                        if (!is_int($pageNumber) || $pageNumber < 1) {
                            throw new \InvalidArgumentException("SQLite WAL hot-journal savepoint checkpoint current-source next161 {$label} page numbers must be one-based integers");
                        }
                        if (!is_string($image) || strlen($image) !== $pageSize) {
                            throw new \InvalidArgumentException("SQLite WAL hot-journal savepoint checkpoint current-source next161 {$label} page {$pageNumber} must be page-size bytes");
                        }
                        $normalized[$pageNumber] = $image;
                    }
                    ksort($normalized, SORT_NUMERIC);

                    return $normalized;
                }

                /**
                 * @param array<int,array{image:string,source_id?:string,epoch?:int,pinned?:bool,dirty?:bool,label?:string}> $cachePages
                 * @return array<int,array{image:string,source_id:string,epoch:int,pinned:bool,dirty:bool,label:string}>
                 */
                private static function normalizeReaderCache(array $cachePages, int $pageSize): array
                {
                    $normalized = [];
                    foreach ($cachePages as $pageNumber => $entry) {
                        if (!is_int($pageNumber) || $pageNumber < 1) {
                            throw new \InvalidArgumentException('SQLite WAL hot-journal savepoint checkpoint current-source next161 reader cache page numbers must be one-based integers');
                        }
                        if (!isset($entry['image']) || !is_string($entry['image']) || strlen($entry['image']) !== $pageSize) {
                            throw new \InvalidArgumentException("SQLite WAL hot-journal savepoint checkpoint current-source next161 reader cache page {$pageNumber} must be page-size bytes");
                        }
                        $sourceId = (string) ($entry['source_id'] ?? '');
                        $epoch = $entry['epoch'] ?? 0;
                        if ($sourceId === '' || !is_int($epoch) || $epoch < 1) {
                            throw new \InvalidArgumentException('SQLite WAL hot-journal savepoint checkpoint current-source next161 reader cache entries require source id and positive epoch');
                        }
                        $normalized[$pageNumber] = [
                            'image' => $entry['image'],
                            'source_id' => $sourceId,
                            'epoch' => $epoch,
                            'pinned' => (bool) ($entry['pinned'] ?? false),
                            'dirty' => (bool) ($entry['dirty'] ?? false),
                            'label' => (string) ($entry['label'] ?? ('cache-page-' . $pageNumber)),
                        ];
                    }
                    ksort($normalized, SORT_NUMERIC);

                    return $normalized;
                }

                /**
                 * @param list<int> $pages
                 */
                private static function assertPageList(array $pages): void
                {
                    foreach ($pages as $pageNumber) {
                        if (!is_int($pageNumber) || $pageNumber < 1) {
                            throw new \InvalidArgumentException('SQLite WAL hot-journal savepoint checkpoint current-source next161 checkpoint pages must be one-based integers');
                        }
                    }
                }

                /**
                 * @param array<int,array{image:string,source:string}> $database
                 */
                private static function assertDatabasePageExists(array $database, int $pageNumber, string $label): void
                {
                    if (!isset($database[$pageNumber])) {
                        throw new \InvalidArgumentException("SQLite WAL hot-journal savepoint checkpoint current-source next161 {$label} page {$pageNumber} is outside the database image");
                    }
                }

                /**
                 * @param array<int,array{image:string,source:string}> $source
                 */
                private static function sourceBytes(array $source, int $pageSize): string
                {
                    ksort($source, SORT_NUMERIC);
                    $bytes = '';
                    foreach ($source as $entry) {
                        if (strlen($entry['image']) !== $pageSize) {
                            throw new \RuntimeException('SQLite WAL hot-journal savepoint checkpoint current-source next161 final image is not page-size bytes');
                        }
                        $bytes .= $entry['image'];
                    }

                    return $bytes;
                }

                /**
                 * @return array{source:string,frame_index:int|null,image:string}
                 */
                private static function checkpointVisibility(string $databaseBytes, string $walBytes, int $pageSize, int $pageNumber, int $readerEndFrame): array
                {
                    if ($walBytes !== '') {
                        $wal = SQLiteWal::parse($walBytes, $pageSize, true);
                        return $wal->readerSnapshotPageImage($databaseBytes, $pageNumber, min($readerEndFrame, $wal->frameCount()));
                    }
                    $offset = ($pageNumber - 1) * $pageSize;
                    $image = substr($databaseBytes, $offset, $pageSize);
                    if (strlen($image) !== $pageSize) {
                        throw new \InvalidArgumentException("SQLite WAL hot-journal savepoint checkpoint current-source next161 checkpoint page {$pageNumber} is outside durable database");
                    }

                    return [
                        'source' => 'database',
                        'frame_index' => null,
                        'image' => $image,
                    ];
                }

                /**
                 * @param array{image:string,source_id:string,epoch:int,pinned:bool,dirty:bool,label:string}|null $cache
                 * @return array{admitted:bool,reason:string}
                 */
                private static function cacheAdmission(?array $cache, string $currentImage, string $sourceId, int $epoch, string $walAction): array
                {
                    if ($cache === null) {
                        return ['admitted' => false, 'reason' => 'reader_cache_missing_after_checkpoint'];
                    }
                    if ($cache['dirty']) {
                        return ['admitted' => false, 'reason' => 'reader_cache_dirty_after_failed_savepoint'];
                    }
                    if ($cache['source_id'] !== $sourceId) {
                        return ['admitted' => false, 'reason' => 'reader_cache_source_token_predates_checkpoint_current_source'];
                    }
                    if ($cache['epoch'] !== $epoch) {
                        return ['admitted' => false, 'reason' => 'reader_cache_epoch_predates_checkpoint_current_source'];
                    }
                    if ($cache['image'] !== $currentImage) {
                        return ['admitted' => false, 'reason' => 'reader_cache_image_predates_hot_journal_savepoint_checkpoint'];
                    }
                    if ($cache['pinned'] && in_array($walAction, ['restart_wal', 'truncate_wal'], true)) {
                        return ['admitted' => false, 'reason' => 'pinned_reader_cache_must_reopen_after_wal_reset'];
                    }

                    return ['admitted' => true, 'reason' => 'reader_cache_matches_checkpoint_current_source_token'];
                }

                private static function sourceId(string $kind, string $databasePath, string $savepoint, string $walBytes, string $databaseBytes, string $mode, int $frame): string
                {
                    return 'wal-hot-journal-savepoint-checkpoint-next161:' . $kind . ':' . substr(hash('sha256', $databasePath . '|' . $savepoint . '|' . $mode . '|' . $frame . '|' . $walBytes . '|' . $databaseBytes), 0, 24);
                }

                private static function label(string $image): string
                {
                    return rtrim(substr($image, 0, 80), ". \0");
                }
        };

        return $impl::plan($databasePath, $databaseBytes, $pageSize, $savepoint, $hotJournalPages, $savepointBeforePages, $currentWal, $currentWalBytes, $nextWal, $nextWalBytes, $readerCachePages, $checkpointPages, $mode, $readerEndFrame, $currentSourceEpoch);
    }

    public static function next162Plan(
        string $databasePath,
        string $dirtyDatabaseBytes,
        string $journalBytes,
        SQLiteSavepointStack $savepoints,
        string $savepoint,
        SQLiteWal $wal,
        string $walBytes,
        array $pageNumbers,
        string $mode = 'restart',
        ?int $readerEndFrame = null,
        bool $reservedLock = false,
        bool $requiresSuperJournal = false,
        ?bool $superJournalExists = null,
    ): array
    {
        $impl = new class {
                /**
                 * @param list<int> $pageNumbers
                 * @return array<string,mixed>
                 */
                public static function plan(
                    string $databasePath,
                    string $dirtyDatabaseBytes,
                    string $journalBytes,
                    SQLiteSavepointStack $savepoints,
                    string $savepoint,
                    SQLiteWal $wal,
                    string $walBytes,
                    array $pageNumbers,
                    string $mode = 'restart',
                    ?int $readerEndFrame = null,
                    bool $reservedLock = false,
                    bool $requiresSuperJournal = false,
                    ?bool $superJournalExists = null,
                ): array {
                    if ($databasePath === '') {
                        throw new \InvalidArgumentException('SQLite WAL hot-journal savepoint checkpoint current-source next162 requires a database path');
                    }
                    if ($dirtyDatabaseBytes === '') {
                        throw new \InvalidArgumentException('SQLite WAL hot-journal savepoint checkpoint current-source next162 requires database bytes');
                    }
                    if ($journalBytes === '') {
                        throw new \InvalidArgumentException('SQLite WAL hot-journal savepoint checkpoint current-source next162 requires rollback journal bytes');
                    }
                    if ($savepoint === '') {
                        throw new \InvalidArgumentException('SQLite WAL hot-journal savepoint checkpoint current-source next162 requires a savepoint');
                    }
                    if ($walBytes === '') {
                        throw new \InvalidArgumentException('SQLite WAL hot-journal savepoint checkpoint current-source next162 requires WAL bytes');
                    }
                    if ($pageNumbers === []) {
                        throw new \InvalidArgumentException('SQLite WAL hot-journal savepoint checkpoint current-source next162 requires page numbers');
                    }
                    if ($wal->toBytes() !== $walBytes) {
                        throw new \InvalidArgumentException('SQLite WAL hot-journal savepoint checkpoint current-source next162 parsed WAL does not match bytes');
                    }

                    $mode = strtolower(trim($mode));
                    if (!in_array($mode, ['restart', 'truncate'], true)) {
                        throw new \InvalidArgumentException('SQLite WAL hot-journal savepoint checkpoint current-source next162 requires restart or truncate mode');
                    }

                    $pageSize = $wal->header->pageSize;
                    if ($pageSize < 512 || strlen($dirtyDatabaseBytes) % $pageSize !== 0) {
                        throw new \InvalidArgumentException('SQLite WAL hot-journal savepoint checkpoint current-source next162 database bytes must be page-size aligned');
                    }
                    foreach ($pageNumbers as $pageNumber) {
                        if (!is_int($pageNumber) || $pageNumber < 1) {
                            throw new \InvalidArgumentException('SQLite WAL hot-journal savepoint checkpoint current-source next162 pages must be one-based integers');
                        }
                    }

                    $journal = SQLiteRollbackJournal::parse($journalBytes, true);
                    if ($journal->header->pageSize !== $pageSize) {
                        throw new \InvalidArgumentException('SQLite WAL hot-journal savepoint checkpoint current-source next162 journal page size does not match WAL page size');
                    }

                    $hot = $journal->hotJournalRecoveryResult(
                        $dirtyDatabaseBytes,
                        $journalBytes,
                        $reservedLock,
                        $requiresSuperJournal,
                        $superJournalExists
                    );
                    if (!$hot['recovered']) {
                        return [
                            'status' => 'wal-hot-journal-savepoint-checkpoint-current-source-blocked-next162',
                            'reason' => $hot['reason'],
                            'database_path' => $databasePath,
                            'journal_path' => $databasePath . '-journal',
                            'wal_path' => $databasePath . '-wal',
                            'savepoint' => $savepoint,
                            'mode' => $mode,
                            'page_size' => $pageSize,
                            'hot_recovered' => false,
                            'current_source_admitted' => false,
                            'dependencies' => [
                                'sqlite-rollback-journal-hot-recovery',
                                'sqlite-wal-hot-journal-savepoint-checkpoint-current-source-next162',
                            ],
                        ];
                    }

                    $hotDatabaseBytes = (string) $hot['database_bytes'];
                    $rollback = $savepoints->walRollbackToByteTruncationPlan($savepoint, $wal, $walBytes);
                    $retainedWalBytes = $savepoints->walRollbackToWalBytes($savepoint, $wal, $walBytes);
                    $retainedWal = SQLiteWal::parse($retainedWalBytes, $pageSize, true);
                    $readerEndFrame ??= $retainedWal->frameCount();
                    if ($readerEndFrame < 0 || $readerEndFrame > $retainedWal->frameCount()) {
                        throw new \InvalidArgumentException('SQLite WAL hot-journal savepoint checkpoint current-source next162 reader frame is outside retained WAL');
                    }

                    $currentCheckpoint = $retainedWal->durableCheckpointResult($hotDatabaseBytes, $mode, $readerEndFrame);
                    $releasedCheckpoint = $retainedWal->durableCheckpointResult($hotDatabaseBytes, $mode);
                    $staleCheckpoint = $retainedWal->durableCheckpointResult($dirtyDatabaseBytes, $mode, $readerEndFrame);

                    $rows = [];
                    foreach ($pageNumbers as $pageNumber) {
                        $dirty = self::databasePage($dirtyDatabaseBytes, $pageSize, $pageNumber);
                        $hotRow = self::databasePage($hotDatabaseBytes, $pageSize, $pageNumber);
                        $retained = $readerEndFrame === 0
                            ? $hotRow
                            : $retainedWal->readerSnapshotPageImage($hotDatabaseBytes, $pageNumber, $readerEndFrame);
                        $current = self::checkpointPage($currentCheckpoint, $pageSize, $pageNumber);
                        $released = self::checkpointPage($releasedCheckpoint, $pageSize, $pageNumber);
                        $stale = self::checkpointPage($staleCheckpoint, $pageSize, $pageNumber);

                        $rows[] = [
                            'page_number' => $pageNumber,
                            'dirty_source' => $dirty['source'],
                            'hot_source' => $hotRow['source'],
                            'retained_source' => $retained['source'],
                            'current_checkpoint_source' => $current['source'],
                            'released_checkpoint_source' => $released['source'],
                            'stale_checkpoint_source' => $stale['source'],
                            'retained_frame' => $retained['frame_index'],
                            'current_checkpoint_frame' => $current['frame_index'],
                            'released_checkpoint_frame' => $released['frame_index'],
                            'dirty_label' => self::label((string) $dirty['image']),
                            'hot_label' => self::label((string) $hotRow['image']),
                            'retained_label' => self::label((string) $retained['image']),
                            'current_checkpoint_label' => self::label((string) $current['image']),
                            'released_checkpoint_label' => self::label((string) $released['image']),
                            'stale_checkpoint_label' => self::label((string) $stale['image']),
                            'hot_replaced_dirty' => $dirty['image'] !== $hotRow['image'],
                            'current_checkpoint_preserves_retained' => $current['image'] === $retained['image'],
                            'released_checkpoint_preserves_retained' => $released['image'] === $retained['image'],
                            'stale_checkpoint_would_publish_dirty' => $stale['image'] !== $current['image'],
                            'source_transition' => implode('>', [$dirty['source'], $hotRow['source'], $retained['source'], $current['source'], $released['source']]),
                        ];
                    }

                    $stalePages = array_values(array_map(
                        static fn (array $row): int => (int) $row['page_number'],
                        array_filter($rows, static fn (array $row): bool => (bool) $row['stale_checkpoint_would_publish_dirty'])
                    ));

                    return [
                        'status' => 'wal-hot-journal-savepoint-checkpoint-current-source-next162',
                        'reason' => 'hot_journal_current_source_required_before_savepoint_checkpoint_publish',
                        'database_path' => $databasePath,
                        'journal_path' => $databasePath . '-journal',
                        'wal_path' => $databasePath . '-wal',
                        'savepoint' => $savepoint,
                        'mode' => $mode,
                        'page_size' => $pageSize,
                        'page_numbers' => array_values($pageNumbers),
                        'hot_recovered' => true,
                        'journal_action' => $hot['journal_action'],
                        'original_frame_count' => $wal->frameCount(),
                        'retained_frame_count' => $retainedWal->frameCount(),
                        'discarded_frame_count' => $rollback['discarded_frame_count'],
                        'discarded_frame_indexes' => array_column($rollback['discarded_wal_frames'], 'frame_index'),
                        'reader_end_frame' => $readerEndFrame,
                        'current_checkpoint_busy' => $currentCheckpoint['busy'],
                        'current_checkpoint_reason' => $currentCheckpoint['reason'],
                        'current_checkpoint_wal_action' => $currentCheckpoint['wal_action'],
                        'released_checkpoint_busy' => $releasedCheckpoint['busy'],
                        'released_checkpoint_reason' => $releasedCheckpoint['reason'],
                        'released_checkpoint_wal_action' => $releasedCheckpoint['wal_action'],
                        'stale_checkpoint_rejected' => $stalePages !== [],
                        'stale_checkpoint_dirty_page_numbers' => $stalePages,
                        'dirty_database_sha256' => hash('sha256', $dirtyDatabaseBytes),
                        'hot_database_sha256' => hash('sha256', $hotDatabaseBytes),
                        'retained_wal_sha256' => hash('sha256', $retainedWalBytes),
                        'current_checkpoint_database_sha256' => hash('sha256', (string) $currentCheckpoint['database_bytes']),
                        'released_checkpoint_database_sha256' => hash('sha256', (string) $releasedCheckpoint['database_bytes']),
                        'current_checkpoint_database_bytes' => (string) $currentCheckpoint['database_bytes'],
                        'released_checkpoint_database_bytes' => (string) $releasedCheckpoint['database_bytes'],
                        'current_checkpoint_wal_bytes_length' => strlen((string) $currentCheckpoint['wal_bytes']),
                        'released_checkpoint_wal_bytes_length' => strlen((string) $releasedCheckpoint['wal_bytes']),
                        'rows' => $rows,
                        'source_transitions' => array_column($rows, 'source_transition'),
                        'retained_sources' => array_column($rows, 'retained_source'),
                        'current_checkpoint_sources' => array_column($rows, 'current_checkpoint_source'),
                        'released_checkpoint_sources' => array_column($rows, 'released_checkpoint_source'),
                        'retained_frame_indexes' => array_column($rows, 'retained_frame'),
                        'current_checkpoint_frame_indexes' => array_column($rows, 'current_checkpoint_frame'),
                        'released_checkpoint_frame_indexes' => array_column($rows, 'released_checkpoint_frame'),
                        'hot_recovery_replaced_dirty_images' => in_array(true, array_column($rows, 'hot_replaced_dirty'), true),
                        'current_checkpoint_preserved_retained_images' => !in_array(false, array_column($rows, 'current_checkpoint_preserves_retained'), true),
                        'released_checkpoint_preserved_retained_images' => !in_array(false, array_column($rows, 'released_checkpoint_preserves_retained'), true),
                        'current_source_admitted' => $stalePages !== [] && hash('sha256', $dirtyDatabaseBytes) !== hash('sha256', $hotDatabaseBytes),
                        'source_digest' => hash('sha256', implode('|', array_column($rows, 'source_transition'))),
                        'operation_reasons' => [
                            'recover_hot_journal_before_savepoint_checkpoint_next162',
                            'rollback_savepoint_wal_prefix_after_hot_journal_next162',
                            'reject_stale_dirty_database_checkpoint_source_next162',
                            'publish_checkpoint_from_hot_current_source_next162',
                        ],
                        'dependencies' => array_values(array_unique(array_merge(
                            $currentCheckpoint['dependencies'],
                            $releasedCheckpoint['dependencies'],
                            [
                                'sqlite-rollback-journal-hot-recovery',
                                'sqlite-savepoint-wal-prefix-truncation',
                                'sqlite-wal-hot-journal-savepoint-checkpoint-current-source-next162',
                                'wordpress-import-current-source-checkpoint-admission',
                            ]
                        ))),
                    ];
                }

                /**
                 * @return array{page_number:int,source:string,frame_index:null,database_offset:int,image:string,snapshot_end_frame:int,snapshot_commit_frame:null,database_page_count:int}
                 */
                private static function databasePage(string $databaseBytes, int $pageSize, int $pageNumber): array
                {
                    $pageCount = intdiv(strlen($databaseBytes), $pageSize);
                    if ($pageNumber > $pageCount) {
                        throw new \OutOfBoundsException("SQLite WAL hot-journal savepoint checkpoint current-source next162 page {$pageNumber} is outside database image");
                    }

                    return [
                        'page_number' => $pageNumber,
                        'source' => 'database',
                        'frame_index' => null,
                        'database_offset' => ($pageNumber - 1) * $pageSize,
                        'image' => substr($databaseBytes, ($pageNumber - 1) * $pageSize, $pageSize),
                        'snapshot_end_frame' => 0,
                        'snapshot_commit_frame' => null,
                        'database_page_count' => $pageCount,
                    ];
                }

                /**
                 * @return array<string,mixed>
                 */
                private static function checkpointPage(array $checkpoint, int $pageSize, int $pageNumber): array
                {
                    $walBytes = (string) $checkpoint['wal_bytes'];
                    if ($walBytes === '') {
                        return self::databasePage((string) $checkpoint['database_bytes'], $pageSize, $pageNumber);
                    }

                    $wal = SQLiteWal::parse($walBytes, $pageSize, true);
                    return $wal->readerSnapshotPageImage((string) $checkpoint['database_bytes'], $pageNumber, $wal->frameCount());
                }

                private static function label(string $image): string
                {
                    return rtrim(substr($image, 0, 96), ".\0");
                }
        };

        return $impl::plan($databasePath, $dirtyDatabaseBytes, $journalBytes, $savepoints, $savepoint, $wal, $walBytes, $pageNumbers, $mode, $readerEndFrame, $reservedLock, $requiresSuperJournal, $superJournalExists);
    }

    public static function next164Plan(
        string $databasePath,
        string $databaseBytes,
        int $pageSize,
        string $savepoint,
        array $hotJournalPages,
        array $savepointBeforePages,
        SQLiteWal $currentWal,
        string $currentWalBytes,
        SQLiteWal $nextWal,
        string $nextWalBytes,
        array $readerCachePages,
        array $checkpointPages,
        array $readers,
        string $mode = 'restart',
        int $readerEndFrame = 0,
        int $currentSourceEpoch = 1,
    ): array
    {
        $impl = new class {
                /**
                 * @param array<int,string> $hotJournalPages
                 * @param array<int,string> $savepointBeforePages
                 * @param array<int,array{image:string,source_id?:string,epoch?:int,pinned?:bool,dirty?:bool,label?:string}> $readerCachePages
                 * @param list<int> $checkpointPages
                 * @param list<array{name:string,source_id?:string,epoch?:int,pinned?:bool,dirty?:bool,closed?:bool}> $readers
                 * @return array<string,mixed>
                 */
                public static function plan(
                    string $databasePath,
                    string $databaseBytes,
                    int $pageSize,
                    string $savepoint,
                    array $hotJournalPages,
                    array $savepointBeforePages,
                    SQLiteWal $currentWal,
                    string $currentWalBytes,
                    SQLiteWal $nextWal,
                    string $nextWalBytes,
                    array $readerCachePages,
                    array $checkpointPages,
                    array $readers,
                    string $mode = 'restart',
                    int $readerEndFrame = 0,
                    int $currentSourceEpoch = 1,
                ): array {
                    if ($readers === []) {
                        throw new \InvalidArgumentException('SQLite WAL hot-journal savepoint checkpoint current-source next164 requires reader admission candidates');
                    }

                    $base = SQLiteWalHotJournalSavepointCheckpointCurrentSourceNextPlan::next161Plan(
                        $databasePath,
                        $databaseBytes,
                        $pageSize,
                        $savepoint,
                        $hotJournalPages,
                        $savepointBeforePages,
                        $currentWal,
                        $currentWalBytes,
                        $nextWal,
                        $nextWalBytes,
                        $readerCachePages,
                        $checkpointPages,
                        $mode,
                        $readerEndFrame,
                        $currentSourceEpoch
                    );

                    $currentToken = $base['current_source_token'];
                    $nextToken = $base['next_source_token'];
                    $readerRows = [];
                    $admitted = [];
                    $reopen = [];
                    foreach ($readers as $reader) {
                        $row = self::readerAdmission($reader, $currentToken, $nextToken, (bool) $base['requires_reader_reopen']);
                        $readerRows[] = $row;
                        if ($row['admitted']) {
                            $admitted[] = $row['name'];
                        } else {
                            $reopen[] = $row['name'];
                        }
                    }

                    $operationNames = $base['operation_names'];
                    foreach ($readerRows as $row) {
                        $operationNames[] = $row['admitted']
                            ? 'admit_reader_on_checkpoint_current_source_next164'
                            : 'force_reader_reopen_for_next_wal_source_next164';
                    }

                    $status = $admitted !== [] && $reopen !== [] && (bool) $base['current_matches_checkpoint']
                        ? 'wal-hot-journal-savepoint-checkpoint-current-source-next164'
                        : 'wal-hot-journal-savepoint-checkpoint-current-source-blocked-next164';

                    return [
                        'status' => $status,
                        'reason' => $status === 'wal-hot-journal-savepoint-checkpoint-current-source-next164'
                            ? 'checkpoint_current_source_readers_admitted_after_hot_journal_savepoint_rollback'
                            : 'checkpoint_current_source_reader_admission_incomplete',
                        'database_path' => $databasePath,
                        'journal_path' => $base['journal_path'],
                        'wal_path' => $base['wal_path'],
                        'page_size' => $pageSize,
                        'savepoint' => $savepoint,
                        'mode' => $base['mode'],
                        'reader_end_frame' => $base['reader_end_frame'],
                        'base_status' => $base['status'],
                        'base_reason' => $base['reason'],
                        'current_source_token' => $currentToken,
                        'next_source_token' => $nextToken,
                        'current_durable' => $base['current_durable'],
                        'next_durable' => $base['next_durable'],
                        'checkpoint_page_numbers' => $base['checkpoint_page_numbers'],
                        'hot_journal_page_numbers' => $base['hot_journal_page_numbers'],
                        'savepoint_rollback_page_numbers' => $base['savepoint_rollback_page_numbers'],
                        'retained_cache_page_numbers' => $base['retained_cache_page_numbers'],
                        'invalidated_cache_page_numbers' => $base['invalidated_cache_page_numbers'],
                        'requires_reader_reopen' => $base['requires_reader_reopen'] || $reopen !== [],
                        'reader_rows' => $readerRows,
                        'admitted_reader_names' => $admitted,
                        'reopen_reader_names' => $reopen,
                        'reader_reopen_count' => count($reopen),
                        'reader_admission_reasons' => array_column($readerRows, 'reason'),
                        'operation_names' => $operationNames,
                        'source_digest' => hash('sha256', $base['source_digest'] . '|' . implode('|', array_column($readerRows, 'transition'))),
                        'base_plan' => $base,
                        'dependencies' => array_values(array_unique(array_merge($base['dependencies'], [
                            'sqlite-wal-hot-journal-savepoint-checkpoint-current-source-next164',
                            'sqlite-wal-reader-admission-current-source-token',
                        ]))),
                        'dependency_closure' => 'no new support component needed; composes native WAL parsing, hot-journal recovery, savepoint rollback, checkpoint source tokens, and reader admission fences',
                        'non_overlap' => 'does not repeat next161 cache-token rebasing or VFS writer byte application; this slice decides reader admission across checkpoint current-source and next WAL source tokens',
                    ];
                }

                /**
                 * @param array{name:string,source_id?:string,epoch?:int,pinned?:bool,dirty?:bool,closed?:bool} $reader
                 * @param array{id:string,epoch:int} $currentToken
                 * @param array{id:string,epoch:int} $nextToken
                 * @return array{name:string,admitted:bool,reason:string,source_id:string,epoch:int,pinned:bool,dirty:bool,closed:bool,transition:string}
                 */
                private static function readerAdmission(array $reader, array $currentToken, array $nextToken, bool $cacheRequiresReopen): array
                {
                    $name = trim((string) ($reader['name'] ?? ''));
                    if ($name === '') {
                        throw new \InvalidArgumentException('SQLite WAL hot-journal savepoint checkpoint current-source next164 reader name is required');
                    }

                    $sourceId = (string) ($reader['source_id'] ?? '');
                    $epoch = $reader['epoch'] ?? 0;
                    if ($sourceId === '' || !is_int($epoch) || $epoch < 1) {
                        throw new \InvalidArgumentException('SQLite WAL hot-journal savepoint checkpoint current-source next164 reader source token and epoch are required');
                    }

                    $pinned = (bool) ($reader['pinned'] ?? false);
                    $dirty = (bool) ($reader['dirty'] ?? false);
                    $closed = (bool) ($reader['closed'] ?? false);
                    $admitted = true;
                    $reason = 'reader_matches_checkpoint_current_source_token';

                    if ($closed) {
                        $admitted = false;
                        $reason = 'reader_closed_before_checkpoint_publish';
                    } elseif ($dirty) {
                        $admitted = false;
                        $reason = 'reader_dirty_after_failed_savepoint';
                    } elseif ($sourceId === (string) $nextToken['id'] && $epoch === (int) $nextToken['epoch']) {
                        $admitted = false;
                        $reason = 'reader_already_reopened_on_next_wal_source';
                    } elseif ($sourceId !== (string) $currentToken['id']) {
                        $admitted = false;
                        $reason = 'reader_source_token_predates_checkpoint_current_source';
                    } elseif ($epoch !== (int) $currentToken['epoch']) {
                        $admitted = false;
                        $reason = 'reader_epoch_predates_checkpoint_current_source';
                    } elseif ($pinned && $cacheRequiresReopen) {
                        $admitted = false;
                        $reason = 'pinned_reader_must_reopen_after_cache_rebase';
                    }

                    return [
                        'name' => $name,
                        'admitted' => $admitted,
                        'reason' => $reason,
                        'source_id' => $sourceId,
                        'epoch' => $epoch,
                        'pinned' => $pinned,
                        'dirty' => $dirty,
                        'closed' => $closed,
                        'transition' => $sourceId . '@' . $epoch . '>' . ($admitted ? 'checkpoint-current' : 'reopen-next'),
                    ];
                }
        };

        return $impl::plan($databasePath, $databaseBytes, $pageSize, $savepoint, $hotJournalPages, $savepointBeforePages, $currentWal, $currentWalBytes, $nextWal, $nextWalBytes, $readerCachePages, $checkpointPages, $readers, $mode, $readerEndFrame, $currentSourceEpoch);
    }

    public static function next165Plan(
        string $databasePath,
        string $dirtyDatabaseBytes,
        string $journalBytes,
        SQLiteSavepointStack $savepoints,
        string $savepoint,
        SQLiteWal $wal,
        string $walBytes,
        array $pageNumbers,
        string $mode = 'restart',
        ?int $readerEndFrame = null,
        bool $reservedLock = false,
        bool $requiresSuperJournal = false,
        ?bool $superJournalExists = null,
    ): array
    {
        $impl = new class {
                /**
                 * @param list<int> $pageNumbers
                 * @return array<string,mixed>
                 */
                public static function plan(
                    string $databasePath,
                    string $dirtyDatabaseBytes,
                    string $journalBytes,
                    SQLiteSavepointStack $savepoints,
                    string $savepoint,
                    SQLiteWal $wal,
                    string $walBytes,
                    array $pageNumbers,
                    string $mode = 'restart',
                    ?int $readerEndFrame = null,
                    bool $reservedLock = false,
                    bool $requiresSuperJournal = false,
                    ?bool $superJournalExists = null,
                ): array {
                    $base = SQLiteWalHotJournalSavepointCheckpointCurrentSourceNextPlan::next162Plan(
                        $databasePath,
                        $dirtyDatabaseBytes,
                        $journalBytes,
                        $savepoints,
                        $savepoint,
                        $wal,
                        $walBytes,
                        $pageNumbers,
                        $mode,
                        $readerEndFrame,
                        $reservedLock,
                        $requiresSuperJournal,
                        $superJournalExists,
                    );

                    if (($base['status'] ?? '') !== 'wal-hot-journal-savepoint-checkpoint-current-source-next162') {
                        return array_merge($base, [
                            'status' => 'wal-hot-journal-savepoint-checkpoint-current-source-blocked-next165',
                            'reason' => $base['reason'] ?? 'current_source_not_admitted',
                            'publish_admitted' => false,
                            'dependencies' => array_values(array_unique(array_merge(
                                $base['dependencies'] ?? [],
                                ['sqlite-wal-hot-journal-savepoint-checkpoint-current-source-next165']
                            ))),
                        ]);
                    }

                    $mode = strtolower(trim($mode));
                    $pageSize = (int) $base['page_size'];
                    $retainedWalBytes = $savepoints->walRollbackToWalBytes($savepoint, $wal, $walBytes);
                    $retainedWal = SQLiteWal::parse($retainedWalBytes, $pageSize, true);
                    $readerEndFrame ??= (int) $base['reader_end_frame'];
                    $currentCheckpoint = $retainedWal->durableCheckpointResult(
                        self::checkpointDatabaseBytes($base, 'current_checkpoint', $dirtyDatabaseBytes),
                        $mode,
                        $readerEndFrame
                    );
                    $releasedCheckpoint = $retainedWal->durableCheckpointResult(
                        self::checkpointDatabaseBytes($base, 'released_checkpoint', $dirtyDatabaseBytes),
                        $mode
                    );

                    $currentDatabaseBytes = (string) $currentCheckpoint['database_bytes'];
                    $releasedDatabaseBytes = (string) $releasedCheckpoint['database_bytes'];
                    $currentWalBytes = (string) $currentCheckpoint['wal_bytes'];
                    $releasedWalBytes = (string) $releasedCheckpoint['wal_bytes'];
                    $currentPayloadKey = $databasePath . '#next165-current-checkpoint';
                    $releasedPayloadKey = $databasePath . '#next165-released-checkpoint';
                    $currentWalPayloadKey = $databasePath . '-wal#next165-current-reader';
                    $releasedWalPayloadKey = $databasePath . '-wal#next165-released-reader';
                    $journalPath = $databasePath . '-journal';
                    $walPath = $databasePath . '-wal';

                    $operations = [
                        [
                            'op' => 'write',
                            'path' => $databasePath,
                            'offset' => 0,
                            'bytes' => strlen($currentDatabaseBytes),
                            'payload_key' => $currentPayloadKey,
                            'reason' => 'publish_hot_journal_savepoint_current_checkpoint_database_next165',
                        ],
                        [
                            'op' => 'truncate',
                            'path' => $databasePath,
                            'bytes' => strlen($currentDatabaseBytes),
                            'reason' => 'trim_database_after_current_checkpoint_publish_next165',
                        ],
                        [
                            'op' => 'write',
                            'path' => $walPath,
                            'offset' => 0,
                            'bytes' => strlen($currentWalBytes),
                            'payload_key' => $currentWalPayloadKey,
                            'reason' => 'preserve_retained_wal_for_pinned_reader_next165',
                        ],
                        [
                            'op' => 'sync',
                            'path' => $databasePath,
                            'durable' => true,
                            'reason' => 'sync_current_checkpoint_before_reader_release_next165',
                        ],
                        [
                            'op' => 'delete',
                            'path' => $journalPath,
                            'reason' => 'delete_hot_journal_after_current_source_checkpoint_next165',
                        ],
                        [
                            'op' => 'write',
                            'path' => $databasePath,
                            'offset' => 0,
                            'bytes' => strlen($releasedDatabaseBytes),
                            'payload_key' => $releasedPayloadKey,
                            'reason' => 'publish_released_savepoint_checkpoint_database_next165',
                        ],
                        [
                            'op' => $releasedWalBytes === '' ? 'truncate' : 'write',
                            'path' => $walPath,
                            'offset' => 0,
                            'bytes' => strlen($releasedWalBytes),
                            'payload_key' => $releasedWalPayloadKey,
                            'reason' => $releasedWalBytes === ''
                                ? 'truncate_wal_after_savepoint_release_next165'
                                : 'restart_wal_after_savepoint_release_next165',
                        ],
                        [
                            'op' => 'sync',
                            'path' => $databasePath,
                            'durable' => true,
                            'reason' => 'sync_released_checkpoint_after_savepoint_publish_next165',
                        ],
                    ];

                    $rows = [];
                    foreach ($base['rows'] as $row) {
                        $rows[] = [
                            'page_number' => $row['page_number'],
                            'dirty_label' => $row['dirty_label'],
                            'current_checkpoint_label' => $row['current_checkpoint_label'],
                            'released_checkpoint_label' => $row['released_checkpoint_label'],
                            'current_source' => $row['current_checkpoint_source'],
                            'released_source' => $row['released_checkpoint_source'],
                            'reader_pinned' => $row['current_checkpoint_source'] === 'wal',
                            'released_from_database' => $row['released_checkpoint_source'] === 'database',
                            'stale_publish_blocked' => $row['stale_checkpoint_would_publish_dirty'],
                            'publish_transition' => $row['dirty_source'] . '>' . $row['current_checkpoint_source'] . '>' . $row['released_checkpoint_source'],
                        ];
                    }

                    $pinnedRows = array_values(array_filter($rows, static fn (array $row): bool => (bool) $row['reader_pinned']));
                    $staleBlockedRows = array_values(array_filter($rows, static fn (array $row): bool => (bool) $row['stale_publish_blocked']));

                    return [
                        'status' => 'wal-hot-journal-savepoint-checkpoint-current-source-next165',
                        'reason' => 'publish_checkpoint_uses_hot_journal_savepoint_current_source_before_wal_reset',
                        'database_path' => $databasePath,
                        'journal_path' => $journalPath,
                        'wal_path' => $walPath,
                        'savepoint' => $savepoint,
                        'mode' => $mode,
                        'page_size' => $pageSize,
                        'page_numbers' => $base['page_numbers'],
                        'publish_admitted' => true,
                        'hot_recovered' => true,
                        'current_checkpoint_busy' => $base['current_checkpoint_busy'],
                        'released_checkpoint_busy' => $base['released_checkpoint_busy'],
                        'current_checkpoint_wal_action' => $base['current_checkpoint_wal_action'],
                        'released_checkpoint_wal_action' => $base['released_checkpoint_wal_action'],
                        'current_database_bytes_length' => strlen($currentDatabaseBytes),
                        'released_database_bytes_length' => strlen($releasedDatabaseBytes),
                        'current_wal_bytes_length' => strlen($currentWalBytes),
                        'released_wal_bytes_length' => strlen($releasedWalBytes),
                        'current_database_sha256' => hash('sha256', $currentDatabaseBytes),
                        'released_database_sha256' => hash('sha256', $releasedDatabaseBytes),
                        'current_wal_sha256' => hash('sha256', $currentWalBytes),
                        'released_wal_sha256' => hash('sha256', $releasedWalBytes),
                        'pinned_reader_page_numbers' => array_column($pinnedRows, 'page_number'),
                        'stale_publish_blocked_page_numbers' => array_column($staleBlockedRows, 'page_number'),
                        'all_released_pages_from_database' => !in_array(false, array_column($rows, 'released_from_database'), true),
                        'operation_reasons' => array_column($operations, 'reason'),
                        'operation_ops' => array_column($operations, 'op'),
                        'payload_keys' => [$currentPayloadKey, $currentWalPayloadKey, $releasedPayloadKey, $releasedWalPayloadKey],
                        'rows' => $rows,
                        'publish_transitions' => array_column($rows, 'publish_transition'),
                        'publish_digest' => hash('sha256', implode('|', array_column($rows, 'publish_transition'))),
                        'operations' => $operations,
                        'payloads' => [
                            $currentPayloadKey => $currentDatabaseBytes,
                            $currentWalPayloadKey => $currentWalBytes,
                            $releasedPayloadKey => $releasedDatabaseBytes,
                            $releasedWalPayloadKey => $releasedWalBytes,
                        ],
                        'base_plan' => $base,
                        'dependencies' => array_values(array_unique(array_merge(
                            $base['dependencies'],
                            $currentCheckpoint['dependencies'],
                            $releasedCheckpoint['dependencies'],
                            [
                                'sqlite-wal-hot-journal-savepoint-checkpoint-current-source-next165',
                                'sqlite-wal-checkpoint-publish-sequence',
                                'wordpress-import-current-source-checkpoint-publish',
                            ]
                        ))),
                        'dependency_closure' => 'no new support component needed; reuses native PHP hot-journal recovery, WAL savepoint truncation, durable checkpoint, and VFS write-plan payload primitives',
                        'non_overlap' => 'extends next162 admission with publish-order payloads and release sequencing; avoids accepted WAL byte truncation, VFS writer/apply, checkpoint transaction, and hot-journal reader-restart surfaces',
                    ];
                }

                /**
                 * @param array<string,mixed> $base
                 */
                private static function checkpointDatabaseBytes(array $base, string $prefix, string $fallback): string
                {
                    $hash = (string) ($base[$prefix . '_database_sha256'] ?? '');
                    $rows = $base['rows'] ?? [];
                    if ($hash === '' || !is_array($rows)) {
                        return $fallback;
                    }

                    return (string) ($base[$prefix . '_database_bytes'] ?? $fallback);
                }
        };

        return $impl::plan($databasePath, $dirtyDatabaseBytes, $journalBytes, $savepoints, $savepoint, $wal, $walBytes, $pageNumbers, $mode, $readerEndFrame, $reservedLock, $requiresSuperJournal, $superJournalExists);
    }

    public static function next166Plan(
        string $databasePath,
        string $databaseBytes,
        int $pageSize,
        string $innerSavepoint,
        string $outerSavepoint,
        array $hotJournalPages,
        array $savepointBeforePages,
        SQLiteWal $currentWal,
        string $currentWalBytes,
        SQLiteWal $nextWal,
        string $nextWalBytes,
        array $readerCachePages,
        array $checkpointPages,
        array $releasedSavepointPages,
        string $mode = 'restart',
        int $readerEndFrame = 0,
        int $currentSourceEpoch = 1,
    ): array
    {
        $impl = new class {
                /**
                 * @param array<int,string> $hotJournalPages
                 * @param array<int,string> $savepointBeforePages
                 * @param array<int,array{image:string,source_id?:string,epoch?:int,pinned?:bool,dirty?:bool,label?:string}> $readerCachePages
                 * @param list<int> $checkpointPages
                 * @param array<string,list<int>> $releasedSavepointPages
                 * @return array<string,mixed>
                 */
                public static function plan(
                    string $databasePath,
                    string $databaseBytes,
                    int $pageSize,
                    string $innerSavepoint,
                    string $outerSavepoint,
                    array $hotJournalPages,
                    array $savepointBeforePages,
                    SQLiteWal $currentWal,
                    string $currentWalBytes,
                    SQLiteWal $nextWal,
                    string $nextWalBytes,
                    array $readerCachePages,
                    array $checkpointPages,
                    array $releasedSavepointPages,
                    string $mode = 'restart',
                    int $readerEndFrame = 0,
                    int $currentSourceEpoch = 1,
                ): array {
                    if ($outerSavepoint === '' || $outerSavepoint === $innerSavepoint) {
                        throw new \InvalidArgumentException('SQLite WAL hot-journal savepoint checkpoint current-source next166 requires a distinct outer savepoint');
                    }
                    self::assertReleasedPages($releasedSavepointPages);

                    $base = SQLiteWalHotJournalSavepointCheckpointCurrentSourceNextPlan::next161Plan(
                        $databasePath,
                        $databaseBytes,
                        $pageSize,
                        $innerSavepoint,
                        $hotJournalPages,
                        $savepointBeforePages,
                        $currentWal,
                        $currentWalBytes,
                        $nextWal,
                        $nextWalBytes,
                        $readerCachePages,
                        $checkpointPages,
                        $mode,
                        $readerEndFrame,
                        $currentSourceEpoch,
                    );

                    $savepointPages = $base['savepoint_rollback_page_numbers'];
                    $releasedInnerPages = $releasedSavepointPages[$innerSavepoint] ?? [];
                    $missingReleasePages = array_values(array_diff($savepointPages, $releasedInnerPages));
                    sort($missingReleasePages, SORT_NUMERIC);

                    $releaseRows = [];
                    foreach ($savepointPages as $pageNumber) {
                        $releaseRows[] = [
                            'savepoint' => $innerSavepoint,
                            'outer_savepoint' => $outerSavepoint,
                            'page_number' => $pageNumber,
                            'released_to_outer' => in_array($pageNumber, $releasedInnerPages, true),
                            'checkpoint_label' => self::rowLabel($base, $pageNumber, 'checkpoint_label'),
                            'next_label' => self::rowLabel($base, $pageNumber, 'next_label'),
                        ];
                    }

                    $barrierRows = [];
                    foreach ($base['rows'] as $row) {
                        $pageNumber = (int) $row['page_number'];
                        $barrierRows[] = [
                            'page_number' => $pageNumber,
                            'write_order' => count($barrierRows) + 1,
                            'requires_release_fence' => in_array($pageNumber, $savepointPages, true),
                            'cache_admitted' => (bool) $row['cache_admitted'],
                            'checkpoint_source' => $row['checkpoint_source'],
                            'next_source' => $row['next_source'],
                        ];
                    }

