                            'source' => $source,
                            'receipt_digest' => $sourceDigest,
                            'receipt_digest_matches' => $digestMatches,
                            'expected_sha256' => hash('sha256', $expectedImage),
                            'actual_sha256' => hash('sha256', $actualImage),
                            'matches' => $digestMatches && $imageMatches,
                            'sequence' => $index + 1,
