                        'receipt_digest' => $receiptDigest,
                        'database_sha256' => $databaseSha,
                        'wal_sha256' => $walSha,
                        'journal_removed' => $journalRemoved,
                        'receipt_publishable' => $receiptPublishable,
                        'can_reopen_after_checkpoint' => $canReopen,
                        'read_rows' => $readRows,
