                            $durable[] = $path;
                        } else {
                            throw new \InvalidArgumentException("Unsupported SQLite WAL hot-journal savepoint checkpoint next180 operation: {$op}");
                        }

                        $applied++;
                    }

                    $published = self::normalizeFiles($working);
                    $verification = self::verifyRows($applyPlan, $published);

                    return [
                        'status' => 'wal-hot-journal-savepoint-checkpoint-current-source-next180',
                        'reason' => $operations === [] ? 'no_vfs_changes_needed_after_next177_verification' : 'atomic_vfs_apply_published_for_hot_journal_savepoint_checkpoint',
                        'database_path' => $applyPlan['database_path'],
                        'journal_path' => $applyPlan['journal_path'],
                        'wal_path' => $applyPlan['wal_path'],
                        'files' => $published,
                        'operation_names' => array_column($operations, 'op'),
                        'applied_operation_count' => $applied,
                        'staged_payload_paths' => array_values(array_unique($staged)),
                        'deleted_paths' => array_values(array_unique($deletedPaths)),
                        'synced_paths' => array_values(array_unique($syncedPaths)),
                        'durable_paths' => array_values(array_unique($durable)),
                        'written_bytes' => $writtenBytes,
                        'truncated_bytes' => $truncatedBytes,
                        'file_digest_before' => $originalDigest,
                        'file_digest_after' => self::fileDigest($published),
                        'published' => true,
                        'rolled_back' => false,
                        'verified_rows' => $verification['rows'],
                        'verified_roles' => array_column($verification['rows'], 'role'),
                        'verified_all_match' => $verification['all_match'],
                        'hot_journal_deleted' => !array_key_exists((string) $applyPlan['journal_path'], $published) || $published[(string) $applyPlan['journal_path']] === null,
                        'blocked_reasons' => [],
                        'dependencies' => self::dependencies($applyPlan),
                        'dependency_closure' => 'no new support component needed; reuses next177 VFS operation metadata and lane-local byte payloads for atomic publication',
                        'non_overlap' => 'next180 materializes next177 ordered resume operations into a caller-visible file map and idempotence verifier; it does not repeat next174 file-state admission, next177 operation planning, VFS writer/sync implementation, rollback-journal apply/commit, WAL byte truncation, or checkpoint transaction planning',
                    ];
                }

                /**
                 * @param array<string,mixed> $applyPlan
                 * @param array<string,string|null> $files
                 * @return array<string,mixed>
                 */
                private static function blocked(array $applyPlan, array $files, array $reasons): array
                {
                    return [
                        'status' => 'wal-hot-journal-savepoint-checkpoint-current-source-blocked-next180',
                        'reason' => 'atomic_vfs_apply_not_admitted',
                        'files' => $files,
                        'file_digest_before' => self::fileDigest(self::normalizeFiles($files)),
                        'file_digest_after' => self::fileDigest(self::normalizeFiles($files)),
                        'published' => false,
                        'rolled_back' => false,
                        'blocked_reasons' => $reasons,
                        'dependencies' => self::dependencies($applyPlan),
                        'dependency_closure' => 'no new support component needed; blocked before publishing file changes',
                        'non_overlap' => 'next180 refuses non-next177 input without repeating older WAL checkpoint planning surfaces',
                    ];
                }

                /**
                 * @param array<string,mixed> $applyPlan
                 * @return list<string>
                 */
                private static function dependencies(array $applyPlan): array
                {
                    return array_values(array_unique(array_merge($applyPlan['dependencies'] ?? [], [
                        'sqlite-wal-hot-journal-savepoint-checkpoint-current-source-next180',
                        'sqlite-vfs-atomic-file-map-publication',
                    ])));
                }

                /**
                 * @param array<string,mixed> $applyPlan
                 * @param array<string,string> $payloadBytes
                 */
                private static function payloadFor(array $applyPlan, array $payloadBytes, string $path): string
                {
                    if (!array_key_exists($path, $payloadBytes)) {
                        throw new \InvalidArgumentException("SQLite WAL hot-journal savepoint checkpoint next180 missing payload bytes for {$path}");
                    }
                    $payload = $payloadBytes[$path];
                    if (!is_string($payload)) {
                        throw new \InvalidArgumentException('SQLite WAL hot-journal savepoint checkpoint next180 payload bytes must be strings');
                    }
                    $metadata = $applyPlan['payloads'][$path] ?? null;
                    if (!is_array($metadata)) {
                        throw new \InvalidArgumentException("SQLite WAL hot-journal savepoint checkpoint next180 missing payload metadata for {$path}");
                    }
                    if ((int) ($metadata['bytes'] ?? -1) !== strlen($payload)) {
                        throw new \InvalidArgumentException("SQLite WAL hot-journal savepoint checkpoint next180 payload length mismatch for {$path}");
                    }
                    if (!hash_equals((string) ($metadata['sha256'] ?? ''), hash('sha256', $payload))) {
                        throw new \InvalidArgumentException("SQLite WAL hot-journal savepoint checkpoint next180 payload digest mismatch for {$path}");
                    }

                    return $payload;
                }

                /**
                 * @param array<string,mixed> $applyPlan
                 * @param array<string,string|null> $files
                 * @return array{rows:list<array<string,mixed>>,all_match:bool}
                 */
                private static function verifyRows(array $applyPlan, array $files): array
                {
                    $rows = [];
                    foreach ($applyPlan['payloads'] as $path => $metadata) {
                        $bytes = $files[$path] ?? null;
                        $rows[] = [
                            'path' => $path,
                            'role' => self::roleForPath($applyPlan, (string) $path),
                            'present' => $bytes !== null,
                            'actual_sha256' => $bytes === null ? null : hash('sha256', $bytes),
                            'expected_sha256' => $metadata['sha256'] ?? null,
                            'actual_length' => $bytes === null ? null : strlen($bytes),
                            'expected_length' => $metadata['bytes'] ?? null,
                            'matches' => $bytes !== null
                                && strlen($bytes) === (int) ($metadata['bytes'] ?? -1)
                                && hash_equals((string) ($metadata['sha256'] ?? ''), hash('sha256', $bytes)),
                        ];
                    }

                    $journalPath = (string) ($applyPlan['journal_path'] ?? '');
                    if ($journalPath !== '' && in_array('delete', array_column($applyPlan['operations'], 'op'), true)) {
                        $rows[] = [
                            'path' => $journalPath,
                            'role' => 'hot-journal',
                            'present' => array_key_exists($journalPath, $files) && $files[$journalPath] !== null,
                            'actual_sha256' => isset($files[$journalPath]) ? hash('sha256', (string) $files[$journalPath]) : null,
                            'expected_sha256' => null,
                            'actual_length' => isset($files[$journalPath]) ? strlen((string) $files[$journalPath]) : null,
                            'expected_length' => null,
                            'matches' => !array_key_exists($journalPath, $files) || $files[$journalPath] === null,
                        ];
                    }

                    return [
                        'rows' => $rows,
                        'all_match' => !in_array(false, array_column($rows, 'matches'), true),
                    ];
                }

                /**
                 * @param array<string,mixed> $applyPlan
                 */
                private static function roleForPath(array $applyPlan, string $path): string
                {
                    if ($path === ($applyPlan['database_path'] ?? null)) {
                        return 'database';
                    }
                    if ($path === ($applyPlan['wal_path'] ?? null)) {
                        return 'wal';
                    }
                    if ($path === ($applyPlan['journal_path'] ?? null)) {
                        return 'hot-journal';
                    }

                    return 'payload';
                }

                /**
                 * @param array<string,string|null> $files
                 * @return array<string,string|null>
                 */
                private static function normalizeFiles(array $files): array
                {
                    ksort($files, SORT_STRING);
                    foreach ($files as $path => $bytes) {
                        if (!is_string($path) || $path === '') {
                            throw new \InvalidArgumentException('SQLite WAL hot-journal savepoint checkpoint next180 file paths must be non-empty strings');
                        }
                        if ($bytes !== null && !is_string($bytes)) {
                            throw new \InvalidArgumentException('SQLite WAL hot-journal savepoint checkpoint next180 file bytes must be strings or null');
                        }
                    }

                    return $files;
                }

                /**
                 * @param array<string,string|null> $files
                 */
                private static function fileDigest(array $files): string
                {
                    $parts = [];
                    foreach (self::normalizeFiles($files) as $path => $bytes) {
                        $parts[] = $path . ':' . ($bytes === null ? 'deleted' : strlen($bytes) . ':' . hash('sha256', $bytes));
                    }

                    return hash('sha256', implode('|', $parts));
                }

                /**
                 * @param array<string,mixed> $applyPlan
                 */
                private static function assertApplyPlan(array $applyPlan): void
                {
                    foreach (['status', 'operations', 'payloads', 'dependencies'] as $key) {
                        if (!array_key_exists($key, $applyPlan)) {
                            throw new \InvalidArgumentException("SQLite WAL hot-journal savepoint checkpoint next180 missing {$key}");
                        }
                    }
                    if (!is_array($applyPlan['operations']) || !is_array($applyPlan['payloads']) || !is_array($applyPlan['dependencies'])) {
                        throw new \InvalidArgumentException('SQLite WAL hot-journal savepoint checkpoint next180 operations, payloads, and dependencies must be arrays');
                    }
                }
        };

        return $impl::apply($applyPlan, $files, $payloadBytes, $failAfterOperation);
    }

    public static function next181Plan(
        array $prepared,
        array $receipt,
        string $databaseBytes,
        ?string $journalBytes,
        string $walBytes,
        SQLiteWal $reopenedWal
    ): array
    {
        $impl = new class {
                /**
                 * @param array<string,mixed> $prepared
                 * @param array<string,mixed> $receipt
                 * @return array<string,mixed>
                 */
                public static function plan(
                    array $prepared,
                    array $receipt,
                    string $databaseBytes,
                    ?string $journalBytes,
                    string $walBytes,
                    SQLiteWal $reopenedWal
                ): array {
                    self::assertPrepared($prepared);
                    self::assertReceipt($receipt);

                    $expectedDatabase = self::preparedDurableString($prepared, ['base_plan', 'current_durable', 'database_bytes']);
                    $expectedWal = self::preparedDurableString($prepared, ['base_plan', 'next_durable', 'wal_bytes']);
                    $databaseHash = hash('sha256', $databaseBytes);
                    $walHash = hash('sha256', $walBytes);
                    $expectedDatabaseHash = hash('sha256', $expectedDatabase);
                    $expectedWalHash = hash('sha256', $expectedWal);
                    $databaseMatches = hash_equals($expectedDatabaseHash, $databaseHash);
                    $walMatches = hash_equals($expectedWalHash, $walHash);
                    $journalAbsent = $journalBytes === null;
                    $receiptPublishable = ($receipt['can_publish_receipt'] ?? false) === true;
                    $receiptDigestPresent = is_string($receipt['receipt_digest'] ?? null) && strlen((string) $receipt['receipt_digest']) === 64;
                    $walReopened = $reopenedWal->checksumsValidated
                        && $reopenedWal->header->checkpointSequence === SQLiteWal::parse($expectedWal, null, true)->header->checkpointSequence
                        && count($reopenedWal->frames) === count(SQLiteWal::parse($expectedWal, null, true)->frames);
                    $commitFrames = array_values(array_filter($reopenedWal->frames, static fn (SQLiteWalFrame $frame): bool => $frame->isCommitFrame()));
                    $lastCommit = $reopenedWal->lastCommitFrame();
                    $lastCommitPageCount = $lastCommit?->databasePageCountAfterCommit;
                    $sourceRows = [
                        [
                            'name' => 'database',
                            'expected_sha256' => $expectedDatabaseHash,
                            'actual_sha256' => $databaseHash,
                            'expected_length' => strlen($expectedDatabase),
                            'actual_length' => strlen($databaseBytes),
                            'matches' => $databaseMatches,
                        ],
                        [
                            'name' => 'journal',
                            'expected_sha256' => null,
                            'actual_sha256' => $journalBytes === null ? null : hash('sha256', $journalBytes),
                            'expected_length' => null,
                            'actual_length' => $journalBytes === null ? null : strlen($journalBytes),
                            'matches' => $journalAbsent,
                        ],
                        [
                            'name' => 'wal',
                            'expected_sha256' => $expectedWalHash,
                            'actual_sha256' => $walHash,
                            'expected_length' => strlen($expectedWal),
                            'actual_length' => strlen($walBytes),
                            'matches' => $walMatches,
                        ],
                    ];
                    $stale = array_values(array_filter($sourceRows, static fn (array $row): bool => !(bool) $row['matches']));
                    $ready = $receiptPublishable && $receiptDigestPresent && $databaseMatches && $journalAbsent && $walMatches && $walReopened && $lastCommit !== null;

                    $blocked = [];
                    if (!$receiptPublishable) {
                        $blocked[] = 'post_apply_receipt_not_publishable';
                    }
                    if (!$receiptDigestPresent) {
                        $blocked[] = 'post_apply_receipt_digest_missing';
                    }
                    foreach ($stale as $row) {
                        $blocked[] = 'reopened_' . $row['name'] . '_does_not_match_durable_payload';
                    }
                    if (!$walReopened) {
                        $blocked[] = 'reopened_wal_checksum_or_header_mismatch';
                    }
                    if ($lastCommit === null) {
                        $blocked[] = 'reopened_wal_has_no_commit_frame';
                    }

                    return [
                        'status' => $ready
                            ? 'wal-hot-journal-savepoint-checkpoint-current-source-next181'
                            : 'wal-hot-journal-savepoint-checkpoint-current-source-blocked-next181',
                        'reason' => $ready
                            ? 'reopened_files_and_wal_frames_confirm_post_apply_checkpoint_publication'
                            : 'reopened_files_or_wal_frames_block_checkpoint_publication',
                        'database_path' => (string) $prepared['database_path'],
                        'journal_path' => (string) $prepared['journal_path'],
                        'wal_path' => (string) $prepared['wal_path'],
                        'receipt_digest' => $receipt['receipt_digest'] ?? null,
                        'receipt_publishable' => $receiptPublishable,
                        'can_reopen_publish' => $ready,
                        'source_rows' => $sourceRows,
                        'matched_source_names' => array_values(array_column(array_filter($sourceRows, static fn (array $row): bool => (bool) $row['matches']), 'name')),
                        'stale_source_names' => array_column($stale, 'name'),
                        'blocked_reasons' => $blocked,
                        'wal_checkpoint_sequence' => $reopenedWal->header->checkpointSequence,
                        'wal_frame_count' => count($reopenedWal->frames),
                        'wal_commit_frame_count' => count($commitFrames),
                        'wal_last_commit_frame' => $lastCommit?->index,
                        'wal_last_commit_page_count' => $lastCommitPageCount,
                        'wal_checksums_validated' => $reopenedWal->checksumsValidated,
                        'reopen_digest' => hash('sha256', implode('|', [
                            (string) ($receipt['receipt_digest'] ?? ''),
                            $databaseHash,
                            $journalAbsent ? 'journal-absent' : hash('sha256', (string) $journalBytes),
                            $walHash,
                            (string) $reopenedWal->header->checkpointSequence,
                            (string) count($reopenedWal->frames),
                            (string) ($lastCommit?->index ?? 0),
                        ])),
                        'dependencies' => array_values(array_unique(array_merge(
                            is_array($receipt['dependencies'] ?? null) ? $receipt['dependencies'] : [],
                            [
                                'sqlite-wal-hot-journal-savepoint-checkpoint-current-source-next181',
                                'sqlite-wal-post-apply-reopen-validated',
                                'wordpress-import-hot-journal-checkpoint-reopen-wal-frames',
                            ]
                        ))),
                        'dependency_closure' => 'no new support component needed; reuses native WAL checksum parsing plus next178 post-apply receipt payloads',
                        'non_overlap' => 'adds reopen-time WAL checksum/frame admission after next178 receipt validation; does not repeat next175 VFS writes, next173 source-hash admission, or next178 post-apply file receipt matching',
                    ];
                }

                /**
                 * @param array<string,mixed> $prepared
                 */
                private static function assertPrepared(array $prepared): void
                {
                    foreach (['database_path', 'journal_path', 'wal_path', 'base_plan'] as $key) {
                        if (!array_key_exists($key, $prepared)) {
                            throw new \InvalidArgumentException("SQLite WAL hot-journal savepoint checkpoint current-source next181 missing prepared {$key}");
                        }
                    }
                }

                /**
                 * @param array<string,mixed> $receipt
                 */
                private static function assertReceipt(array $receipt): void
                {
                    foreach (['status', 'can_publish_receipt', 'receipt_digest'] as $key) {
                        if (!array_key_exists($key, $receipt)) {
                            throw new \InvalidArgumentException("SQLite WAL hot-journal savepoint checkpoint current-source next181 missing receipt {$key}");
                        }
                    }
                }

                /**
                 * @param array<string,mixed> $prepared
                 * @param list<string> $path
                 */
                private static function preparedDurableString(array $prepared, array $path): string
                {
                    $value = $prepared;
                    foreach ($path as $key) {
                        if (!is_array($value) || !array_key_exists($key, $value)) {
                            throw new \InvalidArgumentException('SQLite WAL hot-journal savepoint checkpoint current-source next181 prepared durable payload is missing');
                        }
                        $value = $value[$key];
                    }
                    if (!is_string($value)) {
                        throw new \InvalidArgumentException('SQLite WAL hot-journal savepoint checkpoint current-source next181 durable payload must be a string');
                    }

                    return $value;
                }
        };

        return $impl::plan($prepared, $receipt, $databaseBytes, $journalBytes, $walBytes, $reopenedWal);
    }

    public static function next182Plan(
        string $databasePath,
        string $databaseBytes,
        int $pageSize,
        string $savepoint,
        array $hotJournalPages,
        array $savepointBeforePages,
        SQLiteWal $currentWal,
        string $currentWalBytes,
        SQLiteWal $nextWal,
        string $nextWalBytes,
        array $readerCachePages,
        array $checkpointPages,
        array $readers,
        array $statements,
        int $currentSchemaCookie,
        int $nextSchemaCookie,
        ?array $expectedCurrentToken = null,
        ?array $expectedNextToken = null,
        ?string $expectedPublicationFingerprint = null,
        string $mode = 'restart',
        int $readerEndFrame = 0,
        int $currentSourceEpoch = 1,
    ): array
    {
        $impl = new class {
                /**
                 * @param array<int,string> $hotJournalPages
                 * @param array<int,string> $savepointBeforePages
                 * @param array<int,array{image:string,source_id?:string,epoch?:int,pinned?:bool,dirty?:bool,label?:string}> $readerCachePages
                 * @param list<int> $checkpointPages
                 * @param list<array{name:string,source_id?:string,epoch?:int,pinned?:bool,dirty?:bool,closed?:bool}> $readers
                 * @param list<array{name:string,source_id?:string,epoch?:int,schema_cookie?:int,root_pages?:list<int>,dirty?:bool,closed?:bool,sql?:string}> $statements
                 * @param array{id:string,epoch:int}|null $expectedCurrentToken
                 * @param array{id:string,epoch:int}|null $expectedNextToken
                 * @return array<string,mixed>
                 */
                public static function plan(
                    string $databasePath,
                    string $databaseBytes,
                    int $pageSize,
                    string $savepoint,
                    array $hotJournalPages,
                    array $savepointBeforePages,
                    SQLiteWal $currentWal,
                    string $currentWalBytes,
                    SQLiteWal $nextWal,
                    string $nextWalBytes,
                    array $readerCachePages,
                    array $checkpointPages,
                    array $readers,
                    array $statements,
                    int $currentSchemaCookie,
                    int $nextSchemaCookie,
                    ?array $expectedCurrentToken = null,
                    ?array $expectedNextToken = null,
                    ?string $expectedPublicationFingerprint = null,
                    string $mode = 'restart',
                    int $readerEndFrame = 0,
                    int $currentSourceEpoch = 1,
                ): array {
                    if ($statements === []) {
                        throw new \InvalidArgumentException('SQLite WAL hot-journal savepoint checkpoint current-source next182 requires prepared statements');
                    }
                    if ($currentSchemaCookie < 0 || $nextSchemaCookie < 0) {
                        throw new \InvalidArgumentException('SQLite WAL hot-journal savepoint checkpoint current-source next182 schema cookies must be non-negative');
                    }

                    $base = SQLiteWalHotJournalSavepointCheckpointCurrentSourceNextPlan::next167Plan(
                        $databasePath,
                        $databaseBytes,
                        $pageSize,
                        $savepoint,
                        $hotJournalPages,
                        $savepointBeforePages,
                        $currentWal,
                        $currentWalBytes,
                        $nextWal,
                        $nextWalBytes,
                        $readerCachePages,
                        $checkpointPages,
                        $readers,
                        $expectedCurrentToken,
                        $expectedNextToken,
                        $expectedPublicationFingerprint,
                        $mode,
                        $readerEndFrame,
                        $currentSourceEpoch
                    );

                    $currentToken = $base['current_source_token'];
                    $nextToken = $base['next_source_token'];
                    self::assertToken($currentToken, 'current');
                    self::assertToken($nextToken, 'next');

                    $changedPages = array_values(array_unique(array_merge(
                        array_map('intval', $base['base_plan']['hot_journal_page_numbers'] ?? []),
                        array_map('intval', $base['base_plan']['savepoint_rollback_page_numbers'] ?? [])
                    )));
                    sort($changedPages, SORT_NUMERIC);

                    $statementRows = [];
                    $admitted = [];
                    $reprepare = [];
                    foreach ($statements as $statement) {
                        $row = self::statementAdmission(
                            $statement,
                            $currentToken,
                            $nextToken,
                            $currentSchemaCookie,
                            $nextSchemaCookie,
                            $changedPages
                        );
                        $statementRows[] = $row;
                        if ($row['admitted']) {
                            $admitted[] = $row['name'];
                        } else {
                            $reprepare[] = $row['name'];
                        }
                    }

                    $guardRows = [
                        [
                            'name' => 'publication_guard',
                            'matched' => $base['status'] === 'wal-hot-journal-savepoint-checkpoint-current-source-next167',
                            'reason' => 'base_current_source_publication_guard_admitted_checkpoint',
                        ],
                        [
                            'name' => 'statement_mix',
                            'matched' => $admitted !== [] && $reprepare !== [],
                            'reason' => 'statement_cache_has_current_admissions_and_reprepare_closures',
                        ],
                        [
                            'name' => 'schema_cookie_boundary',
                            'matched' => $nextSchemaCookie >= $currentSchemaCookie,
                            'reason' => 'schema_cookie_not_moved_backwards_across_checkpoint_publication',
                        ],
                    ];
                    $mismatches = array_values(array_filter($guardRows, static fn (array $row): bool => !$row['matched']));
                    $status = $mismatches === []
                        ? 'wal-hot-journal-savepoint-checkpoint-current-source-next182'
                        : 'wal-hot-journal-savepoint-checkpoint-current-source-blocked-next182';

                    return [
                        'status' => $status,
                        'reason' => $status === 'wal-hot-journal-savepoint-checkpoint-current-source-next182'
                            ? 'prepared_statement_cache_rebased_after_hot_journal_savepoint_checkpoint_current_source'
                            : 'prepared_statement_cache_rebase_blocked_after_hot_journal_savepoint_checkpoint',
                        'database_path' => $databasePath,
                        'journal_path' => $base['journal_path'],
                        'wal_path' => $base['wal_path'],
                        'page_size' => $pageSize,
                        'savepoint' => $savepoint,
                        'mode' => $base['mode'],
                        'reader_end_frame' => $base['reader_end_frame'],
                        'base_status' => $base['status'],
                        'base_reason' => $base['reason'],
                        'current_source_token' => $currentToken,
                        'next_source_token' => $nextToken,
                        'publication_fingerprint' => $base['publication_fingerprint'],
                        'current_schema_cookie' => $currentSchemaCookie,
                        'next_schema_cookie' => $nextSchemaCookie,
                        'schema_cookie_changed' => $nextSchemaCookie !== $currentSchemaCookie,
                        'changed_page_numbers' => $changedPages,
                        'statement_rows' => $statementRows,
                        'admitted_statement_names' => $admitted,
                        'reprepare_statement_names' => $reprepare,
                        'statement_reprepare_count' => count($reprepare),
                        'statement_reprepare_reasons' => array_column($statementRows, 'reason'),
                        'statement_transitions' => array_column($statementRows, 'transition'),
                        'guard_rows' => $guardRows,
                        'guard_names' => array_column($guardRows, 'name'),
                        'guard_matches' => array_column($guardRows, 'matched'),
                        'stale_guard_names' => array_column($mismatches, 'name'),
                        'operation_names' => array_values(array_merge(
                            $base['operation_names'],
                            array_map(
                                static fn (array $row): string => $row['admitted']
                                    ? 'admit_statement_on_checkpoint_current_source_next182'
                                    : 'reprepare_statement_for_checkpoint_current_source_next182',
                                $statementRows
                            ),
                            ['publish_statement_cache_current_source_next182']
                        )),
                        'source_digest' => hash('sha256', $base['publication_fingerprint'] . '|' . implode('|', array_column($statementRows, 'transition'))),
                        'base_plan' => $base,
                        'dependencies' => array_values(array_unique(array_merge($base['dependencies'], [
                            'sqlite-wal-hot-journal-savepoint-checkpoint-current-source-next182',
                            'sqlite-wal-current-source-statement-cache-rebase',
                        ]))),
                        'dependency_closure' => 'no new support component needed; composes accepted WAL/hot-journal/savepoint checkpoint publication guards with prepared statement cache admission metadata',
                        'non_overlap' => 'extends accepted next167 current-source publication by deciding prepared statement cache admission after schema-cookie/root-page checks; it does not repeat VFS byte application, pinned-reader preservation, or next167 publication fingerprints',
                    ];
                }

                /**
                 * @param array{name:string,source_id?:string,epoch?:int,schema_cookie?:int,root_pages?:list<int>,dirty?:bool,closed?:bool,sql?:string} $statement
                 * @param array{id:string,epoch:int} $currentToken
                 * @param array{id:string,epoch:int} $nextToken
                 * @param list<int> $changedPages
                 * @return array{name:string,admitted:bool,reason:string,source_id:string,epoch:int,schema_cookie:int,root_pages:list<int>,dirty:bool,closed:bool,sql:string,transition:string}
                 */
                private static function statementAdmission(
                    array $statement,
                    array $currentToken,
                    array $nextToken,
                    int $currentSchemaCookie,
