        array $readers,
        int $currentSchemaCookie,
        int $nextSchemaCookie,
        ?array $expectedCurrentToken = null,
        ?array $expectedNextToken = null,
        string $mode = 'restart',
        int $readerEndFrame = 0,
        int $currentSourceEpoch = 1,
    ): array
    {
        $impl = new class {
                /**
                 * @param list<array{name:string,source_id?:string,epoch?:int,schema_cookie?:int,root_pages?:list<int>,dirty?:bool,closed?:bool,sql?:string,observed_checkpoint_sequence?:int,observed_salt?:list<int>,cursor_page?:int}> $statements
                 * @param list<array{name:string,source_id?:string,epoch?:int,observed_checkpoint_sequence?:int,observed_salt?:list<int>,pinned?:bool,dirty?:bool,closed?:bool}> $readers
                 * @param array{id:string,epoch:int}|null $expectedCurrentToken
                 * @param array{id:string,epoch:int}|null $expectedNextToken
                 * @return array<string,mixed>
                 */
                public static function plan(
                    string $databasePath,
                    string $databaseBytes,
                    int $pageSize,
                    string $savepoint,
                    array $hotJournalPages,
                    array $savepointBeforePages,
                    SQLiteWal $currentWal,
                    string $currentWalBytes,
                    SQLiteWal $nextWal,
                    string $nextWalBytes,
                    array $readerCachePages,
                    array $checkpointPages,
                    array $baseReaders,
                    array $statements,
                    array $readers,
                    int $currentSchemaCookie,
                    int $nextSchemaCookie,
                    ?array $expectedCurrentToken = null,
                    ?array $expectedNextToken = null,
                    string $mode = 'restart',
                    int $readerEndFrame = 0,
                    int $currentSourceEpoch = 1,
                ): array {
                    if ($statements === []) {
                        throw new \InvalidArgumentException('SQLite WAL hot-journal savepoint checkpoint current-source next185 requires prepared statements');
                    }
                    if ($readers === []) {
                        throw new \InvalidArgumentException('SQLite WAL hot-journal savepoint checkpoint current-source next185 requires reader rows');
                    }

                    $base = SQLiteWalHotJournalSavepointCheckpointCurrentSourceNextPlan::next182Plan(
                        $databasePath,
                        $databaseBytes,
                        $pageSize,
                        $savepoint,
                        $hotJournalPages,
                        $savepointBeforePages,
                        $currentWal,
                        $currentWalBytes,
                        $nextWal,
                        $nextWalBytes,
                        $readerCachePages,
                        $checkpointPages,
                        $baseReaders,
                        self::stripGenerationFields($statements),
                        $currentSchemaCookie,
                        $nextSchemaCookie,
                        $expectedCurrentToken,
                        $expectedNextToken,
                        null,
                        $mode,
                        $readerEndFrame,
                        $currentSourceEpoch
                    );

                    $currentToken = $base['current_source_token'];
                    $nextToken = $base['next_source_token'];
                    $currentSequence = $currentWal->header->checkpointSequence;
                    $nextSequence = $nextWal->header->checkpointSequence;
                    $currentSalt = [$currentWal->header->salt1, $currentWal->header->salt2];
                    $nextSalt = [$nextWal->header->salt1, $nextWal->header->salt2];

                    $statementRows = [];
                    $admittedStatements = [];
                    $reprepareStatements = [];
                    foreach ($base['statement_rows'] as $offset => $row) {
                        $generation = self::generationDecision(
                            $statements[$offset],
                            $row,
                            $currentSequence,
                            $nextSequence,
                            $currentSalt,
                            $nextSalt
                        );
                        $statementRows[] = $generation;
                        if ($generation['admitted']) {
                            $admittedStatements[] = $generation['name'];
                        } else {
                            $reprepareStatements[] = $generation['name'];
                        }
                    }

                    $readerRows = [];
                    $admittedReaders = [];
                    $reopenReaders = [];
                    foreach ($readers as $reader) {
                        $row = self::readerDecision($reader, $currentToken, $nextToken, $currentSequence, $nextSequence, $currentSalt, $nextSalt);
                        $readerRows[] = $row;
                        if ($row['admitted']) {
                            $admittedReaders[] = $row['name'];
                        } else {
                            $reopenReaders[] = $row['name'];
                        }
                    }

                    $guardRows = [
                        [
                            'name' => 'base_statement_current_source',
                            'matched' => $base['status'] === 'wal-hot-journal-savepoint-checkpoint-current-source-next182',
                            'reason' => 'base next182 statement token/schema/root admission must pass before generation admission',
                        ],
                        [
                            'name' => 'statement_generation_mix',
                            'matched' => $admittedStatements !== [] && $reprepareStatements !== [],
                            'reason' => 'checkpoint generation guard must admit current statements and reject stale generation statements',
                        ],
                        [
                            'name' => 'reader_generation_mix',
                            'matched' => $admittedReaders !== [] && $reopenReaders !== [],
                            'reason' => 'checkpoint generation guard must keep current readers and force stale readers to reopen',
                        ],
                    ];
                    $mismatches = array_values(array_filter($guardRows, static fn (array $row): bool => !(bool) $row['matched']));
                    $status = $mismatches === []
                        ? 'wal-hot-journal-savepoint-checkpoint-current-source-next185'
                        : 'wal-hot-journal-savepoint-checkpoint-current-source-blocked-next185';

                    return [
                        'status' => $status,
                        'reason' => $status === 'wal-hot-journal-savepoint-checkpoint-current-source-next185'
                            ? 'prepared_statements_and_readers_admitted_by_checkpoint_generation_after_hot_journal_savepoint'
                            : 'checkpoint_generation_admission_blocked_after_hot_journal_savepoint',
                        'database_path' => $databasePath,
                        'journal_path' => $base['journal_path'],
                        'wal_path' => $base['wal_path'],
                        'page_size' => $pageSize,
                        'savepoint' => $savepoint,
                        'mode' => $base['mode'],
                        'reader_end_frame' => $base['reader_end_frame'],
                        'base_status' => $base['status'],
                        'current_source_token' => $currentToken,
                        'next_source_token' => $nextToken,
                        'current_checkpoint_sequence' => $currentSequence,
                        'next_checkpoint_sequence' => $nextSequence,
                        'current_wal_salt' => $currentSalt,
                        'next_wal_salt' => $nextSalt,
                        'statement_rows' => $statementRows,
                        'reader_rows' => $readerRows,
                        'admitted_statement_names' => $admittedStatements,
                        'reprepare_statement_names' => $reprepareStatements,
                        'admitted_reader_names' => $admittedReaders,
                        'reopen_reader_names' => $reopenReaders,
                        'statement_generation_reasons' => array_column($statementRows, 'generation_reason'),
                        'reader_generation_reasons' => array_column($readerRows, 'generation_reason'),
                        'guard_rows' => $guardRows,
                        'guard_names' => array_column($guardRows, 'name'),
                        'guard_matches' => array_column($guardRows, 'matched'),
                        'stale_guard_names' => array_column($mismatches, 'name'),
                        'operation_names' => array_values(array_merge(
                            $base['operation_names'],
                            array_map(
                                static fn (array $row): string => $row['admitted']
                                    ? 'admit_checkpoint_generation_current_source_next185'
                                    : 'reprepare_checkpoint_generation_current_source_next185',
                                $statementRows
                            ),
                            array_map(
                                static fn (array $row): string => $row['admitted']
                                    ? 'retain_reader_checkpoint_generation_next185'
                                    : 'reopen_reader_checkpoint_generation_next185',
                                $readerRows
                            ),
                            ['publish_checkpoint_generation_current_source_next185']
                        )),
                        'generation_digest' => hash('sha256', implode('|', array_merge(
                            [$base['source_digest'], (string) $currentSequence, implode(',', $currentSalt), (string) $nextSequence, implode(',', $nextSalt)],
                            array_column($statementRows, 'generation_transition'),
                            array_column($readerRows, 'generation_transition')
                        ))),
                        'base_plan' => $base,
                        'dependencies' => array_values(array_unique(array_merge($base['dependencies'], [
                            'sqlite-wal-hot-journal-savepoint-checkpoint-current-source-next185',
                            'sqlite-wal-checkpoint-generation-prepared-statement-admission',
                        ]))),
                        'dependency_closure' => 'no new support component needed; composes native WAL header salt/checkpoint parsing with existing hot-journal savepoint current-source statement admission',
                        'non_overlap' => 'adds checkpoint-sequence and salt generation admission for prepared statements/readers after next182 token/schema/root checks; it does not repeat WAL byte truncation, VFS apply, hot-journal rollback application, checkpoint transaction planning, or next182 statement root-page admission',
                    ];
                }

                /**
                 * @param list<array<string,mixed>> $statements
                 * @return list<array<string,mixed>>
                 */
                private static function stripGenerationFields(array $statements): array
                {
                    return array_map(static function (array $statement): array {
                        unset($statement['observed_checkpoint_sequence'], $statement['observed_salt'], $statement['cursor_page']);

                        return $statement;
                    }, $statements);
                }

                /**
                 * @param array<string,mixed> $statement
                 * @param array<string,mixed> $baseRow
                 * @param list<int> $currentSalt
                 * @param list<int> $nextSalt
                 * @return array<string,mixed>
                 */
                private static function generationDecision(array $statement, array $baseRow, int $currentSequence, int $nextSequence, array $currentSalt, array $nextSalt): array
                {
                    $observedSequence = $statement['observed_checkpoint_sequence'] ?? null;
                    if (!is_int($observedSequence) || $observedSequence < 0) {
                        throw new \InvalidArgumentException('SQLite WAL hot-journal savepoint checkpoint current-source next185 statement checkpoint sequence must be non-negative');
                    }
                    $observedSalt = self::observedSalt($statement, 'statement');
                    $cursorPage = $statement['cursor_page'] ?? null;
                    if ($cursorPage !== null && (!is_int($cursorPage) || $cursorPage < 1)) {
                        throw new \InvalidArgumentException('SQLite WAL hot-journal savepoint checkpoint current-source next185 cursor page must be a one-based integer');
                    }

                    $admitted = (bool) $baseRow['admitted'];
                    $reason = $admitted ? 'statement_checkpoint_generation_matches_current_wal' : (string) $baseRow['reason'];
                    if ($admitted && $observedSequence === $nextSequence && $observedSalt === $nextSalt) {
                        $admitted = false;
                        $reason = 'statement_observed_next_wal_generation_before_reprepare';
                    } elseif ($admitted && $observedSequence !== $currentSequence) {
                        $admitted = false;
                        $reason = 'statement_checkpoint_sequence_predates_current_wal_generation';
                    } elseif ($admitted && $observedSalt !== $currentSalt) {
                        $admitted = false;
                        $reason = 'statement_wal_salt_predates_current_checkpoint_generation';
                    }

                    return array_merge($baseRow, [
                        'admitted' => $admitted,
                        'generation_reason' => $reason,
                        'observed_checkpoint_sequence' => $observedSequence,
                        'observed_salt' => $observedSalt,
                        'cursor_page' => $cursorPage,
                        'generation_transition' => $baseRow['name'] . '@' . $observedSequence . '#' . implode(',', $observedSalt) . '>' . ($admitted ? 'retain-current-generation' : 'reprepare-generation'),
                    ]);
                }

                /**
                 * @param array<string,mixed> $reader
                 * @param array{id:string,epoch:int} $currentToken
                 * @param array{id:string,epoch:int} $nextToken
                 * @param list<int> $currentSalt
                 * @param list<int> $nextSalt
                 * @return array<string,mixed>
                 */
                private static function readerDecision(array $reader, array $currentToken, array $nextToken, int $currentSequence, int $nextSequence, array $currentSalt, array $nextSalt): array
                {
                    $name = trim((string) ($reader['name'] ?? ''));
                    $sourceId = (string) ($reader['source_id'] ?? '');
                    $epoch = $reader['epoch'] ?? 0;
                    $observedSequence = $reader['observed_checkpoint_sequence'] ?? null;
                    if ($name === '' || $sourceId === '' || !is_int($epoch) || $epoch < 1 || !is_int($observedSequence) || $observedSequence < 0) {
                        throw new \InvalidArgumentException('SQLite WAL hot-journal savepoint checkpoint current-source next185 reader name, source, epoch, and checkpoint sequence are required');
                    }
                    $observedSalt = self::observedSalt($reader, 'reader');
                    $dirty = (bool) ($reader['dirty'] ?? false);
                    $closed = (bool) ($reader['closed'] ?? false);
                    $pinned = (bool) ($reader['pinned'] ?? false);
                    $admitted = true;
                    $reason = 'reader_checkpoint_generation_matches_current_wal';

                    if ($closed) {
                        $admitted = false;
                        $reason = 'reader_closed_before_checkpoint_generation_publish';
                    } elseif ($dirty) {
                        $admitted = false;
                        $reason = 'reader_dirty_after_failed_savepoint';
                    } elseif ($sourceId === $nextToken['id'] && $epoch === $nextToken['epoch']) {
                        $admitted = false;
                        $reason = 'reader_already_reopened_on_next_wal_generation';
                    } elseif ($sourceId !== $currentToken['id']) {
                        $admitted = false;
                        $reason = 'reader_source_token_predates_checkpoint_current_source';
                    } elseif ($epoch !== $currentToken['epoch']) {
                        $admitted = false;
                        $reason = 'reader_epoch_predates_checkpoint_current_source';
                    } elseif ($observedSequence === $nextSequence && $observedSalt === $nextSalt) {
                        $admitted = false;
                        $reason = 'reader_observed_next_wal_generation_before_reopen';
                    } elseif ($observedSequence !== $currentSequence) {
                        $admitted = false;
                        $reason = 'reader_checkpoint_sequence_predates_current_wal_generation';
                    } elseif ($observedSalt !== $currentSalt) {
                        $admitted = false;
                        $reason = 'reader_wal_salt_predates_current_checkpoint_generation';
                    }

                    return [
                        'name' => $name,
                        'admitted' => $admitted,
                        'generation_reason' => $reason,
                        'source_id' => $sourceId,
                        'epoch' => $epoch,
                        'observed_checkpoint_sequence' => $observedSequence,
                        'observed_salt' => $observedSalt,
                        'pinned' => $pinned,
                        'dirty' => $dirty,
                        'closed' => $closed,
                        'generation_transition' => $name . '@' . $observedSequence . '#' . implode(',', $observedSalt) . '>' . ($admitted ? 'retain-reader-generation' : 'reopen-reader-generation'),
                    ];
                }

                /**
                 * @param array<string,mixed> $row
                 * @return list<int>
                 */
                private static function observedSalt(array $row, string $label): array
                {
                    $salt = $row['observed_salt'] ?? null;
                    if (!is_array($salt) || count($salt) !== 2) {
                        throw new \InvalidArgumentException("SQLite WAL hot-journal savepoint checkpoint current-source next185 {$label} salt must contain two integers");
                    }
                    $salt = array_values($salt);
                    foreach ($salt as $value) {
                        if (!is_int($value) || $value < 0) {
                            throw new \InvalidArgumentException("SQLite WAL hot-journal savepoint checkpoint current-source next185 {$label} salt must contain two non-negative integers");
                        }
                    }

                    return $salt;
                }
        };

        return $impl::plan($databasePath, $databaseBytes, $pageSize, $savepoint, $hotJournalPages, $savepointBeforePages, $currentWal, $currentWalBytes, $nextWal, $nextWalBytes, $readerCachePages, $checkpointPages, $baseReaders, $statements, $readers, $currentSchemaCookie, $nextSchemaCookie, $expectedCurrentToken, $expectedNextToken, $mode, $readerEndFrame, $currentSourceEpoch);
    }

    public static function next186VerifyWalSource(
        array $applyResult,
        array $files,
        int $expectedCheckpointSequence,
        int $expectedPageSize,
        array $readerCacheTokens = [],
        int $readerEpoch = 1
    ): array
    {
        $impl = new class {
                /**
                 * @param array<string,mixed> $applyResult
                 * @param array<string,string|null> $files
                 * @param list<string> $readerCacheTokens
                 * @return array<string,mixed>
                 */
                public static function verifyWalSource(
                    array $applyResult,
                    array $files,
                    int $expectedCheckpointSequence,
                    int $expectedPageSize,
                    array $readerCacheTokens = [],
                    int $readerEpoch = 1
                ): array {
                    if ($expectedCheckpointSequence < 0) {
                        throw new \InvalidArgumentException('SQLite WAL current-source next186 checkpoint sequence must be non-negative');
                    }
                    if ($expectedPageSize < 512 || ($expectedPageSize & ($expectedPageSize - 1)) !== 0) {
                        throw new \InvalidArgumentException('SQLite WAL current-source next186 page size must be a power of two at least 512');
                    }

                    $base = SQLiteWalHotJournalSavepointCheckpointCurrentSourceNextPlan::next183Verify(
                        $applyResult,
                        $files,
                        [],
                        $readerEpoch
                    );
                    $normalized = self::normalizeFiles($files);
                    $walPath = (string) ($applyResult['wal_path'] ?? '');
                    $walBytes = $walPath === '' ? null : ($normalized[$walPath] ?? null);
                    $blocked = [];
                    $wal = null;
                    $walHeader = null;
                    $committedFrames = [];
                    $walDigest = null;

                    if (($base['status'] ?? '') !== 'wal-hot-journal-savepoint-checkpoint-current-source-next183') {
                        $blocked[] = 'next183_current_source_admission_required';
                    }
                    if ($walPath === '' || $walBytes === null) {
                        $blocked[] = 'retained_wal_payload_missing_after_hot_journal_apply';
                    } else {
                        $walDigest = hash('sha256', $walBytes);
                        try {
                            $wal = SQLiteWal::parse($walBytes, $expectedPageSize, true);
                            $walHeader = $wal->header->toArray();
                            foreach ($wal->frames as $frame) {
                                if ($frame->isCommitFrame()) {
                                    $committedFrames[] = [
                                        'frame_index' => $frame->index,
                                        'page_number' => $frame->pageNumber,
                                        'commit_page_count' => $frame->databasePageCountAfterCommit,
                                    ];
                                }
                            }
                            if ($wal->header->pageSize !== $expectedPageSize) {
                                $blocked[] = 'wal_page_size_drift_after_hot_journal_apply';
                            }
                            if ($wal->header->checkpointSequence !== $expectedCheckpointSequence) {
                                $blocked[] = 'wal_checkpoint_sequence_drift_after_hot_journal_apply';
                            }
                            if ($committedFrames === []) {
                                $blocked[] = 'retained_wal_has_no_commit_frame_for_reader_source';
                            }
                        } catch (\InvalidArgumentException $exception) {
                            $blocked[] = 'retained_wal_checksum_or_header_invalid_after_hot_journal_apply';
                            $walHeader = ['error' => $exception->getMessage()];
                        }
                    }

                    $token = self::sourceToken($base, $walDigest, $expectedCheckpointSequence, $expectedPageSize, $readerEpoch);
                    $staleTokens = array_values(array_filter(
                        $readerCacheTokens,
                        static fn (string $candidate): bool => $candidate !== $token
                    ));
                    $retainedTokens = array_values(array_filter(
                        $readerCacheTokens,
                        static fn (string $candidate): bool => $candidate === $token
                    ));
                    if ($staleTokens !== []) {
                        $blocked[] = 'wal_source_reader_cache_token_predates_verified_header';
                    }

                    if ($blocked !== []) {
                        return [
                            'status' => 'wal-hot-journal-savepoint-checkpoint-current-source-blocked-next186',
                            'reason' => 'wal_header_source_not_admitted_after_hot_journal_apply',
                            'base_status' => $base['status'] ?? null,
                            'database_path' => $applyResult['database_path'] ?? null,
                            'journal_path' => $applyResult['journal_path'] ?? null,
                            'wal_path' => $walPath,
                            'reader_epoch' => $readerEpoch,
                            'reader_source_token' => $token,
                            'reader_cache_tokens' => $readerCacheTokens,
                            'retained_reader_cache_tokens' => $retainedTokens,
                            'stale_reader_cache_tokens' => $staleTokens,
                            'requires_reader_reopen' => $staleTokens !== [],
                            'wal_digest' => $walDigest,
                            'wal_header' => $walHeader,
                            'committed_frames' => $committedFrames,
                            'committed_frame_count' => count($committedFrames),
                            'expected_checkpoint_sequence' => $expectedCheckpointSequence,
                            'expected_page_size' => $expectedPageSize,
                            'blocked_reasons' => array_values(array_unique($blocked)),
                            'dependencies' => self::dependencies($base),
                            'dependency_closure' => 'no new support component needed; reuses the accepted WAL parser/checksum validator and next183 current-source admission',
                            'non_overlap' => 'next186 validates retained WAL header/checkpoint source metadata after hot-journal savepoint checkpoint apply; it does not repeat next183 reader-token file-map admission, next180 publication, checkpoint transaction planning, WAL byte truncation, or rollback-journal apply',
                        ];
                    }

                    return [
                        'status' => 'wal-hot-journal-savepoint-checkpoint-current-source-next186',
                        'reason' => 'retained_wal_header_source_verified_after_hot_journal_apply',
                        'base_status' => $base['status'],
                        'database_path' => $applyResult['database_path'],
                        'journal_path' => $applyResult['journal_path'],
                        'wal_path' => $walPath,
                        'reader_epoch' => $readerEpoch,
                        'reader_source_token' => $token,
                        'reader_cache_tokens' => $readerCacheTokens,
                        'retained_reader_cache_tokens' => $retainedTokens,
                        'stale_reader_cache_tokens' => [],
                        'requires_reader_reopen' => false,
                        'wal_digest' => $walDigest,
                        'wal_header' => $walHeader,
                        'wal_byte_order' => $wal?->header->byteOrder(),
                        'wal_checksums_validated' => $wal?->checksumsValidated,
                        'wal_frame_count' => count($wal?->frames ?? []),
                        'committed_frames' => $committedFrames,
                        'committed_frame_count' => count($committedFrames),
                        'last_commit_page_count' => $committedFrames[array_key_last($committedFrames)]['commit_page_count'] ?? null,
                        'expected_checkpoint_sequence' => $expectedCheckpointSequence,
                        'expected_page_size' => $expectedPageSize,
                        'base_reader_source_token' => $base['reader_source_token'],
                        'base_verified_paths' => $base['verified_paths'],
                        'blocked_reasons' => [],
                        'dependencies' => self::dependencies($base),
                        'dependency_closure' => 'no new support component needed; reuses the accepted WAL parser/checksum validator and next183 current-source admission',
                        'non_overlap' => 'next186 validates retained WAL header/checkpoint source metadata after hot-journal savepoint checkpoint apply; it does not repeat next183 reader-token file-map admission, next180 publication, checkpoint transaction planning, WAL byte truncation, or rollback-journal apply',
                    ];
                }

                /**
                 * @param array<string,mixed> $base
                 */
                private static function sourceToken(array $base, ?string $walDigest, int $checkpointSequence, int $pageSize, int $epoch): string
                {
                    return 'wal-hot-journal-savepoint-checkpoint-next186:wal-source:' . substr(hash('sha256', implode('|', [
                        (string) ($base['reader_source_token'] ?? ''),
                        (string) $walDigest,
                        (string) $checkpointSequence,
                        (string) $pageSize,
                        (string) $epoch,
                    ])), 0, 32);
                }

                /**
                 * @param array<string,mixed> $base
                 * @return list<string>
                 */
                private static function dependencies(array $base): array
                {
                    return array_values(array_unique(array_merge($base['dependencies'] ?? [], [
                        'sqlite-wal-hot-journal-savepoint-checkpoint-current-source-next186',
                        'sqlite-retained-wal-header-current-source-admission',
                    ])));
                }

                /**
                 * @param array<string,string|null> $files
                 * @return array<string,string|null>
                 */
                private static function normalizeFiles(array $files): array
                {
                    ksort($files, SORT_STRING);
                    foreach ($files as $path => $bytes) {
                        if (!is_string($path) || $path === '') {
                            throw new \InvalidArgumentException('SQLite WAL current-source next186 file paths must be non-empty strings');
                        }
                        if ($bytes !== null && !is_string($bytes)) {
                            throw new \InvalidArgumentException('SQLite WAL current-source next186 file bytes must be strings or null');
                        }
                    }

                    return $files;
                }
        };

        return $impl::verifyWalSource($applyResult, $files, $expectedCheckpointSequence, $expectedPageSize, $readerCacheTokens, $readerEpoch);
    }

    public static function next187Plan(array $postApply, array $reopen, array $readerTokens, bool $hotJournalObserved = true): array
    {
        $impl = new class {
                /**
                 * @param array<string,mixed> $postApply
                 * @param array<string,mixed> $reopen
                 * @param list<string> $readerTokens
                 * @return array<string,mixed>
                 */
                public static function plan(array $postApply, array $reopen, array $readerTokens, bool $hotJournalObserved = true): array
                {
                    self::assertInput($postApply, $reopen, $readerTokens);

                    $postApplyReady = ($postApply['status'] ?? '') === 'wal-hot-journal-savepoint-checkpoint-current-source-next183'
                        && ($postApply['verified_all_match'] ?? false) === true
                        && ($postApply['directory_sync_verified'] ?? false) === true
                        && ($postApply['hot_journal_deleted'] ?? false) === true;
                    $reopenReady = ($reopen['status'] ?? '') === 'wal-hot-journal-savepoint-checkpoint-current-source-next184'
                        && ($reopen['can_reuse_reader_marks'] ?? false) === true
                        && ($reopen['all_reader_pages_separated'] ?? false) === true
                        && ($reopen['salt_pair_rotated'] ?? false) === true
                        && ($reopen['checkpoint_sequence_advanced'] ?? false) === true;

                    $postToken = (string) $postApply['reader_source_token'];
                    $transitionToken = 'wal-hot-journal-savepoint-checkpoint-next187:retry:' . substr(hash('sha256', implode('|', [
                        $postToken,
                        (string) $reopen['source_transition_digest'],
                        (string) $postApply['file_digest'],
                        (string) $reopen['next_wal_sha256'],
                        implode(',', array_map('strval', $reopen['reader_page_numbers'])),
                    ])), 0, 32);

                    $tokenRows = [];
                    foreach ($readerTokens as $token) {
                        $classification = 'stale';
                        if ($token === $transitionToken) {
                            $classification = 'retry-current';
                        } elseif ($token === $postToken) {
                            $classification = 'post-apply-current';
                        }
                        $tokenRows[] = [
                            'token' => $token,
                            'classification' => $classification,
                            'retained_for_retry' => $classification === 'retry-current',
                            'requires_reopen' => $classification !== 'retry-current',
                        ];
                    }

                    $staleTokens = array_values(array_map(
                        static fn (array $row): string => $row['token'],
                        array_filter($tokenRows, static fn (array $row): bool => $row['classification'] !== 'retry-current')
                    ));
                    $retainedTokens = array_values(array_map(
                        static fn (array $row): string => $row['token'],
                        array_filter($tokenRows, static fn (array $row): bool => $row['classification'] === 'retry-current')
                    ));
                    $postApplyTokenRetired = !in_array($postToken, $readerTokens, true);

                    $blocked = [];
                    if (!$hotJournalObserved) {
                        $blocked[] = 'hot_journal_recovery_observation_required';
                    }
                    if (!$postApplyReady) {
                        $blocked[] = 'next183_post_apply_current_source_not_verified';
                    }
                    if (!$reopenReady) {
                        $blocked[] = 'next184_reopened_wal_source_not_publishable';
                    }
                    if (!$postApplyTokenRetired) {
                        $blocked[] = 'post_apply_reader_token_must_be_retired_before_retry_wal_reuse';
                    }
                    if ($staleTokens !== []) {
                        $blocked[] = 'stale_reader_tokens_require_reopen_before_retry_wal_reuse';
                    }
                    if ($retainedTokens !== [] && !in_array($transitionToken, $retainedTokens, true)) {
                        $blocked[] = 'unexpected_retry_reader_token_retained';
                    }
                    if (count($retainedTokens) > 1) {
                        $blocked[] = 'duplicate_retry_reader_tokens';
                    }

                    $ready = $blocked === [];

                    return [
                        'status' => $ready
                            ? 'wal-hot-journal-savepoint-checkpoint-current-source-next187'
                            : 'wal-hot-journal-savepoint-checkpoint-current-source-blocked-next187',
                        'reason' => $ready
                            ? 'hot_journal_post_apply_reader_token_retired_before_retry_wal_checkpoint_source'
                            : 'retry_wal_checkpoint_source_waits_for_reader_token_retirement',
                        'database_path' => (string) $postApply['database_path'],
                        'wal_path' => (string) $postApply['wal_path'],
                        'post_apply_reader_token' => $postToken,
                        'retry_reader_token' => $transitionToken,
                        'reader_tokens' => $readerTokens,
                        'token_rows' => $tokenRows,
                        'retained_reader_tokens' => $retainedTokens,
                        'stale_reader_tokens' => $staleTokens,
                        'post_apply_token_retired' => $postApplyTokenRetired,
                        'requires_reader_reopen' => $staleTokens !== [],
                        'hot_journal_observed' => $hotJournalObserved,
                        'post_apply_ready' => $postApplyReady,
                        'reopen_ready' => $reopenReady,
                        'can_admit_retry_checkpoint_source' => $ready,
                        'post_apply_file_digest' => (string) $postApply['file_digest'],
                        'retry_transition_digest' => (string) $reopen['source_transition_digest'],
                        'next_wal_sha256' => (string) $reopen['next_wal_sha256'],
                        'reader_page_numbers' => $reopen['reader_page_numbers'],
                        'reader_next_sources' => $reopen['reader_next_sources'],
                        'blocked_reasons' => array_values(array_unique($blocked)),
                        'dependencies' => array_values(array_unique(array_merge(
                            is_array($postApply['dependencies'] ?? null) ? $postApply['dependencies'] : [],
                            is_array($reopen['dependencies'] ?? null) ? $reopen['dependencies'] : [],
                            [
                                'sqlite-wal-hot-journal-savepoint-checkpoint-current-source-next187',
                                'sqlite-hot-journal-reader-token-retirement-before-wal-retry',
                                'wordpress-wal-import-retry-reader-token-fence',
                            ]
                        ))),
                        'dependency_closure' => 'no new support component needed; composes accepted post-apply current-source and reopened WAL source evidence',
                        'non_overlap' => 'next187 fences reader-token handoff between next183 post-apply current source and next184 reopened WAL source; it does not repeat atomic file-map apply, WAL byte truncation, rollback-journal apply, checkpoint transactions, reader-cache verification, or WAL salt/checkpoint parsing',
                    ];
                }

                /**
                 * @param array<string,mixed> $postApply
                 * @param array<string,mixed> $reopen
                 * @param list<string> $readerTokens
                 */
                private static function assertInput(array $postApply, array $reopen, array $readerTokens): void
                {
                    foreach (['database_path', 'wal_path', 'reader_source_token', 'file_digest'] as $key) {
                        if (!array_key_exists($key, $postApply)) {
                            throw new \InvalidArgumentException("SQLite WAL hot-journal savepoint checkpoint next187 missing post-apply {$key}");
                        }
                    }
                    foreach (['source_transition_digest', 'next_wal_sha256', 'reader_page_numbers', 'reader_next_sources'] as $key) {
                        if (!array_key_exists($key, $reopen)) {
                            throw new \InvalidArgumentException("SQLite WAL hot-journal savepoint checkpoint next187 missing reopen {$key}");
                        }
                    }
                    foreach ($readerTokens as $token) {
                        if (!is_string($token) || $token === '') {
                            throw new \InvalidArgumentException('SQLite WAL hot-journal savepoint checkpoint next187 reader tokens must be non-empty strings');
                        }
                    }
                    if (!is_array($reopen['reader_page_numbers']) || !is_array($reopen['reader_next_sources'])) {
                        throw new \InvalidArgumentException('SQLite WAL hot-journal savepoint checkpoint next187 reopen reader rows must be arrays');
                    }
                }
        };

        return $impl::plan($postApply, $reopen, $readerTokens, $hotJournalObserved);
    }

    public static function next188Plan(
        string $databasePath,
        string $databaseBytes,
        int $pageSize,
        string $savepoint,
        array $hotJournalPages,
        array $savepointBeforePages,
        SQLiteWal $currentWal,
        string $currentWalBytes,
        SQLiteWal $nextWal,
        string $nextWalBytes,
        array $readerCachePages,
        array $checkpointPages,
        array $baseReaders,
        array $statements,
        array $readers,
        int $currentSchemaCookie,
        int $nextSchemaCookie,
        int $currentCommitHook,
        int $nextCommitHook,
        ?array $expectedCurrentToken = null,
        ?array $expectedNextToken = null,
        string $mode = 'restart',
        int $readerEndFrame = 0,
        int $currentSourceEpoch = 1,
    ): array
    {
        $impl = new class {
                /**
                 * @param list<array{name:string,source_id?:string,epoch?:int,schema_cookie?:int,root_pages?:list<int>,dirty?:bool,closed?:bool,sql?:string,observed_checkpoint_sequence?:int,observed_salt?:list<int>,cursor_page?:int,observed_commit_hook?:int,observed_schema_cookie?:int}> $statements
                 * @param list<array{name:string,source_id?:string,epoch?:int,observed_checkpoint_sequence?:int,observed_salt?:list<int>,pinned?:bool,dirty?:bool,closed?:bool,observed_commit_hook?:int,observed_schema_cookie?:int}> $readers
                 * @param array{id:string,epoch:int}|null $expectedCurrentToken
                 * @param array{id:string,epoch:int}|null $expectedNextToken
                 * @return array<string,mixed>
                 */
                public static function plan(
                    string $databasePath,
                    string $databaseBytes,
                    int $pageSize,
                    string $savepoint,
                    array $hotJournalPages,
                    array $savepointBeforePages,
                    SQLiteWal $currentWal,
                    string $currentWalBytes,
                    SQLiteWal $nextWal,
                    string $nextWalBytes,
                    array $readerCachePages,
                    array $checkpointPages,
                    array $baseReaders,
                    array $statements,
                    array $readers,
                    int $currentSchemaCookie,
                    int $nextSchemaCookie,
                    int $currentCommitHook,
                    int $nextCommitHook,
                    ?array $expectedCurrentToken = null,
                    ?array $expectedNextToken = null,
                    string $mode = 'restart',
                    int $readerEndFrame = 0,
                    int $currentSourceEpoch = 1,
                ): array {
                    if ($currentCommitHook < 0 || $nextCommitHook < 0) {
                        throw new \InvalidArgumentException('SQLite WAL hot-journal savepoint checkpoint current-source next188 commit hooks must be non-negative');
                    }
                    if ($nextCommitHook < $currentCommitHook) {
                        throw new \InvalidArgumentException('SQLite WAL hot-journal savepoint checkpoint current-source next188 commit hook cannot move backwards');
                    }

                    $base = SQLiteWalHotJournalSavepointCheckpointCurrentSourceNextPlan::next185Plan(
                        $databasePath,
                        $databaseBytes,
                        $pageSize,
                        $savepoint,
                        $hotJournalPages,
                        $savepointBeforePages,
                        $currentWal,
                        $currentWalBytes,
                        $nextWal,
                        $nextWalBytes,
                        $readerCachePages,
                        $checkpointPages,
                        $baseReaders,
                        $statements,
                        $readers,
                        $currentSchemaCookie,
                        $nextSchemaCookie,
                        $expectedCurrentToken,
                        $expectedNextToken,
                        $mode,
                        $readerEndFrame,
                        $currentSourceEpoch
                    );

                    $statementRows = [];
                    $admittedStatements = [];
                    $reprepareStatements = [];
                    foreach ($base['statement_rows'] as $offset => $row) {
                        $decision = self::hookDecision('statement', $statements[$offset], $row, $currentSchemaCookie, $nextSchemaCookie, $currentCommitHook, $nextCommitHook);
                        $statementRows[] = $decision;
                        if ($decision['admitted']) {
                            $admittedStatements[] = $decision['name'];
                        } else {
                            $reprepareStatements[] = $decision['name'];
                        }
                    }

                    $readerRows = [];
                    $admittedReaders = [];
                    $reopenReaders = [];
                    foreach ($base['reader_rows'] as $offset => $row) {
                        $decision = self::hookDecision('reader', $readers[$offset], $row, $currentSchemaCookie, $nextSchemaCookie, $currentCommitHook, $nextCommitHook);
                        $readerRows[] = $decision;
                        if ($decision['admitted']) {
                            $admittedReaders[] = $decision['name'];
                        } else {
                            $reopenReaders[] = $decision['name'];
                        }
                    }

                    $guardRows = [
                        [
                            'name' => 'base_generation_current_source',
                            'matched' => $base['status'] === 'wal-hot-journal-savepoint-checkpoint-current-source-next185',
                            'reason' => 'base next185 WAL generation admission must pass before commit-hook admission',
                        ],
                        [
                            'name' => 'commit_hook_forward',
                            'matched' => $nextCommitHook >= $currentCommitHook,
                            'reason' => 'commit-hook counter cannot move backwards across checkpoint publication',
                        ],
                        [
                            'name' => 'statement_commit_hook_mix',
                            'matched' => $admittedStatements !== [] && $reprepareStatements !== [],
                            'reason' => 'statement cache must retain current hook rows and reprepare stale hook rows',
                        ],
                        [
                            'name' => 'reader_commit_hook_mix',
                            'matched' => $admittedReaders !== [] && $reopenReaders !== [],
                            'reason' => 'reader cache must retain current hook rows and reopen stale hook rows',
                        ],
                    ];
                    $mismatches = array_values(array_filter($guardRows, static fn (array $row): bool => !(bool) $row['matched']));
                    $status = $mismatches === []
                        ? 'wal-hot-journal-savepoint-checkpoint-current-source-next188'
                        : 'wal-hot-journal-savepoint-checkpoint-current-source-blocked-next188';

                    return [
                        'status' => $status,
                        'reason' => $status === 'wal-hot-journal-savepoint-checkpoint-current-source-next188'
                            ? 'prepared_statements_and_readers_admitted_by_commit_hook_after_wal_generation'
                            : 'commit_hook_admission_blocked_after_wal_generation',
                        'database_path' => $base['database_path'],
                        'journal_path' => $base['journal_path'],
                        'wal_path' => $base['wal_path'],
                        'page_size' => $base['page_size'],
                        'savepoint' => $base['savepoint'],
                        'mode' => $base['mode'],
                        'reader_end_frame' => $base['reader_end_frame'],
                        'base_status' => $base['status'],
                        'current_source_token' => $base['current_source_token'],
                        'next_source_token' => $base['next_source_token'],
                        'current_checkpoint_sequence' => $base['current_checkpoint_sequence'],
                        'next_checkpoint_sequence' => $base['next_checkpoint_sequence'],
                        'current_wal_salt' => $base['current_wal_salt'],
                        'next_wal_salt' => $base['next_wal_salt'],
                        'current_schema_cookie' => $currentSchemaCookie,
                        'next_schema_cookie' => $nextSchemaCookie,
                        'current_commit_hook' => $currentCommitHook,
                        'next_commit_hook' => $nextCommitHook,
                        'statement_rows' => $statementRows,
                        'reader_rows' => $readerRows,
                        'admitted_statement_names' => $admittedStatements,
                        'reprepare_statement_names' => $reprepareStatements,
                        'admitted_reader_names' => $admittedReaders,
                        'reopen_reader_names' => $reopenReaders,
                        'statement_hook_reasons' => array_column($statementRows, 'hook_reason'),
                        'reader_hook_reasons' => array_column($readerRows, 'hook_reason'),
                        'statement_hook_transitions' => array_column($statementRows, 'hook_transition'),
                        'reader_hook_transitions' => array_column($readerRows, 'hook_transition'),
                        'guard_rows' => $guardRows,
                        'guard_names' => array_column($guardRows, 'name'),
                        'guard_matches' => array_column($guardRows, 'matched'),
                        'stale_guard_names' => array_column($mismatches, 'name'),
                        'operation_names' => array_values(array_merge(
                            $base['operation_names'],
                            array_map(
                                static fn (array $row): string => $row['admitted']
                                    ? 'admit_commit_hook_current_source_next188'
                                    : 'reprepare_commit_hook_current_source_next188',
                                $statementRows
                            ),
                            array_map(
                                static fn (array $row): string => $row['admitted']
                                    ? 'retain_reader_commit_hook_next188'
                                    : 'reopen_reader_commit_hook_next188',
                                $readerRows
                            ),
                            ['publish_commit_hook_current_source_next188']
                        )),
                        'hook_digest' => hash('sha256', implode('|', array_merge(
                            [$base['generation_digest'], (string) $currentSchemaCookie, (string) $nextSchemaCookie, (string) $currentCommitHook, (string) $nextCommitHook],
                            array_column($statementRows, 'hook_transition'),
                            array_column($readerRows, 'hook_transition')
                        ))),
                        'base_plan' => $base,
                        'dependencies' => array_values(array_unique(array_merge($base['dependencies'], [
                            'sqlite-wal-hot-journal-savepoint-checkpoint-current-source-next188',
                            'sqlite-wal-commit-hook-prepared-statement-reader-admission',
                        ]))),
                        'dependency_closure' => 'no new support component needed; composes existing WAL generation admission with native schema-cookie and commit-hook counters',
                        'non_overlap' => 'adds commit-hook and schema-cookie admission after next185 checkpoint generation checks; it does not repeat WAL byte truncation, VFS savepoint apply, rollback-journal apply, checkpoint transaction planning, next182 statement root admission, or next185 salt/sequence generation checks',
                    ];
                }

                /**
                 * @param array<string,mixed> $input
                 * @param array<string,mixed> $baseRow
                 * @return array<string,mixed>
                 */
                private static function hookDecision(
                    string $kind,
                    array $input,
                    array $baseRow,
                    int $currentSchemaCookie,
                    int $nextSchemaCookie,
                    int $currentCommitHook,
                    int $nextCommitHook
                ): array {
                    $observedHook = $input['observed_commit_hook'] ?? null;
                    $observedSchema = $input['observed_schema_cookie'] ?? null;
                    if (!is_int($observedHook) || $observedHook < 0 || !is_int($observedSchema) || $observedSchema < 0) {
                        throw new \InvalidArgumentException("SQLite WAL hot-journal savepoint checkpoint current-source next188 {$kind} commit hook and schema cookie are required");
                    }

                    $admitted = (bool) $baseRow['admitted'];
                    $reason = $admitted ? "{$kind}_commit_hook_matches_current_source" : (string) ($baseRow['generation_reason'] ?? $baseRow['reason']);
                    if ($admitted && $observedHook === $nextCommitHook && $observedSchema === $nextSchemaCookie) {
                        $admitted = false;
                        $reason = "{$kind}_observed_next_commit_hook_before_reprepare";
                    } elseif ($admitted && $observedHook !== $currentCommitHook) {
                        $admitted = false;
                        $reason = "{$kind}_commit_hook_predates_current_source";
                    } elseif ($admitted && $observedSchema !== $currentSchemaCookie) {
                        $admitted = false;
                        $reason = "{$kind}_schema_cookie_predates_current_source";
                    }

                    return array_merge($baseRow, [
                        'admitted' => $admitted,
                        'hook_reason' => $reason,
                        'observed_commit_hook' => $observedHook,
                        'observed_schema_cookie' => $observedSchema,
                        'hook_transition' => $baseRow['name'] . '@schema' . $observedSchema . '#hook' . $observedHook . '>' . ($admitted ? 'retain-current-hook' : 'reprepare-current-hook'),
                    ]);
                }
        };

        return $impl::plan($databasePath, $databaseBytes, $pageSize, $savepoint, $hotJournalPages, $savepointBeforePages, $currentWal, $currentWalBytes, $nextWal, $nextWalBytes, $readerCachePages, $checkpointPages, $baseReaders, $statements, $readers, $currentSchemaCookie, $nextSchemaCookie, $currentCommitHook, $nextCommitHook, $expectedCurrentToken, $expectedNextToken, $mode, $readerEndFrame, $currentSourceEpoch);
    }

    public static function next189ReaderSnapshotPlan(
        array $applyResult,
        array $files,
        int $expectedCheckpointSequence,
        int $expectedPageSize,
        int $readerEndFrame,
        array $readerPages,
        array $readerCacheTokens = [],
        array $databasePages = [],
        int $readerEpoch = 1
    ): array
    {
        $impl = new class {
                /**
                 * @param array<string,mixed> $applyResult
                 * @param array<string,string|null> $files
                 * @param list<int> $readerPages
                 * @param list<string> $readerCacheTokens
                 * @param array<int,string> $databasePages
                 * @return array<string,mixed>
                 */
                public static function readerSnapshotPlan(
                    array $applyResult,
                    array $files,
                    int $expectedCheckpointSequence,
                    int $expectedPageSize,
                    int $readerEndFrame,
                    array $readerPages,
                    array $readerCacheTokens = [],
                    array $databasePages = [],
                    int $readerEpoch = 1
                ): array {
                    if ($readerEndFrame < 0) {
                        throw new \InvalidArgumentException('SQLite WAL current-source next189 reader end frame must be non-negative');
                    }
                    if ($readerPages === []) {
                        throw new \InvalidArgumentException('SQLite WAL current-source next189 requires reader pages');
                    }

                    $source = SQLiteWalHotJournalSavepointCheckpointCurrentSourceNextPlan::next186VerifyWalSource(
                        $applyResult,
                        $files,
                        $expectedCheckpointSequence,
                        $expectedPageSize,
                        $readerCacheTokens,
                        $readerEpoch
                    );

                    $blocked = $source['blocked_reasons'] ?? [];
                    $walPath = (string) ($applyResult['wal_path'] ?? '');
                    $walBytes = $walPath === '' ? null : ($files[$walPath] ?? null);
                    $wal = null;
                    $lastCommitFrame = null;
                    $commitPageCount = null;
                    $uncommittedTailFrames = [];
                    $readerRows = [];

                    if (($source['status'] ?? '') !== 'wal-hot-journal-savepoint-checkpoint-current-source-next186') {
                        $blocked[] = 'next186_retained_wal_source_required';
                    }

                    if (!is_string($walBytes)) {
                        $blocked[] = 'retained_wal_payload_missing_for_reader_snapshot';
                    } else {
                        try {
                            $wal = SQLiteWal::parse($walBytes, $expectedPageSize, true);
                            foreach ($wal->frames as $frame) {
                                if ($frame->isCommitFrame()) {
                                    $lastCommitFrame = $frame->index;
                                    $commitPageCount = $frame->databasePageCountAfterCommit;
                                }
                            }
                            foreach ($wal->frames as $frame) {
                                if ($lastCommitFrame !== null && $frame->index > $lastCommitFrame) {
                                    $uncommittedTailFrames[] = $frame->index;
                                }
                            }
                            if ($lastCommitFrame === null) {
                                $blocked[] = 'reader_snapshot_has_no_committed_wal_frame';
                            } elseif ($readerEndFrame > $lastCommitFrame) {
                                $blocked[] = 'reader_end_frame_extends_past_last_committed_frame';
                            }
                        } catch (\InvalidArgumentException) {
                            $blocked[] = 'retained_wal_payload_unreadable_for_reader_snapshot';
                        }
                    }

                    foreach ($readerPages as $pageNumber) {
                        if (!is_int($pageNumber) || $pageNumber < 1) {
                            throw new \InvalidArgumentException('SQLite WAL current-source next189 reader pages must be one-based integers');
                        }
                        $frame = $wal === null ? null : self::lastFrameForPage($wal, $pageNumber, $readerEndFrame);
                        $databaseImage = $databasePages[$pageNumber] ?? null;
                        if ($databaseImage !== null && !is_string($databaseImage)) {
                            throw new \InvalidArgumentException('SQLite WAL current-source next189 database page images must be strings');
                        }
                        $readerRows[] = [
                            'page_number' => $pageNumber,
                            'source' => $frame === null ? 'checkpoint-database' : 'retained-wal',
                            'frame_index' => $frame?->index,
                            'has_database_fallback' => $frame === null && $databaseImage !== null,
                            'image_sha256' => $frame === null
                                ? ($databaseImage === null ? null : hash('sha256', $databaseImage))
                                : hash('sha256', $frame->pageImage),
                        ];
                    }

                    $missingDatabaseFallbacks = array_values(array_map(
                        static fn (array $row): int => (int) $row['page_number'],
                        array_filter(
                            $readerRows,
                            static fn (array $row): bool => $row['source'] === 'checkpoint-database' && $row['has_database_fallback'] === false
                        )
                    ));
                    if ($missingDatabaseFallbacks !== []) {
                        $blocked[] = 'checkpoint_database_fallback_missing_for_reader_page';
                    }

                    $blocked = array_values(array_unique($blocked));
                    $status = $blocked === []
                        ? 'wal-hot-journal-savepoint-checkpoint-current-source-next189'
                        : 'wal-hot-journal-savepoint-checkpoint-current-source-blocked-next189';

                    return [
                        'status' => $status,
                        'reason' => $status === 'wal-hot-journal-savepoint-checkpoint-current-source-next189'
                            ? 'reader_snapshot_frames_are_bounded_by_retained_committed_wal_source'
                            : 'reader_snapshot_current_source_blocked_after_savepoint_checkpoint',
                        'database_path' => $applyResult['database_path'] ?? null,
                        'journal_path' => $applyResult['journal_path'] ?? null,
                        'wal_path' => $walPath,
                        'reader_epoch' => $readerEpoch,
                        'reader_end_frame' => $readerEndFrame,
                        'last_commit_frame' => $lastCommitFrame,
                        'last_commit_page_count' => $commitPageCount,
                        'uncommitted_tail_frames' => $uncommittedTailFrames,
                        'has_uncommitted_tail' => $uncommittedTailFrames !== [],
                        'reader_rows' => $readerRows,
                        'reader_page_numbers' => array_column($readerRows, 'page_number'),
                        'reader_sources' => array_column($readerRows, 'source'),
                        'reader_frame_indexes' => array_column($readerRows, 'frame_index'),
                        'missing_database_fallback_pages' => $missingDatabaseFallbacks,
                        'reader_source_token' => $source['reader_source_token'] ?? null,
                        'base_status' => $source['status'] ?? null,
                        'base_blocked_reasons' => $source['blocked_reasons'] ?? [],
                        'blocked_reasons' => $blocked,
                        'snapshot_digest' => hash('sha256', implode('|', array_map(
                            static fn (array $row): string => implode(':', [
                                (string) $row['page_number'],
                                (string) $row['source'],
                                (string) ($row['frame_index'] ?? 'db'),
                                (string) ($row['image_sha256'] ?? 'missing'),
                            ]),
                            $readerRows
                        ))),
                        'dependencies' => array_values(array_unique(array_merge(
                            is_array($source['dependencies'] ?? null) ? $source['dependencies'] : [],
                            [
                                'sqlite-wal-hot-journal-savepoint-checkpoint-current-source-next189',
                                'sqlite-wal-reader-snapshot-retained-commit-frame-admission',
                            ]
                        ))),
                        'dependency_closure' => 'no new support component needed; reuses native WAL parsing/checksum validation and next186 retained WAL current-source admission',
                        'non_overlap' => 'next189 selects reader snapshot page sources bounded by the retained committed WAL frame after next186 source admission; it does not repeat WAL header token validation, checkpoint transaction planning, VFS writer/sync application, savepoint byte truncation, or rollback-journal apply',
                    ];
                }

                private static function lastFrameForPage(SQLiteWal $wal, int $pageNumber, int $readerEndFrame): ?SQLiteWalFrame
                {
                    $match = null;
                    foreach ($wal->frames as $frame) {
                        if ($frame->index > $readerEndFrame) {
                            break;
                        }
                        if ($frame->pageNumber === $pageNumber) {
                            $match = $frame;
                        }
                    }

                    return $match;
                }
        };

        return $impl::readerSnapshotPlan($applyResult, $files, $expectedCheckpointSequence, $expectedPageSize, $readerEndFrame, $readerPages, $readerCacheTokens, $databasePages, $readerEpoch);
    }

    public static function next190Plan(
        array $readerFence,
        array $files,
        string $expectedDatabaseBytes,
        int $expectedPageSize,
        int $expectedCheckpointSequence,
        bool $requireDirectorySync = true
    ): array
    {
        $impl = new class {
                /**
                 * @param array<string,mixed> $readerFence
                 * @param array<string,string|null> $files
                 * @return array<string,mixed>
                 */
                public static function plan(
                    array $readerFence,
                    array $files,
                    string $expectedDatabaseBytes,
                    int $expectedPageSize,
                    int $expectedCheckpointSequence,
                    bool $requireDirectorySync = true
                ): array {
                    self::assertFence($readerFence);
                    $files = self::normalizeFiles($files);
                    if ($expectedDatabaseBytes === '') {
                        throw new \InvalidArgumentException('SQLite WAL hot-journal savepoint checkpoint next190 expected database bytes cannot be empty');
                    }
                    if ($expectedPageSize < 512 || ($expectedPageSize & ($expectedPageSize - 1)) !== 0) {
                        throw new \InvalidArgumentException('SQLite WAL hot-journal savepoint checkpoint next190 page size must be a power of two at least 512');
                    }
                    if ($expectedCheckpointSequence < 0) {
                        throw new \InvalidArgumentException('SQLite WAL hot-journal savepoint checkpoint next190 checkpoint sequence must be non-negative');
                    }

                    $databasePath = (string) $readerFence['database_path'];
                    $walPath = (string) $readerFence['wal_path'];
                    $journalPath = $databasePath . '-journal';
                    $databaseBytes = $files[$databasePath] ?? null;
                    $walBytes = $files[$walPath] ?? null;
                    $journalBytes = $files[$journalPath] ?? null;
                    $blocked = [];
                    $wal = null;
                    $walHeader = null;
                    $walCommitFrames = [];

                    $fenceReady = ($readerFence['status'] ?? '') === 'wal-hot-journal-savepoint-checkpoint-current-source-next187'
                        && ($readerFence['can_admit_retry_checkpoint_source'] ?? false) === true
                        && ($readerFence['requires_reader_reopen'] ?? true) === false
                        && ($readerFence['post_apply_token_retired'] ?? false) === true
                        && ($readerFence['hot_journal_observed'] ?? false) === true;
                    if (!$fenceReady) {
                        $blocked[] = 'next187_reader_token_fence_not_admitted';
                    }

                    if ($databaseBytes === null) {
                        $blocked[] = 'database_file_missing_after_retry_checkpoint_publication';
                    } elseif (!hash_equals(hash('sha256', $expectedDatabaseBytes), hash('sha256', $databaseBytes))) {
                        $blocked[] = 'database_file_digest_drift_after_retry_checkpoint_publication';
                    }

                    if ($walBytes === null || $walBytes === '') {
                        $blocked[] = 'wal_file_missing_after_retry_checkpoint_publication';
                    } else {
                        try {
                            $wal = SQLiteWal::parse($walBytes, $expectedPageSize, true);
                            $walHeader = $wal->header->toArray();
                            foreach ($wal->frames as $frame) {
                                if ($frame->isCommitFrame()) {
                                    $walCommitFrames[] = [
                                        'frame_index' => $frame->index,
                                        'page_number' => $frame->pageNumber,
                                        'commit_page_count' => $frame->databasePageCountAfterCommit,
                                    ];
                                }
                            }
                            if ($wal->header->checkpointSequence !== $expectedCheckpointSequence) {
                                $blocked[] = 'wal_checkpoint_sequence_drift_after_retry_checkpoint_publication';
                            }
                            if ($walCommitFrames === []) {
                                $blocked[] = 'wal_retry_checkpoint_publication_has_no_commit_frame';
                            }
                        } catch (\InvalidArgumentException $exception) {
                            $blocked[] = 'wal_retry_checkpoint_publication_checksum_or_header_invalid';
                            $walHeader = ['error' => $exception->getMessage()];
                        }
                    }

                    if ($journalBytes !== null) {
                        $blocked[] = 'hot_journal_file_must_be_absent_after_retry_checkpoint_publication';
                    }

                    $readerToken = (string) $readerFence['retry_reader_token'];
                    $publicationToken = 'wal-hot-journal-savepoint-checkpoint-next190:publish:' . substr(hash('sha256', implode('|', [
                        $readerToken,
                        hash('sha256', (string) $databaseBytes),
                        hash('sha256', (string) $walBytes),
                        (string) $expectedCheckpointSequence,
                        (string) $expectedPageSize,
                    ])), 0, 32);

                    if ($requireDirectorySync && !in_array('directory_sync_verified', $readerFence['dependencies'], true)) {
                        $blocked[] = 'directory_sync_evidence_required_for_retry_checkpoint_publication';
                    }

                    $ready = $blocked === [];

                    return [
                        'status' => $ready
                            ? 'wal-hot-journal-savepoint-checkpoint-current-source-next190'
                            : 'wal-hot-journal-savepoint-checkpoint-current-source-blocked-next190',
                        'reason' => $ready
                            ? 'retry_checkpoint_publication_matches_reader_fence_and_current_files'
                            : 'retry_checkpoint_publication_waits_for_current_source_file_map',
                        'database_path' => $databasePath,
                        'wal_path' => $walPath,
                        'journal_path' => $journalPath,
                        'reader_retry_token' => $readerToken,
                        'publication_token' => $publicationToken,
                        'database_sha256' => $databaseBytes === null ? null : hash('sha256', $databaseBytes),
                        'expected_database_sha256' => hash('sha256', $expectedDatabaseBytes),
                        'wal_sha256' => $walBytes === null ? null : hash('sha256', $walBytes),
                        'expected_wal_sha256' => $readerFence['next_wal_sha256'],
                        'journal_present' => $journalBytes !== null,
                        'wal_header' => $walHeader,
                        'wal_byte_order' => $wal?->header->byteOrder(),
                        'wal_checksums_validated' => $wal?->checksumsValidated ?? false,
                        'wal_frame_count' => count($wal?->frames ?? []),
                        'wal_commit_frames' => $walCommitFrames,
                        'wal_commit_frame_count' => count($walCommitFrames),
                        'last_commit_page_count' => $walCommitFrames[array_key_last($walCommitFrames)]['commit_page_count'] ?? null,
                        'expected_checkpoint_sequence' => $expectedCheckpointSequence,
                        'expected_page_size' => $expectedPageSize,
                        'reader_page_numbers' => $readerFence['reader_page_numbers'],
                        'reader_next_sources' => $readerFence['reader_next_sources'],
                        'can_publish_retry_checkpoint_source' => $ready,
                        'requires_directory_sync' => $requireDirectorySync,
                        'blocked_reasons' => array_values(array_unique($blocked)),
                        'dependencies' => array_values(array_unique(array_merge(
                            $readerFence['dependencies'],
                            [
                                'sqlite-wal-hot-journal-savepoint-checkpoint-current-source-next190',
                                'sqlite-retry-checkpoint-publication-current-file-map',
                                'wordpress-import-retry-checkpoint-current-source-publication',
                            ]
                        ))),
                        'dependency_closure' => 'no new support component needed; reuses accepted WAL parser/checksum validation plus next187 reader-token fencing',
                        'non_overlap' => 'next190 verifies final retry-checkpoint file-map publication after the next187 reader-token fence; it does not repeat WAL byte truncation, rollback-journal apply, checkpoint transaction planning, reader-cache token fencing, or WAL header source parsing',
                    ];
                }

                /**
                 * @param array<string,mixed> $readerFence
                 */
                private static function assertFence(array $readerFence): void
                {
                    foreach (['database_path', 'wal_path', 'retry_reader_token', 'next_wal_sha256', 'reader_page_numbers', 'reader_next_sources', 'dependencies'] as $key) {
                        if (!array_key_exists($key, $readerFence)) {
                            throw new \InvalidArgumentException("SQLite WAL hot-journal savepoint checkpoint next190 missing reader fence {$key}");
                        }
                    }
                    if (!is_string($readerFence['database_path']) || $readerFence['database_path'] === '') {
                        throw new \InvalidArgumentException('SQLite WAL hot-journal savepoint checkpoint next190 database path must be non-empty');
                    }
                    if (!is_string($readerFence['wal_path']) || $readerFence['wal_path'] === '') {
                        throw new \InvalidArgumentException('SQLite WAL hot-journal savepoint checkpoint next190 WAL path must be non-empty');
                    }
                    if (!is_string($readerFence['retry_reader_token']) || $readerFence['retry_reader_token'] === '') {
                        throw new \InvalidArgumentException('SQLite WAL hot-journal savepoint checkpoint next190 retry token must be non-empty');
                    }
                    if (!is_array($readerFence['reader_page_numbers']) || !is_array($readerFence['reader_next_sources']) || !is_array($readerFence['dependencies'])) {
                        throw new \InvalidArgumentException('SQLite WAL hot-journal savepoint checkpoint next190 reader fence arrays are malformed');
                    }
                }

                /**
                 * @param array<string,string|null> $files
                 * @return array<string,string|null>
                 */
                private static function normalizeFiles(array $files): array
                {
                    ksort($files, SORT_STRING);
                    foreach ($files as $path => $bytes) {
                        if (!is_string($path) || $path === '') {
                            throw new \InvalidArgumentException('SQLite WAL hot-journal savepoint checkpoint next190 file paths must be non-empty strings');
                        }
                        if ($bytes !== null && !is_string($bytes)) {
                            throw new \InvalidArgumentException('SQLite WAL hot-journal savepoint checkpoint next190 file bytes must be strings or null');
                        }
                    }

                    return $files;
                }
        };

        return $impl::plan($readerFence, $files, $expectedDatabaseBytes, $expectedPageSize, $expectedCheckpointSequence, $requireDirectorySync);
    }

    public static function next191Plan(
        array $commitHookPlan,
        array $cacheEntries,
        array $checkpointPages,
        array $hotJournalPages,
        array $savepointPages
    ): array
    {
        $impl = new class {
                /**
                 * @param array<string,mixed> $commitHookPlan
                 * @param list<array{name:string,page:int,source_id?:string,epoch?:int,observed_commit_hook?:int,observed_schema_cookie?:int,dirty?:bool,closed?:bool,image_sha256?:string}> $cacheEntries
                 * @param list<int> $checkpointPages
                 * @param list<int> $hotJournalPages
                 * @param list<int> $savepointPages
                 * @return array<string,mixed>
                 */
                public static function plan(
                    array $commitHookPlan,
                    array $cacheEntries,
                    array $checkpointPages,
                    array $hotJournalPages,
                    array $savepointPages
                ): array {
                    self::assertPlan($commitHookPlan);
                    if ($cacheEntries === []) {
                        throw new \InvalidArgumentException('SQLite WAL hot-journal savepoint checkpoint current-source next191 requires cache entries');
                    }

                    $currentToken = self::token($commitHookPlan['current_source_token'] ?? null);
                    $currentHook = (int) $commitHookPlan['current_commit_hook'];
                    $currentSchema = (int) $commitHookPlan['current_schema_cookie'];
                    $touchedPages = self::uniqueInts(array_merge($checkpointPages, $hotJournalPages, $savepointPages));
                    $checkpointSet = array_fill_keys($checkpointPages, true);
                    $hotSet = array_fill_keys($hotJournalPages, true);
                    $savepointSet = array_fill_keys($savepointPages, true);

                    $rows = [];
                    $retained = [];
                    $invalidated = [];
                    foreach ($cacheEntries as $entry) {
                        $row = self::cacheDecision($entry, $currentToken, $currentHook, $currentSchema, $checkpointSet, $hotSet, $savepointSet);
                        $rows[] = $row;
                        if ($row['retained']) {
                            $retained[] = $row['name'];
                        } else {
                            $invalidated[] = $row['name'];
                        }
                    }

                    $guardRows = [
                        [
                            'name' => 'base_commit_hook_current_source',
                            'matched' => ($commitHookPlan['status'] ?? '') === 'wal-hot-journal-savepoint-checkpoint-current-source-next188',
                            'reason' => 'next188 commit-hook and schema-cookie admission must pass before page-cache reuse',
                        ],
                        [
                            'name' => 'cache_entry_mix',
                            'matched' => $retained !== [] && $invalidated !== [],
                            'reason' => 'the cache must retain untouched current pages and invalidate stale/touched pages',
                        ],
                        [
                            'name' => 'all_touched_pages_accounted',
                            'matched' => $touchedPages !== [],
                            'reason' => 'hot-journal, savepoint, or checkpoint pages must be named before cache invalidation is useful',
                        ],
                    ];
                    $mismatches = array_values(array_filter($guardRows, static fn (array $row): bool => !(bool) $row['matched']));
                    $ready = $mismatches === [];

                    return [
                        'status' => $ready
                            ? 'wal-hot-journal-savepoint-checkpoint-current-source-next191'
                            : 'wal-hot-journal-savepoint-checkpoint-current-source-blocked-next191',
                        'reason' => $ready
                            ? 'page_cache_reused_only_for_current_untouched_pages_after_hot_journal_savepoint_checkpoint'
                            : 'page_cache_reuse_blocked_after_hot_journal_savepoint_checkpoint',
                        'database_path' => (string) $commitHookPlan['database_path'],
                        'wal_path' => (string) $commitHookPlan['wal_path'],
                        'current_source_token' => $currentToken,
                        'current_commit_hook' => $currentHook,
                        'current_schema_cookie' => $currentSchema,
                        'checkpoint_pages' => self::uniqueInts($checkpointPages),
                        'hot_journal_pages' => self::uniqueInts($hotJournalPages),
                        'savepoint_pages' => self::uniqueInts($savepointPages),
                        'touched_pages' => $touchedPages,
                        'cache_rows' => $rows,
                        'retained_cache_names' => $retained,
                        'invalidated_cache_names' => $invalidated,
                        'cache_reasons' => array_column($rows, 'reason'),
                        'guard_rows' => $guardRows,
                        'guard_names' => array_column($guardRows, 'name'),
                        'guard_matches' => array_column($guardRows, 'matched'),
                        'stale_guard_names' => array_column($mismatches, 'name'),
                        'operation_names' => array_values(array_merge(
                            is_array($commitHookPlan['operation_names'] ?? null) ? $commitHookPlan['operation_names'] : [],
                            array_map(
                                static fn (array $row): string => $row['retained']
                                    ? 'retain_page_cache_current_source_next191'
                                    : 'invalidate_page_cache_current_source_next191',
                                $rows
                            ),
                            ['publish_page_cache_admission_current_source_next191']
                        )),
                        'cache_digest' => hash('sha256', implode('|', array_merge(
                            [
                                (string) ($commitHookPlan['hook_digest'] ?? ''),
                                $currentToken['id'],
                                (string) $currentToken['epoch'],
                                (string) $currentHook,
                                (string) $currentSchema,
                            ],
                            array_column($rows, 'transition')
                        ))),
                        'base_plan' => $commitHookPlan,
                        'dependencies' => array_values(array_unique(array_merge(
                            is_array($commitHookPlan['dependencies'] ?? null) ? $commitHookPlan['dependencies'] : [],
                            [
                                'sqlite-wal-hot-journal-savepoint-checkpoint-current-source-next191',
                                'sqlite-wal-hot-journal-savepoint-page-cache-admission',
                                'wordpress-import-page-cache-current-source-fence',
                            ]
                        ))),
                        'dependency_closure' => 'no new support component needed; composes next188 current-source counters with bounded page-cache metadata',
                        'non_overlap' => 'next191 adds page-cache reuse and invalidation after next188 commit-hook admission; it does not repeat WAL byte truncation, VFS apply, rollback-journal apply, checkpoint transaction planning, reader token retirement, salt/sequence admission, or commit-hook/schema-cookie checks',
                    ];
                }

                /**
                 * @param array<string,mixed> $entry
                 * @param array{id:string,epoch:int} $currentToken
                 * @param array<int,true> $checkpointSet
                 * @param array<int,true> $hotSet
                 * @param array<int,true> $savepointSet
                 * @return array<string,mixed>
                 */
                private static function cacheDecision(
                    array $entry,
                    array $currentToken,
                    int $currentHook,
                    int $currentSchema,
                    array $checkpointSet,
                    array $hotSet,
                    array $savepointSet
                ): array {
                    foreach (['name', 'page'] as $key) {
                        if (!array_key_exists($key, $entry)) {
                            throw new \InvalidArgumentException("SQLite WAL hot-journal savepoint checkpoint current-source next191 missing cache {$key}");
                        }
                    }
                    $name = $entry['name'];
                    $page = $entry['page'];
                    if (!is_string($name) || $name === '' || !is_int($page) || $page < 1) {
                        throw new \InvalidArgumentException('SQLite WAL hot-journal savepoint checkpoint current-source next191 cache names must be non-empty and pages must be one-based integers');
                    }
                    $observedHook = $entry['observed_commit_hook'] ?? null;
                    $observedSchema = $entry['observed_schema_cookie'] ?? null;
                    if (!is_int($observedHook) || $observedHook < 0 || !is_int($observedSchema) || $observedSchema < 0) {
                        throw new \InvalidArgumentException('SQLite WAL hot-journal savepoint checkpoint current-source next191 cache entries require non-negative hook and schema counters');
                    }
                    $sourceId = (string) ($entry['source_id'] ?? '');
                    $epoch = $entry['epoch'] ?? null;
                    if (!is_int($epoch) || $epoch < 1) {
                        throw new \InvalidArgumentException('SQLite WAL hot-journal savepoint checkpoint current-source next191 cache epochs must be positive integers');
                    }

                    $touchedBy = [];
                    if (isset($checkpointSet[$page])) {
                        $touchedBy[] = 'checkpoint';
                    }
                    if (isset($hotSet[$page])) {
                        $touchedBy[] = 'hot-journal';
                    }
                    if (isset($savepointSet[$page])) {
                        $touchedBy[] = 'savepoint';
                    }

                    $retained = true;
                    $reason = 'cache_entry_matches_current_source_and_page_not_touched';
                    if (($entry['closed'] ?? false) === true) {
                        $retained = false;
                        $reason = 'cache_entry_closed';
                    } elseif (($entry['dirty'] ?? false) === true) {
                        $retained = false;
                        $reason = 'cache_entry_dirty_before_checkpoint_publish';
                    } elseif ($sourceId !== $currentToken['id'] || $epoch !== $currentToken['epoch']) {
                        $retained = false;
                        $reason = 'cache_entry_source_token_predates_current_source';
                    } elseif ($observedHook !== $currentHook) {
                        $retained = false;
                        $reason = 'cache_entry_commit_hook_predates_current_source';
                    } elseif ($observedSchema !== $currentSchema) {
                        $retained = false;
                        $reason = 'cache_entry_schema_cookie_predates_current_source';
                    } elseif ($touchedBy !== []) {
                        $retained = false;
                        $reason = 'cache_entry_page_touched_by_' . implode('_and_', $touchedBy);
                    }

                    return [
                        'name' => $name,
                        'page' => $page,
                        'source_id' => $sourceId,
                        'epoch' => $epoch,
                        'observed_commit_hook' => $observedHook,
                        'observed_schema_cookie' => $observedSchema,
                        'dirty' => ($entry['dirty'] ?? false) === true,
                        'closed' => ($entry['closed'] ?? false) === true,
                        'image_sha256' => isset($entry['image_sha256']) ? (string) $entry['image_sha256'] : null,
                        'touched_by' => $touchedBy,
                        'retained' => $retained,
                        'requires_reload' => !$retained,
                        'reason' => $reason,
                        'transition' => $name . '@p' . $page . '#hook' . $observedHook . '#schema' . $observedSchema . '>' . ($retained ? 'retain' : 'reload') . ':' . $reason,
                    ];
                }

                /**
                 * @return array{id:string,epoch:int}
                 */
                private static function token(mixed $token): array
                {
                    if (!is_array($token) || !is_string($token['id'] ?? null) || $token['id'] === '' || !is_int($token['epoch'] ?? null) || $token['epoch'] < 1) {
                        throw new \InvalidArgumentException('SQLite WAL hot-journal savepoint checkpoint current-source next191 requires a current source token');
                    }

                    return ['id' => $token['id'], 'epoch' => $token['epoch']];
                }

                /**
                 * @param list<int> $values
                 * @return list<int>
                 */
                private static function uniqueInts(array $values): array
                {
                    foreach ($values as $value) {
                        if (!is_int($value) || $value < 1) {
                            throw new \InvalidArgumentException('SQLite WAL hot-journal savepoint checkpoint current-source next191 page lists must contain one-based integers');
                        }
                    }
                    $values = array_values(array_unique($values));
                    sort($values, SORT_NUMERIC);

                    return $values;
                }

                /**
                 * @param array<string,mixed> $commitHookPlan
                 */
                private static function assertPlan(array $commitHookPlan): void
                {
                    foreach (['status', 'database_path', 'wal_path', 'current_source_token', 'current_commit_hook', 'current_schema_cookie'] as $key) {
                        if (!array_key_exists($key, $commitHookPlan)) {
                            throw new \InvalidArgumentException("SQLite WAL hot-journal savepoint checkpoint current-source next191 missing base {$key}");
                        }
                    }
                    if (!is_int($commitHookPlan['current_commit_hook']) || $commitHookPlan['current_commit_hook'] < 0) {
                        throw new \InvalidArgumentException('SQLite WAL hot-journal savepoint checkpoint current-source next191 current hook must be non-negative');
                    }
                    if (!is_int($commitHookPlan['current_schema_cookie']) || $commitHookPlan['current_schema_cookie'] < 0) {
                        throw new \InvalidArgumentException('SQLite WAL hot-journal savepoint checkpoint current-source next191 schema cookie must be non-negative');
                    }
                }
        };

        return $impl::plan($commitHookPlan, $cacheEntries, $checkpointPages, $hotJournalPages, $savepointPages);
    }

    public static function next192Plan(
        array $basePlan,
        string $preCheckpointDatabaseBytes,
        string $checkpointedDatabaseBytes,
        SQLiteWal $currentWal,
        array $checkpointPages,
        array $statements,
        array $readers
    ): array
    {
        $impl = new class {
                /**
                 * @param array<string,mixed> $basePlan
                 * @param list<int> $checkpointPages
                 * @param list<array{name:string,root_pages?:list<int>,observed_page_digests?:array<int,string>,closed?:bool,dirty?:bool}> $statements
                 * @param list<array{name:string,pinned_pages?:list<int>,observed_page_digests?:array<int,string>,closed?:bool}> $readers
                 * @return array<string,mixed>
                 */
                public static function plan(
                    array $basePlan,
                    string $preCheckpointDatabaseBytes,
                    string $checkpointedDatabaseBytes,
                    SQLiteWal $currentWal,
                    array $checkpointPages,
                    array $statements,
                    array $readers
                ): array {
                    if (($basePlan['status'] ?? null) !== 'wal-hot-journal-savepoint-checkpoint-current-source-next188') {
                        throw new \InvalidArgumentException('SQLite WAL hot-journal savepoint checkpoint current-source next192 requires an admitted next188 base plan');
                    }
                    if ($checkpointPages === []) {
                        throw new \InvalidArgumentException('SQLite WAL hot-journal savepoint checkpoint current-source next192 requires checkpoint pages');
                    }
                    if ($statements === [] || $readers === []) {
                        throw new \InvalidArgumentException('SQLite WAL hot-journal savepoint checkpoint current-source next192 requires statement and reader rows');
                    }

                    $pageSize = (int) ($basePlan['page_size'] ?? $currentWal->header->pageSize);
                    if ($pageSize < 512 || ($pageSize & ($pageSize - 1)) !== 0) {
                        throw new \InvalidArgumentException('SQLite WAL hot-journal savepoint checkpoint current-source next192 page size must be a power of two at least 512');
                    }
                    if (strlen($preCheckpointDatabaseBytes) % $pageSize !== 0 || strlen($checkpointedDatabaseBytes) % $pageSize !== 0) {
                        throw new \InvalidArgumentException('SQLite WAL hot-journal savepoint checkpoint current-source next192 database images must be page-size aligned');
                    }

                    $pageRows = self::checkpointPageRows($preCheckpointDatabaseBytes, $checkpointedDatabaseBytes, $currentWal, $checkpointPages, $pageSize);
                    $mismatchedPages = array_values(array_map(
                        static fn (array $row): int => $row['page_number'],
                        array_filter($pageRows, static fn (array $row): bool => !$row['matches'])
                    ));
                    $checkpointDigests = [];
                    foreach ($pageRows as $row) {
                        $checkpointDigests[$row['page_number']] = $row['actual_digest'];
                    }

                    $statementRows = [];
                    $admittedStatements = [];
                    $reprepareStatements = [];
                    foreach ($statements as $statement) {
                        $row = self::cacheDecision('statement', $statement, $checkpointDigests, $mismatchedPages);
                        $statementRows[] = $row;
                        if ($row['admitted']) {
                            $admittedStatements[] = $row['name'];
                        } else {
                            $reprepareStatements[] = $row['name'];
                        }
                    }

                    $readerRows = [];
                    $admittedReaders = [];
                    $reopenReaders = [];
                    foreach ($readers as $reader) {
                        $row = self::cacheDecision('reader', $reader, $checkpointDigests, $mismatchedPages);
                        $readerRows[] = $row;
                        if ($row['admitted']) {
                            $admittedReaders[] = $row['name'];
                        } else {
                            $reopenReaders[] = $row['name'];
                        }
                    }

                    $guardRows = [
                        [
                            'name' => 'base_commit_hook_current_source',
                            'matched' => ($basePlan['status'] ?? null) === 'wal-hot-journal-savepoint-checkpoint-current-source-next188',
                            'reason' => 'next188 commit-hook admission must pass before checkpoint image publication',
                        ],
                        [
                            'name' => 'checkpoint_pages_materialized',
                            'matched' => $mismatchedPages === [],
                            'reason' => 'all checkpointed pages must contain the committed current WAL page images',
                        ],
                        [
                            'name' => 'statement_digest_mix',
                            'matched' => $admittedStatements !== [] && $reprepareStatements !== [],
                            'reason' => 'statement cache keeps matching page digests and reprepares stale page digests',
                        ],
                        [
                            'name' => 'reader_digest_mix',
                            'matched' => $admittedReaders !== [] && $reopenReaders !== [],
                            'reason' => 'reader cache keeps matching page digests and reopens stale page digests',
                        ],
                    ];
                    $staleGuards = array_values(array_column(
                        array_filter($guardRows, static fn (array $row): bool => !$row['matched']),
                        'name'
                    ));
                    $status = $staleGuards === []
                        ? 'wal-hot-journal-savepoint-checkpoint-current-source-next192'
                        : 'wal-hot-journal-savepoint-checkpoint-current-source-blocked-next192';

                    return [
                        'status' => $status,
                        'reason' => $status === 'wal-hot-journal-savepoint-checkpoint-current-source-next192'
                            ? 'checkpointed_database_pages_match_committed_wal_frames_before_current_source_reuse'
                            : 'checkpointed_database_page_images_block_current_source_reuse',
                        'database_path' => $basePlan['database_path'] ?? null,
                        'journal_path' => $basePlan['journal_path'] ?? null,
                        'wal_path' => $basePlan['wal_path'] ?? null,
                        'page_size' => $pageSize,
                        'base_status' => $basePlan['status'],
                        'base_hook_digest' => $basePlan['hook_digest'] ?? null,
                        'checkpoint_pages' => array_values($checkpointPages),
                        'checkpoint_page_rows' => $pageRows,
                        'checkpoint_page_digests' => $checkpointDigests,
                        'mismatched_checkpoint_pages' => $mismatchedPages,
                        'statement_rows' => $statementRows,
                        'reader_rows' => $readerRows,
                        'admitted_statement_names' => $admittedStatements,
                        'reprepare_statement_names' => $reprepareStatements,
                        'admitted_reader_names' => $admittedReaders,
                        'reopen_reader_names' => $reopenReaders,
                        'guard_rows' => $guardRows,
                        'guard_names' => array_column($guardRows, 'name'),
                        'guard_matches' => array_column($guardRows, 'matched'),
                        'stale_guard_names' => $staleGuards,
                        'operation_names' => array_values(array_merge(
                            $basePlan['operation_names'] ?? [],
                            ['verify_checkpoint_page_images_current_source_next192'],
                            array_map(
                                static fn (array $row): string => $row['admitted']
                                    ? 'admit_checkpoint_page_digest_current_source_next192'
                                    : 'reprepare_checkpoint_page_digest_current_source_next192',
                                $statementRows
                            ),
                            array_map(
                                static fn (array $row): string => $row['admitted']
                                    ? 'retain_reader_checkpoint_page_digest_next192'
                                    : 'reopen_reader_checkpoint_page_digest_next192',
                                $readerRows
                            ),
                            ['publish_checkpoint_page_image_current_source_next192']
                        )),
                        'page_image_digest' => hash('sha256', implode('|', array_merge(
                            [(string) ($basePlan['hook_digest'] ?? ''), hash('sha256', $checkpointedDatabaseBytes)],
                            array_map(static fn (array $row): string => $row['page_number'] . ':' . $row['expected_digest'] . ':' . $row['actual_digest'], $pageRows),
                            array_column($statementRows, 'digest_transition'),
                            array_column($readerRows, 'digest_transition')
                        ))),
                        'dependencies' => array_values(array_unique(array_merge($basePlan['dependencies'] ?? [], [
                            'sqlite-wal-hot-journal-savepoint-checkpoint-current-source-next192',
                            'sqlite-wal-checkpoint-page-image-publication',
                        ]))),
                        'dependency_closure' => 'no new support component needed; reuses the accepted WAL parser, page-image reader snapshots, and next188 current-source commit-hook admission',
                        'non_overlap' => 'next192 verifies checkpointed database page images against committed WAL frames before reusing current-source readers; it does not repeat next188 hook checks, next185 salt/sequence generation, WAL byte truncation, rollback-journal apply, VFS savepoint rollback, or checkpoint transaction planning',
                    ];
                }

                /**
                 * @param list<int> $checkpointPages
                 * @return list<array<string,mixed>>
                 */
                private static function checkpointPageRows(string $preCheckpointDatabaseBytes, string $checkpointedDatabaseBytes, SQLiteWal $currentWal, array $checkpointPages, int $pageSize): array
                {
                    $rows = [];
                    $seen = [];
                    foreach ($checkpointPages as $pageNumber) {
                        if (!is_int($pageNumber) || $pageNumber < 1) {
                            throw new \InvalidArgumentException('SQLite WAL hot-journal savepoint checkpoint current-source next192 checkpoint pages must be one-based integers');
                        }
                        if (isset($seen[$pageNumber])) {
                            continue;
                        }
                        $seen[$pageNumber] = true;
                        $expected = $currentWal->readerSnapshotPageImage($preCheckpointDatabaseBytes, $pageNumber);
                        $offset = ($pageNumber - 1) * $pageSize;
                        $actual = substr($checkpointedDatabaseBytes, $offset, $pageSize);
                        if (strlen($actual) !== $pageSize) {
                            throw new \OutOfBoundsException("SQLite WAL hot-journal savepoint checkpoint current-source next192 checkpoint page {$pageNumber} is missing from the database image");
                        }
                        $expectedDigest = hash('sha256', $expected['image']);
                        $actualDigest = hash('sha256', $actual);
                        $rows[] = [
                            'page_number' => $pageNumber,
                            'source' => $expected['source'],
                            'frame_index' => $expected['frame_index'],
                            'database_offset' => $offset,
                            'expected_digest' => $expectedDigest,
                            'actual_digest' => $actualDigest,
                            'matches' => $expectedDigest === $actualDigest,
                            'expected_prefix' => rtrim(substr($expected['image'], 0, 48), '.'),
                            'actual_prefix' => rtrim(substr($actual, 0, 48), '.'),
                        ];
                    }

                    return $rows;
                }

                /**
                 * @param array<string,mixed> $row
                 * @param array<int,string> $checkpointDigests
                 * @param list<int> $mismatchedPages
                 * @return array<string,mixed>
                 */
                private static function cacheDecision(string $kind, array $row, array $checkpointDigests, array $mismatchedPages): array
                {
                    $name = $row['name'] ?? null;
                    if (!is_string($name) || $name === '') {
                        throw new \InvalidArgumentException("SQLite WAL hot-journal savepoint checkpoint current-source next192 {$kind} name is required");
                    }
                    $pages = $kind === 'statement' ? ($row['root_pages'] ?? []) : ($row['pinned_pages'] ?? []);
                    if (!is_array($pages) || $pages === []) {
                        throw new \InvalidArgumentException("SQLite WAL hot-journal savepoint checkpoint current-source next192 {$kind} pages are required");
                    }
                    $observed = $row['observed_page_digests'] ?? null;
                    if (!is_array($observed)) {
                        throw new \InvalidArgumentException("SQLite WAL hot-journal savepoint checkpoint current-source next192 {$kind} observed page digests are required");
                    }

                    $admitted = empty($row['closed']) && empty($row['dirty']);
                    $reason = $admitted ? "{$kind}_checkpoint_page_images_match_current_source" : "{$kind}_closed_or_dirty_before_checkpoint_publication";
                    $pageRows = [];
                    foreach ($pages as $pageNumber) {
                        if (!is_int($pageNumber) || $pageNumber < 1) {
                            throw new \InvalidArgumentException("SQLite WAL hot-journal savepoint checkpoint current-source next192 {$kind} pages must be one-based integers");
                        }
                        $expectedDigest = $checkpointDigests[$pageNumber] ?? null;
                        $observedDigest = $observed[$pageNumber] ?? null;
                        if (!is_string($observedDigest) || strlen($observedDigest) !== 64) {
                            throw new \InvalidArgumentException("SQLite WAL hot-journal savepoint checkpoint current-source next192 {$kind} observed page digest is malformed");
                        }
                        $pageRows[] = [
                            'page_number' => $pageNumber,
                            'expected_digest' => $expectedDigest,
                            'observed_digest' => $observedDigest,
                            'matches' => $expectedDigest !== null && $expectedDigest === $observedDigest,
                            'checkpoint_page_mismatch' => in_array($pageNumber, $mismatchedPages, true),
                        ];
                        if ($expectedDigest === null) {
                            $admitted = false;
                            $reason = "{$kind}_page_not_in_checkpoint_publication";
                        } elseif (in_array($pageNumber, $mismatchedPages, true)) {
                            $admitted = false;
                            $reason = "{$kind}_checkpoint_page_image_not_materialized";
                        } elseif ($observedDigest !== $expectedDigest) {
                            $admitted = false;
                            $reason = "{$kind}_observed_page_digest_predates_checkpoint";
                        }
                    }

                    return array_merge($row, [
                        'admitted' => $admitted,
                        'digest_reason' => $reason,
                        'page_rows' => $pageRows,
                        'digest_transition' => $name . '>' . ($admitted ? 'retain-checkpoint-pages' : 'reprepare-checkpoint-pages'),
                    ]);
                }
        };

        return $impl::plan($basePlan, $preCheckpointDatabaseBytes, $checkpointedDatabaseBytes, $currentWal, $checkpointPages, $statements, $readers);
    }

    public static function next193PublishReaderMarks(
        array $retryHandoff,
        array $readerSlots,
        int $generation,
        array $expectedPages
    ): array
    {
        $impl = new class {
                /**
                 * @param array<string,mixed> $retryHandoff
                 * @param list<array<string,mixed>> $readerSlots
                 * @param list<int> $expectedPages
                 * @return array<string,mixed>
                 */
                public static function publishReaderMarks(
                    array $retryHandoff,
                    array $readerSlots,
                    int $generation,
                    array $expectedPages
                ): array {
                    self::assertRetryHandoff($retryHandoff);
                    if ($generation < 1) {
                        throw new \InvalidArgumentException('SQLite WAL hot-journal savepoint checkpoint next193 generation must be positive');
                    }
                    if ($expectedPages === []) {
                        throw new \InvalidArgumentException('SQLite WAL hot-journal savepoint checkpoint next193 requires expected reader pages');
                    }

                    $retryToken = (string) $retryHandoff['retry_reader_token'];
                    $pageSet = [];
                    foreach ($expectedPages as $page) {
                        if (!is_int($page) || $page < 1) {
                            throw new \InvalidArgumentException('SQLite WAL hot-journal savepoint checkpoint next193 expected pages must be one-based integers');
                        }
                        $pageSet[$page] = true;
                    }

                    $rows = [];
                    $blocked = [];
                    $seenSlots = [];
                    $coveredPages = [];
                    foreach ($readerSlots as $slot) {
                        self::assertSlot($slot);
                        $slotId = (int) $slot['slot'];
                        $page = (int) $slot['page_number'];
                        $token = (string) $slot['reader_token'];
                        $slotGeneration = (int) $slot['generation'];
                        $frameIndex = $slot['frame_index'];
                        $source = (string) $slot['source'];
                        $valid = true;
                        $reasons = [];

                        if (isset($seenSlots[$slotId])) {
                            $valid = false;
                            $reasons[] = 'duplicate_reader_mark_slot';
                            $blocked[] = 'duplicate_reader_mark_slot';
                        }
                        $seenSlots[$slotId] = true;

                        if (!isset($pageSet[$page])) {
                            $valid = false;
                            $reasons[] = 'reader_mark_page_not_expected';
                            $blocked[] = 'reader_mark_page_not_expected';
                        } else {
                            $coveredPages[$page] = true;
                        }
                        if ($token !== $retryToken) {
                            $valid = false;
                            $reasons[] = 'reader_mark_token_not_retry_source';
                            $blocked[] = 'reader_mark_token_not_retry_source';
                        }
                        if ($slotGeneration !== $generation) {
                            $valid = false;
                            $reasons[] = 'reader_mark_generation_mismatch';
                            $blocked[] = 'reader_mark_generation_mismatch';
                        }
                        if ($source !== 'next-wal' && $source !== 'checkpoint-database') {
                            $valid = false;
                            $reasons[] = 'reader_mark_source_not_retry_visible';
                            $blocked[] = 'reader_mark_source_not_retry_visible';
                        }
                        if ($source === 'checkpoint-database' && $frameIndex !== null) {
                            $valid = false;
                            $reasons[] = 'checkpoint_database_reader_mark_has_frame';
                            $blocked[] = 'checkpoint_database_reader_mark_has_frame';
                        }
                        if ($source === 'next-wal' && (!is_int($frameIndex) || $frameIndex < 1)) {
                            $valid = false;
                            $reasons[] = 'next_wal_reader_mark_missing_frame';
                            $blocked[] = 'next_wal_reader_mark_missing_frame';
                        }

                        $rows[] = [
                            'slot' => $slotId,
                            'page_number' => $page,
                            'source' => $source,
                            'frame_index' => $frameIndex,
                            'reader_token' => $token,
                            'generation' => $slotGeneration,
                            'published' => $valid,
                            'blocked_reasons' => $reasons,
                        ];
                    }

                    $missingPages = array_values(array_diff($expectedPages, array_keys($coveredPages)));
                    if ($missingPages !== []) {
                        $blocked[] = 'reader_mark_pages_missing';
                    }
                    if (($retryHandoff['status'] ?? '') !== 'wal-hot-journal-savepoint-checkpoint-current-source-next187') {
                        $blocked[] = 'next187_retry_handoff_not_admitted';
                    }
                    if (($retryHandoff['can_admit_retry_checkpoint_source'] ?? false) !== true) {
                        $blocked[] = 'retry_checkpoint_source_not_admitted';
                    }
                    if (($retryHandoff['stale_reader_tokens'] ?? []) !== []) {
                        $blocked[] = 'stale_reader_tokens_not_retired_before_mark_publish';
                    }

                    $blocked = array_values(array_unique($blocked));
                    $ready = $blocked === [];
                    $publishedRows = array_values(array_filter($rows, static fn (array $row): bool => $row['published']));

                    return [
                        'status' => $ready
                            ? 'wal-hot-journal-savepoint-checkpoint-current-source-next193'
                            : 'wal-hot-journal-savepoint-checkpoint-current-source-blocked-next193',
                        'reason' => $ready
                            ? 'retry_wal_reader_marks_published_after_hot_journal_checkpoint_handoff'
                            : 'retry_wal_reader_marks_wait_for_clean_current_source_handoff',
                        'database_path' => (string) $retryHandoff['database_path'],
                        'wal_path' => (string) $retryHandoff['wal_path'],
                        'generation' => $generation,
                        'retry_reader_token' => $retryToken,
                        'expected_pages' => $expectedPages,
                        'missing_pages' => $missingPages,
                        'reader_mark_rows' => $rows,
                        'published_reader_mark_rows' => $publishedRows,
                        'published_slot_count' => count($publishedRows),
                        'published_pages' => array_values(array_map(static fn (array $row): int => $row['page_number'], $publishedRows)),
                        'published_sources' => array_values(array_unique(array_map(static fn (array $row): string => $row['source'], $publishedRows))),
                        'requires_reader_reopen' => !$ready,
                        'can_publish_reader_marks' => $ready,
                        'handoff_transition_digest' => (string) $retryHandoff['retry_transition_digest'],
                        'next_wal_sha256' => (string) $retryHandoff['next_wal_sha256'],
                        'reader_mark_digest' => self::readerMarkDigest($retryToken, $generation, $rows),
                        'blocked_reasons' => $blocked,
                        'dependencies' => array_values(array_unique(array_merge(
                            is_array($retryHandoff['dependencies'] ?? null) ? $retryHandoff['dependencies'] : [],
                            [
                                'sqlite-wal-hot-journal-savepoint-checkpoint-current-source-next193',
                                'sqlite-wal-retry-reader-mark-publication-after-hot-journal',
                                'wordpress-wal-import-retry-reader-mark-publication',
                            ]
                        ))),
                        'dependency_closure' => 'no new support component needed; composes next187 retry-source admission with lane-local reader-mark slot metadata',
                        'non_overlap' => 'next193 publishes retry WAL reader-mark slots after next187 token handoff; it does not repeat hot-journal recovery, VFS apply, rollback-journal apply, savepoint byte truncation, checkpoint transactions, next184 salt/checkpoint separation, or next187 token retirement',
                    ];
                }

                /**
                 * @param array<string,mixed> $retryHandoff
                 */
                private static function assertRetryHandoff(array $retryHandoff): void
                {
                    foreach (['database_path', 'wal_path', 'retry_reader_token', 'retry_transition_digest', 'next_wal_sha256'] as $key) {
                        if (!array_key_exists($key, $retryHandoff)) {
                            throw new \InvalidArgumentException("SQLite WAL hot-journal savepoint checkpoint next193 missing handoff {$key}");
                        }
                    }
                }

                /**
                 * @param array<string,mixed> $slot
                 */
                private static function assertSlot(array $slot): void
                {
                    foreach (['slot', 'page_number', 'reader_token', 'generation', 'source', 'frame_index'] as $key) {
                        if (!array_key_exists($key, $slot)) {
                            throw new \InvalidArgumentException("SQLite WAL hot-journal savepoint checkpoint next193 missing reader slot {$key}");
                        }
                    }
                    if (!is_int($slot['slot']) || $slot['slot'] < 0) {
                        throw new \InvalidArgumentException('SQLite WAL hot-journal savepoint checkpoint next193 reader slot ids must be non-negative integers');
                    }
                    if (!is_int($slot['page_number']) || $slot['page_number'] < 1) {
                        throw new \InvalidArgumentException('SQLite WAL hot-journal savepoint checkpoint next193 reader slot pages must be one-based integers');
                    }
                    if (!is_string($slot['reader_token']) || $slot['reader_token'] === '') {
                        throw new \InvalidArgumentException('SQLite WAL hot-journal savepoint checkpoint next193 reader slot tokens must be non-empty strings');
                    }
                    if (!is_int($slot['generation']) || $slot['generation'] < 1) {
                        throw new \InvalidArgumentException('SQLite WAL hot-journal savepoint checkpoint next193 reader slot generation must be positive');
                    }
                    if (!is_string($slot['source']) || $slot['source'] === '') {
                        throw new \InvalidArgumentException('SQLite WAL hot-journal savepoint checkpoint next193 reader slot source must be a non-empty string');
                    }
                    if ($slot['frame_index'] !== null && !is_int($slot['frame_index'])) {
                        throw new \InvalidArgumentException('SQLite WAL hot-journal savepoint checkpoint next193 reader slot frame indexes must be integers or null');
                    }
                }

                /**
                 * @param list<array<string,mixed>> $rows
                 */
                private static function readerMarkDigest(string $retryToken, int $generation, array $rows): string
                {
                    return hash('sha256', json_encode([
                        'retryToken' => $retryToken,
                        'generation' => $generation,
                        'rows' => $rows,
                    ], JSON_THROW_ON_ERROR));
                }
        };

        return $impl::publishReaderMarks($retryHandoff, $readerSlots, $generation, $expectedPages);
    }

    public static function next194SealReaderGeneration(
        array $publication,
        array $readerTickets,
        int $previousReaderEpoch,
        bool $requireExclusiveCheckpointLock = true
    ): array
    {
        $impl = new class {
                /**
                 * @param array<string,mixed> $publication
                 * @param list<array<string,mixed>> $readerTickets
                 * @return array<string,mixed>
                 */
                public static function sealReaderGeneration(
                    array $publication,
                    array $readerTickets,
                    int $previousReaderEpoch,
                    bool $requireExclusiveCheckpointLock = true
                ): array {
                    self::assertPublication($publication);
                    if ($previousReaderEpoch < 0) {
                        throw new \InvalidArgumentException('SQLite WAL current-source next194 previous reader epoch must be non-negative');
                    }
                    if ($readerTickets === []) {
                        throw new \InvalidArgumentException('SQLite WAL current-source next194 requires reader tickets');
                    }

                    $blocked = [];
                    if (($publication['status'] ?? '') !== 'wal-hot-journal-savepoint-checkpoint-current-source-next190') {
                        $blocked[] = 'next190_retry_checkpoint_publication_required';
                    }
                    if (($publication['can_publish_retry_checkpoint_source'] ?? false) !== true) {
                        $blocked[] = 'next190_retry_checkpoint_source_not_publishable';
                    }
                    if (($publication['journal_present'] ?? true) !== false) {
                        $blocked[] = 'hot_journal_must_be_absent_before_reader_generation_seal';
                    }
                    if (($publication['wal_checksums_validated'] ?? false) !== true) {
                        $blocked[] = 'retry_checkpoint_wal_checksums_required_before_reader_generation_seal';
                    }
                    if (($publication['wal_commit_frame_count'] ?? 0) < 1) {
                        $blocked[] = 'retry_checkpoint_commit_frame_required_before_reader_generation_seal';
                    }

                    $expectedPublicationToken = (string) $publication['publication_token'];
                    $expectedDatabaseHash = (string) $publication['database_sha256'];
                    $expectedWalHash = (string) $publication['wal_sha256'];
                    $expectedCheckpoint = (int) $publication['expected_checkpoint_sequence'];
                    $expectedPageSize = (int) $publication['expected_page_size'];
                    $allowedPages = self::intSet($publication['reader_page_numbers']);
                    $allowedSources = self::stringSet($publication['reader_next_sources']);
                    $ticketRows = [];
                    $seenTickets = [];

                    foreach ($readerTickets as $index => $ticket) {
                        if (!is_array($ticket)) {
                            throw new \InvalidArgumentException('SQLite WAL current-source next194 reader ticket rows must be arrays');
                        }
                        $ticketId = self::stringField($ticket, 'ticket_id', $index);
                        if (isset($seenTickets[$ticketId])) {
                            $blocked[] = 'duplicate_reader_ticket_id_after_retry_checkpoint_publication';
                        }
                        $seenTickets[$ticketId] = true;

                        $epoch = self::intField($ticket, 'reader_epoch', $index);
                        $pageNumber = self::intField($ticket, 'page_number', $index);
                        $source = self::stringField($ticket, 'source', $index);
                        $publicationToken = self::stringField($ticket, 'publication_token', $index);
                        $databaseHash = self::stringField($ticket, 'database_sha256', $index);
                        $walHash = self::stringField($ticket, 'wal_sha256', $index);
                        $checkpoint = self::intField($ticket, 'checkpoint_sequence', $index);
                        $pageSize = self::intField($ticket, 'page_size', $index);
                        $hotJournalDigest = $ticket['hot_journal_sha256'] ?? null;
                        if ($hotJournalDigest !== null && !is_string($hotJournalDigest)) {
                            throw new \InvalidArgumentException("SQLite WAL current-source next194 reader ticket {$index} hot journal digest must be a string or null");
                        }
                        $hasSyncReceipt = (bool) ($ticket['has_directory_sync_receipt'] ?? false);
                        $hasLockReceipt = (bool) ($ticket['has_exclusive_checkpoint_lock_receipt'] ?? false);
                        $savepointClosed = (bool) ($ticket['savepoint_closed'] ?? false);

                        $ticketBlocked = [];
                        if ($epoch <= $previousReaderEpoch) {
                            $ticketBlocked[] = 'reader_epoch_must_advance_after_retry_checkpoint_publication';
                        }
                        if (!isset($allowedPages[$pageNumber])) {
                            $ticketBlocked[] = 'reader_ticket_page_not_in_next190_reader_page_set';
                        }
                        if (!isset($allowedSources[$source])) {
                            $ticketBlocked[] = 'reader_ticket_source_not_in_next190_reader_source_set';
                        }
                        if (!hash_equals($expectedPublicationToken, $publicationToken)) {
                            $ticketBlocked[] = 'reader_ticket_publication_token_mismatch';
                        }
                        if (!hash_equals($expectedDatabaseHash, $databaseHash)) {
                            $ticketBlocked[] = 'reader_ticket_database_digest_mismatch';
                        }
                        if (!hash_equals($expectedWalHash, $walHash)) {
                            $ticketBlocked[] = 'reader_ticket_wal_digest_mismatch';
                        }
                        if ($checkpoint !== $expectedCheckpoint) {
                            $ticketBlocked[] = 'reader_ticket_checkpoint_sequence_mismatch';
                        }
                        if ($pageSize !== $expectedPageSize) {
                            $ticketBlocked[] = 'reader_ticket_page_size_mismatch';
                        }
                        if ($hotJournalDigest !== null && $hotJournalDigest !== '') {
                            $ticketBlocked[] = 'reader_ticket_retains_hot_journal_digest';
                        }
                        if (!$hasSyncReceipt) {
                            $ticketBlocked[] = 'reader_ticket_missing_directory_sync_receipt';
                        }
                        if ($requireExclusiveCheckpointLock && !$hasLockReceipt) {
                            $ticketBlocked[] = 'reader_ticket_missing_exclusive_checkpoint_lock_receipt';
                        }
                        if (!$savepointClosed) {
                            $ticketBlocked[] = 'reader_ticket_savepoint_not_closed';
                        }

                        foreach ($ticketBlocked as $reason) {
                            $blocked[] = $reason;
                        }
                        $ticketRows[] = [
                            'ticket_id' => $ticketId,
                            'reader_epoch' => $epoch,
                            'page_number' => $pageNumber,
                            'source' => $source,
                            'checkpoint_sequence' => $checkpoint,
                            'page_size' => $pageSize,
                            'publication_token_matches' => hash_equals($expectedPublicationToken, $publicationToken),
                            'database_digest_matches' => hash_equals($expectedDatabaseHash, $databaseHash),
                            'wal_digest_matches' => hash_equals($expectedWalHash, $walHash),
                            'has_directory_sync_receipt' => $hasSyncReceipt,
                            'has_exclusive_checkpoint_lock_receipt' => $hasLockReceipt,
                            'savepoint_closed' => $savepointClosed,
                            'hot_journal_digest_retained' => $hotJournalDigest !== null && $hotJournalDigest !== '',
                            'blocked_reasons' => $ticketBlocked,
                        ];
                    }

                    $blocked = array_values(array_unique($blocked));
                    $ready = $blocked === [];

                    return [
                        'status' => $ready
                            ? 'wal-hot-journal-savepoint-checkpoint-current-source-next194'
                            : 'wal-hot-journal-savepoint-checkpoint-current-source-blocked-next194',
                        'reason' => $ready
                            ? 'reopened_reader_generation_sealed_to_retry_checkpoint_publication'
                            : 'reopened_reader_generation_waits_for_retry_checkpoint_receipts',
                        'database_path' => $publication['database_path'],
                        'wal_path' => $publication['wal_path'],
                        'journal_path' => $publication['journal_path'],
                        'publication_token' => $expectedPublicationToken,
                        'previous_reader_epoch' => $previousReaderEpoch,
                        'sealed_reader_epoch' => $ready ? max(array_column($ticketRows, 'reader_epoch')) : null,
                        'reader_ticket_count' => count($ticketRows),
                        'reader_ticket_ids' => array_column($ticketRows, 'ticket_id'),
                        'reader_pages' => array_column($ticketRows, 'page_number'),
                        'reader_sources' => array_column($ticketRows, 'source'),
                        'ticket_rows' => $ticketRows,
                        'requires_exclusive_checkpoint_lock' => $requireExclusiveCheckpointLock,
                        'can_expose_reopened_readers' => $ready,
                        'blocked_reasons' => $blocked,
                        'seal_digest' => hash('sha256', implode('|', array_map(
                            static fn (array $row): string => implode(':', [
                                (string) $row['ticket_id'],
                                (string) $row['reader_epoch'],
                                (string) $row['page_number'],
                                (string) $row['source'],
                                $row['publication_token_matches'] ? 'pub' : 'badpub',
                                $row['database_digest_matches'] ? 'db' : 'baddb',
                                $row['wal_digest_matches'] ? 'wal' : 'badwal',
                            ]),
                            $ticketRows
                        ))),
                        'dependencies' => array_values(array_unique(array_merge(
                            $publication['dependencies'],
                            [
                                'sqlite-wal-hot-journal-savepoint-checkpoint-current-source-next194',
                                'sqlite-reopened-reader-generation-seal',
                                'wordpress-import-retry-checkpoint-reader-exposure',
                            ]
                        ))),
                        'dependency_closure' => 'no new support component needed; reuses next190 retry checkpoint publication evidence plus directory-sync and checkpoint-lock receipts',
                        'non_overlap' => 'next194 seals reopened reader tickets to an already-published next190 retry checkpoint; it does not repeat WAL byte truncation, rollback-journal apply, checkpoint transaction planning, VFS writer/sync application, or next190 file-map publication',
                    ];
                }

                /**
                 * @param array<string,mixed> $publication
                 */
                private static function assertPublication(array $publication): void
                {
                    foreach (['database_path', 'wal_path', 'journal_path', 'publication_token', 'database_sha256', 'wal_sha256', 'expected_checkpoint_sequence', 'expected_page_size', 'reader_page_numbers', 'reader_next_sources', 'dependencies'] as $key) {
                        if (!array_key_exists($key, $publication)) {
                            throw new \InvalidArgumentException("SQLite WAL current-source next194 publication missing {$key}");
                        }
                    }
                    foreach (['database_path', 'wal_path', 'journal_path', 'publication_token', 'database_sha256', 'wal_sha256'] as $key) {
                        if (!is_string($publication[$key]) || $publication[$key] === '') {
                            throw new \InvalidArgumentException("SQLite WAL current-source next194 publication {$key} must be a non-empty string");
                        }
                    }
                    if (!is_int($publication['expected_checkpoint_sequence']) || $publication['expected_checkpoint_sequence'] < 0) {
                        throw new \InvalidArgumentException('SQLite WAL current-source next194 publication checkpoint sequence must be a non-negative integer');
                    }
                    if (!is_int($publication['expected_page_size']) || $publication['expected_page_size'] < 512 || (($publication['expected_page_size'] & ($publication['expected_page_size'] - 1)) !== 0)) {
                        throw new \InvalidArgumentException('SQLite WAL current-source next194 publication page size must be a power of two at least 512');
                    }
                    if (!is_array($publication['reader_page_numbers']) || $publication['reader_page_numbers'] === [] || !is_array($publication['reader_next_sources']) || $publication['reader_next_sources'] === [] || !is_array($publication['dependencies'])) {
                        throw new \InvalidArgumentException('SQLite WAL current-source next194 publication reader/dependency arrays are malformed');
                    }
                    foreach ($publication['reader_page_numbers'] as $pageNumber) {
                        if (!is_int($pageNumber) || $pageNumber < 1) {
                            throw new \InvalidArgumentException('SQLite WAL current-source next194 publication reader pages must be one-based integers');
                        }
                    }
                    foreach ($publication['reader_next_sources'] as $source) {
                        if (!is_string($source) || $source === '') {
                            throw new \InvalidArgumentException('SQLite WAL current-source next194 publication reader sources must be non-empty strings');
                        }
                    }
                }

                /**
                 * @param list<int> $values
                 * @return array<int,true>
                 */
                private static function intSet(array $values): array
                {
                    $set = [];
                    foreach ($values as $value) {
                        $set[$value] = true;
                    }

                    return $set;
                }

                /**
                 * @param list<string> $values
                 * @return array<string,true>
                 */
                private static function stringSet(array $values): array
                {
                    $set = [];
                    foreach ($values as $value) {
                        $set[$value] = true;
                    }

                    return $set;
                }

                /**
                 * @param array<string,mixed> $ticket
                 */
                private static function stringField(array $ticket, string $key, int $index): string
                {
                    if (!isset($ticket[$key]) || !is_string($ticket[$key]) || $ticket[$key] === '') {
                        throw new \InvalidArgumentException("SQLite WAL current-source next194 reader ticket {$index} {$key} must be a non-empty string");
                    }

                    return $ticket[$key];
                }

                /**
                 * @param array<string,mixed> $ticket
                 */
                private static function intField(array $ticket, string $key, int $index): int
                {
                    if (!isset($ticket[$key]) || !is_int($ticket[$key])) {
                        throw new \InvalidArgumentException("SQLite WAL current-source next194 reader ticket {$index} {$key} must be an integer");
                    }

                    return $ticket[$key];
                }
        };

        return $impl::sealReaderGeneration($publication, $readerTickets, $previousReaderEpoch, $requireExclusiveCheckpointLock);
    }

    public static function next195Plan(array $checkpoint, array $readers): array
    {
        $impl = new class {
                /**
                 * @param array<string,mixed> $checkpoint
                 * @param list<array<string,mixed>> $readers
                 * @return array<string,mixed>
                 */
                public static function plan(array $checkpoint, array $readers): array
                {
                    self::assertCheckpoint($checkpoint);
                    if ($readers === []) {
                        throw new \InvalidArgumentException('SQLite WAL hot-journal current-source next195 requires reader rows');
                    }

                    $token = $checkpoint['current_source_token'];
                    $tokenId = (string) $token['id'];
                    $epoch = (int) $token['epoch'];
                    $databasePath = (string) $checkpoint['database_path'];
                    $walPath = (string) $checkpoint['wal_path'];
                    $journalPath = (string) ($checkpoint['journal_path'] ?? ($databasePath . '-journal'));
                    $checkpointCookie = (int) $checkpoint['checkpoint_cookie'];
                    $schemaCookie = (int) $checkpoint['schema_cookie'];
                    $walSalt = (string) $checkpoint['wal_salt'];
                    $hotGeneration = (int) $checkpoint['hot_journal_generation'];
                    $savepointGeneration = (int) $checkpoint['savepoint_generation'];
                    $journalRemoved = (bool) $checkpoint['journal_removed'];
                    $checkpointPublished = (bool) $checkpoint['checkpoint_published'];

                    $rows = [];
                    foreach ($readers as $index => $reader) {
                        $rows[] = self::readerRow(
                            $reader,
                            $index,
                            $tokenId,
                            $epoch,
                            $checkpointCookie,
                            $schemaCookie,
                            $walSalt,
                            $hotGeneration,
                            $savepointGeneration,
                            $journalRemoved,
                            $checkpointPublished
                        );
                    }

                    $admitted = array_values(array_column(array_filter($rows, static fn (array $row): bool => $row['admitted']), 'name'));
                    $reopened = array_values(array_column(array_filter($rows, static fn (array $row): bool => !$row['admitted']), 'name'));
                    $guards = [
                        'checkpoint_published' => $checkpointPublished,
                        'hot_journal_removed' => $journalRemoved,
                        'reader_mix' => $admitted !== [] && $reopened !== [],
                        'current_source_token' => $tokenId !== '' && $epoch > 0,
                    ];
                    $blockedGuards = array_keys(array_filter($guards, static fn (bool $passed): bool => !$passed));
                    $canPublish = $blockedGuards === [];

                    return [
                        'status' => $canPublish
                            ? 'wal-hot-journal-savepoint-checkpoint-current-source-next195'
                            : 'wal-hot-journal-savepoint-checkpoint-current-source-blocked-next195',
                        'reason' => $canPublish
                            ? 'reader_retry_handles_match_hot_journal_savepoint_checkpoint_current_source'
                            : 'reader_retry_handles_do_not_prove_hot_journal_savepoint_checkpoint_current_source',
                        'database_path' => $databasePath,
                        'wal_path' => $walPath,
                        'journal_path' => $journalPath,
                        'current_source_token' => $token,
                        'checkpoint_cookie' => $checkpointCookie,
                        'schema_cookie' => $schemaCookie,
                        'wal_salt' => $walSalt,
                        'hot_journal_generation' => $hotGeneration,
                        'savepoint_generation' => $savepointGeneration,
                        'journal_removed' => $journalRemoved,
                        'checkpoint_published' => $checkpointPublished,
                        'reader_rows' => $rows,
                        'admitted_reader_names' => $admitted,
                        'reopen_reader_names' => $reopened,
                        'guard_names' => array_keys($guards),
                        'guard_matches' => array_values($guards),
                        'blocked_guard_names' => $blockedGuards,
                        'operation_names' => array_values(array_unique(array_merge(
                            is_array($checkpoint['operation_names'] ?? null) ? $checkpoint['operation_names'] : [],
                            ['admit_current_reader_retry_next195', 'force_reopen_stale_reader_retry_next195']
                        ))),
                        'reader_digest' => hash('sha256', json_encode($rows, JSON_THROW_ON_ERROR)),
                        'dependencies' => array_values(array_unique(array_merge(
                            is_array($checkpoint['dependencies'] ?? null) ? $checkpoint['dependencies'] : [],
                            [
                                'sqlite-wal-hot-journal-savepoint-checkpoint-current-source-next195',
                                'sqlite-wal-hot-journal-reader-retry-current-source',
                                'wordpress-import-reader-reopen-after-hot-journal-checkpoint',
                            ]
                        ))),
                        'dependency_closure' => 'no new support component needed; reuses lane-local WAL checkpoint tokens, hot-journal generation markers, and reader retry metadata',
                        'non_overlap' => 'adds reader retry admission after hot-journal savepoint checkpoint publication; does not repeat WAL byte truncation, VFS writer apply, page-cache next191, or hot-journal checkpoint byte publication',
                    ];
                }

                /**
                 * @param array<string,mixed> $checkpoint
                 */
                private static function assertCheckpoint(array $checkpoint): void
                {
                    foreach (['database_path', 'wal_path', 'current_source_token', 'checkpoint_cookie', 'schema_cookie', 'wal_salt', 'hot_journal_generation', 'savepoint_generation', 'journal_removed', 'checkpoint_published'] as $key) {
                        if (!array_key_exists($key, $checkpoint)) {
                            throw new \InvalidArgumentException("SQLite WAL hot-journal current-source next195 missing checkpoint {$key}");
                        }
                    }
                    if (!is_array($checkpoint['current_source_token'])) {
                        throw new \InvalidArgumentException('SQLite WAL hot-journal current-source next195 token must be an array');
                    }
                    $token = $checkpoint['current_source_token'];
                    if (($token['id'] ?? '') === '' || (int) ($token['epoch'] ?? 0) <= 0) {
                        throw new \InvalidArgumentException('SQLite WAL hot-journal current-source next195 token is invalid');
                    }
                    if ((string) $checkpoint['database_path'] === '' || (string) $checkpoint['wal_path'] === '') {
                        throw new \InvalidArgumentException('SQLite WAL hot-journal current-source next195 paths are required');
                    }
                    if ((int) $checkpoint['checkpoint_cookie'] <= 0 || (int) $checkpoint['schema_cookie'] <= 0) {
                        throw new \InvalidArgumentException('SQLite WAL hot-journal current-source next195 cookies must be positive');
                    }
                    if ((string) $checkpoint['wal_salt'] === '') {
                        throw new \InvalidArgumentException('SQLite WAL hot-journal current-source next195 WAL salt is required');
                    }
                    if ((int) $checkpoint['hot_journal_generation'] <= 0 || (int) $checkpoint['savepoint_generation'] <= 0) {
                        throw new \InvalidArgumentException('SQLite WAL hot-journal current-source next195 generations must be positive');
                    }
                }

                /**
                 * @param array<string,mixed> $reader
                 * @return array<string,mixed>
                 */
                private static function readerRow(
                    array $reader,
                    int $index,
                    string $tokenId,
                    int $epoch,
                    int $checkpointCookie,
                    int $schemaCookie,
                    string $walSalt,
                    int $hotGeneration,
                    int $savepointGeneration,
                    bool $journalRemoved,
                    bool $checkpointPublished
                ): array {
                    foreach (['name', 'page', 'source_id', 'epoch', 'observed_checkpoint_cookie', 'observed_schema_cookie', 'observed_wal_salt', 'observed_hot_journal_generation', 'observed_savepoint_generation'] as $key) {
                        if (!array_key_exists($key, $reader)) {
                            throw new \InvalidArgumentException("SQLite WAL hot-journal current-source next195 missing reader {$key}");
                        }
                    }
                    $name = (string) $reader['name'];
                    $page = (int) $reader['page'];
                    if ($name === '' || $page <= 0) {
                        throw new \InvalidArgumentException('SQLite WAL hot-journal current-source next195 reader name/page is invalid');
                    }

                    $checks = [
                        'source_token' => (string) $reader['source_id'] === $tokenId,
                        'source_epoch' => (int) $reader['epoch'] === $epoch,
                        'checkpoint_cookie' => (int) $reader['observed_checkpoint_cookie'] === $checkpointCookie,
                        'schema_cookie' => (int) $reader['observed_schema_cookie'] === $schemaCookie,
                        'wal_salt' => (string) $reader['observed_wal_salt'] === $walSalt,
                        'hot_journal_generation' => (int) $reader['observed_hot_journal_generation'] === $hotGeneration,
                        'savepoint_generation' => (int) $reader['observed_savepoint_generation'] === $savepointGeneration,
                        'journal_removed' => $journalRemoved,
                        'checkpoint_published' => $checkpointPublished,
                        'not_dirty' => ($reader['dirty'] ?? false) !== true,
                        'not_closed' => ($reader['closed'] ?? false) !== true,
                    ];
                    $failed = array_keys(array_filter($checks, static fn (bool $passed): bool => !$passed));
                    $admitted = $failed === [];

                    return [
                        'ordinal' => $index,
                        'name' => $name,
                        'page' => $page,
                        'admitted' => $admitted,
                        'requires_reopen' => !$admitted,
                        'failed_checks' => $failed,
                        'reason' => $admitted
                            ? 'reader_retry_matches_current_hot_journal_checkpoint_source'
                            : 'reader_retry_must_reopen_after_hot_journal_checkpoint',
                        'transition' => $name . '>' . ($admitted ? 'admit-current-reader' : 'reopen-current-reader') . ':next195',
                        'image_sha256' => isset($reader['image_sha256']) ? (string) $reader['image_sha256'] : null,
                    ];
                }
        };

        return $impl::plan($checkpoint, $readers);
    }

    public static function next196Plan(
        array $basePlan,
        SQLiteWal $currentWal,
        string $currentWalBytes,
        string $persistedWalBytes,
        string $mode,
        array $statements,
        array $readers,
        ?int $readerEndFrame = null
    ): array
    {
        $impl = new class {
                /**
                 * @param array<string,mixed> $basePlan
                 * @param list<array{name:string,observed_wal_digest?:string,requires_wal_sidecar?:bool,closed?:bool,dirty?:bool}> $statements
                 * @param list<array{name:string,observed_wal_digest?:string,pinned?:bool,closed?:bool,dirty?:bool}> $readers
                 * @return array<string,mixed>
                 */
                public static function plan(
                    array $basePlan,
                    SQLiteWal $currentWal,
                    string $currentWalBytes,
                    string $persistedWalBytes,
                    string $mode,
                    array $statements,
                    array $readers,
                    ?int $readerEndFrame = null
                ): array {
                    if (($basePlan['status'] ?? null) !== 'wal-hot-journal-savepoint-checkpoint-current-source-next192') {
                        throw new \InvalidArgumentException('SQLite WAL hot-journal savepoint checkpoint current-source next196 requires an admitted next192 base plan');
                    }
                    if (!in_array($mode, ['truncate', 'restart', 'preserve_busy'], true)) {
                        throw new \InvalidArgumentException('SQLite WAL hot-journal savepoint checkpoint current-source next196 requires truncate, restart, or preserve_busy mode');
                    }
                    if ($statements === [] || $readers === []) {
                        throw new \InvalidArgumentException('SQLite WAL hot-journal savepoint checkpoint current-source next196 requires statement and reader rows');
                    }
                    if ($currentWalBytes === '') {
                        throw new \InvalidArgumentException('SQLite WAL hot-journal savepoint checkpoint current-source next196 requires current WAL bytes');
                    }
                    if (hash('sha256', $currentWal->toBytes()) !== hash('sha256', $currentWalBytes)) {
                        throw new \InvalidArgumentException('SQLite WAL hot-journal savepoint checkpoint current-source next196 current WAL bytes do not match parsed WAL');
                    }
                    if ($readerEndFrame !== null && ($readerEndFrame < 0 || $readerEndFrame > $currentWal->frameCount())) {
                        throw new \InvalidArgumentException('SQLite WAL hot-journal savepoint checkpoint current-source next196 reader frame is outside the current WAL');
                    }

                    $sidecar = self::sidecarDecision($currentWal, $currentWalBytes, $persistedWalBytes, $mode, $readerEndFrame);
                    $statementRows = [];
                    $admittedStatements = [];
                    $reprepareStatements = [];
                    foreach ($statements as $statement) {
                        $row = self::cacheDecision('statement', $statement, $sidecar);
                        $statementRows[] = $row;
                        if ($row['admitted']) {
                            $admittedStatements[] = $row['name'];
                        } else {
                            $reprepareStatements[] = $row['name'];
                        }
                    }

                    $readerRows = [];
                    $admittedReaders = [];
                    $reopenReaders = [];
                    foreach ($readers as $reader) {
                        $row = self::cacheDecision('reader', $reader, $sidecar);
                        $readerRows[] = $row;
                        if ($row['admitted']) {
                            $admittedReaders[] = $row['name'];
                        } else {
                            $reopenReaders[] = $row['name'];
                        }
                    }

                    $guardRows = [
                        [
                            'name' => 'base_checkpoint_page_images',
                            'matched' => ($basePlan['status'] ?? null) === 'wal-hot-journal-savepoint-checkpoint-current-source-next192',
                            'reason' => 'next192 checkpoint page-image publication must pass before WAL sidecar publication',
                        ],
                        [
                            'name' => 'wal_sidecar_publication',
                            'matched' => $sidecar['matched'],
                            'reason' => 'persisted WAL sidecar must match the checkpoint mode after hot-journal savepoint recovery',
                        ],
                        [
                            'name' => 'statement_sidecar_mix',
                            'matched' => $admittedStatements !== [] && $reprepareStatements !== [],
                            'reason' => 'statement cache retains rows that observed the published sidecar and reprepares stale rows',
                        ],
                        [
                            'name' => 'reader_sidecar_mix',
                            'matched' => $admittedReaders !== [] && $reopenReaders !== [],
                            'reason' => 'reader cache retains rows that observed the published sidecar and reopens stale rows',
                        ],
                    ];
                    $staleGuards = array_values(array_column(
                        array_filter($guardRows, static fn (array $row): bool => !$row['matched']),
                        'name'
                    ));
                    $status = $staleGuards === []
                        ? 'wal-hot-journal-savepoint-checkpoint-current-source-next196'
                        : 'wal-hot-journal-savepoint-checkpoint-current-source-blocked-next196';

                    return [
                        'status' => $status,
                        'reason' => $status === 'wal-hot-journal-savepoint-checkpoint-current-source-next196'
                            ? 'wal_sidecar_publication_matches_checkpoint_mode_after_hot_journal_savepoint'
                            : 'wal_sidecar_publication_blocks_current_source_reuse_after_hot_journal_savepoint',
                        'database_path' => $basePlan['database_path'] ?? null,
                        'journal_path' => $basePlan['journal_path'] ?? null,
                        'wal_path' => $basePlan['wal_path'] ?? null,
                        'page_size' => $basePlan['page_size'] ?? $currentWal->header->pageSize,
                        'base_status' => $basePlan['status'],
                        'base_page_image_digest' => $basePlan['page_image_digest'] ?? null,
                        'mode' => $mode,
                        'reader_end_frame' => $readerEndFrame,
                        'sidecar' => $sidecar,
                        'current_wal_digest' => hash('sha256', $currentWalBytes),
                        'persisted_wal_digest' => hash('sha256', $persistedWalBytes),
                        'persisted_wal_bytes_length' => strlen($persistedWalBytes),
                        'statement_rows' => $statementRows,
                        'reader_rows' => $readerRows,
                        'admitted_statement_names' => $admittedStatements,
                        'reprepare_statement_names' => $reprepareStatements,
                        'admitted_reader_names' => $admittedReaders,
                        'reopen_reader_names' => $reopenReaders,
                        'guard_rows' => $guardRows,
                        'guard_names' => array_column($guardRows, 'name'),
                        'guard_matches' => array_column($guardRows, 'matched'),
                        'stale_guard_names' => $staleGuards,
                        'operation_names' => array_values(array_merge(
                            $basePlan['operation_names'] ?? [],
                            ['verify_wal_sidecar_publication_current_source_next196'],
                            array_map(
                                static fn (array $row): string => $row['admitted']
                                    ? 'admit_wal_sidecar_current_source_next196'
                                    : 'reprepare_wal_sidecar_current_source_next196',
                                $statementRows
                            ),
                            array_map(
                                static fn (array $row): string => $row['admitted']
                                    ? 'retain_reader_wal_sidecar_next196'
                                    : 'reopen_reader_wal_sidecar_next196',
                                $readerRows
                            ),
                            ['publish_wal_sidecar_current_source_next196']
                        )),
                        'sidecar_digest' => hash('sha256', implode('|', array_merge(
                            [(string) ($basePlan['page_image_digest'] ?? ''), $mode, $sidecar['expected_digest'], $sidecar['actual_digest']],
                            array_column($statementRows, 'sidecar_transition'),
                            array_column($readerRows, 'sidecar_transition')
                        ))),
                        'dependencies' => array_values(array_unique(array_merge($basePlan['dependencies'] ?? [], [
                            'sqlite-wal-hot-journal-savepoint-checkpoint-current-source-next196',
                            'sqlite-wal-sidecar-publication-after-checkpoint',
                        ]))),
                        'dependency_closure' => 'no new support component needed; composes the accepted WAL parser/checkpoint page-image guard with bounded WAL sidecar reset, truncate, and reader-pinned preserve admission',
                        'non_overlap' => 'next196 verifies the persisted WAL sidecar after next192 page-image publication; it does not repeat next192 page digest checks, next188 hook checks, next185 generation checks, VFS savepoint rollback, rollback-journal apply, VFS sync/write wrappers, or WAL byte truncation planning',
                    ];
                }

                /**
                 * @return array<string,mixed>
                 */
                private static function sidecarDecision(SQLiteWal $currentWal, string $currentWalBytes, string $persistedWalBytes, string $mode, ?int $readerEndFrame): array
                {
                    $actualDigest = hash('sha256', $persistedWalBytes);
                    $currentDigest = hash('sha256', $currentWalBytes);
                    if ($mode === 'truncate') {
                        return [
                            'mode' => $mode,
                            'matched' => $persistedWalBytes === '',
                            'reason' => $persistedWalBytes === '' ? 'wal_sidecar_truncated_after_checkpoint' : 'wal_sidecar_not_truncated_after_checkpoint',
                            'expected_action' => 'truncate_wal',
                            'expected_digest' => hash('sha256', ''),
                            'actual_digest' => $actualDigest,
                            'actual_frame_count' => 0,
                            'actual_checkpoint_sequence' => null,
                            'next_checkpoint_sequence' => null,
                            'reader_preserved_current_wal' => false,
                        ];
                    }

                    if ($mode === 'preserve_busy') {
                        $matched = $readerEndFrame !== null && $readerEndFrame > 0 && hash_equals($currentDigest, $actualDigest);

                        return [
                            'mode' => $mode,
                            'matched' => $matched,
                            'reason' => $matched ? 'reader_pin_preserves_current_wal_sidecar' : 'reader_pin_preserve_wal_sidecar_mismatch',
                            'expected_action' => 'preserve_wal',
                            'expected_digest' => $currentDigest,
                            'actual_digest' => $actualDigest,
                            'actual_frame_count' => $matched ? $currentWal->frameCount() : null,
                            'actual_checkpoint_sequence' => $matched ? $currentWal->header->checkpointSequence : null,
                            'next_checkpoint_sequence' => null,
                            'reader_preserved_current_wal' => $matched,
                        ];
                    }

                    if ($persistedWalBytes === '') {
                        return [
                            'mode' => $mode,
                            'matched' => false,
                            'reason' => 'restart_checkpoint_missing_restarted_wal_header',
                            'expected_action' => 'restart_wal',
                            'expected_digest' => 'restart-generation',
                            'actual_digest' => $actualDigest,
                            'actual_frame_count' => 0,
                            'actual_checkpoint_sequence' => null,
                            'next_checkpoint_sequence' => (($currentWal->header->checkpointSequence + 1) & 0xffffffff),
                            'reader_preserved_current_wal' => false,
                        ];
                    }

                    $restartWal = SQLiteWal::parse($persistedWalBytes, $currentWal->header->pageSize, $currentWal->checksumsValidated);
                    $expectedSequence = (($currentWal->header->checkpointSequence + 1) & 0xffffffff);
                    $matched = $restartWal->frameCount() === 0
                        && $restartWal->header->checkpointSequence === $expectedSequence
                        && ($restartWal->header->salt1 !== $currentWal->header->salt1 || $restartWal->header->salt2 !== $currentWal->header->salt2);

                    return [
                        'mode' => $mode,
                        'matched' => $matched,
                        'reason' => $matched ? 'wal_sidecar_restarted_after_checkpoint' : 'wal_sidecar_restart_generation_mismatch',
                        'expected_action' => 'restart_wal',
                        'expected_digest' => hash('sha256', $persistedWalBytes),
                        'actual_digest' => $actualDigest,
                        'actual_frame_count' => $restartWal->frameCount(),
                        'actual_checkpoint_sequence' => $restartWal->header->checkpointSequence,
                        'next_checkpoint_sequence' => $expectedSequence,
                        'reader_preserved_current_wal' => false,
                    ];
                }

                /**
                 * @param array<string,mixed> $row
                 * @param array<string,mixed> $sidecar
                 * @return array<string,mixed>
                 */
                private static function cacheDecision(string $kind, array $row, array $sidecar): array
                {
                    $name = $row['name'] ?? null;
                    if (!is_string($name) || $name === '') {
                        throw new \InvalidArgumentException("SQLite WAL hot-journal savepoint checkpoint current-source next196 {$kind} name is required");
                    }
                    $observedDigest = $row['observed_wal_digest'] ?? null;
                    if (!is_string($observedDigest) || strlen($observedDigest) !== 64) {
                        throw new \InvalidArgumentException("SQLite WAL hot-journal savepoint checkpoint current-source next196 {$kind} observed WAL digest is required");
                    }

                    $requiresWal = (bool) ($row['requires_wal_sidecar'] ?? $row['pinned'] ?? false);
                    $admitted = (bool) $sidecar['matched'] && empty($row['closed']) && empty($row['dirty']);
                    $reason = $admitted ? "{$kind}_wal_sidecar_matches_checkpoint_publication" : "{$kind}_closed_or_dirty_before_wal_sidecar_publication";
                    if ($admitted && $observedDigest !== $sidecar['actual_digest']) {
                        $admitted = false;
                        $reason = "{$kind}_observed_wal_sidecar_predates_checkpoint_publication";
                    } elseif ($admitted && $requiresWal && $sidecar['expected_action'] === 'truncate_wal') {
                        $admitted = false;
                        $reason = "{$kind}_requires_wal_sidecar_after_truncate_checkpoint";
                    } elseif (!$sidecar['matched']) {
                        $admitted = false;
                        $reason = "{$kind}_wal_sidecar_publication_not_durable";
                    }

                    return array_merge($row, [
                        'admitted' => $admitted,
                        'sidecar_reason' => $reason,
                        'expected_wal_digest' => $sidecar['actual_digest'],
                        'observed_wal_digest' => $observedDigest,
                        'requires_wal_sidecar' => $requiresWal,
                        'sidecar_transition' => $name . '>' . ($admitted ? 'retain-wal-sidecar' : 'reprepare-wal-sidecar'),
                    ]);
                }
        };

        return $impl::plan($basePlan, $currentWal, $currentWalBytes, $persistedWalBytes, $mode, $statements, $readers, $readerEndFrame);
    }

    public static function next200AdmitDurableReaders(
        array $sealedGeneration,
        array $durabilityReceipts,
        string $expectedHotJournalDigest,
        int $expectedSavepointGeneration,
        string $expectedCheckpointDigest
    ): array
    {
        $impl = new class {
                /**
                 * @param array<string,mixed> $sealedGeneration
                 * @param list<array<string,mixed>> $durabilityReceipts
                 * @return array<string,mixed>
                 */
                public static function admitDurableReaders(
                    array $sealedGeneration,
                    array $durabilityReceipts,
                    string $expectedHotJournalDigest,
                    int $expectedSavepointGeneration,
                    string $expectedCheckpointDigest
                ): array {
                    self::assertGeneration($sealedGeneration);
                    if ($durabilityReceipts === []) {
                        throw new \InvalidArgumentException('SQLite WAL current-source next200 requires durability receipts');
                    }
                    if ($expectedHotJournalDigest === '' || $expectedCheckpointDigest === '') {
                        throw new \InvalidArgumentException('SQLite WAL current-source next200 expected digests must be non-empty strings');
                    }
                    if ($expectedSavepointGeneration < 1) {
                        throw new \InvalidArgumentException('SQLite WAL current-source next200 savepoint generation must be positive');
                    }

                    $blocked = [];
                    if (($sealedGeneration['status'] ?? '') !== 'wal-hot-journal-savepoint-checkpoint-current-source-next194') {
                        $blocked[] = 'next194_reader_generation_seal_required';
                    }
                    if (($sealedGeneration['can_expose_reopened_readers'] ?? false) !== true) {
                        $blocked[] = 'next194_reader_generation_not_exposable';
                    }

                    $allowedTickets = self::stringSet($sealedGeneration['reader_ticket_ids']);
                    $allowedPages = self::intSet($sealedGeneration['reader_pages']);
                    $expectedPublicationToken = (string) $sealedGeneration['publication_token'];
                    $previousReaderEpoch = (int) $sealedGeneration['previous_reader_epoch'];
                    $sealedReaderEpoch = (int) ($sealedGeneration['sealed_reader_epoch'] ?? 0);
                    $receiptRows = [];
                    $seenTickets = [];

                    foreach ($durabilityReceipts as $index => $receipt) {
                        if (!is_array($receipt)) {
                            throw new \InvalidArgumentException('SQLite WAL current-source next200 receipt rows must be arrays');
                        }
                        $ticketId = self::stringField($receipt, 'ticket_id', $index);
                        $pageNumber = self::intField($receipt, 'page_number', $index);
                        $readerEpoch = self::intField($receipt, 'reader_epoch', $index);
                        $publicationToken = self::stringField($receipt, 'publication_token', $index);
                        $hotJournalDigest = self::stringField($receipt, 'hot_journal_recovery_digest', $index);
                        $checkpointDigest = self::stringField($receipt, 'checkpoint_database_digest', $index);
                        $savepointGeneration = self::intField($receipt, 'savepoint_generation', $index);
                        $walSyncReceipt = (bool) ($receipt['wal_sync_receipt'] ?? false);
                        $databaseSyncReceipt = (bool) ($receipt['database_sync_receipt'] ?? false);
                        $directorySyncReceipt = (bool) ($receipt['directory_sync_receipt'] ?? false);
                        $readerReopened = (bool) ($receipt['reader_reopened_after_hot_journal'] ?? false);
                        $savepointReleased = (bool) ($receipt['savepoint_release_observed'] ?? false);

                        $rowBlocked = [];
                        if (isset($seenTickets[$ticketId])) {
                            $rowBlocked[] = 'duplicate_durability_receipt_ticket';
                        }
                        $seenTickets[$ticketId] = true;
                        if (!isset($allowedTickets[$ticketId])) {
                            $rowBlocked[] = 'durability_receipt_ticket_not_in_next194_generation';
                        }
                        if (!isset($allowedPages[$pageNumber])) {
                            $rowBlocked[] = 'durability_receipt_page_not_in_next194_generation';
                        }
                        if ($readerEpoch <= $previousReaderEpoch || $readerEpoch > $sealedReaderEpoch) {
                            $rowBlocked[] = 'durability_receipt_epoch_outside_sealed_generation';
                        }
                        if (!hash_equals($expectedPublicationToken, $publicationToken)) {
                            $rowBlocked[] = 'durability_receipt_publication_token_mismatch';
                        }
                        if (!hash_equals($expectedHotJournalDigest, $hotJournalDigest)) {
                            $rowBlocked[] = 'durability_receipt_hot_journal_digest_mismatch';
                        }
                        if (!hash_equals($expectedCheckpointDigest, $checkpointDigest)) {
                            $rowBlocked[] = 'durability_receipt_checkpoint_digest_mismatch';
                        }
                        if ($savepointGeneration !== $expectedSavepointGeneration) {
                            $rowBlocked[] = 'durability_receipt_savepoint_generation_mismatch';
                        }
                        if (!$walSyncReceipt) {
                            $rowBlocked[] = 'durability_receipt_missing_wal_sync';
                        }
                        if (!$databaseSyncReceipt) {
                            $rowBlocked[] = 'durability_receipt_missing_database_sync';
                        }
                        if (!$directorySyncReceipt) {
                            $rowBlocked[] = 'durability_receipt_missing_directory_sync';
                        }
                        if (!$readerReopened) {
                            $rowBlocked[] = 'durability_receipt_reader_not_reopened_after_hot_journal';
                        }
                        if (!$savepointReleased) {
                            $rowBlocked[] = 'durability_receipt_savepoint_release_not_observed';
                        }

                        foreach ($rowBlocked as $reason) {
                            $blocked[] = $reason;
                        }
                        $receiptRows[] = [
                            'ticket_id' => $ticketId,
                            'page_number' => $pageNumber,
                            'reader_epoch' => $readerEpoch,
                            'publication_token_matches' => hash_equals($expectedPublicationToken, $publicationToken),
                            'hot_journal_digest_matches' => hash_equals($expectedHotJournalDigest, $hotJournalDigest),
                            'checkpoint_digest_matches' => hash_equals($expectedCheckpointDigest, $checkpointDigest),
                            'savepoint_generation' => $savepointGeneration,
                            'wal_sync_receipt' => $walSyncReceipt,
                            'database_sync_receipt' => $databaseSyncReceipt,
                            'directory_sync_receipt' => $directorySyncReceipt,
                            'reader_reopened_after_hot_journal' => $readerReopened,
                            'savepoint_release_observed' => $savepointReleased,
                            'blocked_reasons' => $rowBlocked,
                        ];
                    }

                    foreach (array_keys($allowedTickets) as $ticketId) {
                        if (!isset($seenTickets[$ticketId])) {
                            $blocked[] = 'missing_durability_receipt_for_sealed_reader_ticket';
                            break;
                        }
                    }

                    $blocked = array_values(array_unique($blocked));
                    $ready = $blocked === [];

                    return [
                        'status' => $ready
                            ? 'wal-hot-journal-savepoint-checkpoint-current-source-next200'
                            : 'wal-hot-journal-savepoint-checkpoint-current-source-blocked-next200',
                        'reason' => $ready
                            ? 'sealed_reader_generation_has_hot_journal_savepoint_checkpoint_durability_receipts'
                            : 'sealed_reader_generation_waits_for_hot_journal_savepoint_checkpoint_durability',
                        'database_path' => $sealedGeneration['database_path'],
                        'wal_path' => $sealedGeneration['wal_path'],
                        'journal_path' => $sealedGeneration['journal_path'],
                        'publication_token' => $expectedPublicationToken,
                        'previous_reader_epoch' => $previousReaderEpoch,
                        'sealed_reader_epoch' => $sealedReaderEpoch,
                        'receipt_count' => count($receiptRows),
                        'receipt_ticket_ids' => array_column($receiptRows, 'ticket_id'),
                        'receipt_pages' => array_column($receiptRows, 'page_number'),
                        'receipt_rows' => $receiptRows,
                        'expected_hot_journal_recovery_digest' => $expectedHotJournalDigest,
                        'expected_savepoint_generation' => $expectedSavepointGeneration,
                        'expected_checkpoint_database_digest' => $expectedCheckpointDigest,
                        'can_admit_durable_readers' => $ready,
                        'blocked_reasons' => $blocked,
                        'durability_digest' => hash('sha256', implode('|', array_map(
                            static fn (array $row): string => implode(':', [
                                (string) $row['ticket_id'],
                                (string) $row['page_number'],
                                (string) $row['reader_epoch'],
                                $row['hot_journal_digest_matches'] ? 'hot' : 'badhot',
                                $row['checkpoint_digest_matches'] ? 'checkpoint' : 'badcheckpoint',
                                $row['wal_sync_receipt'] ? 'wal-sync' : 'no-wal-sync',
                                $row['database_sync_receipt'] ? 'db-sync' : 'no-db-sync',
                            ]),
                            $receiptRows
                        ))),
                        'dependencies' => array_values(array_unique(array_merge(
                            $sealedGeneration['dependencies'],
                            [
                                'sqlite-wal-hot-journal-savepoint-checkpoint-current-source-next200',
                                'sqlite-hot-journal-savepoint-checkpoint-durable-reader-admission',
                                'wordpress-import-retry-checkpoint-durable-reader-admission',
                            ]
                        ))),
                        'dependency_closure' => 'no new support component needed; reuses next194 reader-generation sealing plus existing WAL, checkpoint, directory-sync, and savepoint-release receipts',
                        'non_overlap' => 'next200 adds hot-journal recovery digest, savepoint generation, and checkpoint database digest durability admission after next194 reader sealing; it does not repeat WAL byte truncation, checkpoint file-map publication, VFS writer/sync application, or reopened reader ticket sealing',
                    ];
                }

                /**
                 * @param array<string,mixed> $generation
                 */
                private static function assertGeneration(array $generation): void
                {
                    foreach (['database_path', 'wal_path', 'journal_path', 'publication_token', 'previous_reader_epoch', 'sealed_reader_epoch', 'reader_ticket_ids', 'reader_pages', 'dependencies'] as $key) {
                        if (!array_key_exists($key, $generation)) {
                            throw new \InvalidArgumentException("SQLite WAL current-source next200 generation missing {$key}");
                        }
                    }
                    foreach (['database_path', 'wal_path', 'journal_path', 'publication_token'] as $key) {
                        if (!is_string($generation[$key]) || $generation[$key] === '') {
                            throw new \InvalidArgumentException("SQLite WAL current-source next200 generation {$key} must be a non-empty string");
                        }
                    }
                    if (!is_int($generation['previous_reader_epoch']) || !is_int($generation['sealed_reader_epoch'])) {
                        throw new \InvalidArgumentException('SQLite WAL current-source next200 generation epochs must be integers');
                    }
                    if (!is_array($generation['reader_ticket_ids']) || $generation['reader_ticket_ids'] === [] || !is_array($generation['reader_pages']) || $generation['reader_pages'] === [] || !is_array($generation['dependencies'])) {
                        throw new \InvalidArgumentException('SQLite WAL current-source next200 generation arrays are malformed');
                    }
                    foreach ($generation['reader_ticket_ids'] as $ticketId) {
                        if (!is_string($ticketId) || $ticketId === '') {
                            throw new \InvalidArgumentException('SQLite WAL current-source next200 reader ticket ids must be non-empty strings');
                        }
                    }
                    foreach ($generation['reader_pages'] as $pageNumber) {
                        if (!is_int($pageNumber) || $pageNumber < 1) {
                            throw new \InvalidArgumentException('SQLite WAL current-source next200 reader pages must be one-based integers');
                        }
                    }
                }

                /**
                 * @param list<int> $values
                 * @return array<int,true>
                 */
                private static function intSet(array $values): array
                {
                    $set = [];
                    foreach ($values as $value) {
                        $set[$value] = true;
                    }

                    return $set;
                }

                /**
                 * @param list<string> $values
                 * @return array<string,true>
                 */
                private static function stringSet(array $values): array
                {
                    $set = [];
                    foreach ($values as $value) {
                        $set[$value] = true;
                    }

                    return $set;
                }

                /**
                 * @param array<string,mixed> $row
                 */
                private static function stringField(array $row, string $key, int $index): string
                {
                    if (!isset($row[$key]) || !is_string($row[$key]) || $row[$key] === '') {
                        throw new \InvalidArgumentException("SQLite WAL current-source next200 receipt {$index} {$key} must be a non-empty string");
                    }

                    return $row[$key];
                }

                /**
                 * @param array<string,mixed> $row
                 */
                private static function intField(array $row, string $key, int $index): int
                {
                    if (!isset($row[$key]) || !is_int($row[$key])) {
                        throw new \InvalidArgumentException("SQLite WAL current-source next200 receipt {$index} {$key} must be an integer");
                    }

                    return $row[$key];
                }
        };

        return $impl::admitDurableReaders($sealedGeneration, $durabilityReceipts, $expectedHotJournalDigest, $expectedSavepointGeneration, $expectedCheckpointDigest);
    }

    public static function next202Plan(
        array $sidecarPublication,
        string $checkpointedDatabaseBytes,
        string $hotJournalBytes,
        bool $savepointReleased,
        bool $exclusiveCheckpointLock,
        bool $databaseSyncReceipt,
        bool $walSyncReceipt,
        bool $directorySyncReceipt,
        array $handles
    ): array
    {
        $impl = new class {
                /**
                 * @param array<string,mixed> $sidecarPublication
                 * @param list<array<string,mixed>> $handles
                 * @return array<string,mixed>
                 */
                public static function plan(
                    array $sidecarPublication,
                    string $checkpointedDatabaseBytes,
                    string $hotJournalBytes,
                    bool $savepointReleased,
                    bool $exclusiveCheckpointLock,
                    bool $databaseSyncReceipt,
                    bool $walSyncReceipt,
                    bool $directorySyncReceipt,
                    array $handles
                ): array {
                    self::assertPublication($sidecarPublication);
                    if ($checkpointedDatabaseBytes === '') {
                        throw new \InvalidArgumentException('SQLite WAL hot-journal savepoint checkpoint current-source next202 requires checkpointed database bytes');
                    }
                    if ($handles === []) {
                        throw new \InvalidArgumentException('SQLite WAL hot-journal savepoint checkpoint current-source next202 requires handle rows');
                    }

                    $databaseDigest = hash('sha256', $checkpointedDatabaseBytes);
                    $hotJournalDigest = hash('sha256', $hotJournalBytes);
                    $expectedDatabaseDigest = (string) ($sidecarPublication['checkpointed_database_digest'] ?? $databaseDigest);
                    $expectedWalDigest = (string) $sidecarPublication['persisted_wal_digest'];
                    $expectedSidecarDigest = (string) $sidecarPublication['sidecar_digest'];
                    $expectedMode = (string) $sidecarPublication['mode'];
                    $baseOperations = is_array($sidecarPublication['operation_names'] ?? null)
                        ? $sidecarPublication['operation_names']
                        : [];

                    $rows = [];
                    foreach ($handles as $index => $handle) {
                        $rows[] = self::handleRow(
                            $handle,
                            $index,
                            $expectedDatabaseDigest,
                            $expectedWalDigest,
                            $expectedSidecarDigest,
                            $expectedMode,
                            $hotJournalBytes,
                            $savepointReleased,
                            $exclusiveCheckpointLock,
                            $databaseSyncReceipt,
                            $walSyncReceipt,
                            $directorySyncReceipt
                        );
                    }

                    $admitted = array_values(array_column(array_filter($rows, static fn (array $row): bool => $row['admitted']), 'name'));
                    $reopened = array_values(array_column(array_filter($rows, static fn (array $row): bool => !$row['admitted']), 'name'));
                    $guards = [
                        [
                            'name' => 'next196_sidecar_publication',
                            'matched' => ($sidecarPublication['status'] ?? '') === 'wal-hot-journal-savepoint-checkpoint-current-source-next196',
                            'reason' => 'WAL sidecar publication must have matched the checkpoint mode before current handles are reused',
                        ],
                        [
                            'name' => 'checkpointed_database_digest',
                            'matched' => hash_equals($expectedDatabaseDigest, $databaseDigest),
                            'reason' => 'database image digest must match the checkpointed page publication used by the handles',
                        ],
                        [
                            'name' => 'hot_journal_removed',
                            'matched' => $hotJournalBytes === '',
                            'reason' => 'hot rollback journal bytes must be absent before current-source handles are admitted',
                        ],
                        [
                            'name' => 'savepoint_released',
                            'matched' => $savepointReleased,
                            'reason' => 'savepoint rollback state must be closed before the checkpoint generation becomes reusable',
                        ],
                        [
                            'name' => 'exclusive_checkpoint_lock',
                            'matched' => $exclusiveCheckpointLock,
                            'reason' => 'checkpoint publication requires the exclusive checkpoint lock receipt',
                        ],
                        [
                            'name' => 'sync_receipts',
                            'matched' => $databaseSyncReceipt && $walSyncReceipt && $directorySyncReceipt,
                            'reason' => 'database, WAL sidecar, and containing directory sync receipts must all be present',
                        ],
                        [
                            'name' => 'handle_mix',
                            'matched' => $admitted !== [] && $reopened !== [],
                            'reason' => 'the plan must retain matching handles and reopen stale handles',
                        ],
                    ];
                    $blocked = array_values(array_column(
                        array_filter($guards, static fn (array $row): bool => !$row['matched']),
                        'name'
                    ));
                    $ready = $blocked === [];

                    return [
                        'status' => $ready
                            ? 'wal-hot-journal-savepoint-checkpoint-current-source-next202'
                            : 'wal-hot-journal-savepoint-checkpoint-current-source-blocked-next202',
                        'reason' => $ready
                            ? 'checkpoint_file_receipts_admit_current_source_handles_after_hot_journal_savepoint'
                            : 'checkpoint_file_receipts_block_current_source_handles_after_hot_journal_savepoint',
                        'database_path' => $sidecarPublication['database_path'] ?? null,
                        'journal_path' => $sidecarPublication['journal_path'] ?? null,
                        'wal_path' => $sidecarPublication['wal_path'] ?? null,
                        'mode' => $expectedMode,
                        'database_digest' => $databaseDigest,
                        'expected_database_digest' => $expectedDatabaseDigest,
                        'persisted_wal_digest' => $expectedWalDigest,
                        'sidecar_digest' => $expectedSidecarDigest,
                        'hot_journal_digest' => $hotJournalDigest,
                        'hot_journal_bytes_length' => strlen($hotJournalBytes),
                        'savepoint_released' => $savepointReleased,
                        'exclusive_checkpoint_lock' => $exclusiveCheckpointLock,
                        'database_sync_receipt' => $databaseSyncReceipt,
                        'wal_sync_receipt' => $walSyncReceipt,
                        'directory_sync_receipt' => $directorySyncReceipt,
                        'handle_rows' => $rows,
                        'admitted_handle_names' => $admitted,
                        'reopen_handle_names' => $reopened,
                        'guard_rows' => $guards,
                        'guard_names' => array_column($guards, 'name'),
                        'guard_matches' => array_column($guards, 'matched'),
                        'blocked_guard_names' => $blocked,
                        'operation_names' => array_values(array_unique(array_merge(
                            $baseOperations,
                            [
                                'verify_checkpoint_file_receipts_current_source_next202',
                                'publish_current_source_file_receipts_next202',
                                'admit_or_reopen_current_source_handles_next202',
                            ]
                        ))),
                        'receipt_digest' => hash('sha256', json_encode([
                            'database' => $databaseDigest,
                            'wal' => $expectedWalDigest,
                            'sidecar' => $expectedSidecarDigest,
                            'hot' => $hotJournalDigest,
                            'released' => $savepointReleased,
                            'lock' => $exclusiveCheckpointLock,
                            'sync' => [$databaseSyncReceipt, $walSyncReceipt, $directorySyncReceipt],
                            'rows' => $rows,
                        ], JSON_THROW_ON_ERROR)),
                        'dependencies' => array_values(array_unique(array_merge(
                            is_array($sidecarPublication['dependencies'] ?? null) ? $sidecarPublication['dependencies'] : [],
                            [
                                'sqlite-wal-hot-journal-savepoint-checkpoint-current-source-next202',
                                'sqlite-wal-checkpoint-file-receipt-admission',
                                'wordpress-import-hot-journal-savepoint-checkpoint-handle-reopen',
                            ]
                        ))),
                        'dependency_closure' => 'no new support component needed; reuses accepted WAL sidecar publication plus lane-local file receipt, lock receipt, sync receipt, and handle cache metadata',
                        'non_overlap' => 'next202 admits current-source file handles after next196 sidecar publication by checking database/WAL/hot-journal/savepoint/sync receipts; it does not repeat WAL byte truncation, rollback-journal apply, VFS savepoint rollback, checkpoint transaction planning, VFS sync apply, or next196 sidecar digest classification',
                    ];
                }

                /**
                 * @param array<string,mixed> $publication
                 */
                private static function assertPublication(array $publication): void
                {
                    foreach (['status', 'mode', 'persisted_wal_digest', 'sidecar_digest'] as $key) {
                        if (!array_key_exists($key, $publication)) {
                            throw new \InvalidArgumentException("SQLite WAL hot-journal savepoint checkpoint current-source next202 missing publication {$key}");
                        }
                    }
                    foreach (['mode', 'persisted_wal_digest', 'sidecar_digest'] as $key) {
                        if (!is_string($publication[$key]) || $publication[$key] === '') {
                            throw new \InvalidArgumentException("SQLite WAL hot-journal savepoint checkpoint current-source next202 publication {$key} must be a non-empty string");
                        }
                    }
                    if (!in_array($publication['mode'], ['truncate', 'restart', 'preserve_busy'], true)) {
                        throw new \InvalidArgumentException('SQLite WAL hot-journal savepoint checkpoint current-source next202 publication mode is invalid');
                    }
                }

                /**
                 * @param array<string,mixed> $handle
                 * @return array<string,mixed>
                 */
                private static function handleRow(
                    array $handle,
                    int $index,
                    string $expectedDatabaseDigest,
                    string $expectedWalDigest,
                    string $expectedSidecarDigest,
                    string $expectedMode,
                    string $hotJournalBytes,
                    bool $savepointReleased,
                    bool $exclusiveCheckpointLock,
                    bool $databaseSyncReceipt,
                    bool $walSyncReceipt,
                    bool $directorySyncReceipt
                ): array {
                    foreach (['name', 'kind', 'observed_database_digest', 'observed_wal_digest', 'observed_sidecar_digest', 'observed_mode'] as $key) {
                        if (!array_key_exists($key, $handle)) {
                            throw new \InvalidArgumentException("SQLite WAL hot-journal savepoint checkpoint current-source next202 missing handle {$key}");
                        }
                    }

                    $name = (string) $handle['name'];
                    $kind = (string) $handle['kind'];
                    if ($name === '' || !in_array($kind, ['statement', 'reader', 'writer'], true)) {
                        throw new \InvalidArgumentException('SQLite WAL hot-journal savepoint checkpoint current-source next202 handle name/kind is invalid');
                    }

                    $checks = [
                        'database_digest' => hash_equals($expectedDatabaseDigest, (string) $handle['observed_database_digest']),
                        'wal_digest' => hash_equals($expectedWalDigest, (string) $handle['observed_wal_digest']),
                        'sidecar_digest' => hash_equals($expectedSidecarDigest, (string) $handle['observed_sidecar_digest']),
                        'checkpoint_mode' => (string) $handle['observed_mode'] === $expectedMode,
                        'hot_journal_removed' => $hotJournalBytes === '',
                        'savepoint_released' => $savepointReleased,
                        'exclusive_checkpoint_lock' => $exclusiveCheckpointLock,
                        'database_sync_receipt' => $databaseSyncReceipt,
                        'wal_sync_receipt' => $walSyncReceipt,
                        'directory_sync_receipt' => $directorySyncReceipt,
                        'not_dirty' => ($handle['dirty'] ?? false) !== true,
                        'not_closed' => ($handle['closed'] ?? false) !== true,
                    ];
                    if (($handle['requires_wal_sidecar'] ?? false) === true && $expectedMode === 'truncate') {
                        $checks['wal_sidecar_required_after_truncate'] = false;
                    }

                    $failed = array_keys(array_filter($checks, static fn (bool $passed): bool => !$passed));
                    $admitted = $failed === [];

                    return [
                        'ordinal' => $index,
                        'name' => $name,
                        'kind' => $kind,
                        'admitted' => $admitted,
                        'requires_reopen' => !$admitted,
                        'failed_checks' => $failed,
                        'reason' => $admitted
                            ? 'handle_receipts_match_checkpoint_current_source'
                            : 'handle_must_reopen_for_checkpoint_current_source',
                        'transition' => $name . '>' . ($admitted ? 'admit-current-source-handle' : 'reopen-current-source-handle') . ':next202',
                        'observed_database_digest' => (string) $handle['observed_database_digest'],
                        'observed_wal_digest' => (string) $handle['observed_wal_digest'],
                        'observed_sidecar_digest' => (string) $handle['observed_sidecar_digest'],
                        'observed_mode' => (string) $handle['observed_mode'],
                        'requires_wal_sidecar' => (bool) ($handle['requires_wal_sidecar'] ?? false),
                    ];
                }
        };

        return $impl::plan($sidecarPublication, $checkpointedDatabaseBytes, $hotJournalBytes, $savepointReleased, $exclusiveCheckpointLock, $databaseSyncReceipt, $walSyncReceipt, $directorySyncReceipt, $handles);
    }

    public static function next203Plan(array $basePlan, string $checkpointedDatabaseBytes, array $leases): array
    {
        $impl = new class {
                /**
                 * @param array<string,mixed> $basePlan
                 * @param list<array{name:string,root_pages:list<int>,observed_wal_digest:string,observed_page_digests:array<int,string>,closed?:bool,dirty?:bool,requires_wal_sidecar?:bool}> $leases
                 * @return array<string,mixed>
                 */
                public static function plan(array $basePlan, string $checkpointedDatabaseBytes, array $leases): array
                {
                    if (($basePlan['status'] ?? null) !== 'wal-hot-journal-savepoint-checkpoint-current-source-next196') {
                        throw new \InvalidArgumentException('SQLite WAL hot-journal savepoint checkpoint current-source next203 requires an admitted next196 base plan');
                    }

                    $pageSize = $basePlan['page_size'] ?? null;
                    if (!is_int($pageSize) || $pageSize <= 0) {
                        throw new \InvalidArgumentException('SQLite WAL hot-journal savepoint checkpoint current-source next203 requires a positive page size');
                    }
                    if ($checkpointedDatabaseBytes === '' || strlen($checkpointedDatabaseBytes) % $pageSize !== 0) {
                        throw new \InvalidArgumentException('SQLite WAL hot-journal savepoint checkpoint current-source next203 requires complete checkpointed database pages');
                    }
                    if ($leases === []) {
                        throw new \InvalidArgumentException('SQLite WAL hot-journal savepoint checkpoint current-source next203 requires page-cache lease rows');
                    }

                    $expectedWalDigest = $basePlan['sidecar']['actual_digest'] ?? $basePlan['persisted_wal_digest'] ?? null;
                    if (!is_string($expectedWalDigest) || strlen($expectedWalDigest) !== 64) {
                        throw new \InvalidArgumentException('SQLite WAL hot-journal savepoint checkpoint current-source next203 requires the published WAL sidecar digest');
                    }

                    $expectedPageDigests = self::pageDigests($checkpointedDatabaseBytes, $pageSize);
                    $leaseRows = [];
                    $admitted = [];
                    $reopen = [];
                    foreach ($leases as $lease) {
                        $row = self::leaseDecision($lease, $expectedWalDigest, $expectedPageDigests, $pageSize);
                        $leaseRows[] = $row;
                        if ($row['admitted']) {
                            $admitted[] = $row['name'];
                        } else {
                            $reopen[] = $row['name'];
                        }
                    }

                    $sidecarMatched = (bool) ($basePlan['sidecar']['matched'] ?? false);
                    $guardRows = [
                        [
                            'name' => 'base_wal_sidecar_publication',
                            'matched' => $sidecarMatched,
                            'reason' => 'next196 WAL sidecar publication must be durable before page-cache leases are reused',
                        ],
                        [
                            'name' => 'checkpointed_database_image',
                            'matched' => $expectedPageDigests !== [],
                            'reason' => 'checkpointed database image supplies the canonical page digests for cache reuse',
                        ],
                        [
                            'name' => 'lease_reuse_mix',
                            'matched' => $admitted !== [] && $reopen !== [],
                            'reason' => 'current leases are retained while stale WAL/page-cache leases are reopened',
                        ],
                    ];
                    $staleGuards = array_values(array_column(
                        array_filter($guardRows, static fn (array $row): bool => !$row['matched']),
                        'name'
                    ));
                    $status = $staleGuards === []
                        ? 'wal-hot-journal-savepoint-checkpoint-current-source-next203'
                        : 'wal-hot-journal-savepoint-checkpoint-current-source-blocked-next203';

                    return [
                        'status' => $status,
                        'reason' => $status === 'wal-hot-journal-savepoint-checkpoint-current-source-next203'
                            ? 'wal_sidecar_and_checkpoint_page_cache_leases_match_current_source'
                            : 'wal_sidecar_or_checkpoint_page_cache_leases_block_current_source_reuse',
                        'base_status' => $basePlan['status'],
                        'database_path' => $basePlan['database_path'] ?? null,
                        'journal_path' => $basePlan['journal_path'] ?? null,
                        'wal_path' => $basePlan['wal_path'] ?? null,
                        'page_size' => $pageSize,
                        'mode' => $basePlan['mode'] ?? null,
                        'checkpointed_database_digest' => hash('sha256', $checkpointedDatabaseBytes),
                        'checkpointed_page_count' => count($expectedPageDigests),
                        'expected_wal_digest' => $expectedWalDigest,
                        'expected_page_digests' => $expectedPageDigests,
                        'lease_rows' => $leaseRows,
                        'admitted_lease_names' => $admitted,
                        'reopen_lease_names' => $reopen,
                        'guard_rows' => $guardRows,
                        'guard_names' => array_column($guardRows, 'name'),
                        'guard_matches' => array_column($guardRows, 'matched'),
                        'stale_guard_names' => $staleGuards,
                        'operation_names' => array_values(array_merge(
                            $basePlan['operation_names'] ?? [],
                            ['verify_checkpoint_page_cache_leases_current_source_next203'],
                            array_map(
                                static fn (array $row): string => $row['admitted']
                                    ? 'retain_checkpoint_page_cache_lease_next203'
                                    : 'reopen_checkpoint_page_cache_lease_next203',
                                $leaseRows
                            )
                        )),
                        'lease_digest' => hash('sha256', implode('|', array_merge(
                            [$expectedWalDigest, hash('sha256', $checkpointedDatabaseBytes)],
                            array_column($leaseRows, 'lease_transition')
                        ))),
                        'dependencies' => array_values(array_unique(array_merge($basePlan['dependencies'] ?? [], [
                            'sqlite-wal-hot-journal-savepoint-checkpoint-current-source-next203',
                            'sqlite-checkpoint-page-cache-lease-fence',
                        ]))),
                        'dependency_closure' => 'no new support component needed; reuses the accepted WAL sidecar publication and checkpointed database page digests to fence page-cache lease reuse',
                        'non_overlap' => 'next203 validates page-cache lease reuse after next196 WAL sidecar publication; it does not repeat next196 sidecar restart/truncate/preserve decisions, next192 checkpoint page-image publication, reader retry admission, VFS savepoint rollback, rollback-journal apply, or WAL byte truncation planning',
                    ];
                }

                /**
                 * @return array<int,string>
                 */
                private static function pageDigests(string $databaseBytes, int $pageSize): array
                {
                    $digests = [];
                    $pageCount = intdiv(strlen($databaseBytes), $pageSize);
                    for ($pageNumber = 1; $pageNumber <= $pageCount; $pageNumber++) {
                        $offset = ($pageNumber - 1) * $pageSize;
                        $digests[$pageNumber] = hash('sha256', substr($databaseBytes, $offset, $pageSize));
                    }

                    return $digests;
                }

                /**
                 * @param array<string,mixed> $lease
                 * @param array<int,string> $expectedPageDigests
                 * @return array<string,mixed>
                 */
                private static function leaseDecision(array $lease, string $expectedWalDigest, array $expectedPageDigests, int $pageSize): array
                {
                    $name = $lease['name'] ?? null;
                    if (!is_string($name) || $name === '') {
                        throw new \InvalidArgumentException('SQLite WAL hot-journal savepoint checkpoint current-source next203 lease name is required');
                    }
                    $observedWalDigest = $lease['observed_wal_digest'] ?? null;
                    if (!is_string($observedWalDigest) || strlen($observedWalDigest) !== 64) {
                        throw new \InvalidArgumentException("SQLite WAL hot-journal savepoint checkpoint current-source next203 {$name} observed WAL digest is required");
                    }
                    $rootPages = $lease['root_pages'] ?? null;
                    if (!is_array($rootPages) || $rootPages === []) {
                        throw new \InvalidArgumentException("SQLite WAL hot-journal savepoint checkpoint current-source next203 {$name} root pages are required");
                    }
                    $observedPageDigests = $lease['observed_page_digests'] ?? null;
                    if (!is_array($observedPageDigests) || $observedPageDigests === []) {
                        throw new \InvalidArgumentException("SQLite WAL hot-journal savepoint checkpoint current-source next203 {$name} observed page digests are required");
                    }

                    $pageRows = [];
                    $missingPages = [];
                    $stalePages = [];
                    foreach ($rootPages as $pageNumber) {
                        if (!is_int($pageNumber) || $pageNumber <= 0) {
                            throw new \InvalidArgumentException("SQLite WAL hot-journal savepoint checkpoint current-source next203 {$name} root page must be positive");
                        }
                        $expectedDigest = $expectedPageDigests[$pageNumber] ?? null;
                        if ($expectedDigest === null) {
                            $missingPages[] = $pageNumber;
                            $pageRows[] = [
                                'page' => $pageNumber,
                                'matched' => false,
                                'reason' => 'page_outside_checkpointed_database_image',
                                'expected_digest' => null,
                                'observed_digest' => $observedPageDigests[$pageNumber] ?? null,
                            ];
                            continue;
                        }
                        $observedDigest = $observedPageDigests[$pageNumber] ?? null;
                        if (!is_string($observedDigest) || strlen($observedDigest) !== 64) {
                            throw new \InvalidArgumentException("SQLite WAL hot-journal savepoint checkpoint current-source next203 {$name} page digest is required");
                        }
                        $matched = hash_equals($expectedDigest, $observedDigest);
                        if (!$matched) {
                            $stalePages[] = $pageNumber;
                        }
                        $pageRows[] = [
                            'page' => $pageNumber,
                            'matched' => $matched,
                            'reason' => $matched ? 'checkpoint_page_digest_matches' : 'checkpoint_page_digest_stale',
                            'expected_digest' => $expectedDigest,
                            'observed_digest' => $observedDigest,
                        ];
                    }

                    $admitted = empty($lease['closed']) && empty($lease['dirty']);
                    $reason = $admitted ? 'lease_matches_wal_sidecar_and_checkpoint_pages' : 'lease_closed_or_dirty_before_checkpoint_page_publication';
                    if ($admitted && $observedWalDigest !== $expectedWalDigest) {
                        $admitted = false;
                        $reason = 'lease_observed_wal_sidecar_predates_checkpoint_publication';
                    } elseif ($admitted && ($missingPages !== [] || $stalePages !== [])) {
                        $admitted = false;
                        $reason = 'lease_observed_checkpoint_page_digest_is_stale';
                    } elseif ($admitted && (bool) ($lease['requires_wal_sidecar'] ?? false) && ($observedWalDigest === hash('sha256', ''))) {
                        $admitted = false;
                        $reason = 'lease_requires_wal_sidecar_after_truncate_checkpoint';
                    }

                    return array_merge($lease, [
                        'admitted' => $admitted,
                        'lease_reason' => $reason,
                        'expected_wal_digest' => $expectedWalDigest,
                        'observed_wal_digest' => $observedWalDigest,
                        'root_pages' => array_values($rootPages),
                        'page_size' => $pageSize,
                        'page_rows' => $pageRows,
                        'stale_pages' => $stalePages,
                        'missing_pages' => $missingPages,
                        'lease_transition' => $name . '>' . ($admitted ? 'retain-checkpoint-page-cache' : 'reopen-checkpoint-page-cache'),
                    ]);
                }
        };

        return $impl::plan($basePlan, $checkpointedDatabaseBytes, $leases);
    }

    public static function next205Plan(array $checkpoint, array $readers): array
    {
        $impl = new class {
                /**
                 * @param array<string,mixed> $checkpoint
                 * @param list<array<string,mixed>> $readers
                 * @return array<string,mixed>
                 */
                public static function plan(array $checkpoint, array $readers): array
                {
                    self::assertCheckpoint($checkpoint);
                    if ($readers === []) {
                        throw new \InvalidArgumentException('SQLite WAL hot-journal current-source next205 requires reader rows');
                    }

                    $token = $checkpoint['current_source_token'];
                    $tokenId = (string) $token['id'];
                    $epoch = (int) $token['epoch'];
                    $checkpointFrame = (int) $checkpoint['checkpoint_frame'];
                    $checkpointCookie = (int) $checkpoint['checkpoint_cookie'];
                    $schemaCookie = (int) $checkpoint['schema_cookie'];
                    $walSalt = (string) $checkpoint['wal_salt'];
                    $hotGeneration = (int) $checkpoint['hot_journal_generation'];
                    $savepointGeneration = (int) $checkpoint['savepoint_generation'];
                    $cacheGeneration = (int) $checkpoint['cache_generation'];
                    $pageDigests = self::pageDigests($checkpoint['page_digests']);
                    $published = (bool) $checkpoint['checkpoint_published'];
                    $journalRemoved = (bool) $checkpoint['journal_removed'];

                    $rows = [];
                    foreach ($readers as $index => $reader) {
                        $rows[] = self::readerRow(
                            $reader,
                            $index,
                            $tokenId,
                            $epoch,
                            $checkpointFrame,
                            $checkpointCookie,
                            $schemaCookie,
                            $walSalt,
                            $hotGeneration,
                            $savepointGeneration,
                            $cacheGeneration,
                            $pageDigests,
                            $published,
                            $journalRemoved
                        );
                    }

                    $admitted = array_values(array_column(array_filter($rows, static fn (array $row): bool => $row['admitted']), 'name'));
                    $reopened = array_values(array_column(array_filter($rows, static fn (array $row): bool => !$row['admitted']), 'name'));
                    $reasons = [];
                    foreach ($rows as $row) {
                        foreach ($row['failed_checks'] as $reason) {
                            $reasons[] = $reason;
                        }
                    }

                    $guards = [
                        'checkpoint_published' => $published,
                        'hot_journal_removed' => $journalRemoved,
                        'page_digest_map' => $pageDigests !== [],
                        'reader_mix' => $admitted !== [] && $reopened !== [],
                        'current_source_token' => $tokenId !== '' && $epoch > 0,
                    ];
                    $blocked = array_keys(array_filter($guards, static fn (bool $passed): bool => !$passed));

                    return [
                        'status' => $blocked === []
                            ? 'wal-hot-journal-savepoint-checkpoint-current-source-next205'
                            : 'wal-hot-journal-savepoint-checkpoint-current-source-blocked-next205',
                        'reason' => $blocked === []
                            ? 'reader_page_images_match_hot_journal_checkpoint_current_source'
                            : 'reader_page_images_do_not_prove_hot_journal_checkpoint_current_source',
                        'database_path' => (string) $checkpoint['database_path'],
                        'wal_path' => (string) $checkpoint['wal_path'],
                        'journal_path' => (string) ($checkpoint['journal_path'] ?? ((string) $checkpoint['database_path'] . '-journal')),
                        'current_source_token' => $token,
                        'checkpoint_frame' => $checkpointFrame,
                        'checkpoint_cookie' => $checkpointCookie,
                        'schema_cookie' => $schemaCookie,
                        'wal_salt' => $walSalt,
                        'hot_journal_generation' => $hotGeneration,
                        'savepoint_generation' => $savepointGeneration,
                        'cache_generation' => $cacheGeneration,
                        'page_numbers' => array_keys($pageDigests),
                        'checkpoint_published' => $published,
                        'journal_removed' => $journalRemoved,
                        'reader_rows' => $rows,
                        'admitted_reader_names' => $admitted,
                        'reopen_reader_names' => $reopened,
                        'reopen_reasons' => array_values(array_unique($reasons)),
                        'guard_names' => array_keys($guards),
                        'guard_matches' => array_values($guards),
                        'blocked_guard_names' => $blocked,
                        'operation_names' => array_values(array_unique(array_merge(
                            is_array($checkpoint['operation_names'] ?? null) ? $checkpoint['operation_names'] : [],
                            ['verify_reader_page_digest_next205', 'reopen_stale_page_cache_next205']
                        ))),
                        'reader_digest' => hash('sha256', json_encode($rows, JSON_THROW_ON_ERROR)),
                        'dependencies' => array_values(array_unique(array_merge(
                            is_array($checkpoint['dependencies'] ?? null) ? $checkpoint['dependencies'] : [],
                            [
                                'sqlite-wal-hot-journal-savepoint-checkpoint-current-source-next205',
                                'sqlite-wal-hot-journal-reader-page-image-current-source',
                                'wordpress-import-reader-cache-reopen-after-hot-journal-checkpoint',
                            ]
                        ))),
                        'dependency_closure' => 'no new support component needed; reuses checkpoint current-source tokens, WAL frame bounds, page-image digests, and reader cache metadata',
                        'non_overlap' => 'next205 adds per-page reader cache image validation after hot-journal savepoint checkpoint publication; it does not repeat next195 token-only reader retry admission, WAL byte truncation, VFS savepoint rollback apply, rollback-journal commit/apply, or checkpoint transaction planning',
                    ];
                }

                /**
                 * @param array<string,mixed> $checkpoint
                 */
                private static function assertCheckpoint(array $checkpoint): void
                {
                    foreach (['database_path', 'wal_path', 'current_source_token', 'checkpoint_frame', 'checkpoint_cookie', 'schema_cookie', 'wal_salt', 'hot_journal_generation', 'savepoint_generation', 'cache_generation', 'page_digests', 'checkpoint_published', 'journal_removed'] as $key) {
                        if (!array_key_exists($key, $checkpoint)) {
                            throw new \InvalidArgumentException("SQLite WAL hot-journal current-source next205 missing checkpoint {$key}");
                        }
                    }
                    if ((string) $checkpoint['database_path'] === '' || (string) $checkpoint['wal_path'] === '') {
                        throw new \InvalidArgumentException('SQLite WAL hot-journal current-source next205 paths are required');
                    }
                    if (!is_array($checkpoint['current_source_token'])) {
                        throw new \InvalidArgumentException('SQLite WAL hot-journal current-source next205 token must be an array');
                    }
                    $token = $checkpoint['current_source_token'];
                    if ((string) ($token['id'] ?? '') === '' || (int) ($token['epoch'] ?? 0) <= 0) {
                        throw new \InvalidArgumentException('SQLite WAL hot-journal current-source next205 token is invalid');
                    }
                    foreach (['checkpoint_frame', 'checkpoint_cookie', 'schema_cookie', 'hot_journal_generation', 'savepoint_generation', 'cache_generation'] as $key) {
                        if ((int) $checkpoint[$key] <= 0) {
                            throw new \InvalidArgumentException("SQLite WAL hot-journal current-source next205 {$key} must be positive");
                        }
                    }
                    if ((string) $checkpoint['wal_salt'] === '') {
                        throw new \InvalidArgumentException('SQLite WAL hot-journal current-source next205 WAL salt is required');
                    }
                    if (!is_array($checkpoint['page_digests'])) {
                        throw new \InvalidArgumentException('SQLite WAL hot-journal current-source next205 page digests must be an array');
                    }
                }

                /**
                 * @param array<mixed,mixed> $digests
                 * @return array<int,string>
                 */
                private static function pageDigests(array $digests): array
                {
                    $normalized = [];
                    foreach ($digests as $page => $digest) {
                        $pageNumber = (int) $page;
                        if ($pageNumber <= 0 || !is_string($digest) || !preg_match('/^[a-f0-9]{64}$/', $digest)) {
                            throw new \InvalidArgumentException('SQLite WAL hot-journal current-source next205 page digest entries must map positive pages to sha256 strings');
                        }
                        $normalized[$pageNumber] = $digest;
                    }
                    ksort($normalized);

                    return $normalized;
                }

                /**
                 * @param array<string,mixed> $reader
                 * @param array<int,string> $pageDigests
                 * @return array<string,mixed>
                 */
                private static function readerRow(
                    array $reader,
                    int $index,
                    string $tokenId,
                    int $epoch,
                    int $checkpointFrame,
                    int $checkpointCookie,
                    int $schemaCookie,
                    string $walSalt,
                    int $hotGeneration,
                    int $savepointGeneration,
                    int $cacheGeneration,
                    array $pageDigests,
                    bool $published,
                    bool $journalRemoved
                ): array {
                    foreach (['name', 'page', 'source_id', 'epoch', 'observed_checkpoint_frame', 'observed_checkpoint_cookie', 'observed_schema_cookie', 'observed_wal_salt', 'observed_hot_journal_generation', 'observed_savepoint_generation', 'observed_cache_generation', 'image_sha256'] as $key) {
                        if (!array_key_exists($key, $reader)) {
                            throw new \InvalidArgumentException("SQLite WAL hot-journal current-source next205 missing reader {$key}");
                        }
                    }
                    $name = (string) $reader['name'];
                    $page = (int) $reader['page'];
                    if ($name === '' || $page <= 0) {
                        throw new \InvalidArgumentException('SQLite WAL hot-journal current-source next205 reader name/page is invalid');
                    }
                    $imageSha = (string) $reader['image_sha256'];
                    if (!preg_match('/^[a-f0-9]{64}$/', $imageSha)) {
                        throw new \InvalidArgumentException('SQLite WAL hot-journal current-source next205 reader image digest must be a sha256 string');
                    }
                    $expectedDigest = $pageDigests[$page] ?? null;
                    $checks = [
                        'source_token' => (string) $reader['source_id'] === $tokenId,
                        'source_epoch' => (int) $reader['epoch'] === $epoch,
                        'checkpoint_frame' => (int) $reader['observed_checkpoint_frame'] === $checkpointFrame,
                        'checkpoint_cookie' => (int) $reader['observed_checkpoint_cookie'] === $checkpointCookie,
                        'schema_cookie' => (int) $reader['observed_schema_cookie'] === $schemaCookie,
                        'wal_salt' => (string) $reader['observed_wal_salt'] === $walSalt,
                        'hot_journal_generation' => (int) $reader['observed_hot_journal_generation'] === $hotGeneration,
                        'savepoint_generation' => (int) $reader['observed_savepoint_generation'] === $savepointGeneration,
                        'cache_generation' => (int) $reader['observed_cache_generation'] === $cacheGeneration,
                        'page_known' => $expectedDigest !== null,
                        'page_image' => $expectedDigest !== null && hash_equals($expectedDigest, $imageSha),
                        'not_dirty' => ($reader['dirty'] ?? false) !== true,
                        'not_closed' => ($reader['closed'] ?? false) !== true,
                        'checkpoint_published' => $published,
                        'journal_removed' => $journalRemoved,
                    ];
                    $failed = array_keys(array_filter($checks, static fn (bool $passed): bool => !$passed));
                    $admitted = $failed === [];

                    return [
                        'ordinal' => $index,
                        'name' => $name,
                        'page' => $page,
                        'admitted' => $admitted,
                        'requires_reopen' => !$admitted,
                        'failed_checks' => $failed,
                        'expected_image_sha256' => $expectedDigest,
                        'observed_image_sha256' => $imageSha,
                        'reason' => $admitted
                            ? 'reader_cache_page_image_matches_hot_journal_checkpoint_source'
                            : 'reader_cache_page_image_requires_reopen_after_hot_journal_checkpoint',
                        'transition' => $name . '>' . ($admitted ? 'reuse-page-cache' : 'reopen-page-cache') . ':next205',
                    ];
                }
        };

        return $impl::plan($checkpoint, $readers);
    }

    public static function next206Plan(array $leasePlan, array $consumers, int $minimumStatementGeneration): array
    {
        $impl = new class {
                /**
                 * @param array<string,mixed> $leasePlan
                 * @param list<array{name:string,reader_epoch:int,statement_generation:int,root_pages:list<int>,observed_database_digest:string,observed_wal_digest:string,observed_page_digests:array<int,string>,hot_journal_digest?:?string,savepoint_depth?:int,dirty?:bool,closed?:bool}> $consumers
                 * @return array<string,mixed>
                 */
                public static function plan(array $leasePlan, array $consumers, int $minimumStatementGeneration): array
                {
                    if (($leasePlan['status'] ?? null) !== 'wal-hot-journal-savepoint-checkpoint-current-source-next203') {
                        throw new \InvalidArgumentException('SQLite WAL hot-journal savepoint checkpoint current-source next206 requires an admitted next203 lease plan');
                    }
                    if ($consumers === []) {
                        throw new \InvalidArgumentException('SQLite WAL hot-journal savepoint checkpoint current-source next206 requires consumer rows');
                    }
                    if ($minimumStatementGeneration < 0) {
                        throw new \InvalidArgumentException('SQLite WAL hot-journal savepoint checkpoint current-source next206 requires a non-negative statement generation');
                    }

                    $databaseDigest = self::stringDigest($leasePlan, 'checkpointed_database_digest');
                    $walDigest = self::stringDigest($leasePlan, 'expected_wal_digest');
                    $pageDigests = $leasePlan['expected_page_digests'] ?? null;
                    if (!is_array($pageDigests) || $pageDigests === []) {
                        throw new \InvalidArgumentException('SQLite WAL hot-journal savepoint checkpoint current-source next206 requires checkpoint page digests');
                    }

                    $consumerRows = [];
                    $admitted = [];
                    $quarantined = [];
                    foreach ($consumers as $consumer) {
                        $row = self::consumerDecision($consumer, $databaseDigest, $walDigest, $pageDigests, $minimumStatementGeneration);
                        $consumerRows[] = $row;
                        if ($row['admitted']) {
                            $admitted[] = $row['name'];
                        } else {
                            $quarantined[] = $row['name'];
                        }
                    }

                    $guardRows = [
                        [
                            'name' => 'next203_page_cache_lease_fence',
                            'matched' => ($leasePlan['stale_guard_names'] ?? []) === [],
                            'reason' => 'next203 must publish a clean WAL sidecar and checkpoint page-cache fence',
                        ],
                        [
                            'name' => 'statement_generation_mix',
                            'matched' => $admitted !== [] && $quarantined !== [],
                            'reason' => 'current consumers are retained while stale prepared statements are quarantined',
                        ],
                        [
                            'name' => 'hot_journal_absent_from_admitted_consumers',
                            'matched' => self::admittedHotJournalFree($consumerRows),
                            'reason' => 'no admitted reopened statement may retain hot-journal identity after checkpoint publication',
                        ],
                    ];
                    $blockedGuards = array_values(array_column(
                        array_filter($guardRows, static fn (array $row): bool => !$row['matched']),
                        'name'
                    ));

                    $status = $blockedGuards === []
                        ? 'wal-hot-journal-savepoint-checkpoint-current-source-next206'
                        : 'wal-hot-journal-savepoint-checkpoint-current-source-blocked-next206';

                    return [
                        'status' => $status,
                        'reason' => $status === 'wal-hot-journal-savepoint-checkpoint-current-source-next206'
                            ? 'reopened_statement_consumers_match_checkpoint_generation'
                            : 'reopened_statement_consumers_wait_for_checkpoint_generation_reprepare',
                        'base_status' => $leasePlan['status'],
                        'database_path' => $leasePlan['database_path'] ?? null,
                        'wal_path' => $leasePlan['wal_path'] ?? null,
                        'journal_path' => $leasePlan['journal_path'] ?? null,
                        'page_size' => $leasePlan['page_size'] ?? null,
                        'minimum_statement_generation' => $minimumStatementGeneration,
