                        'reopened_reader_slot_names' => $reopened,
                        'guard_rows' => $guardRows,
                        'guard_names' => array_column($guardRows, 'name'),
                        'guard_matches' => array_column($guardRows, 'matched'),
                        'blocked_guard_names' => $blockedGuards,
                        'operation_names' => array_values(array_merge(
                            $consumerPlan['operation_names'] ?? [],
                            ['verify_checkpoint_reader_slots_current_source_next208'],
                            array_map(
                                static fn (array $row): string => $row['admitted']
                                    ? 'retain_checkpoint_reader_slot_current_source_next208'
                                    : 'reopen_checkpoint_reader_slot_current_source_next208',
                                $slotRows
                            )
                        )),
                        'reader_slot_digest' => hash('sha256', implode('|', array_merge(
                            [$databaseDigest, $walDigest, (string) $minimumGeneration, (string) $checkpointFrame],
                            array_column($slotRows, 'slot_transition')
                        ))),
                        'dependencies' => array_values(array_unique(array_merge($consumerPlan['dependencies'] ?? [], [
                            'sqlite-wal-hot-journal-savepoint-checkpoint-current-source-next208',
                            'sqlite-checkpoint-reader-slot-current-source-map',
                            'wordpress-import-reader-slot-reopen-after-checkpoint',
                        ]))),
                        'dependency_closure' => 'no new support component needed; reuses next206 current-source statement fencing plus checkpoint page digests to decide reader-slot reuse after checkpoint publication',
                        'non_overlap' => 'next208 maps post-checkpoint reader-slot reuse from next206 admitted consumers; it does not repeat next206 prepared-statement quarantine, next203 page-cache lease checks, WAL byte truncation, WAL sidecar writes, rollback-journal commit/apply, checkpoint transaction planning, or VFS savepoint rollback',
                    ];
                }

                /**
                 * @param array<string,mixed> $values
                 */
                private static function digestField(array $values, string $key): string
                {
                    $value = $values[$key] ?? null;
                    if (!is_string($value) || strlen($value) !== 64) {
                        throw new \InvalidArgumentException("SQLite WAL hot-journal savepoint checkpoint current-source next208 requires {$key}");
                    }

                    return $value;
                }

                /**
                 * @param mixed $values
                 * @return array<string,true>
                 */
                private static function stringSet($values): array
                {
                    if (!is_array($values) || $values === []) {
                        throw new \InvalidArgumentException('SQLite WAL hot-journal savepoint checkpoint current-source next208 requires admitted consumer names');
                    }
                    $set = [];
                    foreach ($values as $value) {
                        if (!is_string($value) || $value === '') {
                            throw new \InvalidArgumentException('SQLite WAL hot-journal savepoint checkpoint current-source next208 admitted consumer names must be non-empty strings');
                        }
                        $set[$value] = true;
                    }

                    return $set;
                }

                /**
                 * @param array<string,mixed> $slot
                 * @param array<string,true> $admittedConsumers
                 * @param array<int,string> $pageDigests
                 * @return array<string,mixed>
                 */
                private static function slotDecision(array $slot, array $admittedConsumers, string $databaseDigest, string $walDigest, array $pageDigests, int $minimumGeneration, int $checkpointFrame): array
                {
                    $name = self::stringField($slot, 'name');
                    $consumerName = self::stringField($slot, 'consumer_name');
                    $readMark = self::intField($slot, 'read_mark');
                    $readerEpoch = self::intField($slot, 'reader_epoch');
                    $slotCheckpointFrame = self::intField($slot, 'checkpoint_frame');
                    if ($readMark < 0 || $readerEpoch < 0 || $slotCheckpointFrame < 0) {
                        throw new \InvalidArgumentException("SQLite WAL hot-journal savepoint checkpoint current-source next208 {$name} numeric fields must be non-negative");
                    }
                    $observedDatabaseDigest = self::digestField($slot, 'observed_database_digest');
                    $observedWalDigest = self::digestField($slot, 'observed_wal_digest');
                    $rootPages = $slot['root_pages'] ?? null;
                    $observedPageDigests = $slot['observed_page_digests'] ?? null;
                    if (!is_array($rootPages) || $rootPages === [] || !is_array($observedPageDigests) || $observedPageDigests === []) {
                        throw new \InvalidArgumentException("SQLite WAL hot-journal savepoint checkpoint current-source next208 {$name} page rows are required");
                    }

                    $pageRows = [];
                    $stalePages = [];
                    $missingPages = [];
                    foreach ($rootPages as $pageNumber) {
                        if (!is_int($pageNumber) || $pageNumber < 1) {
                            throw new \InvalidArgumentException("SQLite WAL hot-journal savepoint checkpoint current-source next208 {$name} root page must be positive");
                        }
                        $expectedDigest = $pageDigests[$pageNumber] ?? null;
                        if (!is_string($expectedDigest)) {
                            $missingPages[] = $pageNumber;
                            $pageRows[] = [
                                'page' => $pageNumber,
                                'matched' => false,
                                'reason' => 'page_outside_checkpoint_reader_generation',
                                'expected_digest' => null,
                                'observed_digest' => $observedPageDigests[$pageNumber] ?? null,
                            ];
                            continue;
                        }
                        $observedDigest = $observedPageDigests[$pageNumber] ?? null;
                        if (!is_string($observedDigest) || strlen($observedDigest) !== 64) {
                            throw new \InvalidArgumentException("SQLite WAL hot-journal savepoint checkpoint current-source next208 {$name} page digest is required");
                        }
                        $matched = hash_equals($expectedDigest, $observedDigest);
                        if (!$matched) {
                            $stalePages[] = $pageNumber;
                        }
                        $pageRows[] = [
                            'page' => $pageNumber,
                            'matched' => $matched,
                            'reason' => $matched ? 'checkpoint_reader_page_matches' : 'checkpoint_reader_page_stale',
                            'expected_digest' => $expectedDigest,
                            'observed_digest' => $observedDigest,
                        ];
                    }

                    $hotJournalDigest = $slot['hot_journal_digest'] ?? null;
                    if ($hotJournalDigest !== null && (!is_string($hotJournalDigest) || strlen($hotJournalDigest) !== 64)) {
                        throw new \InvalidArgumentException("SQLite WAL hot-journal savepoint checkpoint current-source next208 {$name} hot journal digest must be a sha256 string or null");
                    }

                    $reasons = [];
                    if (!isset($admittedConsumers[$consumerName])) {
                        $reasons[] = 'reader_slot_consumer_not_admitted_by_next206';
                    }
                    if ($readerEpoch < $minimumGeneration) {
                        $reasons[] = 'reader_slot_epoch_predates_checkpoint_generation';
                    }
                    if ($slotCheckpointFrame > $checkpointFrame) {
                        $reasons[] = 'reader_slot_frame_exceeds_checkpoint_publication';
                    }
                    if (!hash_equals($databaseDigest, $observedDatabaseDigest)) {
                        $reasons[] = 'reader_slot_database_digest_mismatch';
                    }
                    if (!hash_equals($walDigest, $observedWalDigest)) {
                        $reasons[] = 'reader_slot_wal_digest_mismatch';
                    }
                    if ($stalePages !== [] || $missingPages !== []) {
                        $reasons[] = 'reader_slot_page_digest_mismatch';
                    }
                    if ($hotJournalDigest !== null) {
                        $reasons[] = 'reader_slot_retains_hot_journal_digest';
                    }
                    if (($slot['savepoint_depth'] ?? 0) !== 0) {
                        $reasons[] = 'reader_slot_savepoint_scope_not_closed';
                    }
                    if (empty($slot['lock_receipt'])) {
                        $reasons[] = 'reader_slot_missing_shared_lock_receipt';
                    }
                    if (!empty($slot['dirty'])) {
                        $reasons[] = 'reader_slot_dirty_before_checkpoint_publication';
                    }
                    if (!empty($slot['closed'])) {
                        $reasons[] = 'reader_slot_closed_before_checkpoint_publication';
                    }

                    $admitted = $reasons === [];

                    return array_merge($slot, [
                        'admitted' => $admitted,
                        'slot_reason' => $admitted ? 'reader_slot_matches_checkpoint_generation' : $reasons[0],
                        'blocked_reasons' => $reasons,
                        'expected_database_digest' => $databaseDigest,
                        'expected_wal_digest' => $walDigest,
                        'root_pages' => array_values($rootPages),
                        'page_rows' => $pageRows,
                        'stale_pages' => $stalePages,
                        'missing_pages' => $missingPages,
                        'hot_journal_retained' => $hotJournalDigest !== null,
                        'slot_transition' => $name . '>' . ($admitted ? 'retain-reader-slot' : 'reopen-reader-slot'),
                    ]);
                }

                /**
                 * @param array<string,mixed> $row
                 */
                private static function stringField(array $row, string $key): string
                {
                    $value = $row[$key] ?? null;
                    if (!is_string($value) || $value === '') {
                        throw new \InvalidArgumentException("SQLite WAL hot-journal savepoint checkpoint current-source next208 {$key} must be a non-empty string");
                    }

                    return $value;
                }

                /**
                 * @param array<string,mixed> $row
                 */
                private static function intField(array $row, string $key): int
                {
                    $value = $row[$key] ?? null;
                    if (!is_int($value)) {
                        throw new \InvalidArgumentException("SQLite WAL hot-journal savepoint checkpoint current-source next208 {$key} must be an integer");
                    }

                    return $value;
                }

                /**
                 * @param list<array<string,mixed>> $slotRows
                 */
                private static function retainedSlotsWithinCheckpoint(array $slotRows, int $checkpointFrame): bool
                {
                    foreach ($slotRows as $row) {
                        if (($row['admitted'] ?? false) === true && ($row['checkpoint_frame'] ?? 0) > $checkpointFrame) {
                            return false;
                        }
                    }

                    return true;
                }
        };

        return $impl::plan($consumerPlan, $readerSlots, $checkpointFrame);
    }

    public static function next209Plan(array $statementPlan, array $writers, int $nextWriterGeneration): array
    {
        $impl = new class {
                /**
                 * @param array<string,mixed> $statementPlan
                 * @param list<array<string,mixed>> $writers
                 * @return array<string,mixed>
                 */
                public static function plan(array $statementPlan, array $writers, int $nextWriterGeneration): array
                {
                    if (($statementPlan['status'] ?? null) !== 'wal-hot-journal-savepoint-checkpoint-current-source-next206') {
                        throw new \InvalidArgumentException('SQLite WAL hot-journal savepoint checkpoint current-source next209 requires an admitted next206 statement-consumer plan');
                    }
                    if ($writers === []) {
                        throw new \InvalidArgumentException('SQLite WAL hot-journal savepoint checkpoint current-source next209 requires writer rows');
                    }
                    if ($nextWriterGeneration < 1) {
                        throw new \InvalidArgumentException('SQLite WAL hot-journal savepoint checkpoint current-source next209 requires a positive writer generation');
                    }

                    $databaseDigest = self::digestField($statementPlan, 'checkpointed_database_digest');
                    $walDigest = self::digestField($statementPlan, 'expected_wal_digest');
                    $consumerDigest = self::digestField($statementPlan, 'consumer_digest');
                    $minimumStatementGeneration = $statementPlan['minimum_statement_generation'] ?? null;
                    if (!is_int($minimumStatementGeneration) || $minimumStatementGeneration < 0) {
                        throw new \InvalidArgumentException('SQLite WAL hot-journal savepoint checkpoint current-source next209 requires a non-negative minimum statement generation');
                    }
                    if ($nextWriterGeneration <= $minimumStatementGeneration) {
                        throw new \InvalidArgumentException('SQLite WAL hot-journal savepoint checkpoint current-source next209 writer generation must follow the statement generation');
                    }

                    $admittedConsumers = self::stringList($statementPlan, 'admitted_consumer_names');
                    $quarantinedConsumers = self::stringList($statementPlan, 'quarantined_consumer_names');
                    $blockedGuards = $statementPlan['blocked_guard_names'] ?? null;
                    if (!is_array($blockedGuards)) {
                        throw new \InvalidArgumentException('SQLite WAL hot-journal savepoint checkpoint current-source next209 requires next206 guard state');
                    }

                    $writerRows = [];
                    $admittedWriters = [];
                    $reopenWriters = [];
                    foreach ($writers as $writer) {
                        $row = self::writerDecision($writer, $databaseDigest, $walDigest, $consumerDigest, $nextWriterGeneration, $admittedConsumers, $quarantinedConsumers);
                        $writerRows[] = $row;
                        if ($row['admitted']) {
                            $admittedWriters[] = $row['name'];
                        } else {
                            $reopenWriters[] = $row['name'];
                        }
                    }

                    $guardRows = [
                        [
                            'name' => 'next206_statement_generation_fence',
                            'matched' => $blockedGuards === [],
                            'reason' => 'reopened statement consumers must already be admitted or quarantined by next206',
                        ],
                        [
                            'name' => 'current_and_stale_consumer_mix',
                            'matched' => $admittedConsumers !== [] && $quarantinedConsumers !== [],
                            'reason' => 'writer admission must prove current consumers are retained while stale consumers stay quarantined',
                        ],
                        [
                            'name' => 'writer_generation_mix',
                            'matched' => $admittedWriters !== [] && $reopenWriters !== [],
                            'reason' => 'current writers are retained while stale writer handles are reopened',
                        ],
                        [
                            'name' => 'writer_rows_hot_journal_free',
                            'matched' => self::admittedWritersHotJournalFree($writerRows),
                            'reason' => 'no admitted writer may retain hot-journal identity after checkpoint publication',
                        ],
                    ];
                    $blocked = array_values(array_column(
                        array_filter($guardRows, static fn (array $row): bool => !$row['matched']),
                        'name'
                    ));
                    $ready = $blocked === [];

                    return [
                        'status' => $ready
                            ? 'wal-hot-journal-savepoint-checkpoint-current-source-next209'
                            : 'wal-hot-journal-savepoint-checkpoint-current-source-blocked-next209',
                        'reason' => $ready
                            ? 'post_checkpoint_writers_follow_current_statement_generation'
                            : 'post_checkpoint_writers_wait_for_current_source_reopen',
                        'base_status' => $statementPlan['status'],
                        'database_path' => $statementPlan['database_path'] ?? null,
                        'journal_path' => $statementPlan['journal_path'] ?? null,
                        'wal_path' => $statementPlan['wal_path'] ?? null,
                        'page_size' => $statementPlan['page_size'] ?? null,
                        'minimum_statement_generation' => $minimumStatementGeneration,
                        'next_writer_generation' => $nextWriterGeneration,
                        'checkpointed_database_digest' => $databaseDigest,
                        'expected_wal_digest' => $walDigest,
                        'consumer_digest' => $consumerDigest,
                        'admitted_consumer_names' => $admittedConsumers,
                        'quarantined_consumer_names' => $quarantinedConsumers,
                        'writer_rows' => $writerRows,
                        'admitted_writer_names' => $admittedWriters,
                        'reopen_writer_names' => $reopenWriters,
                        'guard_rows' => $guardRows,
                        'guard_names' => array_column($guardRows, 'name'),
                        'guard_matches' => array_column($guardRows, 'matched'),
                        'blocked_guard_names' => $blocked,
                        'operation_names' => array_values(array_merge(
                            is_array($statementPlan['operation_names'] ?? null) ? $statementPlan['operation_names'] : [],
                            ['verify_post_checkpoint_writer_generation_current_source_next209'],
                            array_map(
                                static fn (array $row): string => $row['admitted']
                                    ? 'retain_post_checkpoint_writer_current_source_next209'
                                    : 'reopen_post_checkpoint_writer_current_source_next209',
                                $writerRows
                            )
                        )),
                        'writer_digest' => hash('sha256', implode('|', array_merge(
                            [$databaseDigest, $walDigest, $consumerDigest, (string) $nextWriterGeneration],
                            array_column($writerRows, 'writer_transition')
                        ))),
                        'dependencies' => array_values(array_unique(array_merge(
                            is_array($statementPlan['dependencies'] ?? null) ? $statementPlan['dependencies'] : [],
                            [
                                'sqlite-wal-hot-journal-savepoint-checkpoint-current-source-next209',
                                'sqlite-post-checkpoint-writer-generation-fence',
                                'wordpress-import-post-checkpoint-writer-reopen',
                            ]
                        ))),
                        'dependency_closure' => 'no new support component needed; reuses next206 statement-consumer fences, WAL/database digests, and lane-local writer handle metadata',
                        'non_overlap' => 'next209 gates post-checkpoint writer handle reuse after next206 statement admission; it does not repeat WAL byte truncation, VFS savepoint rollback, rollback-journal commit/apply, checkpoint transaction planning, WAL file writing, or next206 reopened-statement consumer classification',
                    ];
                }

                /**
                 * @param array<string,mixed> $values
                 */
                private static function digestField(array $values, string $key): string
                {
                    $value = $values[$key] ?? null;
                    if (!is_string($value) || strlen($value) !== 64) {
                        throw new \InvalidArgumentException("SQLite WAL hot-journal savepoint checkpoint current-source next209 requires {$key}");
                    }

                    return $value;
                }

                /**
                 * @param array<string,mixed> $values
                 * @return list<string>
                 */
                private static function stringList(array $values, string $key): array
                {
                    $list = $values[$key] ?? null;
                    if (!is_array($list)) {
                        throw new \InvalidArgumentException("SQLite WAL hot-journal savepoint checkpoint current-source next209 requires {$key}");
                    }
                    foreach ($list as $value) {
                        if (!is_string($value) || $value === '') {
                            throw new \InvalidArgumentException("SQLite WAL hot-journal savepoint checkpoint current-source next209 {$key} must contain non-empty strings");
                        }
                    }

                    return array_values($list);
                }

                /**
                 * @param array<string,mixed> $writer
                 * @param list<string> $admittedConsumers
                 * @param list<string> $quarantinedConsumers
                 * @return array<string,mixed>
                 */
                private static function writerDecision(
                    array $writer,
                    string $databaseDigest,
                    string $walDigest,
                    string $consumerDigest,
                    int $nextWriterGeneration,
                    array $admittedConsumers,
                    array $quarantinedConsumers
                ): array {
                    $name = $writer['name'] ?? null;
                    if (!is_string($name) || $name === '') {
                        throw new \InvalidArgumentException('SQLite WAL hot-journal savepoint checkpoint current-source next209 writer name is required');
                    }
                    $kind = $writer['kind'] ?? 'writer';
                    if (!is_string($kind) || !in_array($kind, ['writer', 'checkpoint', 'schema'], true)) {
                        throw new \InvalidArgumentException("SQLite WAL hot-journal savepoint checkpoint current-source next209 {$name} writer kind is invalid");
                    }
                    $writerGeneration = $writer['writer_generation'] ?? null;
                    $statementGeneration = $writer['statement_generation'] ?? null;
                    if (!is_int($writerGeneration) || $writerGeneration < 0 || !is_int($statementGeneration) || $statementGeneration < 0) {
                        throw new \InvalidArgumentException("SQLite WAL hot-journal savepoint checkpoint current-source next209 {$name} generations must be non-negative integers");
                    }
                    foreach (['observed_database_digest', 'observed_wal_digest', 'observed_consumer_digest'] as $key) {
                        if (!is_string($writer[$key] ?? null) || strlen((string) $writer[$key]) !== 64) {
                            throw new \InvalidArgumentException("SQLite WAL hot-journal savepoint checkpoint current-source next209 {$name} {$key} is required");
                        }
                    }
                    $retainsConsumers = $writer['retains_consumers'] ?? null;
                    $reopensConsumers = $writer['reopens_consumers'] ?? null;
                    if (!is_array($retainsConsumers) || !is_array($reopensConsumers)) {
                        throw new \InvalidArgumentException("SQLite WAL hot-journal savepoint checkpoint current-source next209 {$name} consumer lists are required");
                    }

                    $missingRetained = array_values(array_diff($admittedConsumers, $retainsConsumers));
                    $missingReopened = array_values(array_diff($quarantinedConsumers, $reopensConsumers));
                    $unexpectedRetained = array_values(array_intersect($quarantinedConsumers, $retainsConsumers));
                    $unexpectedReopened = array_values(array_intersect($admittedConsumers, $reopensConsumers));

                    $reasons = [];
                    if ($writerGeneration !== $nextWriterGeneration) {
                        $reasons[] = 'writer_generation_mismatch';
                    }
                    if ($statementGeneration < $nextWriterGeneration - 1) {
                        $reasons[] = 'writer_statement_generation_predates_checkpoint';
                    }
                    if (!hash_equals($databaseDigest, (string) $writer['observed_database_digest'])) {
                        $reasons[] = 'writer_database_digest_mismatch';
                    }
                    if (!hash_equals($walDigest, (string) $writer['observed_wal_digest'])) {
                        $reasons[] = 'writer_wal_digest_mismatch';
                    }
                    if (!hash_equals($consumerDigest, (string) $writer['observed_consumer_digest'])) {
                        $reasons[] = 'writer_consumer_digest_mismatch';
                    }
                    if ($missingRetained !== [] || $unexpectedReopened !== []) {
                        $reasons[] = 'writer_current_consumers_not_retained';
                    }
                    if ($missingReopened !== [] || $unexpectedRetained !== []) {
                        $reasons[] = 'writer_stale_consumers_not_reopened';
                    }
                    if (($writer['hot_journal_digest'] ?? null) !== null) {
                        if (!is_string($writer['hot_journal_digest']) || strlen($writer['hot_journal_digest']) !== 64) {
                            throw new \InvalidArgumentException("SQLite WAL hot-journal savepoint checkpoint current-source next209 {$name} hot journal digest must be a sha256 string or null");
                        }
                        $reasons[] = 'writer_retains_hot_journal_digest';
                    }
                    if (($writer['savepoint_depth'] ?? 0) !== 0) {
                        $reasons[] = 'writer_savepoint_scope_not_closed';
                    }
                    if (!empty($writer['dirty'])) {
                        $reasons[] = 'writer_cache_dirty_before_append';
                    }
                    if (!empty($writer['closed'])) {
                        $reasons[] = 'writer_handle_closed_before_append';
                    }

                    $admitted = $reasons === [];

                    return array_merge($writer, [
                        'kind' => $kind,
                        'admitted' => $admitted,
                        'writer_reason' => $admitted ? 'writer_matches_post_checkpoint_generation' : $reasons[0],
                        'blocked_reasons' => $reasons,
                        'expected_database_digest' => $databaseDigest,
                        'expected_wal_digest' => $walDigest,
                        'expected_consumer_digest' => $consumerDigest,
                        'missing_retained_consumers' => $missingRetained,
                        'missing_reopened_consumers' => $missingReopened,
                        'unexpected_retained_consumers' => $unexpectedRetained,
                        'unexpected_reopened_consumers' => $unexpectedReopened,
                        'hot_journal_retained' => ($writer['hot_journal_digest'] ?? null) !== null,
                        'writer_transition' => $name . '>' . ($admitted ? 'retain-writer' : 'reopen-writer'),
                    ]);
                }

                /**
                 * @param list<array<string,mixed>> $writerRows
                 */
                private static function admittedWritersHotJournalFree(array $writerRows): bool
                {
                    foreach ($writerRows as $row) {
                        if (($row['admitted'] ?? false) === true && ($row['hot_journal_retained'] ?? false) === true) {
                            return false;
                        }
                    }

                    return true;
                }
        };

        return $impl::plan($statementPlan, $writers, $nextWriterGeneration);
    }

    public static function next210Plan(array $writerPlan, array $appendBatches, int $nextCommitFrame): array
    {
        $impl = new class {
                /**
                 * @param array<string,mixed> $writerPlan
                 * @param list<array<string,mixed>> $appendBatches
                 * @return array<string,mixed>
                 */
                public static function plan(array $writerPlan, array $appendBatches, int $nextCommitFrame): array
                {
                    if (($writerPlan['status'] ?? null) !== 'wal-hot-journal-savepoint-checkpoint-current-source-next209') {
                        throw new \InvalidArgumentException('SQLite WAL hot-journal savepoint checkpoint current-source next210 requires an admitted next209 writer plan');
                    }
                    if ($appendBatches === []) {
                        throw new \InvalidArgumentException('SQLite WAL hot-journal savepoint checkpoint current-source next210 requires append batches');
                    }

                    $minimumStatementGeneration = self::intField($writerPlan, 'minimum_statement_generation', 0);
                    $nextWriterGeneration = self::intField($writerPlan, 'next_writer_generation', $minimumStatementGeneration + 1);
                    if ($nextWriterGeneration <= $minimumStatementGeneration) {
                        throw new \InvalidArgumentException('SQLite WAL hot-journal savepoint checkpoint current-source next210 writer generation must follow the statement generation');
                    }
                    if ($nextCommitFrame < 1) {
                        throw new \InvalidArgumentException('SQLite WAL hot-journal savepoint checkpoint current-source next210 commit frame must be positive');
                    }

                    $databaseDigest = self::digestField($writerPlan, 'checkpointed_database_digest');
                    $walDigest = self::digestField($writerPlan, 'expected_wal_digest');
                    $consumerDigest = self::digestField($writerPlan, 'consumer_digest');
                    $admittedWriters = self::stringList($writerPlan, 'admitted_writer_names');
                    $reopenWriters = self::stringList($writerPlan, 'reopen_writer_names');
                    $blockedGuards = $writerPlan['blocked_guard_names'] ?? null;
                    if (!is_array($blockedGuards)) {
                        throw new \InvalidArgumentException('SQLite WAL hot-journal savepoint checkpoint current-source next210 requires next209 guard state');
                    }

                    $batchRows = [];
                    $accepted = [];
                    $blocked = [];
                    foreach ($appendBatches as $batch) {
                        $row = self::batchDecision($batch, $databaseDigest, $walDigest, $consumerDigest, $nextWriterGeneration, $nextCommitFrame, $admittedWriters, $reopenWriters);
                        $batchRows[] = $row;
                        if ($row['accepted']) {
                            $accepted[] = $row['name'];
                        } else {
                            $blocked[] = $row['name'];
                        }
                    }

                    $guardRows = [
                        [
                            'name' => 'next209_writer_generation_fence',
                            'matched' => $blockedGuards === [],
                            'reason' => 'writer handles must already be admitted or reopened by next209',
                        ],
                        [
                            'name' => 'post_checkpoint_append_mix',
                            'matched' => $accepted !== [] && $blocked !== [],
                            'reason' => 'the append fence must prove current batches advance while stale batches are blocked',
                        ],
                        [
                            'name' => 'commit_frame_advances_checkpoint',
                            'matched' => $nextCommitFrame > self::maxCheckpointFrame($batchRows),
                            'reason' => 'new WAL commit frames must follow the checkpoint frame held by the writer source',
                        ],
                        [
                            'name' => 'accepted_batches_hot_journal_free',
                            'matched' => self::acceptedBatchesHotJournalFree($batchRows),
                            'reason' => 'accepted appends cannot retain hot rollback-journal identity',
                        ],
                    ];
                    $blockedGuardsNext210 = array_values(array_column(
                        array_filter($guardRows, static fn (array $row): bool => !$row['matched']),
                        'name'
                    ));
                    $ready = $blockedGuardsNext210 === [];

                    return [
                        'status' => $ready
                            ? 'wal-hot-journal-savepoint-checkpoint-current-source-next210'
                            : 'wal-hot-journal-savepoint-checkpoint-current-source-blocked-next210',
                        'reason' => $ready
                            ? 'post_checkpoint_wal_appends_follow_current_writer_generation'
                            : 'post_checkpoint_wal_appends_wait_for_current_source_refresh',
                        'base_status' => $writerPlan['status'],
                        'database_path' => $writerPlan['database_path'] ?? null,
                        'journal_path' => $writerPlan['journal_path'] ?? null,
                        'wal_path' => $writerPlan['wal_path'] ?? null,
                        'page_size' => $writerPlan['page_size'] ?? null,
                        'minimum_statement_generation' => $minimumStatementGeneration,
                        'next_writer_generation' => $nextWriterGeneration,
                        'next_commit_frame' => $nextCommitFrame,
                        'checkpointed_database_digest' => $databaseDigest,
                        'expected_wal_digest' => $walDigest,
                        'consumer_digest' => $consumerDigest,
                        'admitted_writer_names' => $admittedWriters,
                        'reopen_writer_names' => $reopenWriters,
                        'append_batch_rows' => $batchRows,
                        'accepted_append_batch_names' => $accepted,
                        'blocked_append_batch_names' => $blocked,
                        'guard_rows' => $guardRows,
                        'guard_names' => array_column($guardRows, 'name'),
                        'guard_matches' => array_column($guardRows, 'matched'),
                        'blocked_guard_names' => $blockedGuardsNext210,
                        'operation_names' => array_values(array_merge(
                            is_array($writerPlan['operation_names'] ?? null) ? $writerPlan['operation_names'] : [],
                            ['verify_post_checkpoint_wal_append_current_source_next210'],
                            array_map(
                                static fn (array $row): string => $row['accepted']
                                    ? 'accept_post_checkpoint_wal_append_current_source_next210'
                                    : 'block_post_checkpoint_wal_append_current_source_next210',
                                $batchRows
                            )
                        )),
                        'append_digest' => hash('sha256', implode('|', array_merge(
                            [$databaseDigest, $walDigest, $consumerDigest, (string) $nextWriterGeneration, (string) $nextCommitFrame],
                            array_column($batchRows, 'append_transition')
                        ))),
                        'dependencies' => array_values(array_unique(array_merge(
                            is_array($writerPlan['dependencies'] ?? null) ? $writerPlan['dependencies'] : [],
                            [
                                'sqlite-wal-hot-journal-savepoint-checkpoint-current-source-next210',
                                'sqlite-post-checkpoint-wal-append-generation-fence',
                                'wordpress-import-post-checkpoint-wal-append-after-hot-journal',
                            ]
                        ))),
                        'dependency_closure' => 'no new support component needed; reuses next209 writer-generation fences, WAL/database digests, and append-frame metadata',
                        'non_overlap' => 'next210 gates new WAL append batches after next209 writer reuse; it does not repeat next208 reader-slot reuse, next209 writer-handle admission, WAL byte truncation, checkpoint transaction planning, VFS savepoint rollback apply, rollback-journal commit/apply, WAL file writing, or hot-journal recovery application',
                    ];
                }

                /**
                 * @param array<string,mixed> $values
                 */
                private static function intField(array $values, string $key, int $minimum): int
                {
                    $value = $values[$key] ?? null;
                    if (!is_int($value) || $value < $minimum) {
                        throw new \InvalidArgumentException("SQLite WAL hot-journal savepoint checkpoint current-source next210 requires {$key}");
                    }

                    return $value;
                }

                /**
                 * @param array<string,mixed> $values
                 */
                private static function digestField(array $values, string $key): string
                {
                    $value = $values[$key] ?? null;
                    if (!is_string($value) || !preg_match('/^[a-f0-9]{64}$/', $value)) {
                        throw new \InvalidArgumentException("SQLite WAL hot-journal savepoint checkpoint current-source next210 requires {$key}");
                    }

                    return $value;
                }

                /**
                 * @param array<string,mixed> $values
                 * @return list<string>
                 */
                private static function stringList(array $values, string $key): array
                {
                    $list = $values[$key] ?? null;
                    if (!is_array($list) || $list === []) {
                        throw new \InvalidArgumentException("SQLite WAL hot-journal savepoint checkpoint current-source next210 requires {$key}");
                    }
                    foreach ($list as $value) {
                        if (!is_string($value) || $value === '') {
                            throw new \InvalidArgumentException("SQLite WAL hot-journal savepoint checkpoint current-source next210 {$key} must contain non-empty strings");
                        }
                    }

                    return array_values($list);
                }

                /**
                 * @param array<string,mixed> $batch
                 * @param list<string> $admittedWriters
                 * @param list<string> $reopenWriters
                 * @return array<string,mixed>
                 */
                private static function batchDecision(
                    array $batch,
                    string $databaseDigest,
                    string $walDigest,
                    string $consumerDigest,
                    int $nextWriterGeneration,
                    int $nextCommitFrame,
                    array $admittedWriters,
                    array $reopenWriters
                ): array {
                    $name = $batch['name'] ?? null;
                    if (!is_string($name) || $name === '') {
                        throw new \InvalidArgumentException('SQLite WAL hot-journal savepoint checkpoint current-source next210 append batch name is required');
                    }
                    $writer = $batch['writer_name'] ?? null;
                    if (!is_string($writer) || $writer === '') {
                        throw new \InvalidArgumentException("SQLite WAL hot-journal savepoint checkpoint current-source next210 {$name} writer name is required");
                    }
                    $writerGeneration = $batch['writer_generation'] ?? null;
                    $checkpointFrame = $batch['checkpoint_frame'] ?? null;
                    $firstFrame = $batch['first_frame'] ?? null;
                    $commitFrame = $batch['commit_frame'] ?? null;
                    foreach (['writer_generation' => $writerGeneration, 'checkpoint_frame' => $checkpointFrame, 'first_frame' => $firstFrame, 'commit_frame' => $commitFrame] as $key => $value) {
                        if (!is_int($value) || $value < 0) {
                            throw new \InvalidArgumentException("SQLite WAL hot-journal savepoint checkpoint current-source next210 {$name} {$key} must be a non-negative integer");
                        }
                    }
                    foreach (['observed_database_digest', 'observed_wal_digest', 'observed_consumer_digest'] as $key) {
                        if (!is_string($batch[$key] ?? null) || !preg_match('/^[a-f0-9]{64}$/', (string) $batch[$key])) {
                            throw new \InvalidArgumentException("SQLite WAL hot-journal savepoint checkpoint current-source next210 {$name} {$key} is required");
                        }
                    }
                    $pageDigests = $batch['page_digests'] ?? null;
                    if (!is_array($pageDigests) || $pageDigests === []) {
                        throw new \InvalidArgumentException("SQLite WAL hot-journal savepoint checkpoint current-source next210 {$name} page digests are required");
                    }
                    $normalizedPages = [];
                    foreach ($pageDigests as $page => $digest) {
                        $pageNumber = (int) $page;
                        if ($pageNumber <= 0 || !is_string($digest) || !preg_match('/^[a-f0-9]{64}$/', $digest)) {
                            throw new \InvalidArgumentException("SQLite WAL hot-journal savepoint checkpoint current-source next210 {$name} page digests must map positive pages to sha256 strings");
                        }
                        $normalizedPages[$pageNumber] = $digest;
                    }
                    ksort($normalizedPages);

                    $reasons = [];
                    if (!in_array($writer, $admittedWriters, true)) {
                        $reasons[] = in_array($writer, $reopenWriters, true) ? 'append_writer_requires_reopen' : 'append_writer_not_admitted';
                    }
                    if ($writerGeneration !== $nextWriterGeneration) {
                        $reasons[] = 'append_writer_generation_mismatch';
                    }
                    if ($firstFrame !== $checkpointFrame + 1) {
                        $reasons[] = 'append_first_frame_does_not_follow_checkpoint';
                    }
                    if ($commitFrame !== $nextCommitFrame) {
                        $reasons[] = 'append_commit_frame_mismatch';
                    }
                    if ($commitFrame < $firstFrame) {
                        $reasons[] = 'append_commit_frame_before_first_frame';
                    }
                    if (!hash_equals($databaseDigest, (string) $batch['observed_database_digest'])) {
                        $reasons[] = 'append_database_digest_mismatch';
                    }
                    if (!hash_equals($walDigest, (string) $batch['observed_wal_digest'])) {
                        $reasons[] = 'append_wal_digest_mismatch';
                    }
                    if (!hash_equals($consumerDigest, (string) $batch['observed_consumer_digest'])) {
                        $reasons[] = 'append_consumer_digest_mismatch';
                    }
                    if (($batch['hot_journal_digest'] ?? null) !== null) {
                        if (!is_string($batch['hot_journal_digest']) || !preg_match('/^[a-f0-9]{64}$/', $batch['hot_journal_digest'])) {
                            throw new \InvalidArgumentException("SQLite WAL hot-journal savepoint checkpoint current-source next210 {$name} hot journal digest must be a sha256 string or null");
                        }
                        $reasons[] = 'append_retains_hot_journal_digest';
                    }
                    if (($batch['savepoint_depth'] ?? 0) !== 0) {
                        $reasons[] = 'append_savepoint_scope_not_closed';
                    }
                    if (empty($batch['exclusive_lock_receipt'])) {
                        $reasons[] = 'append_missing_exclusive_lock_receipt';
                    }
                    if (!empty($batch['dirty_before_append'])) {
                        $reasons[] = 'append_dirty_cache_before_frame_write';
                    }

                    $accepted = $reasons === [];

                    return array_merge($batch, [
                        'page_digests' => $normalizedPages,
                        'accepted' => $accepted,
                        'append_reason' => $accepted ? 'append_batch_matches_current_writer_generation' : $reasons[0],
                        'blocked_reasons' => $reasons,
                        'expected_database_digest' => $databaseDigest,
                        'expected_wal_digest' => $walDigest,
                        'expected_consumer_digest' => $consumerDigest,
                        'expected_writer_generation' => $nextWriterGeneration,
                        'expected_commit_frame' => $nextCommitFrame,
                        'page_numbers' => array_keys($normalizedPages),
                        'page_digest' => hash('sha256', implode('|', array_map(
                            static fn (int $page, string $digest): string => $page . ':' . $digest,
                            array_keys($normalizedPages),
                            $normalizedPages
                        ))),
                        'hot_journal_retained' => ($batch['hot_journal_digest'] ?? null) !== null,
                        'append_transition' => $name . '>' . ($accepted ? 'append-wal-frames' : 'block-wal-append'),
                    ]);
                }

                /**
                 * @param list<array<string,mixed>> $batchRows
                 */
                private static function maxCheckpointFrame(array $batchRows): int
                {
                    $frames = array_map(static fn (array $row): int => (int) $row['checkpoint_frame'], $batchRows);

                    return max($frames);
                }

                /**
                 * @param list<array<string,mixed>> $batchRows
                 */
                private static function acceptedBatchesHotJournalFree(array $batchRows): bool
                {
                    foreach ($batchRows as $row) {
                        if (($row['accepted'] ?? false) === true && ($row['hot_journal_retained'] ?? false) === true) {
                            return false;
                        }
                    }

                    return true;
                }
        };

        return $impl::plan($writerPlan, $appendBatches, $nextCommitFrame);
    }

    public static function next211Plan(array $readerPlan, array $acknowledgements): array
    {
        $impl = new class {
                /**
                 * @param array<string,mixed> $readerPlan
                 * @param array<string,array<string,mixed>> $acknowledgements
                 * @return array<string,mixed>
                 */
                public static function plan(array $readerPlan, array $acknowledgements): array
                {
                    self::assertReaderPlan($readerPlan);
                    if ($acknowledgements === []) {
                        throw new \InvalidArgumentException('SQLite WAL hot-journal current-source next211 requires acknowledgement rows');
                    }

                    $token = $readerPlan['current_source_token'];
                    $tokenId = (string) $token['id'];
                    $epoch = (int) $token['epoch'];
                    $readerRows = $readerPlan['reader_rows'];
                    $checkpointFrame = (int) $readerPlan['checkpoint_frame'];
                    $checkpointCookie = (int) $readerPlan['checkpoint_cookie'];
                    $schemaCookie = (int) $readerPlan['schema_cookie'];
                    $pageNumbers = array_map('intval', $readerPlan['page_numbers']);

                    $rows = [];
                    foreach ($readerRows as $reader) {
                        $readerName = (string) $reader['name'];
                        $ack = $acknowledgements[$readerName] ?? null;
                        $rows[] = self::admissionRow(
                            $reader,
                            is_array($ack) ? $ack : null,
                            $tokenId,
                            $epoch,
                            $checkpointFrame,
                            $checkpointCookie,
                            $schemaCookie
                        );
                    }

                    $missingAcknowledgements = array_values(array_column(array_filter(
                        $rows,
                        static fn (array $row): bool => $row['expected_action'] === 'retain-reader-cache' && $row['acknowledged'] === false
                    ), 'reader'));
                    $missingReopenFences = array_values(array_column(array_filter(
                        $rows,
                        static fn (array $row): bool => $row['expected_action'] === 'reopen-reader-cache' && $row['reopen_fenced'] === false
                    ), 'reader'));
                    $unexpectedAcknowledgements = array_values(array_column(array_filter(
                        $rows,
                        static fn (array $row): bool => $row['expected_action'] === 'reopen-reader-cache' && $row['acknowledged'] === true
                    ), 'reader'));
                    $staleAcknowledgements = array_values(array_column(array_filter(
                        $rows,
                        static fn (array $row): bool => $row['stale_acknowledgement'] === true
                    ), 'reader'));
                    $orphanAcknowledgements = array_values(array_diff(array_keys($acknowledgements), array_column($rows, 'reader')));

                    $guards = [
                        'next205_reader_plan_ready' => $readerPlan['status'] === 'wal-hot-journal-savepoint-checkpoint-current-source-next205',
                        'checkpoint_published' => ($readerPlan['checkpoint_published'] ?? false) === true,
                        'journal_removed' => ($readerPlan['journal_removed'] ?? false) === true,
                        'all_retained_readers_acknowledged' => $missingAcknowledgements === [],
                        'all_reopened_readers_fenced' => $missingReopenFences === [],
                        'no_stale_acknowledgements' => $staleAcknowledgements === [],
                        'no_unexpected_stale_reader_acknowledgements' => $unexpectedAcknowledgements === [],
                        'no_orphan_acknowledgements' => $orphanAcknowledgements === [],
                    ];
                    $blocked = array_keys(array_filter($guards, static fn (bool $passed): bool => !$passed));
                    $admittedReaders = array_values(array_column(array_filter($rows, static fn (array $row): bool => $row['checkpoint_admitted']), 'reader'));
                    $reopenReaders = array_values(array_column(array_filter($rows, static fn (array $row): bool => $row['expected_action'] === 'reopen-reader-cache'), 'reader'));

                    return [
                        'status' => $blocked === []
                            ? 'wal-hot-journal-savepoint-checkpoint-current-source-next211'
                            : 'wal-hot-journal-savepoint-checkpoint-current-source-blocked-next211',
                        'reason' => $blocked === []
                            ? 'checkpoint_current_source_acknowledgements_admit_next_source'
                            : 'checkpoint_current_source_acknowledgements_block_next_source',
                        'database_path' => (string) $readerPlan['database_path'],
                        'wal_path' => (string) $readerPlan['wal_path'],
                        'journal_path' => (string) $readerPlan['journal_path'],
                        'current_source_token' => $token,
                        'checkpoint_frame' => $checkpointFrame,
                        'checkpoint_cookie' => $checkpointCookie,
                        'schema_cookie' => $schemaCookie,
                        'page_numbers' => $pageNumbers,
                        'reader_admission_rows' => $rows,
                        'admitted_reader_names' => $admittedReaders,
                        'reopen_reader_names' => $reopenReaders,
                        'missing_acknowledgements' => $missingAcknowledgements,
                        'missing_reopen_fences' => $missingReopenFences,
                        'unexpected_acknowledgements' => $unexpectedAcknowledgements,
                        'stale_acknowledgements' => $staleAcknowledgements,
                        'orphan_acknowledgements' => $orphanAcknowledgements,
                        'guard_names' => array_keys($guards),
                        'guard_matches' => array_values($guards),
                        'blocked_guard_names' => $blocked,
                        'checkpoint_admitted' => $blocked === [],
                        'next_source_epoch' => $epoch + 1,
                        'checkpoint_admission_digest' => hash('sha256', json_encode($rows, JSON_THROW_ON_ERROR)),
                        'operation_names' => array_values(array_unique(array_merge(
                            is_array($readerPlan['operation_names'] ?? null) ? $readerPlan['operation_names'] : [],
                            [
                                'acknowledge_reader_page_digest_next211',
                                'fence_reopened_reader_cache_next211',
                                'admit_checkpoint_next_source_after_hot_journal_next211',
                            ]
                        ))),
                        'dependencies' => array_values(array_unique(array_merge(
                            is_array($readerPlan['dependencies'] ?? null) ? $readerPlan['dependencies'] : [],
                            [
                                'sqlite-wal-hot-journal-savepoint-checkpoint-current-source-next211',
                                'sqlite-wal-current-source-reader-acknowledgement-fence',
                                'wordpress-import-checkpoint-reader-reopen-fence',
                            ]
                        ))),
                        'dependency_closure' => 'no new support component needed; reuses next205 reader page digests, current-source tokens, checkpoint cookies, and reopen fences',
                        'non_overlap' => 'next211 admits checkpoint next-source publication only after reader digest acknowledgements and reopen fences; it does not repeat next205 page-image validation, WAL byte truncation, VFS savepoint rollback apply, rollback-journal commit/apply, checkpoint transaction planning, or writer-handle fencing',
                    ];
                }

                /**
                 * @param array<string,mixed> $readerPlan
                 */
                private static function assertReaderPlan(array $readerPlan): void
                {
                    foreach (['status', 'database_path', 'wal_path', 'journal_path', 'current_source_token', 'checkpoint_frame', 'checkpoint_cookie', 'schema_cookie', 'page_numbers', 'reader_rows'] as $key) {
                        if (!array_key_exists($key, $readerPlan)) {
                            throw new \InvalidArgumentException("SQLite WAL hot-journal current-source next211 missing reader plan {$key}");
                        }
                    }
                    if (!is_array($readerPlan['current_source_token']) || (string) ($readerPlan['current_source_token']['id'] ?? '') === '' || (int) ($readerPlan['current_source_token']['epoch'] ?? 0) <= 0) {
                        throw new \InvalidArgumentException('SQLite WAL hot-journal current-source next211 token is invalid');
                    }
                    if (!is_array($readerPlan['reader_rows']) || $readerPlan['reader_rows'] === []) {
                        throw new \InvalidArgumentException('SQLite WAL hot-journal current-source next211 requires reader rows');
                    }
                    if (!is_array($readerPlan['page_numbers']) || $readerPlan['page_numbers'] === []) {
                        throw new \InvalidArgumentException('SQLite WAL hot-journal current-source next211 requires page numbers');
                    }
                    foreach (['checkpoint_frame', 'checkpoint_cookie', 'schema_cookie'] as $key) {
                        if ((int) $readerPlan[$key] <= 0) {
                            throw new \InvalidArgumentException("SQLite WAL hot-journal current-source next211 {$key} must be positive");
                        }
                    }
                }

                /**
                 * @param array<string,mixed> $reader
                 * @param array<string,mixed>|null $ack
                 * @return array<string,mixed>
                 */
                private static function admissionRow(
                    array $reader,
                    ?array $ack,
                    string $tokenId,
                    int $epoch,
                    int $checkpointFrame,
                    int $checkpointCookie,
                    int $schemaCookie
                ): array {
                    foreach (['name', 'page', 'admitted', 'requires_reopen', 'expected_image_sha256', 'observed_image_sha256'] as $key) {
                        if (!array_key_exists($key, $reader)) {
                            throw new \InvalidArgumentException("SQLite WAL hot-journal current-source next211 missing reader {$key}");
                        }
                    }
                    $name = (string) $reader['name'];
                    $page = (int) $reader['page'];
                    if ($name === '' || $page <= 0) {
                        throw new \InvalidArgumentException('SQLite WAL hot-journal current-source next211 reader name/page is invalid');
                    }
                    $expected = (string) $reader['expected_image_sha256'];
                    $observed = (string) $reader['observed_image_sha256'];
                    if ($expected === '' || !preg_match('/^[a-f0-9]{64}$/', $observed)) {
                        throw new \InvalidArgumentException('SQLite WAL hot-journal current-source next211 reader digests are invalid');
                    }

                    $expectsRetain = (bool) $reader['admitted'] && (bool) $reader['requires_reopen'] === false;
                    $acknowledged = $ack !== null && ($ack['acknowledged'] ?? false) === true;
                    $reopenFenced = $ack !== null && ($ack['reopen_fenced'] ?? false) === true;
                    $ackDigest = $ack === null ? null : (string) ($ack['image_sha256'] ?? '');
                    $ackSource = $ack === null ? null : (string) ($ack['source_id'] ?? '');
                    $ackEpoch = $ack === null ? null : (int) ($ack['epoch'] ?? 0);
                    $ackFrame = $ack === null ? null : (int) ($ack['checkpoint_frame'] ?? 0);
                    $ackCookie = $ack === null ? null : (int) ($ack['checkpoint_cookie'] ?? 0);
                    $ackSchema = $ack === null ? null : (int) ($ack['schema_cookie'] ?? 0);

                    $stale = $ack !== null && (
                        $ackSource !== $tokenId
                        || $ackEpoch !== $epoch
                        || $ackFrame !== $checkpointFrame
                        || $ackCookie !== $checkpointCookie
                        || $ackSchema !== $schemaCookie
                        || ($expectsRetain && !hash_equals($observed, $ackDigest))
                    );
                    $checkpointAdmitted = $expectsRetain
                        && $acknowledged
                        && !$stale
                        && hash_equals($expected, $observed);

                    return [
                        'reader' => $name,
                        'page' => $page,
                        'expected_action' => $expectsRetain ? 'retain-reader-cache' : 'reopen-reader-cache',
                        'acknowledged' => $acknowledged,
                        'reopen_fenced' => $reopenFenced,
                        'stale_acknowledgement' => $stale,
                        'checkpoint_admitted' => $checkpointAdmitted,
                        'source_id' => $ackSource,
                        'epoch' => $ackEpoch,
                        'acknowledged_image_sha256' => $ackDigest,
                        'expected_image_sha256' => $expected,
                        'observed_image_sha256' => $observed,
                        'reason' => $checkpointAdmitted
                            ? 'reader_acknowledged_checkpoint_current_source_digest'
                            : ($expectsRetain ? 'reader_acknowledgement_required_before_next_source' : 'reader_reopen_fence_required_before_next_source'),
                        'transition' => $name . '>' . ($checkpointAdmitted ? 'admit-next-source' : ($expectsRetain ? 'wait-for-ack' : 'fence-reopen')) . ':next211',
                    ];
                }
        };

        return $impl::plan($readerPlan, $acknowledgements);
    }

    public static function next212PassiveCheckpoint(array $writerPlan, array $readers, int $requestedFrame): array
    {
        $impl = new class {
                /**
                 * @param array<string,mixed> $writerPlan
                 * @param list<array<string,mixed>> $readers
                 * @return array<string,mixed>
                 */
                public static function passiveCheckpoint(array $writerPlan, array $readers, int $requestedFrame): array
                {
                    if (($writerPlan['status'] ?? null) !== 'wal-hot-journal-savepoint-checkpoint-current-source-next209') {
                        throw new \InvalidArgumentException('SQLite WAL hot-journal savepoint checkpoint current-source next212 requires an admitted next209 writer plan');
                    }
                    if ($readers === []) {
                        throw new \InvalidArgumentException('SQLite WAL hot-journal savepoint checkpoint current-source next212 requires reader rows');
                    }
                    if ($requestedFrame <= 0) {
                        throw new \InvalidArgumentException('SQLite WAL hot-journal savepoint checkpoint current-source next212 requires a positive checkpoint frame');
                    }

                    $databaseDigest = self::digestField($writerPlan, 'checkpointed_database_digest');
                    $walDigest = self::digestField($writerPlan, 'expected_wal_digest');
                    $writerDigest = self::digestField($writerPlan, 'writer_digest');
                    $nextWriterGeneration = self::positiveInt($writerPlan, 'next_writer_generation');
                    $minimumStatementGeneration = self::nonNegativeInt($writerPlan, 'minimum_statement_generation');
                    $admittedWriters = self::stringList($writerPlan, 'admitted_writer_names');
                    $reopenWriters = self::stringList($writerPlan, 'reopen_writer_names');

                    $readerRows = [];
                    foreach ($readers as $reader) {
                        $readerRows[] = self::readerRow(
                            $reader,
                            $databaseDigest,
                            $walDigest,
                            $writerDigest,
                            $nextWriterGeneration,
                            $minimumStatementGeneration,
                            $requestedFrame
                        );
                    }

                    $activePins = array_values(array_filter($readerRows, static fn (array $row): bool => $row['pins_current_source']));
                    $staleReaders = array_values(array_filter($readerRows, static fn (array $row): bool => !$row['admitted']));
                    $checkpointedFrame = $activePins === []
                        ? $requestedFrame
                        : min(array_column($activePins, 'reader_end_frame'));
                    $busy = $checkpointedFrame < $requestedFrame;
                    $blockedReasons = [];
                    foreach ($staleReaders as $row) {
                        foreach ($row['blocked_reasons'] as $reason) {
                            $blockedReasons[] = $reason;
                        }
                    }

                    $guardRows = [
                        [
                            'name' => 'next209_writer_generation_admitted',
                            'matched' => $admittedWriters !== [] && $reopenWriters !== [],
                            'reason' => 'passive checkpoint follows the mixed current/stale writer fence from next209',
                        ],
                        [
                            'name' => 'checkpoint_frame_not_before_statement_generation',
                            'matched' => $requestedFrame >= $minimumStatementGeneration,
                            'reason' => 'checkpoint may not publish a frame older than the current statement generation',
                        ],
                        [
                            'name' => 'active_reader_pin_detected',
                            'matched' => $activePins !== [],
                            'reason' => 'PASSIVE checkpoint must report partial progress when a current reader pins the source',
                        ],
                        [
                            'name' => 'stale_readers_reopened',
                            'matched' => $staleReaders !== [],
                            'reason' => 'stale readers are not allowed to advance the current-source checkpoint',
                        ],
                    ];
                    $blockedGuards = array_values(array_column(
                        array_filter($guardRows, static fn (array $row): bool => !$row['matched']),
                        'name'
                    ));

                    return [
                        'status' => $blockedGuards === []
                            ? 'wal-hot-journal-savepoint-checkpoint-current-source-next212'
