    public static function next217Plan(array $admissionPlan, array $receipts): array
    {
        $impl = new class {
                /**
                 * @param array<string,mixed> $admissionPlan
                 * @param array<string,array<string,mixed>> $receipts
                 * @return array<string,mixed>
                 */
                public static function plan(array $admissionPlan, array $receipts): array
                {
                    self::assertAdmissionPlan($admissionPlan);
                    if ($receipts === []) {
                        throw new \InvalidArgumentException('SQLite WAL current-source next217 requires reader receipt rows');
                    }

                    $token = $admissionPlan['current_source_token'];
                    $sourceId = (string) $token['id'];
                    $epoch = (int) $token['epoch'];
                    $checkpointFrame = (int) $admissionPlan['checkpoint_frame'];
                    $checkpointCookie = (int) $admissionPlan['checkpoint_cookie'];
                    $schemaCookie = (int) $admissionPlan['schema_cookie'];
                    $readerRows = $admissionPlan['reader_admission_rows'];

                    $rows = [];
                    foreach ($readerRows as $reader) {
                        if (!is_array($reader)) {
                            throw new \InvalidArgumentException('SQLite WAL current-source next217 reader row must be an array');
                        }
                        $name = (string) ($reader['reader'] ?? '');
                        $receipt = $receipts[$name] ?? null;
                        $rows[] = self::receiptRow(
                            $reader,
                            is_array($receipt) ? $receipt : null,
                            $sourceId,
                            $epoch,
                            $checkpointFrame,
                            $checkpointCookie,
                            $schemaCookie
                        );
                    }

                    $orphanReceipts = array_values(array_diff(array_keys($receipts), array_column($rows, 'reader')));
                    $blockedRows = array_values(array_filter($rows, static fn (array $row): bool => $row['admitted'] === false));
                    $retainedRows = array_values(array_filter($rows, static fn (array $row): bool => $row['expected_action'] === 'retain-reader-cache'));
                    $reopenedRows = array_values(array_filter($rows, static fn (array $row): bool => $row['expected_action'] === 'reopen-reader-cache'));

                    $guards = [
                        'next211_checkpoint_admitted' => $admissionPlan['status'] === 'wal-hot-journal-savepoint-checkpoint-current-source-next211'
                            && ($admissionPlan['checkpoint_admitted'] ?? false) === true,
                        'all_receipts_match_current_source' => $blockedRows === [],
                        'no_orphan_receipts' => $orphanReceipts === [],
                        'retained_readers_acknowledged' => self::allRowsPass($retainedRows, 'ack_receipt_matches'),
                        'reopened_readers_fenced' => self::allRowsPass($reopenedRows, 'reopen_receipt_matches'),
                        'hot_journal_delete_durable' => self::allRowsPass($rows, 'journal_delete_durable'),
                        'wal_generation_synced' => self::allRowsPass($rows, 'wal_sync_durable'),
                        'directory_entry_synced' => self::allRowsPass($rows, 'directory_sync_durable'),
                    ];
                    $blocked = array_keys(array_filter($guards, static fn (bool $passed): bool => !$passed));

                    return [
                        'status' => $blocked === []
                            ? 'wal-hot-journal-savepoint-checkpoint-current-source-next217'
                            : 'wal-hot-journal-savepoint-checkpoint-current-source-blocked-next217',
                        'reason' => $blocked === []
                            ? 'durable_reader_receipts_admit_checkpoint_next_source'
                            : 'durable_reader_receipts_block_checkpoint_next_source',
                        'database_path' => (string) $admissionPlan['database_path'],
                        'wal_path' => (string) $admissionPlan['wal_path'],
                        'journal_path' => (string) $admissionPlan['journal_path'],
                        'current_source_token' => $token,
                        'checkpoint_frame' => $checkpointFrame,
                        'checkpoint_cookie' => $checkpointCookie,
                        'schema_cookie' => $schemaCookie,
                        'reader_receipt_rows' => $rows,
                        'retained_reader_names' => array_values(array_column($retainedRows, 'reader')),
                        'reopened_reader_names' => array_values(array_column($reopenedRows, 'reader')),
                        'admitted_reader_names' => array_values(array_column(array_filter($rows, static fn (array $row): bool => $row['admitted']), 'reader')),
                        'blocked_reader_names' => array_values(array_column($blockedRows, 'reader')),
                        'orphan_receipts' => $orphanReceipts,
                        'guard_names' => array_keys($guards),
                        'guard_matches' => array_values($guards),
                        'blocked_guard_names' => $blocked,
                        'checkpoint_admitted' => $blocked === [],
                        'next_source_epoch' => $epoch + 1,
                        'receipt_digest' => hash('sha256', json_encode($rows, JSON_THROW_ON_ERROR)),
                        'operation_names' => array_values(array_unique(array_merge(
                            is_array($admissionPlan['operation_names'] ?? null) ? $admissionPlan['operation_names'] : [],
                            [
                                'verify_durable_reader_ack_receipts_next217',
                                'verify_reopen_fence_receipts_next217',
                                'admit_checkpoint_next_source_after_durable_receipts_next217',
                            ]
                        ))),
                        'dependencies' => array_values(array_unique(array_merge(
                            is_array($admissionPlan['dependencies'] ?? null) ? $admissionPlan['dependencies'] : [],
                            [
                                'sqlite-wal-hot-journal-savepoint-checkpoint-current-source-next217',
                                'sqlite-wal-reader-durable-receipt-fence',
                                'wordpress-import-hot-journal-checkpoint-reopen-receipts',
                            ]
                        ))),
                        'dependency_closure' => 'no new support component needed; reuses next211 reader acknowledgement rows, hot-journal delete receipts, WAL sync receipts, and directory sync receipts',
                        'non_overlap' => 'next217 validates durable receipt fencing after next211 acknowledgement admission; it does not repeat next211 page digest admission, next208 reader slot validation, WAL byte truncation, VFS savepoint rollback apply, rollback-journal commit/apply, or checkpoint transaction planning',
                    ];
                }

                /**
                 * @param array<string,mixed> $admissionPlan
                 */
                private static function assertAdmissionPlan(array $admissionPlan): void
                {
                    foreach (['status', 'database_path', 'wal_path', 'journal_path', 'current_source_token', 'checkpoint_frame', 'checkpoint_cookie', 'schema_cookie', 'reader_admission_rows'] as $key) {
                        if (!array_key_exists($key, $admissionPlan)) {
                            throw new \InvalidArgumentException("SQLite WAL current-source next217 missing admission {$key}");
                        }
                    }
                    if (!is_array($admissionPlan['current_source_token']) || (string) ($admissionPlan['current_source_token']['id'] ?? '') === '' || (int) ($admissionPlan['current_source_token']['epoch'] ?? 0) <= 0) {
                        throw new \InvalidArgumentException('SQLite WAL current-source next217 token is invalid');
                    }
                    if (!is_array($admissionPlan['reader_admission_rows']) || $admissionPlan['reader_admission_rows'] === []) {
                        throw new \InvalidArgumentException('SQLite WAL current-source next217 requires reader admission rows');
                    }
                    foreach (['checkpoint_frame', 'checkpoint_cookie', 'schema_cookie'] as $key) {
                        if ((int) $admissionPlan[$key] <= 0) {
                            throw new \InvalidArgumentException("SQLite WAL current-source next217 {$key} must be positive");
                        }
                    }
                }

                /**
                 * @param list<array<string,mixed>> $rows
                 */
                private static function allRowsPass(array $rows, string $key): bool
                {
                    foreach ($rows as $row) {
                        if (($row[$key] ?? false) !== true) {
                            return false;
                        }
                    }

                    return true;
                }

                /**
                 * @param array<string,mixed> $reader
                 * @param array<string,mixed>|null $receipt
                 * @return array<string,mixed>
                 */
                private static function receiptRow(
                    array $reader,
                    ?array $receipt,
                    string $sourceId,
                    int $epoch,
                    int $checkpointFrame,
                    int $checkpointCookie,
                    int $schemaCookie
                ): array {
                    foreach (['reader', 'page', 'expected_action', 'acknowledged_image_sha256', 'observed_image_sha256', 'checkpoint_admitted'] as $key) {
                        if (!array_key_exists($key, $reader)) {
                            throw new \InvalidArgumentException("SQLite WAL current-source next217 missing reader {$key}");
                        }
                    }

                    $name = (string) $reader['reader'];
                    $page = (int) $reader['page'];
                    $expectedAction = (string) $reader['expected_action'];
                    if ($name === '' || $page <= 0 || !in_array($expectedAction, ['retain-reader-cache', 'reopen-reader-cache'], true)) {
                        throw new \InvalidArgumentException('SQLite WAL current-source next217 reader row is invalid');
                    }

                    $receiptSource = $receipt === null ? null : (string) ($receipt['source_id'] ?? '');
                    $receiptEpoch = $receipt === null ? null : (int) ($receipt['epoch'] ?? 0);
                    $receiptFrame = $receipt === null ? null : (int) ($receipt['checkpoint_frame'] ?? 0);
                    $receiptCookie = $receipt === null ? null : (int) ($receipt['checkpoint_cookie'] ?? 0);
                    $receiptSchema = $receipt === null ? null : (int) ($receipt['schema_cookie'] ?? 0);
                    $receiptDigest = $receipt === null ? null : (string) ($receipt['image_sha256'] ?? '');
                    $fenceToken = $receipt === null ? null : (string) ($receipt['reopen_fence_token'] ?? '');
                    $ackReceiptMatches = $receipt !== null
                        && ($receipt['acknowledged'] ?? false) === true
                        && $receiptSource === $sourceId
                        && $receiptEpoch === $epoch
                        && $receiptFrame === $checkpointFrame
                        && $receiptCookie === $checkpointCookie
                        && $receiptSchema === $schemaCookie
                        && hash_equals((string) $reader['observed_image_sha256'], $receiptDigest);
                    $reopenReceiptMatches = $receipt !== null
                        && ($receipt['reopen_fenced'] ?? false) === true
                        && $receiptSource === $sourceId
                        && $receiptEpoch === $epoch
                        && $receiptFrame === $checkpointFrame
                        && $receiptCookie === $checkpointCookie
                        && $receiptSchema === $schemaCookie
                        && $fenceToken === 'reopen:' . $name . ':' . $sourceId . ':' . $checkpointFrame;
                    $journalDeleteDurable = $receipt !== null && ($receipt['journal_deleted'] ?? false) === true;
                    $walSyncDurable = $receipt !== null && ($receipt['wal_synced'] ?? false) === true;
                    $directorySyncDurable = $receipt !== null && ($receipt['directory_synced'] ?? false) === true;
                    $expectedMatches = $expectedAction === 'retain-reader-cache'
                        ? $ackReceiptMatches && ($reader['checkpoint_admitted'] ?? false) === true
                        : $reopenReceiptMatches;
                    $admitted = $expectedMatches && $journalDeleteDurable && $walSyncDurable && $directorySyncDurable;

                    return [
                        'reader' => $name,
                        'page' => $page,
                        'expected_action' => $expectedAction,
                        'source_id' => $receiptSource,
                        'epoch' => $receiptEpoch,
                        'checkpoint_frame' => $receiptFrame,
                        'checkpoint_cookie' => $receiptCookie,
                        'schema_cookie' => $receiptSchema,
                        'ack_receipt_matches' => $ackReceiptMatches,
                        'reopen_receipt_matches' => $reopenReceiptMatches,
                        'journal_delete_durable' => $journalDeleteDurable,
                        'wal_sync_durable' => $walSyncDurable,
                        'directory_sync_durable' => $directorySyncDurable,
                        'admitted' => $admitted,
                        'acknowledged_image_sha256' => $receiptDigest,
                        'expected_image_sha256' => (string) ($reader['expected_image_sha256'] ?? ''),
                        'observed_image_sha256' => (string) $reader['observed_image_sha256'],
                        'reopen_fence_token' => $fenceToken,
                        'reason' => $admitted
                            ? 'durable_reader_receipt_matches_current_source'
                            : ($expectedAction === 'retain-reader-cache' ? 'durable_reader_ack_receipt_required' : 'durable_reopen_fence_receipt_required'),
                        'transition' => $name . '>' . ($admitted ? 'admit-next-source' : 'block-next-source') . ':next217',
                    ];
                }
        };

        return $impl::plan($admissionPlan, $receipts);
    }

    public static function next218RestartOrTruncate(array $passiveCheckpoint, array $writers, string $mode): array
    {
        $impl = new class {
                /**
                 * @param array<string,mixed> $passiveCheckpoint
                 * @param list<array<string,mixed>> $writers
                 * @return array<string,mixed>
                 */
                public static function restartOrTruncate(array $passiveCheckpoint, array $writers, string $mode): array
                {
                    if (($passiveCheckpoint['status'] ?? null) !== 'wal-hot-journal-savepoint-checkpoint-current-source-next212') {
                        throw new \InvalidArgumentException('SQLite WAL hot-journal savepoint checkpoint current-source next218 requires an admitted next212 passive checkpoint');
                    }
                    if (!in_array($mode, ['restart', 'truncate'], true)) {
                        throw new \InvalidArgumentException('SQLite WAL hot-journal savepoint checkpoint current-source next218 mode must be restart or truncate');
                    }
                    if ($writers === []) {
                        throw new \InvalidArgumentException('SQLite WAL hot-journal savepoint checkpoint current-source next218 requires writer rows');
                    }

                    $requestedFrame = self::positiveInt($passiveCheckpoint, 'requested_checkpoint_frame');
                    $checkpointedFrame = self::positiveInt($passiveCheckpoint, 'checkpointed_frame');
                    $databaseDigest = self::digestField($passiveCheckpoint, 'database_digest');
                    $walDigest = self::digestField($passiveCheckpoint, 'wal_digest');
                    $writerDigest = self::digestField($passiveCheckpoint, 'writer_digest');
                    $nextWriterGeneration = self::positiveInt($passiveCheckpoint, 'next_writer_generation');
                    $minimumStatementGeneration = self::nonNegativeInt($passiveCheckpoint, 'minimum_statement_generation');
                    $activeReaders = self::stringList($passiveCheckpoint, 'active_reader_names');
                    $reopenReaders = self::stringList($passiveCheckpoint, 'reopen_reader_names');

                    $writerRows = [];
                    foreach ($writers as $writer) {
                        $writerRows[] = self::writerRow(
                            $writer,
                            $databaseDigest,
                            $walDigest,
                            $writerDigest,
                            $requestedFrame,
                            $checkpointedFrame,
                            $nextWriterGeneration,
                            $minimumStatementGeneration
                        );
                    }

                    $admitted = array_values(array_filter($writerRows, static fn (array $row): bool => $row['admitted']));
                    $blocked = array_values(array_filter($writerRows, static fn (array $row): bool => !$row['admitted']));
                    $blockedReasons = [];
                    foreach ($blocked as $row) {
                        foreach ($row['blocked_reasons'] as $reason) {
                            $blockedReasons[] = $reason;
                        }
                    }

                    $readerPins = ($passiveCheckpoint['busy'] ?? false) === true || $checkpointedFrame < $requestedFrame || $activeReaders !== [];
                    $hasReopenReaders = $reopenReaders !== [];
                    $allFramesCheckpointed = $checkpointedFrame === $requestedFrame;
                    $canReset = !$readerPins && !$hasReopenReaders && $allFramesCheckpointed && $blocked === [];

                    $guardRows = [
                        [
                            'name' => 'next212_passive_checkpoint_complete',
                            'matched' => !$readerPins && $allFramesCheckpointed,
                            'reason' => 'restart/truncate may reset only after PASSIVE checkpoint wrote every requested frame and no reader pins the WAL',
                        ],
                        [
                            'name' => 'no_reopen_readers_pending',
                            'matched' => !$hasReopenReaders,
                            'reason' => 'stale current-source readers must reopen before a WAL reset can be published',
                        ],
                        [
                            'name' => 'writer_generation_fence',
                            'matched' => $admitted !== [] && $blocked === [],
                            'reason' => 'all candidate writers must observe the checkpointed database, WAL, writer digest, and savepoint fence',
                        ],
                    ];
                    $blockedGuards = array_values(array_column(
                        array_filter($guardRows, static fn (array $row): bool => !$row['matched']),
                        'name'
                    ));

                    $walAction = $canReset
                        ? ($mode === 'truncate' ? 'truncate_wal_to_zero_bytes' : 'restart_wal_header_with_new_salt')
                        : 'preserve_wal_for_reader_or_writer_reopen';

                    return [
                        'status' => $canReset
                            ? 'wal-hot-journal-savepoint-checkpoint-current-source-next218'
                            : 'wal-hot-journal-savepoint-checkpoint-current-source-blocked-next218',
                        'reason' => $canReset
                            ? 'restart_or_truncate_checkpoint_can_reset_wal_after_hot_journal_savepoint_fence'
                            : 'restart_or_truncate_checkpoint_preserves_wal_until_readers_and_writers_reopen',
                        'base_status' => $passiveCheckpoint['status'],
                        'mode' => $mode,
                        'database_path' => $passiveCheckpoint['database_path'] ?? null,
                        'journal_path' => $passiveCheckpoint['journal_path'] ?? null,
                        'wal_path' => $passiveCheckpoint['wal_path'] ?? null,
                        'page_size' => $passiveCheckpoint['page_size'] ?? null,
                        'requested_checkpoint_frame' => $requestedFrame,
                        'checkpointed_frame' => $checkpointedFrame,
                        'all_frames_checkpointed' => $allFramesCheckpointed,
                        'reader_pins_wal' => $readerPins,
                        'active_reader_names' => $activeReaders,
                        'reopen_reader_names' => $reopenReaders,
                        'database_digest' => $databaseDigest,
                        'wal_digest' => $walDigest,
                        'writer_digest' => $writerDigest,
                        'next_writer_generation' => $nextWriterGeneration,
                        'minimum_statement_generation' => $minimumStatementGeneration,
                        'writer_rows' => $writerRows,
                        'admitted_writer_names' => array_values(array_column($admitted, 'name')),
                        'blocked_writer_names' => array_values(array_column($blocked, 'name')),
                        'blocked_writer_reasons' => array_values(array_unique($blockedReasons)),
                        'can_reset_wal' => $canReset,
                        'reset_allowed' => $canReset && $mode === 'restart',
                        'truncate_allowed' => $canReset && $mode === 'truncate',
                        'wal_action' => $walAction,
                        'database_action' => 'checkpoint_database_already_contains_frames_through_' . $checkpointedFrame,
                        'sync_action' => $canReset ? 'sync_database_then_' . $mode . '_wal_header' : 'skip_wal_reset_sync_until_reopen',
                        'guard_rows' => $guardRows,
                        'guard_names' => array_column($guardRows, 'name'),
                        'guard_matches' => array_column($guardRows, 'matched'),
                        'blocked_guard_names' => $blockedGuards,
                        'operation_names' => array_values(array_unique(array_merge(
                            is_array($passiveCheckpoint['operation_names'] ?? null) ? $passiveCheckpoint['operation_names'] : [],
                            [
                                'verify_restart_truncate_current_source_next218',
                                $canReset ? 'publish_wal_reset_current_source_next218' : 'preserve_wal_reset_current_source_next218',
                                $walAction,
                            ]
                        ))),
                        'reset_digest' => hash('sha256', json_encode([$mode, $canReset, $writerRows, $checkpointedFrame], JSON_THROW_ON_ERROR)),
                        'dependencies' => array_values(array_unique(array_merge(
                            is_array($passiveCheckpoint['dependencies'] ?? null) ? $passiveCheckpoint['dependencies'] : [],
                            [
                                'sqlite-wal-hot-journal-savepoint-checkpoint-current-source-next218',
                                'sqlite-wal-restart-truncate-after-hot-journal-savepoint-fence',
                                'wordpress-import-checkpoint-reset-waits-for-current-source-reopen',
                            ]
                        ))),
                        'dependency_closure' => 'no new support component needed; reuses next212 checkpoint frame accounting, current-source reader reopen lists, and writer generation digests',
                        'non_overlap' => 'next218 finalizes RESTART/TRUNCATE reset admission after next212 PASSIVE checkpoint frame accounting; it does not repeat next212 reader-pin progress, next209 writer fences, WAL byte truncation, VFS savepoint rollback, rollback-journal commit/apply, or checkpoint transaction planning',
                    ];
                }

                /**
                 * @param array<string,mixed> $values
                 */
                private static function digestField(array $values, string $key): string
                {
                    $value = $values[$key] ?? null;
                    if (!is_string($value) || !preg_match('/^[a-f0-9]{64}$/', $value)) {
                        throw new \InvalidArgumentException("SQLite WAL hot-journal savepoint checkpoint current-source next218 requires {$key}");
                    }

                    return $value;
                }

                /**
                 * @param array<string,mixed> $values
                 */
                private static function positiveInt(array $values, string $key): int
                {
                    $value = $values[$key] ?? null;
                    if (!is_int($value) || $value <= 0) {
                        throw new \InvalidArgumentException("SQLite WAL hot-journal savepoint checkpoint current-source next218 requires positive {$key}");
                    }

                    return $value;
                }

                /**
                 * @param array<string,mixed> $values
                 */
                private static function nonNegativeInt(array $values, string $key): int
                {
                    $value = $values[$key] ?? null;
                    if (!is_int($value) || $value < 0) {
                        throw new \InvalidArgumentException("SQLite WAL hot-journal savepoint checkpoint current-source next218 requires non-negative {$key}");
                    }

                    return $value;
                }

                /**
                 * @param array<string,mixed> $values
                 * @return list<string>
                 */
                private static function stringList(array $values, string $key): array
                {
                    $list = $values[$key] ?? null;
                    if (!is_array($list)) {
                        throw new \InvalidArgumentException("SQLite WAL hot-journal savepoint checkpoint current-source next218 requires {$key}");
                    }
                    foreach ($list as $value) {
                        if (!is_string($value) || $value === '') {
                            throw new \InvalidArgumentException("SQLite WAL hot-journal savepoint checkpoint current-source next218 {$key} must contain non-empty strings");
                        }
                    }

                    return array_values($list);
                }

                /**
                 * @param array<string,mixed> $writer
                 * @return array<string,mixed>
                 */
                private static function writerRow(
                    array $writer,
                    string $databaseDigest,
                    string $walDigest,
                    string $writerDigest,
                    int $requestedFrame,
                    int $checkpointedFrame,
                    int $nextWriterGeneration,
                    int $minimumStatementGeneration
                ): array {
                    $name = $writer['name'] ?? null;
                    if (!is_string($name) || $name === '') {
                        throw new \InvalidArgumentException('SQLite WAL hot-journal savepoint checkpoint current-source next218 writer name is required');
                    }
                    foreach (['observed_database_digest', 'observed_wal_digest', 'observed_writer_digest'] as $key) {
                        if (!is_string($writer[$key] ?? null) || !preg_match('/^[a-f0-9]{64}$/', (string) $writer[$key])) {
                            throw new \InvalidArgumentException("SQLite WAL hot-journal savepoint checkpoint current-source next218 {$name} {$key} is required");
                        }
                    }
                    $generation = $writer['writer_generation'] ?? null;
                    $startFrame = $writer['start_frame'] ?? null;
                    $lastFrame = $writer['last_frame'] ?? null;
                    if (!is_int($generation) || $generation < 0 || !is_int($startFrame) || $startFrame <= 0 || !is_int($lastFrame) || $lastFrame < $startFrame) {
                        throw new \InvalidArgumentException("SQLite WAL hot-journal savepoint checkpoint current-source next218 {$name} generation/frame bounds are invalid");
                    }

                    $reasons = [];
                    if ($generation !== $nextWriterGeneration) {
                        $reasons[] = 'writer_generation_mismatch';
                    }
                    if ($startFrame < $minimumStatementGeneration) {
                        $reasons[] = 'writer_start_frame_before_statement_generation';
                    }
                    if ($lastFrame !== $requestedFrame || $checkpointedFrame !== $requestedFrame) {
                        $reasons[] = 'writer_wal_frame_not_fully_checkpointed';
                    }
                    if (!hash_equals($databaseDigest, (string) $writer['observed_database_digest'])) {
                        $reasons[] = 'writer_database_digest_mismatch';
                    }
                    if (!hash_equals($walDigest, (string) $writer['observed_wal_digest'])) {
                        $reasons[] = 'writer_wal_digest_mismatch';
                    }
                    if (!hash_equals($writerDigest, (string) $writer['observed_writer_digest'])) {
                        $reasons[] = 'writer_digest_mismatch';
                    }
                    if (($writer['hot_journal_present'] ?? false) === true) {
                        $reasons[] = 'writer_hot_journal_present';
                    }
                    if (($writer['savepoint_depth'] ?? 0) !== 0) {
                        $reasons[] = 'writer_savepoint_scope_not_closed';
                    }
                    if (($writer['dirty'] ?? false) === true) {
                        $reasons[] = 'writer_dirty_page_cache';
                    }
                    if (($writer['sync_receipt'] ?? false) !== true) {
                        $reasons[] = 'writer_missing_sync_receipt';
                    }

                    $admitted = $reasons === [];

                    return [
                        'name' => $name,
                        'writer_generation' => $generation,
                        'expected_generation' => $nextWriterGeneration,
                        'start_frame' => $startFrame,
                        'last_frame' => $lastFrame,
                        'expected_checkpoint_frame' => $requestedFrame,
                        'observed_database_digest' => (string) $writer['observed_database_digest'],
                        'observed_wal_digest' => (string) $writer['observed_wal_digest'],
                        'observed_writer_digest' => (string) $writer['observed_writer_digest'],
                        'expected_database_digest' => $databaseDigest,
                        'expected_wal_digest' => $walDigest,
                        'expected_writer_digest' => $writerDigest,
                        'hot_journal_present' => ($writer['hot_journal_present'] ?? false) === true,
                        'savepoint_depth' => (int) ($writer['savepoint_depth'] ?? 0),
                        'dirty' => ($writer['dirty'] ?? false) === true,
                        'sync_receipt' => ($writer['sync_receipt'] ?? false) === true,
                        'admitted' => $admitted,
                        'writer_reason' => $admitted ? 'writer_can_publish_restart_truncate_reset' : implode('|', $reasons),
                        'blocked_reasons' => $reasons,
                    ];
                }
        };

        return $impl::restartOrTruncate($passiveCheckpoint, $writers, $mode);
    }

    public static function next219Plan(array $admissionPlan, array $savepointScopes): array
    {
        $impl = new class {
                /**
                 * @param array<string,mixed> $admissionPlan
                 * @param list<array<string,mixed>> $savepointScopes
                 * @return array<string,mixed>
                 */
                public static function plan(array $admissionPlan, array $savepointScopes): array
                {
                    self::assertAdmissionPlan($admissionPlan);
                    if ($savepointScopes === []) {
                        throw new \InvalidArgumentException('SQLite WAL hot-journal current-source next219 requires savepoint scope rows');
                    }

                    $token = $admissionPlan['current_source_token'];
                    $epoch = (int) $token['epoch'];
                    $checkpointFrame = (int) $admissionPlan['checkpoint_frame'];
                    $checkpointCookie = (int) $admissionPlan['checkpoint_cookie'];
                    $schemaCookie = (int) $admissionPlan['schema_cookie'];
                    $admittedReaders = self::stringSet($admissionPlan['admitted_reader_names']);
                    $reopenReaders = self::stringSet($admissionPlan['reopen_reader_names']);

                    $rows = [];
                    foreach ($savepointScopes as $scope) {
                        $rows[] = self::scopeRow($scope, $epoch, $checkpointFrame, $checkpointCookie, $schemaCookie, $admittedReaders, $reopenReaders);
                    }

                    $finalized = array_values(array_column(array_filter($rows, static fn (array $row): bool => $row['finalized']), 'name'));
                    $blocked = array_values(array_column(array_filter($rows, static fn (array $row): bool => !$row['finalized']), 'name'));
                    $blockedReasons = [];
                    foreach ($rows as $row) {
                        foreach ($row['blocked_reasons'] as $reason) {
                            $blockedReasons[] = $reason;
                        }
                    }
                    $blockedReasons = array_values(array_unique($blockedReasons));

                    $guards = [
                        'next211_checkpoint_admitted' => $admissionPlan['status'] === 'wal-hot-journal-savepoint-checkpoint-current-source-next211'
                            && ($admissionPlan['checkpoint_admitted'] ?? false) === true,
                        'all_savepoint_scopes_finalized' => $blocked === [],
                        'at_least_one_scope_finalized' => $finalized !== [],
                        'no_reader_reopen_overlap' => !self::hasReaderOverlap($rows, $reopenReaders),
                    ];
                    $guardBlocks = array_keys(array_filter($guards, static fn (bool $passed): bool => !$passed));

                    return [
                        'status' => $guardBlocks === []
                            ? 'wal-hot-journal-savepoint-checkpoint-current-source-next219'
                            : 'wal-hot-journal-savepoint-checkpoint-current-source-blocked-next219',
                        'reason' => $guardBlocks === []
                            ? 'savepoint_scopes_finalized_before_checkpoint_next_source'
                            : 'savepoint_scopes_block_checkpoint_next_source',
                        'database_path' => (string) $admissionPlan['database_path'],
                        'wal_path' => (string) $admissionPlan['wal_path'],
                        'journal_path' => (string) $admissionPlan['journal_path'],
                        'current_source_token' => $token,
                        'checkpoint_frame' => $checkpointFrame,
                        'checkpoint_cookie' => $checkpointCookie,
                        'schema_cookie' => $schemaCookie,
                        'next_source_epoch' => (int) $admissionPlan['next_source_epoch'],
                        'scope_rows' => $rows,
                        'finalized_scope_names' => $finalized,
                        'blocked_scope_names' => $blocked,
                        'blocked_scope_reasons' => $blockedReasons,
                        'guard_names' => array_keys($guards),
                        'guard_matches' => array_values($guards),
                        'blocked_guard_names' => $guardBlocks,
                        'checkpoint_next_source_published' => $guardBlocks === [],
                        'savepoint_scope_digest' => hash('sha256', json_encode($rows, JSON_THROW_ON_ERROR)),
                        'operation_names' => array_values(array_unique(array_merge(
                            is_array($admissionPlan['operation_names'] ?? null) ? $admissionPlan['operation_names'] : [],
                            [
                                'finalize_hot_journal_savepoint_scope_next219',
                                'verify_checkpoint_cookie_after_savepoint_finalization_next219',
                                'publish_checkpoint_next_source_after_savepoint_finalization_next219',
                            ]
                        ))),
                        'dependencies' => array_values(array_unique(array_merge(
                            is_array($admissionPlan['dependencies'] ?? null) ? $admissionPlan['dependencies'] : [],
                            [
                                'sqlite-wal-hot-journal-savepoint-checkpoint-current-source-next219',
                                'sqlite-savepoint-scope-finalization-before-wal-current-source',
                                'wordpress-import-hot-journal-savepoint-finalization',
                            ]
                        ))),
                        'dependency_closure' => 'no new support component needed; reuses next211 reader acknowledgements plus savepoint scope generation, journal delete receipts, and checkpoint cookies',
                        'non_overlap' => 'next219 finalizes savepoint scopes before publishing checkpoint next-source state; it does not repeat next211 reader acknowledgements, next208 reader-slot digest validation, WAL byte truncation, VFS savepoint rollback apply, rollback-journal commit/apply, or checkpoint transaction planning',
                    ];
                }

                /**
                 * @param array<string,mixed> $admissionPlan
                 */
                private static function assertAdmissionPlan(array $admissionPlan): void
                {
                    foreach (['status', 'database_path', 'wal_path', 'journal_path', 'current_source_token', 'checkpoint_frame', 'checkpoint_cookie', 'schema_cookie', 'next_source_epoch', 'admitted_reader_names', 'reopen_reader_names'] as $key) {
                        if (!array_key_exists($key, $admissionPlan)) {
                            throw new \InvalidArgumentException("SQLite WAL hot-journal current-source next219 missing admission {$key}");
                        }
                    }
                    if (!is_array($admissionPlan['current_source_token']) || (string) ($admissionPlan['current_source_token']['id'] ?? '') === '' || (int) ($admissionPlan['current_source_token']['epoch'] ?? 0) <= 0) {
                        throw new \InvalidArgumentException('SQLite WAL hot-journal current-source next219 token is invalid');
                    }
                    foreach (['checkpoint_frame', 'checkpoint_cookie', 'schema_cookie', 'next_source_epoch'] as $key) {
                        if ((int) $admissionPlan[$key] <= 0) {
                            throw new \InvalidArgumentException("SQLite WAL hot-journal current-source next219 {$key} must be positive");
                        }
                    }
                    if ((int) $admissionPlan['next_source_epoch'] <= (int) $admissionPlan['current_source_token']['epoch']) {
                        throw new \InvalidArgumentException('SQLite WAL hot-journal current-source next219 next source epoch must advance');
                    }
                }

                /**
                 * @param mixed $values
                 * @return array<string,true>
                 */
                private static function stringSet($values): array
                {
                    if (!is_array($values)) {
                        throw new \InvalidArgumentException('SQLite WAL hot-journal current-source next219 reader names must be arrays');
                    }
                    $set = [];
                    foreach ($values as $value) {
                        if (!is_string($value) || $value === '') {
                            throw new \InvalidArgumentException('SQLite WAL hot-journal current-source next219 reader names must be non-empty strings');
                        }
                        $set[$value] = true;
                    }

                    return $set;
                }

                /**
                 * @param array<string,mixed> $scope
                 * @param array<string,true> $admittedReaders
                 * @param array<string,true> $reopenReaders
                 * @return array<string,mixed>
                 */
                private static function scopeRow(array $scope, int $epoch, int $checkpointFrame, int $checkpointCookie, int $schemaCookie, array $admittedReaders, array $reopenReaders): array
                {
                    foreach (['name', 'savepoint_depth', 'released', 'rollback_generation', 'checkpoint_frame', 'checkpoint_cookie', 'schema_cookie', 'journal_delete_receipt', 'wal_reset_frame', 'reader_names', 'page_digests'] as $key) {
                        if (!array_key_exists($key, $scope)) {
                            throw new \InvalidArgumentException("SQLite WAL hot-journal current-source next219 missing scope {$key}");
                        }
                    }
                    $name = (string) $scope['name'];
                    if ($name === '') {
                        throw new \InvalidArgumentException('SQLite WAL hot-journal current-source next219 scope name is required');
                    }
                    foreach (['savepoint_depth', 'rollback_generation', 'checkpoint_frame', 'checkpoint_cookie', 'schema_cookie', 'wal_reset_frame'] as $key) {
                        if (!is_int($scope[$key]) || $scope[$key] < 0) {
                            throw new \InvalidArgumentException("SQLite WAL hot-journal current-source next219 {$name} {$key} must be a non-negative integer");
                        }
                    }
                    $readerNames = self::stringSet($scope['reader_names']);
                    $pageDigests = self::pageDigestMap($scope['page_digests'], $name);

                    $reasons = [];
                    if ((int) $scope['savepoint_depth'] !== 0) {
                        $reasons[] = 'savepoint_scope_depth_open';
                    }
                    if (($scope['released'] ?? false) !== true) {
                        $reasons[] = 'savepoint_scope_not_released';
                    }
                    if ((int) $scope['rollback_generation'] > $epoch) {
                        $reasons[] = 'savepoint_rollback_generation_after_current_source';
                    }
                    if ((int) $scope['checkpoint_frame'] !== $checkpointFrame) {
                        $reasons[] = 'savepoint_checkpoint_frame_mismatch';
                    }
                    if ((int) $scope['checkpoint_cookie'] !== $checkpointCookie) {
                        $reasons[] = 'savepoint_checkpoint_cookie_mismatch';
                    }
                    if ((int) $scope['schema_cookie'] !== $schemaCookie) {
                        $reasons[] = 'savepoint_schema_cookie_mismatch';
                    }
                    if (($scope['journal_delete_receipt'] ?? false) !== true) {
                        $reasons[] = 'savepoint_hot_journal_delete_receipt_missing';
                    }
                    if ((int) $scope['wal_reset_frame'] < $checkpointFrame) {
                        $reasons[] = 'savepoint_wal_reset_before_checkpoint_frame';
                    }
                    if (($scope['hot_journal_present'] ?? false) === true) {
                        $reasons[] = 'savepoint_hot_journal_still_present';
                    }

                    $unknownReaders = array_values(array_diff(array_keys($readerNames), array_keys($admittedReaders), array_keys($reopenReaders)));
                    if ($unknownReaders !== []) {
                        $reasons[] = 'savepoint_reader_not_in_checkpoint_admission';
                    }
                    $reopenOverlap = array_values(array_intersect(array_keys($readerNames), array_keys($reopenReaders)));
                    if ($reopenOverlap !== []) {
                        $reasons[] = 'savepoint_reader_waits_for_reopen_fence';
                    }

                    $finalized = $reasons === [];

                    return [
                        'name' => $name,
                        'savepoint_depth' => (int) $scope['savepoint_depth'],
                        'released' => (bool) $scope['released'],
                        'rollback_generation' => (int) $scope['rollback_generation'],
                        'checkpoint_frame' => (int) $scope['checkpoint_frame'],
                        'checkpoint_cookie' => (int) $scope['checkpoint_cookie'],
                        'schema_cookie' => (int) $scope['schema_cookie'],
                        'journal_delete_receipt' => (bool) $scope['journal_delete_receipt'],
                        'wal_reset_frame' => (int) $scope['wal_reset_frame'],
                        'reader_names' => array_keys($readerNames),
                        'page_numbers' => array_keys($pageDigests),
                        'page_digest_count' => count($pageDigests),
                        'page_digests' => $pageDigests,
                        'hot_journal_present' => ($scope['hot_journal_present'] ?? false) === true,
                        'unknown_readers' => $unknownReaders,
                        'reopen_reader_overlap' => $reopenOverlap,
                        'finalized' => $finalized,
                        'blocked_reasons' => $reasons,
                        'scope_reason' => $finalized ? 'savepoint_scope_finalized_for_checkpoint_next_source' : $reasons[0],
                        'scope_transition' => $name . '>' . ($finalized ? 'publish-checkpoint-next-source' : 'hold-current-source') . ':next219',
                    ];
                }

                /**
                 * @param mixed $values
                 * @return array<int,string>
                 */
                private static function pageDigestMap($values, string $scopeName): array
                {
                    if (!is_array($values) || $values === []) {
                        throw new \InvalidArgumentException("SQLite WAL hot-journal current-source next219 {$scopeName} requires page digests");
                    }
                    $normalized = [];
                    foreach ($values as $page => $digest) {
                        $pageNumber = (int) $page;
                        if ($pageNumber <= 0 || !is_string($digest) || !preg_match('/^[a-f0-9]{64}$/', $digest)) {
                            throw new \InvalidArgumentException("SQLite WAL hot-journal current-source next219 {$scopeName} page digests must map positive pages to sha256 strings");
                        }
                        $normalized[$pageNumber] = $digest;
                    }
                    ksort($normalized);

                    return $normalized;
                }

                /**
                 * @param list<array<string,mixed>> $rows
                 * @param array<string,true> $reopenReaders
                 */
                private static function hasReaderOverlap(array $rows, array $reopenReaders): bool
                {
                    foreach ($rows as $row) {
                        foreach ($row['reader_names'] as $readerName) {
                            if (isset($reopenReaders[$readerName])) {
                                return true;
                            }
                        }
                    }

                    return false;
                }
        };

        return $impl::plan($admissionPlan, $savepointScopes);
    }

    public static function next221Plan(array $next217Plan, array $sidecarReceipts): array
    {
        $impl = new class {
                /**
                 * @param array<string,mixed> $next217Plan
                 * @param list<array<string,mixed>> $sidecarReceipts
                 * @return array<string,mixed>
                 */
                public static function plan(array $next217Plan, array $sidecarReceipts): array
                {
                    self::assertNext217Plan($next217Plan);
                    if ($sidecarReceipts === []) {
                        throw new \InvalidArgumentException('SQLite WAL current-source next221 requires sidecar retirement receipts');
                    }

                    $token = $next217Plan['current_source_token'];
                    $sourceId = (string) $token['id'];
                    $sourceEpoch = (int) $token['epoch'];
                    $nextEpoch = (int) ($next217Plan['next_source_epoch'] ?? ($sourceEpoch + 1));
                    $checkpointFrame = (int) $next217Plan['checkpoint_frame'];
                    $checkpointCookie = (int) $next217Plan['checkpoint_cookie'];

                    $rows = [];
                    foreach ($sidecarReceipts as $receipt) {
                        $rows[] = self::sidecarRow($receipt, $sourceId, $nextEpoch, $checkpointFrame, $checkpointCookie);
                    }

                    $blockedRows = array_values(array_filter($rows, static fn (array $row): bool => !$row['admitted']));
                    $byKind = [];
                    foreach ($rows as $row) {
                        $byKind[$row['kind']] = ($byKind[$row['kind']] ?? 0) + 1;
                    }

                    $requiredKinds = ['hot-journal', 'wal', 'shm'];
                    $missingKinds = array_values(array_filter($requiredKinds, static fn (string $kind): bool => !isset($byKind[$kind])));
                    $guards = [
                        'next217_checkpoint_admitted' => ($next217Plan['status'] ?? null) === 'wal-hot-journal-savepoint-checkpoint-current-source-next217'
                            && ($next217Plan['checkpoint_admitted'] ?? false) === true,
                        'next217_has_no_blocked_readers' => ($next217Plan['blocked_reader_names'] ?? []) === [],
                        'required_sidecars_observed' => $missingKinds === [],
                        'sidecar_receipts_match_next_source' => $blockedRows === [],
                        'old_hot_journal_retired' => self::kindHasAction($rows, 'hot-journal', 'delete'),
                        'next_wal_generation_durable' => self::kindHasAction($rows, 'wal', 'restart-header'),
                        'shm_read_marks_reset' => self::kindHasAction($rows, 'shm', 'reset-read-marks'),
                        'directory_sync_after_retirement' => self::allRowsPass($rows, 'directory_sync_durable'),
                    ];
                    $blocked = array_keys(array_filter($guards, static fn (bool $passed): bool => !$passed));

                    return [
                        'status' => $blocked === []
                            ? 'wal-hot-journal-savepoint-checkpoint-current-source-next221'
                            : 'wal-hot-journal-savepoint-checkpoint-current-source-blocked-next221',
                        'reason' => $blocked === []
                            ? 'sidecar_retirement_receipts_publish_next_current_source'
                            : 'sidecar_retirement_receipts_block_next_current_source',
                        'database_path' => (string) $next217Plan['database_path'],
                        'wal_path' => (string) $next217Plan['wal_path'],
                        'journal_path' => (string) $next217Plan['journal_path'],
                        'shm_path' => (string) ($next217Plan['shm_path'] ?? ((string) $next217Plan['wal_path'] . '-shm')),
                        'current_source_token' => $token,
                        'next_source_token' => [
                            'id' => $sourceId . ':next221',
                            'epoch' => $nextEpoch,
                            'checkpoint_frame' => $checkpointFrame,
                            'checkpoint_cookie' => $checkpointCookie,
                        ],
                        'checkpoint_frame' => $checkpointFrame,
                        'checkpoint_cookie' => $checkpointCookie,
                        'sidecar_rows' => $rows,
                        'sidecar_kinds' => array_keys($byKind),
                        'missing_sidecar_kinds' => $missingKinds,
                        'admitted_sidecar_names' => array_values(array_column(array_filter($rows, static fn (array $row): bool => $row['admitted']), 'name')),
                        'blocked_sidecar_names' => array_values(array_column($blockedRows, 'name')),
                        'guard_names' => array_keys($guards),
                        'guard_matches' => array_values($guards),
                        'blocked_guard_names' => $blocked,
                        'checkpoint_admitted' => $blocked === [],
                        'retirement_digest' => hash('sha256', json_encode($rows, JSON_THROW_ON_ERROR)),
                        'operation_names' => array_values(array_unique(array_merge(
                            is_array($next217Plan['operation_names'] ?? null) ? $next217Plan['operation_names'] : [],
                            [
                                'verify_hot_journal_retirement_receipt_next221',
                                'verify_restarted_wal_generation_receipt_next221',
                                'verify_shm_read_mark_reset_receipt_next221',
                                'publish_next_current_source_after_sidecar_retirement_next221',
                            ]
                        ))),
                        'dependencies' => array_values(array_unique(array_merge(
                            is_array($next217Plan['dependencies'] ?? null) ? $next217Plan['dependencies'] : [],
                            [
                                'sqlite-wal-hot-journal-savepoint-checkpoint-current-source-next221',
                                'sqlite-wal-sidecar-retirement-current-source-barrier',
                                'wordpress-import-hot-journal-checkpoint-sidecar-retirement',
                            ]
                        ))),
                        'dependency_closure' => 'no new support component needed; reuses next217 durable reader receipts, WAL checkpoint metadata, VFS sidecar paths, and directory sync receipts',
                        'non_overlap' => 'next221 verifies post-next217 sidecar retirement receipts before publishing the next current-source token; it does not repeat next217 reader receipt admission, next211 page digest admission, next208 reader slot validation, WAL byte truncation, VFS savepoint rollback apply, rollback-journal commit/apply, or checkpoint transaction planning',
                    ];
                }

                /**
                 * @param array<string,mixed> $plan
                 */
                private static function assertNext217Plan(array $plan): void
                {
                    foreach (['status', 'database_path', 'wal_path', 'journal_path', 'current_source_token', 'checkpoint_frame', 'checkpoint_cookie', 'blocked_reader_names'] as $key) {
                        if (!array_key_exists($key, $plan)) {
                            throw new \InvalidArgumentException("SQLite WAL current-source next221 missing next217 {$key}");
                        }
                    }
                    if (!is_array($plan['current_source_token']) || (string) ($plan['current_source_token']['id'] ?? '') === '' || (int) ($plan['current_source_token']['epoch'] ?? 0) <= 0) {
                        throw new \InvalidArgumentException('SQLite WAL current-source next221 token is invalid');
                    }
                    foreach (['checkpoint_frame', 'checkpoint_cookie'] as $key) {
                        if ((int) $plan[$key] <= 0) {
                            throw new \InvalidArgumentException("SQLite WAL current-source next221 {$key} must be positive");
                        }
                    }
                }

                /**
                 * @param array<string,mixed> $receipt
                 * @return array<string,mixed>
                 */
                private static function sidecarRow(array $receipt, string $sourceId, int $nextEpoch, int $checkpointFrame, int $checkpointCookie): array
                {
                    foreach (['name', 'kind', 'path', 'action', 'source_id', 'next_epoch', 'checkpoint_frame', 'checkpoint_cookie', 'receipt_sha256'] as $key) {
                        if (!array_key_exists($key, $receipt)) {
                            throw new \InvalidArgumentException("SQLite WAL current-source next221 missing sidecar {$key}");
                        }
                    }

                    $name = (string) $receipt['name'];
                    $kind = (string) $receipt['kind'];
                    $action = (string) $receipt['action'];
                    $path = (string) $receipt['path'];
                    if ($name === '' || $path === '' || !in_array($kind, ['hot-journal', 'wal', 'shm'], true)) {
                        throw new \InvalidArgumentException('SQLite WAL current-source next221 sidecar receipt identity is invalid');
                    }
                    if (!in_array($action, ['delete', 'restart-header', 'reset-read-marks', 'preserve'], true)) {
                        throw new \InvalidArgumentException('SQLite WAL current-source next221 sidecar receipt action is invalid');
                    }
                    $sha = (string) $receipt['receipt_sha256'];
                    if (!preg_match('/^[a-f0-9]{64}$/', $sha)) {
                        throw new \InvalidArgumentException('SQLite WAL current-source next221 sidecar receipt digest must be sha256');
                    }

                    $checks = [
                        'source_token' => (string) $receipt['source_id'] === $sourceId,
                        'next_epoch' => (int) $receipt['next_epoch'] === $nextEpoch,
                        'checkpoint_frame' => (int) $receipt['checkpoint_frame'] === $checkpointFrame,
                        'checkpoint_cookie' => (int) $receipt['checkpoint_cookie'] === $checkpointCookie,
                        'receipt_synced' => ($receipt['synced'] ?? false) === true,
                        'directory_sync_durable' => ($receipt['directory_synced'] ?? false) === true,
                        'savepoint_closed' => ($receipt['savepoint_closed'] ?? false) === true,
                        'lock_receipt' => ($receipt['exclusive_lock_receipt'] ?? false) === true,
                        'action_matches_kind' => self::actionMatchesKind($kind, $action),
                    ];
                    $failed = array_keys(array_filter($checks, static fn (bool $passed): bool => !$passed));

                    return [
                        'name' => $name,
                        'kind' => $kind,
                        'path' => $path,
                        'action' => $action,
                        'source_id' => (string) $receipt['source_id'],
                        'next_epoch' => (int) $receipt['next_epoch'],
                        'checkpoint_frame' => (int) $receipt['checkpoint_frame'],
                        'checkpoint_cookie' => (int) $receipt['checkpoint_cookie'],
                        'receipt_sha256' => $sha,
                        'directory_sync_durable' => $checks['directory_sync_durable'],
                        'admitted' => $failed === [],
                        'failed_checks' => $failed,
                        'reason' => $failed === []
                            ? 'sidecar_retirement_receipt_matches_next_source'
                            : 'sidecar_retirement_receipt_requires_replay',
                        'transition' => $name . '>' . ($failed === [] ? 'retire-sidecar' : 'replay-sidecar') . ':next221',
                    ];
                }

                private static function actionMatchesKind(string $kind, string $action): bool
                {
                    return ($kind === 'hot-journal' && $action === 'delete')
                        || ($kind === 'wal' && $action === 'restart-header')
                        || ($kind === 'shm' && $action === 'reset-read-marks');
                }

                /**
                 * @param list<array<string,mixed>> $rows
                 */
                private static function kindHasAction(array $rows, string $kind, string $action): bool
                {
                    foreach ($rows as $row) {
                        if ($row['kind'] === $kind && $row['action'] === $action && $row['admitted'] === true) {
                            return true;
                        }
                    }

                    return false;
                }

                /**
                 * @param list<array<string,mixed>> $rows
                 */
                private static function allRowsPass(array $rows, string $key): bool
                {
                    foreach ($rows as $row) {
                        if (($row[$key] ?? false) !== true) {
                            return false;
                        }
                    }

                    return true;
                }
        };

        return $impl::plan($next217Plan, $sidecarReceipts);
    }

    public static function next220ReaderReopenPlan(array $next219Plan, array $readerReceipts): array
    {
        $impl = new class {
                /**
                 * @param array<string,mixed> $next219Plan
                 * @param list<array<string,mixed>> $readerReceipts
                 * @return array<string,mixed>
                 */
                public static function plan(array $next219Plan, array $readerReceipts): array
                {
                    if (($next219Plan['status'] ?? null) !== 'wal-hot-journal-savepoint-checkpoint-current-source-next219') {
                        throw new \InvalidArgumentException('SQLite WAL hot-journal savepoint checkpoint current-source next220 requires an admitted next219 plan');
                    }
                    if (($next219Plan['checkpoint_next_source_published'] ?? null) !== true) {
                        throw new \InvalidArgumentException('SQLite WAL hot-journal savepoint checkpoint current-source next220 requires published checkpoint source');
                    }
                    if ($readerReceipts === []) {
                        throw new \InvalidArgumentException('SQLite WAL hot-journal savepoint checkpoint current-source next220 requires reader reopen receipts');
                    }

                    $token = self::token($next219Plan['current_source_token'] ?? null);
                    $checkpointFrame = self::positiveInt($next219Plan, 'checkpoint_frame');
                    $checkpointCookie = self::positiveInt($next219Plan, 'checkpoint_cookie');
                    $schemaCookie = self::positiveInt($next219Plan, 'schema_cookie');
                    $nextEpoch = self::positiveInt($next219Plan, 'next_source_epoch');

                    $admittedReaders = self::stringList($next219Plan['admitted_reader_names'] ?? null, 'admitted readers');
                    $reopenReaders = self::stringList($next219Plan['reopen_reader_names'] ?? [], 'reopen readers', true);
                    $allowedReaders = array_values(array_unique(array_merge($admittedReaders, $reopenReaders)));

                    $rows = [];
                    foreach ($readerReceipts as $receipt) {
                        $rows[] = self::readerRow($receipt, $token, $checkpointFrame, $checkpointCookie, $schemaCookie, $nextEpoch, $allowedReaders);
                    }

                    $admitted = array_values(array_filter($rows, static fn (array $row): bool => $row['admitted']));
                    $blocked = array_values(array_filter($rows, static fn (array $row): bool => !$row['admitted']));
                    $requiredReaders = array_values(array_unique($reopenReaders));
                    $admittedNames = array_values(array_column($admitted, 'name'));
                    $missingReopenReaders = array_values(array_diff($requiredReaders, $admittedNames));
                    $canReopen = $blocked === [] && $missingReopenReaders === [];

                    $guardRows = [
                        ['name' => 'next219_checkpoint_source_published', 'matched' => true],
                        ['name' => 'all_reader_reopen_receipts_current', 'matched' => $blocked === []],
                        ['name' => 'required_reopen_readers_observed', 'matched' => $missingReopenReaders === []],
                    ];

                    return [
                        'status' => $canReopen
                            ? 'wal-hot-journal-savepoint-checkpoint-current-source-next220'
                            : 'wal-hot-journal-savepoint-checkpoint-current-source-blocked-next220',
                        'reason' => $canReopen
                            ? 'reader_reopen_receipts_observe_checkpoint_next_source'
                            : 'reader_reopen_receipts_wait_for_checkpoint_next_source',
                        'base_status' => $next219Plan['status'],
                        'database_path' => $next219Plan['database_path'] ?? null,
                        'wal_path' => $next219Plan['wal_path'] ?? null,
                        'journal_path' => $next219Plan['journal_path'] ?? null,
                        'current_source_token' => $token,
                        'checkpoint_frame' => $checkpointFrame,
                        'checkpoint_cookie' => $checkpointCookie,
                        'schema_cookie' => $schemaCookie,
                        'next_source_epoch' => $nextEpoch,
                        'reader_rows' => $rows,
                        'admitted_reader_names' => $admittedNames,
                        'blocked_reader_names' => array_values(array_column($blocked, 'name')),
                        'required_reopen_reader_names' => $requiredReaders,
                        'missing_reopen_reader_names' => $missingReopenReaders,
                        'reader_reopen_allowed' => $canReopen,
                        'reader_cache_action' => $canReopen ? 'install_reopened_checkpoint_reader_cache_next220' : 'preserve_previous_reader_cache_until_reopen_receipts',
                        'guard_rows' => $guardRows,
                        'guard_names' => array_column($guardRows, 'name'),
                        'guard_matches' => array_column($guardRows, 'matched'),
                        'blocked_guard_names' => array_values(array_column(array_filter($guardRows, static fn (array $row): bool => !$row['matched']), 'name')),
                        'operation_names' => array_values(array_unique(array_merge(
                            is_array($next219Plan['operation_names'] ?? null) ? $next219Plan['operation_names'] : [],
                            [
                                'verify_reader_reopen_checkpoint_source_next220',
                                $canReopen ? 'publish_reopened_reader_cache_next220' : 'hold_reader_reopen_fence_next220',
                            ]
                        ))),
                        'reader_reopen_digest' => hash('sha256', json_encode([$token, $checkpointFrame, $checkpointCookie, $schemaCookie, $rows], JSON_THROW_ON_ERROR)),
                        'dependencies' => array_values(array_unique(array_merge(
                            is_array($next219Plan['dependencies'] ?? null) ? $next219Plan['dependencies'] : [],
                            [
                                'sqlite-wal-hot-journal-savepoint-checkpoint-current-source-next220',
                                'sqlite-checkpoint-next-source-reader-reopen',
