                        'checkpoint_frame' => $ticketFrame,
                        'checkpoint_cookie' => $ticketCookie,
                        'ticket_sha256' => (string) $ticket['ticket_sha256'],
                        'sidecar_retired' => ($ticket['sidecar_retired'] ?? false) === true,
                        'sync_receipt' => ($ticket['sync_receipt'] ?? false) === true,
                        'admitted' => $reasons === [],
                        'reason' => $reasons[0] ?? 'source_ticket_matches_sidecar_retired_checkpoint',
                        'blocked_reasons' => $reasons,
                        'transition' => $name . '>' . ($reasons === [] ? 'seal-source-ticket' : 'hold-source-ticket') . ':next222',
                    ];
                }
        };

        return $impl::plan($next221Plan, $tickets);
    }

    public static function next224PublishReset(array $resetPlan, array $sidecars, array $readers, string $sourceToken): array
    {
        $impl = new class {
                /**
                 * @param array<string,mixed> $resetPlan
                 * @param list<array<string,mixed>> $sidecars
                 * @param list<array<string,mixed>> $readers
                 * @return array<string,mixed>
                 */
                public static function publishReset(array $resetPlan, array $sidecars, array $readers, string $sourceToken): array
                {
                    if (($resetPlan['status'] ?? null) !== 'wal-hot-journal-savepoint-checkpoint-current-source-next218') {
                        throw new \InvalidArgumentException('SQLite WAL hot-journal savepoint checkpoint current-source next224 requires an admitted next218 reset plan');
                    }
                    if (($resetPlan['can_reset_wal'] ?? null) !== true) {
                        throw new \InvalidArgumentException('SQLite WAL hot-journal savepoint checkpoint current-source next224 requires reset permission');
                    }
                    if ($sidecars === []) {
                        throw new \InvalidArgumentException('SQLite WAL hot-journal savepoint checkpoint current-source next224 requires sidecar receipts');
                    }
                    if ($readers === []) {
                        throw new \InvalidArgumentException('SQLite WAL hot-journal savepoint checkpoint current-source next224 requires reader receipts');
                    }
                    if (!preg_match('/^[A-Za-z0-9_.:-]+$/', $sourceToken)) {
                        throw new \InvalidArgumentException('SQLite WAL hot-journal savepoint checkpoint current-source next224 source token is invalid');
                    }

                    $mode = (string) ($resetPlan['mode'] ?? '');
                    if (!in_array($mode, ['restart', 'truncate'], true)) {
                        throw new \InvalidArgumentException('SQLite WAL hot-journal savepoint checkpoint current-source next224 reset mode is invalid');
                    }
                    $databaseDigest = self::digestField($resetPlan, 'database_digest');
                    $walDigest = self::digestField($resetPlan, 'wal_digest');
                    $generation = self::positiveInt($resetPlan, 'next_writer_generation');

                    $sidecarRows = [];
                    foreach ($sidecars as $receipt) {
                        $sidecarRows[] = self::sidecarRow($receipt, $mode, $databaseDigest, $walDigest, $generation);
                    }
                    $readerRows = [];
                    foreach ($readers as $receipt) {
                        $readerRows[] = self::readerRow($receipt, $sourceToken, $generation);
                    }

                    $blockedSidecars = array_values(array_filter($sidecarRows, static fn (array $row): bool => !$row['admitted']));
                    $blockedReaders = array_values(array_filter($readerRows, static fn (array $row): bool => !$row['admitted']));
                    $sidecarReasons = self::reasonList($blockedSidecars);
                    $readerReasons = self::reasonList($blockedReaders);
                    $sidecarTypes = array_values(array_unique(array_column($sidecarRows, 'type')));

                    $requiredSidecars = ['database', 'wal', 'journal', 'shm'];
                    $missingSidecars = array_values(array_diff($requiredSidecars, $sidecarTypes));
                    $guardRows = [
                        [
                            'name' => 'next218_reset_already_admitted',
                            'matched' => true,
                            'reason' => 'restart/truncate admission and writer fences were handled by next218',
                        ],
                        [
                            'name' => 'required_sidecar_receipts_present',
                            'matched' => $missingSidecars === [],
                            'reason' => 'database, wal, journal, and shm receipts must be present before publishing the current source',
                        ],
                        [
                            'name' => 'sidecars_match_reset_publication',
                            'matched' => $blockedSidecars === [],
                            'reason' => 'sidecar receipts must match reset mode, digests, deletion state, generation, and sync receipts',
                        ],
                        [
                            'name' => 'readers_reopened_or_invalidated',
                            'matched' => $blockedReaders === [],
                            'reason' => 'readers may observe the new source only after reopening on it or invalidating their old handle',
                        ],
                    ];
                    $blockedGuards = array_values(array_column(
                        array_filter($guardRows, static fn (array $row): bool => !$row['matched']),
                        'name'
                    ));
                    $published = $blockedGuards === [];

                    return [
                        'status' => $published
                            ? 'wal-hot-journal-savepoint-checkpoint-current-source-next224'
                            : 'wal-hot-journal-savepoint-checkpoint-current-source-blocked-next224',
                        'reason' => $published
                            ? 'restart_truncate_reset_publication_receipts_admit_current_source'
                            : 'restart_truncate_reset_publication_waits_for_sidecar_or_reader_receipts',
                        'base_status' => $resetPlan['status'],
                        'mode' => $mode,
                        'database_path' => $resetPlan['database_path'] ?? null,
                        'journal_path' => $resetPlan['journal_path'] ?? null,
                        'wal_path' => $resetPlan['wal_path'] ?? null,
                        'source_token' => $sourceToken,
                        'next_writer_generation' => $generation,
                        'database_digest' => $databaseDigest,
                        'previous_wal_digest' => $walDigest,
                        'sidecar_rows' => $sidecarRows,
                        'reader_rows' => $readerRows,
                        'admitted_sidecar_names' => array_values(array_column(array_filter($sidecarRows, static fn (array $row): bool => $row['admitted']), 'name')),
                        'blocked_sidecar_names' => array_values(array_column($blockedSidecars, 'name')),
                        'blocked_sidecar_reasons' => $sidecarReasons,
                        'admitted_reader_names' => array_values(array_column(array_filter($readerRows, static fn (array $row): bool => $row['admitted']), 'name')),
                        'blocked_reader_names' => array_values(array_column($blockedReaders, 'name')),
                        'blocked_reader_reasons' => $readerReasons,
                        'missing_sidecar_types' => $missingSidecars,
                        'publication_allowed' => $published,
                        'checkpoint_reset_visible' => $published,
                        'wal_publication_action' => $published
                            ? ($mode === 'truncate' ? 'publish_zero_length_wal_generation' : 'publish_restarted_wal_header_generation')
                            : 'hold_previous_wal_generation',
                        'reader_action' => $published ? 'reuse_only_reopened_current_source_readers' : 'force_reader_reopen_before_current_source',
                        'guard_rows' => $guardRows,
                        'guard_names' => array_column($guardRows, 'name'),
                        'guard_matches' => array_column($guardRows, 'matched'),
                        'blocked_guard_names' => $blockedGuards,
                        'operation_names' => array_values(array_unique(array_merge(
                            is_array($resetPlan['operation_names'] ?? null) ? $resetPlan['operation_names'] : [],
                            [
                                'verify_reset_publication_receipts_current_source_next224',
                                $published ? 'publish_checkpoint_reset_current_source_next224' : 'defer_checkpoint_reset_current_source_next224',
                            ]
                        ))),
                        'publication_digest' => hash('sha256', json_encode([$sourceToken, $mode, $sidecarRows, $readerRows, $blockedGuards], JSON_THROW_ON_ERROR)),
                        'dependencies' => array_values(array_unique(array_merge(
                            is_array($resetPlan['dependencies'] ?? null) ? $resetPlan['dependencies'] : [],
                            [
                                'sqlite-wal-hot-journal-savepoint-checkpoint-current-source-next224',
                                'sqlite-wal-reset-publication-sidecar-receipts',
                                'wordpress-import-checkpoint-reset-reader-reopen-publication',
                            ]
                        ))),
                        'dependency_closure' => 'no new support component needed; reuses next218 reset admission, sidecar receipt metadata, and reader reopen invalidation receipts',
                        'non_overlap' => 'next224 checks publication receipts after next218 reset admission; it does not repeat next218 writer fences, WAL byte truncation, VFS writer/sync/apply, rollback-journal commit/apply, or checkpoint transaction planning',
                    ];
                }

                /**
                 * @param array<string,mixed> $values
                 */
                private static function digestField(array $values, string $key): string
                {
                    $value = $values[$key] ?? null;
                    if (!is_string($value) || !preg_match('/^[a-f0-9]{64}$/', $value)) {
                        throw new \InvalidArgumentException("SQLite WAL hot-journal savepoint checkpoint current-source next224 requires {$key}");
                    }

                    return $value;
                }

                /**
                 * @param array<string,mixed> $values
                 */
                private static function positiveInt(array $values, string $key): int
                {
                    $value = $values[$key] ?? null;
                    if (!is_int($value) || $value <= 0) {
                        throw new \InvalidArgumentException("SQLite WAL hot-journal savepoint checkpoint current-source next224 requires positive {$key}");
                    }

                    return $value;
                }

                /**
                 * @param array<string,mixed> $receipt
                 * @return array<string,mixed>
                 */
                private static function sidecarRow(array $receipt, string $mode, string $databaseDigest, string $walDigest, int $generation): array
                {
                    $name = self::token($receipt['name'] ?? null, 'sidecar name');
                    $type = self::token($receipt['type'] ?? null, "{$name} sidecar type");
                    if (!in_array($type, ['database', 'wal', 'journal', 'shm'], true)) {
                        throw new \InvalidArgumentException("SQLite WAL hot-journal savepoint checkpoint current-source next224 {$name} sidecar type is invalid");
                    }
                    $observedGeneration = $receipt['generation'] ?? null;
                    if (!is_int($observedGeneration) || $observedGeneration < 0) {
                        throw new \InvalidArgumentException("SQLite WAL hot-journal savepoint checkpoint current-source next224 {$name} generation is invalid");
                    }

                    $exists = ($receipt['exists'] ?? false) === true;
                    $deleted = ($receipt['deleted'] ?? false) === true;
                    $synced = ($receipt['sync_receipt'] ?? false) === true;
                    $size = $receipt['size'] ?? null;
                    if (!is_int($size) || $size < 0) {
                        throw new \InvalidArgumentException("SQLite WAL hot-journal savepoint checkpoint current-source next224 {$name} size is invalid");
                    }
                    $digest = $receipt['digest'] ?? null;
                    if (!is_string($digest) || !preg_match('/^[a-f0-9]{64}$/', $digest)) {
                        throw new \InvalidArgumentException("SQLite WAL hot-journal savepoint checkpoint current-source next224 {$name} digest is required");
                    }

                    $reasons = [];
                    if ($type === 'database') {
                        if (!$exists || $deleted) {
                            $reasons[] = 'database_sidecar_missing';
                        }
                        if (!hash_equals($databaseDigest, $digest)) {
                            $reasons[] = 'database_digest_mismatch';
                        }
                        if (!$synced) {
                            $reasons[] = 'database_sync_missing';
                        }
                    } elseif ($type === 'wal') {
                        if ($mode === 'truncate') {
                            if ($exists && $size !== 0) {
                                $reasons[] = 'truncate_wal_not_empty';
                            }
                        } else {
                            if (!$exists || $deleted || $size === 0) {
                                $reasons[] = 'restart_wal_header_missing';
                            }
                            if (hash_equals($walDigest, $digest)) {
                                $reasons[] = 'restart_wal_reused_old_digest';
                            }
                        }
                        if (!$synced) {
                            $reasons[] = 'wal_sync_missing';
                        }
                    } elseif ($type === 'journal') {
                        if ($exists || !$deleted || $size !== 0) {
                            $reasons[] = 'hot_journal_not_cleared';
                        }
                    } elseif ($type === 'shm') {
                        if ($exists && $observedGeneration < $generation) {
                            $reasons[] = 'shm_generation_stale';
                        }
                    }
                    if ($observedGeneration !== 0 && $observedGeneration < $generation) {
                        $reasons[] = 'sidecar_generation_before_reset';
                    }

                    return [
                        'name' => $name,
                        'type' => $type,
                        'path' => is_string($receipt['path'] ?? null) ? $receipt['path'] : null,
                        'generation' => $observedGeneration,
                        'expected_generation' => $generation,
                        'exists' => $exists,
                        'deleted' => $deleted,
                        'size' => $size,
                        'digest' => $digest,
                        'sync_receipt' => $synced,
                        'admitted' => $reasons === [],
                        'receipt_reason' => $reasons === [] ? 'sidecar_matches_reset_publication' : implode('|', $reasons),
                        'blocked_reasons' => $reasons,
                    ];
                }

                /**
                 * @param array<string,mixed> $receipt
                 * @return array<string,mixed>
                 */
                private static function readerRow(array $receipt, string $sourceToken, int $generation): array
                {
                    $name = self::token($receipt['name'] ?? null, 'reader name');
                    $observedSource = self::token($receipt['source_token'] ?? null, "{$name} source token");
                    $observedGeneration = $receipt['generation'] ?? null;
                    if (!is_int($observedGeneration) || $observedGeneration < 0) {
                        throw new \InvalidArgumentException("SQLite WAL hot-journal savepoint checkpoint current-source next224 {$name} generation is invalid");
                    }
                    $reopened = ($receipt['reopened'] ?? false) === true;
                    $invalidated = ($receipt['invalidated'] ?? false) === true;
                    $pinned = ($receipt['pinned'] ?? false) === true;

                    $reasons = [];
                    if ($pinned) {
                        $reasons[] = 'reader_still_pins_old_wal';
                    }
                    if (!$reopened && !$invalidated) {
                        $reasons[] = 'reader_not_reopened_or_invalidated';
                    }
                    if ($reopened && $observedSource !== $sourceToken) {
                        $reasons[] = 'reader_source_token_mismatch';
                    }
                    if ($reopened && $observedGeneration !== $generation) {
                        $reasons[] = 'reader_generation_mismatch';
                    }
                    if ($invalidated && $observedGeneration >= $generation) {
                        $reasons[] = 'invalidated_reader_not_stale';
                    }

                    return [
                        'name' => $name,
                        'source_token' => $observedSource,
                        'expected_source_token' => $sourceToken,
                        'generation' => $observedGeneration,
                        'expected_generation' => $generation,
                        'reopened' => $reopened,
                        'invalidated' => $invalidated,
                        'pinned' => $pinned,
                        'admitted' => $reasons === [],
                        'receipt_reason' => $reasons === [] ? 'reader_safe_for_reset_publication' : implode('|', $reasons),
                        'blocked_reasons' => $reasons,
                    ];
                }

                private static function token(mixed $value, string $label): string
                {
                    if (!is_string($value) || $value === '') {
                        throw new \InvalidArgumentException("SQLite WAL hot-journal savepoint checkpoint current-source next224 {$label} is required");
                    }

                    return $value;
                }

                /**
                 * @param list<array<string,mixed>> $rows
                 * @return list<string>
                 */
                private static function reasonList(array $rows): array
                {
                    $reasons = [];
                    foreach ($rows as $row) {
                        foreach ($row['blocked_reasons'] as $reason) {
                            $reasons[] = $reason;
                        }
                    }

                    return array_values(array_unique($reasons));
                }
        };

        return $impl::publishReset($resetPlan, $sidecars, $readers, $sourceToken);
    }

    public static function next225Plan(array $publishPlan, array $headerReceipts): array
    {
        $impl = new class {
                /**
                 * @param array<string,mixed> $publishPlan
                 * @param list<array<string,mixed>> $headerReceipts
                 * @return array<string,mixed>
                 */
                public static function plan(array $publishPlan, array $headerReceipts): array
                {
                    self::assertPublishPlan($publishPlan);
                    if ($headerReceipts === []) {
                        throw new \InvalidArgumentException('SQLite WAL hot-journal savepoint checkpoint current-source next225 requires database header receipts');
                    }

                    $token = $publishPlan['current_source_token'];
                    $sourceId = (string) $token['id'];
                    $epoch = (int) $token['epoch'];
                    $checkpointFrame = (int) $publishPlan['checkpoint_frame'];
                    $checkpointCookie = (int) $publishPlan['checkpoint_cookie'];
                    $schemaCookie = (int) $publishPlan['schema_cookie'];
                    $nextSourceEpoch = (int) $publishPlan['next_source_epoch'];
                    $scopeDigest = (string) $publishPlan['savepoint_scope_digest'];

                    $rows = [];
                    foreach ($headerReceipts as $receipt) {
                        $rows[] = self::receiptRow(
                            $receipt,
                            $sourceId,
                            $epoch,
                            $checkpointFrame,
                            $checkpointCookie,
                            $schemaCookie,
                            $nextSourceEpoch,
                            $scopeDigest
                        );
                    }

                    $publishedRows = array_values(array_filter($rows, static fn (array $row): bool => $row['published']));
                    $blockedRows = array_values(array_filter($rows, static fn (array $row): bool => !$row['published']));
                    $blockedReasons = [];
                    foreach ($blockedRows as $row) {
                        foreach ($row['blocked_reasons'] as $reason) {
                            $blockedReasons[] = $reason;
                        }
                    }
                    $requiredRegions = ['database-header', 'wal-index-header', 'change-counter'];
                    $publishedRegions = array_values(array_unique(array_column($publishedRows, 'header_region')));
                    sort($publishedRegions);
                    sort($requiredRegions);

                    $guards = [
                        'next219_checkpoint_source_published' => $publishPlan['status'] === 'wal-hot-journal-savepoint-checkpoint-current-source-next219'
                            && ($publishPlan['checkpoint_next_source_published'] ?? false) === true,
                        'database_header_receipts_current' => $blockedRows === [],
                        'required_header_regions_written' => $publishedRegions === $requiredRegions,
                        'next_source_epoch_advanced' => $nextSourceEpoch > $epoch,
                    ];
                    $blockedGuards = array_keys(array_filter($guards, static fn (bool $passed): bool => !$passed));

                    return [
                        'status' => $blockedGuards === []
                            ? 'wal-hot-journal-savepoint-checkpoint-current-source-next225'
                            : 'wal-hot-journal-savepoint-checkpoint-current-source-blocked-next225',
                        'reason' => $blockedGuards === []
                            ? 'database_header_receipts_publish_checkpoint_current_source'
                            : 'database_header_receipts_block_checkpoint_current_source',
                        'database_path' => (string) $publishPlan['database_path'],
                        'wal_path' => (string) $publishPlan['wal_path'],
                        'journal_path' => (string) $publishPlan['journal_path'],
                        'current_source_token' => $token,
                        'checkpoint_frame' => $checkpointFrame,
                        'checkpoint_cookie' => $checkpointCookie,
                        'schema_cookie' => $schemaCookie,
                        'next_source_epoch' => $nextSourceEpoch,
                        'savepoint_scope_digest' => $scopeDigest,
                        'receipt_rows' => $rows,
                        'published_receipt_names' => array_values(array_column($publishedRows, 'name')),
                        'blocked_receipt_names' => array_values(array_column($blockedRows, 'name')),
                        'blocked_receipt_reasons' => array_values(array_unique($blockedReasons)),
                        'published_header_regions' => $publishedRegions,
                        'required_header_regions' => $requiredRegions,
                        'guard_names' => array_keys($guards),
                        'guard_matches' => array_values($guards),
                        'blocked_guard_names' => $blockedGuards,
                        'checkpoint_current_source_header_published' => $blockedGuards === [],
                        'header_receipt_digest' => hash('sha256', json_encode($rows, JSON_THROW_ON_ERROR)),
                        'operation_names' => array_values(array_unique(array_merge(
                            is_array($publishPlan['operation_names'] ?? null) ? $publishPlan['operation_names'] : [],
                            [
                                'verify_checkpoint_database_header_receipts_next225',
                                'publish_database_header_current_source_after_hot_journal_next225',
                                'fence_stale_hot_journal_header_after_savepoint_checkpoint_next225',
                            ]
                        ))),
                        'dependencies' => array_values(array_unique(array_merge(
                            is_array($publishPlan['dependencies'] ?? null) ? $publishPlan['dependencies'] : [],
                            [
                                'sqlite-wal-hot-journal-savepoint-checkpoint-current-source-next225',
                                'sqlite-database-header-current-source-after-wal-checkpoint',
                                'wordpress-import-checkpoint-header-receipts',
                            ]
                        ))),
                        'dependency_closure' => 'no new support component needed; reuses next219 savepoint-scope publication, checkpoint cookies, WAL-index header metadata, and native database header write receipts',
                        'non_overlap' => 'next225 admits database-header current-source publication after savepoint finalization; it does not repeat next219 savepoint-scope finalization, next212 passive reader pins, next172 sync receipts, VFS writer/sync apply, rollback-journal commit/apply, or WAL byte truncation',
                    ];
                }

                /**
                 * @param array<string,mixed> $publishPlan
                 */
                private static function assertPublishPlan(array $publishPlan): void
                {
                    foreach (['status', 'database_path', 'wal_path', 'journal_path', 'current_source_token', 'checkpoint_frame', 'checkpoint_cookie', 'schema_cookie', 'next_source_epoch', 'savepoint_scope_digest'] as $key) {
                        if (!array_key_exists($key, $publishPlan)) {
                            throw new \InvalidArgumentException("SQLite WAL hot-journal savepoint checkpoint current-source next225 missing publish {$key}");
                        }
                    }
                    if (!is_array($publishPlan['current_source_token']) || (string) ($publishPlan['current_source_token']['id'] ?? '') === '' || (int) ($publishPlan['current_source_token']['epoch'] ?? 0) <= 0) {
                        throw new \InvalidArgumentException('SQLite WAL hot-journal savepoint checkpoint current-source next225 token is invalid');
                    }
                    foreach (['checkpoint_frame', 'checkpoint_cookie', 'schema_cookie', 'next_source_epoch'] as $key) {
                        if (!is_int($publishPlan[$key]) || $publishPlan[$key] <= 0) {
                            throw new \InvalidArgumentException("SQLite WAL hot-journal savepoint checkpoint current-source next225 {$key} must be a positive integer");
                        }
                    }
                    if (!is_string($publishPlan['savepoint_scope_digest']) || !preg_match('/^[a-f0-9]{64}$/', $publishPlan['savepoint_scope_digest'])) {
                        throw new \InvalidArgumentException('SQLite WAL hot-journal savepoint checkpoint current-source next225 savepoint scope digest is invalid');
                    }
                }

                /**
                 * @param array<string,mixed> $receipt
                 * @return array<string,mixed>
                 */
                private static function receiptRow(
                    array $receipt,
                    string $sourceId,
                    int $epoch,
                    int $checkpointFrame,
                    int $checkpointCookie,
                    int $schemaCookie,
                    int $nextSourceEpoch,
                    string $scopeDigest
                ): array {
                    foreach (['name', 'header_region', 'source_id', 'source_epoch', 'checkpoint_frame', 'checkpoint_cookie', 'schema_cookie', 'next_source_epoch', 'savepoint_scope_digest', 'header_digest', 'write_synced'] as $key) {
                        if (!array_key_exists($key, $receipt)) {
                            throw new \InvalidArgumentException("SQLite WAL hot-journal savepoint checkpoint current-source next225 missing receipt {$key}");
                        }
                    }
                    $name = (string) $receipt['name'];
                    $region = (string) $receipt['header_region'];
                    if ($name === '' || $region === '') {
                        throw new \InvalidArgumentException('SQLite WAL hot-journal savepoint checkpoint current-source next225 receipt name and region are required');
                    }
                    foreach (['source_epoch', 'checkpoint_frame', 'checkpoint_cookie', 'schema_cookie', 'next_source_epoch'] as $key) {
                        if (!is_int($receipt[$key]) || $receipt[$key] < 0) {
                            throw new \InvalidArgumentException("SQLite WAL hot-journal savepoint checkpoint current-source next225 {$name} {$key} must be a non-negative integer");
                        }
                    }
                    if (!is_string($receipt['header_digest']) || !preg_match('/^[a-f0-9]{64}$/', $receipt['header_digest'])) {
                        throw new \InvalidArgumentException("SQLite WAL hot-journal savepoint checkpoint current-source next225 {$name} header digest is invalid");
                    }
                    if (!is_string($receipt['savepoint_scope_digest']) || !preg_match('/^[a-f0-9]{64}$/', $receipt['savepoint_scope_digest'])) {
                        throw new \InvalidArgumentException("SQLite WAL hot-journal savepoint checkpoint current-source next225 {$name} scope digest is invalid");
                    }

                    $reasons = [];
                    if ((string) $receipt['source_id'] !== $sourceId) {
                        $reasons[] = 'header_source_id_mismatch';
                    }
                    if ((int) $receipt['source_epoch'] !== $epoch) {
                        $reasons[] = 'header_source_epoch_mismatch';
                    }
                    if ((int) $receipt['checkpoint_frame'] !== $checkpointFrame) {
                        $reasons[] = 'header_checkpoint_frame_mismatch';
                    }
                    if ((int) $receipt['checkpoint_cookie'] !== $checkpointCookie) {
                        $reasons[] = 'header_checkpoint_cookie_mismatch';
                    }
                    if ((int) $receipt['schema_cookie'] !== $schemaCookie) {
                        $reasons[] = 'header_schema_cookie_mismatch';
                    }
                    if ((int) $receipt['next_source_epoch'] !== $nextSourceEpoch) {
                        $reasons[] = 'header_next_source_epoch_mismatch';
                    }
                    if ((string) $receipt['savepoint_scope_digest'] !== $scopeDigest) {
                        $reasons[] = 'header_savepoint_scope_digest_mismatch';
                    }
                    if (($receipt['write_synced'] ?? false) !== true) {
                        $reasons[] = 'header_write_not_synced';
                    }
                    if (($receipt['hot_journal_present'] ?? false) === true) {
                        $reasons[] = 'header_hot_journal_still_present';
                    }
                    if (($receipt['stale_header_bytes'] ?? false) === true) {
                        $reasons[] = 'header_stale_bytes_observed';
                    }

                    $published = $reasons === [];

                    return [
                        'name' => $name,
                        'header_region' => $region,
                        'source_id' => (string) $receipt['source_id'],
                        'source_epoch' => (int) $receipt['source_epoch'],
                        'checkpoint_frame' => (int) $receipt['checkpoint_frame'],
                        'checkpoint_cookie' => (int) $receipt['checkpoint_cookie'],
                        'schema_cookie' => (int) $receipt['schema_cookie'],
                        'next_source_epoch' => (int) $receipt['next_source_epoch'],
                        'savepoint_scope_digest' => (string) $receipt['savepoint_scope_digest'],
                        'header_digest' => (string) $receipt['header_digest'],
                        'write_synced' => (bool) $receipt['write_synced'],
                        'hot_journal_present' => ($receipt['hot_journal_present'] ?? false) === true,
                        'stale_header_bytes' => ($receipt['stale_header_bytes'] ?? false) === true,
                        'published' => $published,
                        'blocked_reasons' => $reasons,
                        'receipt_reason' => $published ? 'header_receipt_published_current_source' : $reasons[0],
                        'receipt_transition' => $name . '>' . ($published ? 'publish-header-current-source' : 'hold-header-current-source') . ':next225',
                    ];
                }
        };

        return $impl::plan($publishPlan, $headerReceipts);
    }

    public static function next226VerifyResetFiles(array $resetPlan, array $files, array $receipts, string $expectedWalBytes, string $expectedDatabaseDigest): array
    {
        $impl = new class {
                /**
                 * @param array<string,mixed> $resetPlan
                 * @param array<string,string> $files
                 * @param list<array<string,mixed>> $receipts
                 * @return array<string,mixed>
                 */
                public static function verifyResetFiles(array $resetPlan, array $files, array $receipts, string $expectedWalBytes, string $expectedDatabaseDigest): array
                {
                    self::assertResetPlan($resetPlan);
                    if ($files === [] || $receipts === []) {
                        throw new \InvalidArgumentException('SQLite WAL hot-journal savepoint checkpoint current-source next226 requires files and reset receipts');
                    }
                    if ($expectedWalBytes === '' || !self::isDigest($expectedDatabaseDigest)) {
                        throw new \InvalidArgumentException('SQLite WAL hot-journal savepoint checkpoint current-source next226 requires expected WAL bytes and database digest');
                    }

                    $databasePath = (string) $resetPlan['database_path'];
                    $walPath = (string) $resetPlan['wal_path'];
                    $journalPath = (string) $resetPlan['journal_path'];
                    $mode = (string) $resetPlan['mode'];
                    $expectedWalDigest = hash('sha256', $expectedWalBytes);
                    $fileRows = self::fileRows($files, $databasePath, $walPath, $journalPath, $expectedWalBytes, $expectedDatabaseDigest);
                    $receiptRows = [];
                    foreach ($receipts as $receipt) {
                        $receiptRows[] = self::receiptRow($receipt, $mode, $expectedWalDigest, $expectedDatabaseDigest, (int) $resetPlan['next_writer_generation']);
                    }

                    $blockedReasons = [];
                    foreach (array_merge($fileRows, $receiptRows) as $row) {
                        foreach ($row['blocked_reasons'] as $reason) {
                            $blockedReasons[] = $reason;
                        }
                    }
                    $blockedReasons = array_values(array_unique($blockedReasons));

                    $guards = [
                        'next218_reset_admitted' => ($resetPlan['status'] ?? null) === 'wal-hot-journal-savepoint-checkpoint-current-source-next218'
                            && ($resetPlan['can_reset_wal'] ?? false) === true,
                        'database_bytes_match_checkpoint_digest' => $fileRows[0]['matched'],
                        'wal_bytes_match_reset_mode' => $fileRows[1]['matched'],
                        'hot_journal_absent_after_reset' => $fileRows[2]['matched'],
                        'all_reset_receipts_match_current_source' => $blockedReasons === [],
                    ];
                    $blockedGuards = array_keys(array_filter($guards, static fn (bool $matched): bool => !$matched));
                    $admitted = $blockedGuards === [];

                    return [
                        'status' => $admitted
                            ? 'wal-hot-journal-savepoint-checkpoint-current-source-next226'
                            : 'wal-hot-journal-savepoint-checkpoint-current-source-blocked-next226',
                        'reason' => $admitted
                            ? 'restart_truncate_reset_files_match_checkpoint_current_source'
                            : 'restart_truncate_reset_files_do_not_match_checkpoint_current_source',
                        'base_status' => $resetPlan['status'],
                        'mode' => $mode,
                        'database_path' => $databasePath,
                        'wal_path' => $walPath,
                        'journal_path' => $journalPath,
                        'expected_database_digest' => $expectedDatabaseDigest,
                        'observed_database_digest' => hash('sha256', $files[$databasePath] ?? ''),
                        'expected_wal_digest' => $expectedWalDigest,
                        'observed_wal_digest' => hash('sha256', $files[$walPath] ?? ''),
                        'expected_wal_length' => strlen($expectedWalBytes),
                        'observed_wal_length' => strlen($files[$walPath] ?? ''),
                        'journal_present' => array_key_exists($journalPath, $files),
                        'next_writer_generation' => (int) $resetPlan['next_writer_generation'],
                        'file_rows' => $fileRows,
                        'receipt_rows' => $receiptRows,
                        'receipt_names' => array_values(array_column($receiptRows, 'name')),
                        'receipt_count' => count($receiptRows),
                        'blocked_reasons' => $blockedReasons,
                        'guard_names' => array_keys($guards),
                        'guard_matches' => array_values($guards),
                        'blocked_guard_names' => $blockedGuards,
                        'can_publish_reopened_current_source' => $admitted,
                        'operation_names' => array_values(array_unique(array_merge(
                            is_array($resetPlan['operation_names'] ?? null) ? $resetPlan['operation_names'] : [],
                            [
                                'verify_reset_file_state_current_source_next226',
                                $admitted ? 'publish_reopened_current_source_after_reset_next226' : 'block_reopened_current_source_after_reset_next226',
                            ]
                        ))),
                        'publication_digest' => hash('sha256', json_encode([$mode, $fileRows, $receiptRows], JSON_THROW_ON_ERROR)),
                        'dependencies' => array_values(array_unique(array_merge(
                            is_array($resetPlan['dependencies'] ?? null) ? $resetPlan['dependencies'] : [],
                            [
                                'sqlite-wal-hot-journal-savepoint-checkpoint-current-source-next226',
                                'sqlite-wal-reset-file-state-reopen-fence',
                                'wordpress-import-wal-reset-file-state-reopen',
                            ]
                        ))),
                        'dependency_closure' => 'no new support component needed; reuses next218 restart/truncate admission, file-state digests, hot-journal absence checks, and durable reset receipts',
                        'non_overlap' => 'next226 verifies post-reset file-state receipts after accepted next218 restart/truncate admission; it does not repeat next218 reset admission, next219 checkpoint publication, WAL byte truncation, rollback-journal commit/apply, VFS savepoint rollback, or reader-slot validation',
                    ];
                }

                /**
                 * @param array<string,mixed> $resetPlan
                 */
                private static function assertResetPlan(array $resetPlan): void
                {
                    foreach (['status', 'mode', 'database_path', 'wal_path', 'journal_path', 'can_reset_wal', 'next_writer_generation'] as $key) {
                        if (!array_key_exists($key, $resetPlan)) {
                            throw new \InvalidArgumentException("SQLite WAL hot-journal savepoint checkpoint current-source next226 missing reset {$key}");
                        }
                    }
                    if (($resetPlan['status'] ?? null) !== 'wal-hot-journal-savepoint-checkpoint-current-source-next218' || ($resetPlan['can_reset_wal'] ?? false) !== true) {
                        throw new \InvalidArgumentException('SQLite WAL hot-journal savepoint checkpoint current-source next226 requires an admitted next218 reset plan');
                    }
                    if (!in_array($resetPlan['mode'], ['restart', 'truncate'], true)) {
                        throw new \InvalidArgumentException('SQLite WAL hot-journal savepoint checkpoint current-source next226 mode must be restart or truncate');
                    }
                    foreach (['database_path', 'wal_path', 'journal_path'] as $key) {
                        if (!is_string($resetPlan[$key]) || $resetPlan[$key] === '') {
                            throw new \InvalidArgumentException("SQLite WAL hot-journal savepoint checkpoint current-source next226 {$key} is required");
                        }
                    }
                    if (!is_int($resetPlan['next_writer_generation']) || $resetPlan['next_writer_generation'] <= 0) {
                        throw new \InvalidArgumentException('SQLite WAL hot-journal savepoint checkpoint current-source next226 next writer generation must be positive');
                    }
                }

                /**
                 * @param array<string,string> $files
                 * @return list<array<string,mixed>>
                 */
                private static function fileRows(array $files, string $databasePath, string $walPath, string $journalPath, string $expectedWalBytes, string $expectedDatabaseDigest): array
                {
                    foreach ($files as $path => $bytes) {
                        if (!is_string($path) || $path === '' || !is_string($bytes)) {
                            throw new \InvalidArgumentException('SQLite WAL hot-journal savepoint checkpoint current-source next226 files must map non-empty paths to byte strings');
                        }
                    }

                    $databaseBytes = $files[$databasePath] ?? null;
                    $walBytes = $files[$walPath] ?? null;
                    $journalPresent = array_key_exists($journalPath, $files);

                    return [
                        self::fileRow('database', $databasePath, $databaseBytes, $expectedDatabaseDigest, 'database_digest_mismatch'),
                        self::fileRow('wal', $walPath, $walBytes, hash('sha256', $expectedWalBytes), 'wal_reset_bytes_mismatch', strlen($expectedWalBytes)),
                        [
                            'name' => 'hot-journal',
                            'path' => $journalPath,
                            'matched' => !$journalPresent,
                            'observed_digest' => $journalPresent ? hash('sha256', (string) $files[$journalPath]) : null,
                            'expected_digest' => null,
                            'observed_length' => $journalPresent ? strlen((string) $files[$journalPath]) : 0,
                            'expected_length' => 0,
                            'blocked_reasons' => $journalPresent ? ['hot_journal_still_present_after_reset'] : [],
                        ],
                    ];
                }

                /**
                 * @return array<string,mixed>
                 */
                private static function fileRow(string $name, string $path, ?string $bytes, string $expectedDigest, string $blockedReason, ?int $expectedLength = null): array
                {
                    $observedDigest = $bytes === null ? null : hash('sha256', $bytes);
                    $observedLength = $bytes === null ? 0 : strlen($bytes);
                    $matched = $bytes !== null && hash_equals($expectedDigest, (string) $observedDigest) && ($expectedLength === null || $observedLength === $expectedLength);

                    return [
                        'name' => $name,
                        'path' => $path,
                        'matched' => $matched,
                        'observed_digest' => $observedDigest,
                        'expected_digest' => $expectedDigest,
                        'observed_length' => $observedLength,
                        'expected_length' => $expectedLength,
                        'blocked_reasons' => $matched ? [] : [$bytes === null ? $name . '_file_missing_after_reset' : $blockedReason],
                    ];
                }

                /**
                 * @param array<string,mixed> $receipt
                 * @return array<string,mixed>
                 */
                private static function receiptRow(array $receipt, string $mode, string $expectedWalDigest, string $expectedDatabaseDigest, int $expectedGeneration): array
                {
                    $name = $receipt['name'] ?? null;
                    if (!is_string($name) || $name === '') {
                        throw new \InvalidArgumentException('SQLite WAL hot-journal savepoint checkpoint current-source next226 receipt name is required');
                    }
                    $generation = $receipt['writer_generation'] ?? null;
                    if (!is_int($generation) || $generation <= 0) {
                        throw new \InvalidArgumentException("SQLite WAL hot-journal savepoint checkpoint current-source next226 {$name} writer generation is required");
                    }
                    foreach (['database_digest', 'wal_digest'] as $key) {
                        if (!is_string($receipt[$key] ?? null) || !self::isDigest((string) $receipt[$key])) {
                            throw new \InvalidArgumentException("SQLite WAL hot-journal savepoint checkpoint current-source next226 {$name} {$key} is required");
                        }
                    }

                    $reasons = [];
                    if (($receipt['mode'] ?? null) !== $mode) {
                        $reasons[] = 'reset_mode_mismatch';
                    }
                    if ($generation !== $expectedGeneration) {
                        $reasons[] = 'writer_generation_mismatch';
                    }
                    if (!hash_equals($expectedDatabaseDigest, (string) $receipt['database_digest'])) {
                        $reasons[] = 'receipt_database_digest_mismatch';
                    }
                    if (!hash_equals($expectedWalDigest, (string) $receipt['wal_digest'])) {
                        $reasons[] = 'receipt_wal_digest_mismatch';
                    }
                    foreach ([
                        'database_synced' => 'database_sync_missing',
                        'wal_synced' => 'wal_sync_missing',
                        'directory_synced' => 'directory_sync_missing',
                        'hot_journal_absent' => 'hot_journal_absence_receipt_missing',
                        'savepoint_closed' => 'savepoint_closed_receipt_missing',
                        'readers_reopened' => 'readers_reopened_receipt_missing',
                    ] as $key => $reason) {
                        if (($receipt[$key] ?? false) !== true) {
                            $reasons[] = $reason;
                        }
                    }

                    return [
                        'name' => $name,
                        'mode' => $receipt['mode'] ?? null,
                        'writer_generation' => $generation,
                        'database_digest' => $receipt['database_digest'],
                        'wal_digest' => $receipt['wal_digest'],
                        'database_digest_matches' => hash_equals($expectedDatabaseDigest, (string) $receipt['database_digest']),
                        'wal_digest_matches' => hash_equals($expectedWalDigest, (string) $receipt['wal_digest']),
                        'database_synced' => ($receipt['database_synced'] ?? false) === true,
                        'wal_synced' => ($receipt['wal_synced'] ?? false) === true,
                        'directory_synced' => ($receipt['directory_synced'] ?? false) === true,
                        'hot_journal_absent' => ($receipt['hot_journal_absent'] ?? false) === true,
                        'savepoint_closed' => ($receipt['savepoint_closed'] ?? false) === true,
                        'readers_reopened' => ($receipt['readers_reopened'] ?? false) === true,
                        'admitted' => $reasons === [],
                        'blocked_reasons' => $reasons,
                        'receipt_reason' => $reasons === [] ? 'reset_file_state_receipt_matches_current_source' : implode(',', $reasons),
                    ];
                }

                private static function isDigest(string $value): bool
                {
                    return preg_match('/^[a-f0-9]{64}$/', $value) === 1;
                }
        };

        return $impl::verifyResetFiles($resetPlan, $files, $receipts, $expectedWalBytes, $expectedDatabaseDigest);
    }

    public static function next227Plan(array $finalizationPlan, array $publishReceipts): array
    {
        $impl = new class {
                /**
                 * @param array<string,mixed> $finalizationPlan
                 * @param list<array<string,mixed>> $publishReceipts
                 * @return array<string,mixed>
                 */
                public static function plan(array $finalizationPlan, array $publishReceipts): array
                {
                    self::assertFinalizationPlan($finalizationPlan);
                    if ($publishReceipts === []) {
                        throw new \InvalidArgumentException('SQLite WAL hot-journal current-source next227 requires publish receipts');
                    }

                    $token = $finalizationPlan['current_source_token'];
                    $expectedTokenId = (string) $token['id'];
                    $expectedEpoch = (int) $token['epoch'];
                    $expectedCheckpointFrame = (int) $finalizationPlan['checkpoint_frame'];
                    $expectedCheckpointCookie = (int) $finalizationPlan['checkpoint_cookie'];
                    $expectedSchemaCookie = (int) $finalizationPlan['schema_cookie'];
                    $expectedNextEpoch = (int) $finalizationPlan['next_source_epoch'];
                    $finalizedNames = self::stringList($finalizationPlan['finalized_scope_names'], 'finalized scope names');
                    $scopeRows = self::scopeRowsByName($finalizationPlan['scope_rows']);

                    $receiptRows = [];
                    foreach ($publishReceipts as $receipt) {
                        $receiptRows[] = self::receiptRow(
                            $receipt,
                            $scopeRows,
                            $expectedTokenId,
                            $expectedEpoch,
                            $expectedCheckpointFrame,
                            $expectedCheckpointCookie,
                            $expectedSchemaCookie,
                            $expectedNextEpoch
                        );
                    }

                    $receiptNames = array_values(array_unique(array_column($receiptRows, 'scope_name')));
                    $missingScopes = array_values(array_diff($finalizedNames, $receiptNames));
                    $extraScopes = array_values(array_diff($receiptNames, $finalizedNames));
                    $blockedRows = array_values(array_filter($receiptRows, static fn (array $row): bool => !$row['publishable']));
                    $blockedReasons = [];
                    foreach ($blockedRows as $row) {
                        foreach ($row['blocked_reasons'] as $reason) {
                            $blockedReasons[] = $reason;
                        }
                    }
                    if ($missingScopes !== []) {
                        $blockedReasons[] = 'finalized_scope_publish_receipt_missing';
                    }
                    if ($extraScopes !== []) {
                        $blockedReasons[] = 'publish_receipt_for_unfinalized_scope';
                    }
                    $duplicateScopes = self::duplicateValues(array_column($receiptRows, 'scope_name'));
                    if ($duplicateScopes !== []) {
                        $blockedReasons[] = 'duplicate_scope_publish_receipt';
                    }
                    $blockedReasons = array_values(array_unique($blockedReasons));

                    $guards = [
                        'next219_finalization_admitted' => ($finalizationPlan['status'] ?? null) === 'wal-hot-journal-savepoint-checkpoint-current-source-next219'
                            && ($finalizationPlan['checkpoint_next_source_published'] ?? false) === true,
                        'all_finalized_scopes_have_receipts' => $missingScopes === [],
                        'no_unfinalized_scope_receipts' => $extraScopes === [],
                        'no_duplicate_scope_receipts' => $duplicateScopes === [],
                        'all_receipts_publishable' => $blockedRows === [],
                        'next_source_epoch_advances_once' => self::allNextEpochsMatch($receiptRows, $expectedNextEpoch),
                    ];
                    $blockedGuards = array_keys(array_filter($guards, static fn (bool $matched): bool => !$matched));
                    $publishable = $blockedGuards === [];

                    return [
                        'status' => $publishable
                            ? 'wal-hot-journal-savepoint-checkpoint-current-source-next227'
                            : 'wal-hot-journal-savepoint-checkpoint-current-source-blocked-next227',
                        'reason' => $publishable
                            ? 'publish_receipts_seal_hot_journal_savepoint_checkpoint_next_source'
                            : 'publish_receipts_hold_hot_journal_savepoint_checkpoint_current_source',
                        'database_path' => (string) $finalizationPlan['database_path'],
                        'wal_path' => (string) $finalizationPlan['wal_path'],
                        'journal_path' => (string) $finalizationPlan['journal_path'],
                        'current_source_token' => $token,
                        'checkpoint_frame' => $expectedCheckpointFrame,
                        'checkpoint_cookie' => $expectedCheckpointCookie,
                        'schema_cookie' => $expectedSchemaCookie,
                        'next_source_epoch' => $expectedNextEpoch,
                        'receipt_rows' => $receiptRows,
                        'publishable_scope_names' => array_values(array_column(array_filter($receiptRows, static fn (array $row): bool => $row['publishable']), 'scope_name')),
                        'blocked_scope_names' => array_values(array_unique(array_column($blockedRows, 'scope_name'))),
                        'missing_scope_names' => $missingScopes,
                        'extra_scope_names' => $extraScopes,
                        'duplicate_scope_names' => $duplicateScopes,
                        'blocked_reasons' => $blockedReasons,
                        'guard_names' => array_keys($guards),
                        'guard_matches' => array_values($guards),
                        'blocked_guard_names' => $blockedGuards,
                        'checkpoint_publish_allowed' => $publishable,
                        'publish_digest' => hash('sha256', json_encode([$token, $receiptRows, $guards], JSON_THROW_ON_ERROR)),
                        'operation_names' => array_values(array_unique(array_merge(
                            is_array($finalizationPlan['operation_names'] ?? null) ? $finalizationPlan['operation_names'] : [],
                            [
                                'seal_hot_journal_delete_receipt_current_source_next227',
                                'verify_savepoint_page_digest_receipts_current_source_next227',
                                $publishable ? 'publish_checkpoint_next_source_receipt_next227' : 'hold_checkpoint_current_source_receipt_next227',
                            ]
                        ))),
                        'dependencies' => array_values(array_unique(array_merge(
                            is_array($finalizationPlan['dependencies'] ?? null) ? $finalizationPlan['dependencies'] : [],
                            [
                                'sqlite-wal-hot-journal-savepoint-checkpoint-current-source-next227',
                                'sqlite-hot-journal-savepoint-publish-receipt-seal',
                                'wordpress-import-hot-journal-checkpoint-publish-receipts',
                            ]
                        ))),
                        'dependency_closure' => 'no new support component needed; reuses next219 finalized savepoint scopes plus per-scope hot-journal delete receipts and page digest seals',
                        'non_overlap' => 'next227 validates publish receipts after next219 scope finalization; it does not repeat next211 reader acknowledgements, next219 finalization, WAL byte truncation, VFS savepoint rollback apply, rollback-journal commit/apply, or checkpoint transaction planning',
                    ];
                }

                /**
                 * @param array<string,mixed> $plan
                 */
                private static function assertFinalizationPlan(array $plan): void
                {
                    foreach (['status', 'database_path', 'wal_path', 'journal_path', 'current_source_token', 'checkpoint_frame', 'checkpoint_cookie', 'schema_cookie', 'next_source_epoch', 'finalized_scope_names', 'scope_rows'] as $key) {
                        if (!array_key_exists($key, $plan)) {
                            throw new \InvalidArgumentException("SQLite WAL hot-journal current-source next227 missing finalization {$key}");
                        }
                    }
                    if (!is_array($plan['current_source_token']) || (string) ($plan['current_source_token']['id'] ?? '') === '' || (int) ($plan['current_source_token']['epoch'] ?? 0) <= 0) {
                        throw new \InvalidArgumentException('SQLite WAL hot-journal current-source next227 token is invalid');
                    }
                    foreach (['checkpoint_frame', 'checkpoint_cookie', 'schema_cookie', 'next_source_epoch'] as $key) {
                        if (!is_int($plan[$key]) || $plan[$key] <= 0) {
                            throw new \InvalidArgumentException("SQLite WAL hot-journal current-source next227 {$key} must be positive");
                        }
                    }
                    if ((int) $plan['next_source_epoch'] <= (int) $plan['current_source_token']['epoch']) {
                        throw new \InvalidArgumentException('SQLite WAL hot-journal current-source next227 next source epoch must advance');
                    }
                }

                /**
                 * @param mixed $values
                 * @return list<string>
                 */
                private static function stringList($values, string $label): array
                {
                    if (!is_array($values)) {
                        throw new \InvalidArgumentException("SQLite WAL hot-journal current-source next227 {$label} must be a list");
                    }
                    $list = [];
                    foreach ($values as $value) {
                        if (!is_string($value) || $value === '') {
                            throw new \InvalidArgumentException("SQLite WAL hot-journal current-source next227 {$label} must contain non-empty strings");
                        }
                        $list[] = $value;
                    }

                    return $list;
                }

                /**
                 * @param mixed $rows
                 * @return array<string,array<string,mixed>>
                 */
                private static function scopeRowsByName($rows): array
                {
                    if (!is_array($rows) || $rows === []) {
                        throw new \InvalidArgumentException('SQLite WAL hot-journal current-source next227 requires scope rows');
                    }
                    $indexed = [];
                    foreach ($rows as $row) {
                        if (!is_array($row) || !is_string($row['name'] ?? null) || $row['name'] === '') {
                            throw new \InvalidArgumentException('SQLite WAL hot-journal current-source next227 scope rows are malformed');
                        }
                        $indexed[$row['name']] = $row;
                    }

                    return $indexed;
                }

                /**
                 * @param array<string,mixed> $receipt
                 * @param array<string,array<string,mixed>> $scopeRows
                 * @return array<string,mixed>
                 */
                private static function receiptRow(
                    array $receipt,
                    array $scopeRows,
                    string $expectedTokenId,
                    int $expectedEpoch,
                    int $expectedCheckpointFrame,
                    int $expectedCheckpointCookie,
                    int $expectedSchemaCookie,
                    int $expectedNextEpoch
                ): array {
                    foreach (['scope_name', 'source_token_id', 'source_epoch', 'checkpoint_frame', 'checkpoint_cookie', 'schema_cookie', 'journal_delete_receipt', 'page_digests', 'next_source_epoch'] as $key) {
                        if (!array_key_exists($key, $receipt)) {
                            throw new \InvalidArgumentException("SQLite WAL hot-journal current-source next227 missing receipt {$key}");
                        }
                    }
                    $scopeName = (string) $receipt['scope_name'];
                    if ($scopeName === '') {
                        throw new \InvalidArgumentException('SQLite WAL hot-journal current-source next227 receipt scope is required');
                    }
                    foreach (['source_epoch', 'checkpoint_frame', 'checkpoint_cookie', 'schema_cookie', 'next_source_epoch'] as $key) {
                        if (!is_int($receipt[$key]) || $receipt[$key] <= 0) {
                            throw new \InvalidArgumentException("SQLite WAL hot-journal current-source next227 {$scopeName} {$key} must be positive");
                        }
                    }
                    $receiptDigests = self::pageDigestMap($receipt['page_digests'], $scopeName);
                    $scope = $scopeRows[$scopeName] ?? null;
                    $scopeDigests = is_array($scope) ? self::pageDigestMapFromScope($scope, $scopeName) : [];

                    $reasons = [];
                    if (!is_array($scope)) {
                        $reasons[] = 'publish_scope_missing_from_finalization';
                    } elseif (($scope['finalized'] ?? false) !== true) {
                        $reasons[] = 'publish_scope_not_finalized';
                    }
                    if ((string) $receipt['source_token_id'] !== $expectedTokenId) {
                        $reasons[] = 'publish_source_token_mismatch';
                    }
                    if ((int) $receipt['source_epoch'] !== $expectedEpoch) {
                        $reasons[] = 'publish_source_epoch_mismatch';
                    }
                    if ((int) $receipt['checkpoint_frame'] !== $expectedCheckpointFrame) {
                        $reasons[] = 'publish_checkpoint_frame_mismatch';
                    }
                    if ((int) $receipt['checkpoint_cookie'] !== $expectedCheckpointCookie) {
                        $reasons[] = 'publish_checkpoint_cookie_mismatch';
                    }
                    if ((int) $receipt['schema_cookie'] !== $expectedSchemaCookie) {
                        $reasons[] = 'publish_schema_cookie_mismatch';
                    }
                    if (($receipt['journal_delete_receipt'] ?? false) !== true) {
                        $reasons[] = 'publish_hot_journal_delete_receipt_missing';
                    }
                    if ((int) $receipt['next_source_epoch'] !== $expectedNextEpoch) {
                        $reasons[] = 'publish_next_source_epoch_mismatch';
                    }
                    if (is_array($scope) && count($receiptDigests) !== (int) ($scope['page_digest_count'] ?? -1)) {
                        $reasons[] = 'publish_page_digest_count_mismatch';
                    }
                    if (is_array($scope) && array_keys($receiptDigests) !== array_map('intval', $scope['page_numbers'] ?? [])) {
                        $reasons[] = 'publish_page_number_mismatch';
                    }
                    if (is_array($scope) && $scopeDigests !== [] && $receiptDigests !== $scopeDigests) {
                        $reasons[] = 'publish_page_digest_mismatch';
                    }

                    $publishable = $reasons === [];

                    return [
                        'scope_name' => $scopeName,
                        'source_token_id' => (string) $receipt['source_token_id'],
                        'source_epoch' => (int) $receipt['source_epoch'],
                        'checkpoint_frame' => (int) $receipt['checkpoint_frame'],
                        'checkpoint_cookie' => (int) $receipt['checkpoint_cookie'],
                        'schema_cookie' => (int) $receipt['schema_cookie'],
                        'journal_delete_receipt' => (bool) $receipt['journal_delete_receipt'],
                        'next_source_epoch' => (int) $receipt['next_source_epoch'],
                        'page_numbers' => array_keys($receiptDigests),
                        'page_digest_count' => count($receiptDigests),
                        'publishable' => $publishable,
                        'blocked_reasons' => $reasons,
                        'receipt_reason' => $publishable ? 'publish_receipt_matches_finalized_scope' : $reasons[0],
                        'receipt_digest' => hash('sha256', json_encode([$scopeName, $receiptDigests, $receipt], JSON_THROW_ON_ERROR)),
                    ];
                }

                /**
                 * @param mixed $values
                 * @return array<int,string>
                 */
                private static function pageDigestMap($values, string $scopeName): array
                {
                    if (!is_array($values) || $values === []) {
                        throw new \InvalidArgumentException("SQLite WAL hot-journal current-source next227 {$scopeName} requires page digests");
                    }
                    $normalized = [];
                    foreach ($values as $page => $digest) {
                        $pageNumber = (int) $page;
                        if ($pageNumber <= 0 || !is_string($digest) || !preg_match('/^[a-f0-9]{64}$/', $digest)) {
                            throw new \InvalidArgumentException("SQLite WAL hot-journal current-source next227 {$scopeName} page digests must map positive pages to sha256 strings");
                        }
                        $normalized[$pageNumber] = $digest;
                    }
                    ksort($normalized);

                    return $normalized;
                }

                /**
                 * @param array<string,mixed> $scope
                 * @return array<int,string>
                 */
                private static function pageDigestMapFromScope(array $scope, string $scopeName): array
                {
                    $pageNumbers = $scope['page_numbers'] ?? null;
                    $digestCount = $scope['page_digest_count'] ?? null;
                    $pageDigests = $scope['page_digests'] ?? null;
                    if (!is_array($pageNumbers) || !is_int($digestCount) || !is_array($pageDigests)) {
                        throw new \InvalidArgumentException("SQLite WAL hot-journal current-source next227 {$scopeName} finalized scope page metadata is malformed");
                    }
                    $numbers = array_map('intval', $pageNumbers);
                    sort($numbers);
                    if (count($numbers) !== $digestCount) {
                        throw new \InvalidArgumentException("SQLite WAL hot-journal current-source next227 {$scopeName} finalized scope digest count is malformed");
                    }

                    return self::pageDigestMap($pageDigests, $scopeName);
                }

                /**
                 * @param list<mixed> $values
                 * @return list<string>
                 */
                private static function duplicateValues(array $values): array
                {
                    $seen = [];
                    $duplicates = [];
                    foreach ($values as $value) {
                        $key = (string) $value;
                        if (isset($seen[$key])) {
                            $duplicates[$key] = true;
                            continue;
                        }
                        $seen[$key] = true;
                    }

                    return array_keys($duplicates);
                }

                /**
                 * @param list<array<string,mixed>> $rows
                 */
                private static function allNextEpochsMatch(array $rows, int $expectedNextEpoch): bool
                {
                    foreach ($rows as $row) {
                        if (($row['next_source_epoch'] ?? null) !== $expectedNextEpoch) {
                            return false;
                        }
                    }

                    return $rows !== [];
                }
        };

        return $impl::plan($finalizationPlan, $publishReceipts);
    }

    public static function next228AdmitDurableSource(array $publication, array $barriers, array $readers, string $sourceToken): array
    {
        $impl = new class {
                /**
                 * @param array<string,mixed> $publication
                 * @param list<array<string,mixed>> $barriers
                 * @param list<array<string,mixed>> $readers
                 * @return array<string,mixed>
                 */
                public static function admitDurableSource(array $publication, array $barriers, array $readers, string $sourceToken): array
                {
                    if (($publication['status'] ?? null) !== 'wal-hot-journal-savepoint-checkpoint-current-source-next224') {
                        throw new \InvalidArgumentException('SQLite WAL hot-journal savepoint checkpoint current-source next228 requires a published next224 reset source');
                    }
                    if (($publication['publication_allowed'] ?? null) !== true || ($publication['checkpoint_reset_visible'] ?? null) !== true) {
                        throw new \InvalidArgumentException('SQLite WAL hot-journal savepoint checkpoint current-source next228 requires visible reset publication');
                    }
                    if ($barriers === []) {
                        throw new \InvalidArgumentException('SQLite WAL hot-journal savepoint checkpoint current-source next228 requires durability barriers');
                    }
                    if ($readers === []) {
                        throw new \InvalidArgumentException('SQLite WAL hot-journal savepoint checkpoint current-source next228 requires reader receipts');
                    }

                    $expectedToken = self::token($publication['source_token'] ?? null, 'publication source token');
                    $requestedToken = self::token($sourceToken, 'requested source token');
                    if ($requestedToken !== $expectedToken) {
                        throw new \InvalidArgumentException('SQLite WAL hot-journal savepoint checkpoint current-source next228 source token mismatch');
                    }

                    $generation = self::positiveInt($publication, 'next_writer_generation');
                    $databaseDigest = self::digest($publication['database_digest'] ?? null, 'database digest');
                    $mode = self::mode($publication['mode'] ?? null);

                    $barrierRows = [];
                    foreach ($barriers as $barrier) {
                        $barrierRows[] = self::barrierRow($barrier, $mode, $generation, $databaseDigest, $expectedToken);
                    }

                    $readerRows = [];
                    foreach ($readers as $reader) {
                        $readerRows[] = self::readerRow($reader, $generation, $expectedToken);
                    }

                    $requiredBarriers = ['database_sync', 'wal_reset_sync', 'journal_unlink_dir_sync', 'shm_lock_epoch', 'savepoint_release'];
                    $barrierTypes = array_values(array_unique(array_column($barrierRows, 'type')));
                    $missingBarriers = array_values(array_diff($requiredBarriers, $barrierTypes));
                    $blockedBarriers = array_values(array_filter($barrierRows, static fn (array $row): bool => !$row['admitted']));
                    $blockedReaders = array_values(array_filter($readerRows, static fn (array $row): bool => !$row['admitted']));

                    $guardRows = [
                        [
                            'name' => 'next224_publication_visible',
                            'matched' => true,
                            'reason' => 'next224 already verified reset sidecars and reader reopen admission',
                        ],
                        [
                            'name' => 'required_durability_barriers_present',
                            'matched' => $missingBarriers === [],
                            'reason' => 'database sync, WAL reset sync, journal unlink directory sync, SHM lock epoch, and savepoint release barriers are required',
                        ],
                        [
                            'name' => 'durability_barriers_match_current_source',
                            'matched' => $blockedBarriers === [],
                            'reason' => 'barrier receipts must match source token, generation, mode, database digest, lock epoch, and durable sync ordering',
                        ],
                        [
                            'name' => 'readers_observe_durable_source',
                            'matched' => $blockedReaders === [],
                            'reason' => 'readers may reuse a handle only after observing the durable source token and generation',
                        ],
                    ];
                    $blockedGuards = array_values(array_column(
                        array_filter($guardRows, static fn (array $row): bool => !$row['matched']),
                        'name'
                    ));
                    $admitted = $blockedGuards === [];

                    return [
                        'status' => $admitted
                            ? 'wal-hot-journal-savepoint-checkpoint-current-source-next228'
                            : 'wal-hot-journal-savepoint-checkpoint-current-source-blocked-next228',
                        'reason' => $admitted
                            ? 'durable_checkpoint_source_barriers_admit_reopened_readers'
                            : 'durable_checkpoint_source_waits_for_barrier_or_reader_receipts',
                        'base_status' => $publication['status'],
                        'mode' => $mode,
                        'source_token' => $expectedToken,
                        'next_writer_generation' => $generation,
                        'database_digest' => $databaseDigest,
                        'barrier_rows' => $barrierRows,
                        'reader_rows' => $readerRows,
                        'admitted_barrier_names' => array_values(array_column(array_filter($barrierRows, static fn (array $row): bool => $row['admitted']), 'name')),
                        'blocked_barrier_names' => array_values(array_column($blockedBarriers, 'name')),
                        'blocked_barrier_reasons' => self::reasonList($blockedBarriers),
                        'missing_barrier_types' => $missingBarriers,
                        'admitted_reader_names' => array_values(array_column(array_filter($readerRows, static fn (array $row): bool => $row['admitted']), 'name')),
                        'blocked_reader_names' => array_values(array_column($blockedReaders, 'name')),
                        'blocked_reader_reasons' => self::reasonList($blockedReaders),
                        'current_source_admitted' => $admitted,
                        'checkpoint_reusable_by_readers' => $admitted,
                        'next_writer_action' => $admitted ? 'start_after_durable_checkpoint_source' : 'wait_for_durable_checkpoint_source',
                        'reader_action' => $admitted ? 'reuse_reopened_durable_source_readers' : 'reopen_after_durability_barrier',
                        'guard_rows' => $guardRows,
                        'guard_names' => array_column($guardRows, 'name'),
                        'guard_matches' => array_column($guardRows, 'matched'),
                        'blocked_guard_names' => $blockedGuards,
                        'operation_names' => array_values(array_unique(array_merge(
                            is_array($publication['operation_names'] ?? null) ? $publication['operation_names'] : [],
                            [
                                'verify_durable_checkpoint_source_barriers_current_source_next228',
                                $admitted ? 'admit_durable_checkpoint_source_current_source_next228' : 'defer_durable_checkpoint_source_current_source_next228',
                            ]
                        ))),
                        'admission_digest' => hash('sha256', json_encode([$expectedToken, $mode, $generation, $barrierRows, $readerRows, $blockedGuards], JSON_THROW_ON_ERROR)),
                        'dependencies' => array_values(array_unique(array_merge(
                            is_array($publication['dependencies'] ?? null) ? $publication['dependencies'] : [],
                            [
                                'sqlite-wal-hot-journal-savepoint-checkpoint-current-source-next228',
                                'sqlite-durable-checkpoint-source-barriers',
                                'wordpress-import-reopened-reader-durable-source',
                            ]
                        ))),
                        'dependency_closure' => 'no new support component needed; reuses next224 reset publication metadata, VFS sync receipts, SHM lock epochs, and savepoint release receipts',
                        'non_overlap' => 'next228 verifies post-publication durability barriers and reopened-reader reuse; it does not repeat next224 sidecar publication receipts, next218 reset admission, WAL byte truncation, VFS writer/sync apply, rollback-journal commit/apply, or checkpoint transaction planning',
                    ];
                }

                /**
                 * @param array<string,mixed> $barrier
                 * @return array<string,mixed>
                 */
                private static function barrierRow(array $barrier, string $mode, int $generation, string $databaseDigest, string $sourceToken): array
                {
                    $name = self::token($barrier['name'] ?? null, 'barrier name');
                    $type = self::token($barrier['type'] ?? null, "{$name} barrier type");
                    if (!in_array($type, ['database_sync', 'wal_reset_sync', 'journal_unlink_dir_sync', 'shm_lock_epoch', 'savepoint_release'], true)) {
                        throw new \InvalidArgumentException("SQLite WAL hot-journal savepoint checkpoint current-source next228 {$name} barrier type is invalid");
                    }
                    $observedToken = self::token($barrier['source_token'] ?? null, "{$name} source token");
                    $observedGeneration = self::nonNegativeInt($barrier['generation'] ?? null, "{$name} generation");
                    $syncOrder = self::nonNegativeInt($barrier['sync_order'] ?? null, "{$name} sync order");
                    $receipt = ($barrier['receipt'] ?? false) === true;
                    $exclusive = ($barrier['exclusive_lock'] ?? false) === true;
                    $digest = isset($barrier['database_digest']) ? self::digest($barrier['database_digest'], "{$name} database digest") : null;
                    $observedMode = isset($barrier['mode']) ? self::mode($barrier['mode']) : $mode;
                    $savepointReleased = ($barrier['savepoint_released'] ?? false) === true;
                    $journalUnlinked = ($barrier['journal_unlinked'] ?? false) === true;
                    $walReset = ($barrier['wal_reset'] ?? false) === true;

                    $reasons = [];
                    if (!$receipt) {
                        $reasons[] = 'barrier_receipt_missing';
                    }
                    if ($observedToken !== $sourceToken) {
                        $reasons[] = 'source_token_mismatch';
                    }
                    if ($observedGeneration !== $generation) {
                        $reasons[] = 'generation_mismatch';
                    }
                    if ($syncOrder <= 0) {
                        $reasons[] = 'sync_order_missing';
                    }
                    if (!$exclusive && in_array($type, ['database_sync', 'wal_reset_sync', 'shm_lock_epoch'], true)) {
                        $reasons[] = 'exclusive_lock_missing';
                    }
                    if ($type === 'database_sync' && $digest !== $databaseDigest) {
                        $reasons[] = 'database_digest_mismatch';
                    }
                    if ($type === 'wal_reset_sync') {
                        if (!$walReset) {
                            $reasons[] = 'wal_reset_not_observed';
                        }
                        if ($observedMode !== $mode) {
                            $reasons[] = 'wal_reset_mode_mismatch';
                        }
                    }
                    if ($type === 'journal_unlink_dir_sync' && !$journalUnlinked) {
                        $reasons[] = 'hot_journal_unlink_not_synced';
                    }
                    if ($type === 'savepoint_release' && !$savepointReleased) {
                        $reasons[] = 'savepoint_not_released';
                    }

                    return [
                        'name' => $name,
                        'type' => $type,
                        'source_token' => $observedToken,
                        'expected_source_token' => $sourceToken,
                        'generation' => $observedGeneration,
                        'expected_generation' => $generation,
                        'mode' => $observedMode,
                        'expected_mode' => $mode,
                        'sync_order' => $syncOrder,
                        'receipt' => $receipt,
                        'exclusive_lock' => $exclusive,
                        'database_digest' => $digest,
                        'wal_reset' => $walReset,
                        'journal_unlinked' => $journalUnlinked,
                        'savepoint_released' => $savepointReleased,
                        'admitted' => $reasons === [],
                        'receipt_reason' => $reasons === [] ? 'durability_barrier_matches_current_source' : implode('|', $reasons),
                        'blocked_reasons' => $reasons,
                    ];
