                    }
                    foreach (['database_path', 'wal_path', 'journal_path'] as $key) {
                        if (!is_string($plan[$key]) || $plan[$key] === '') {
                            throw new \InvalidArgumentException("SQLite WAL hot-journal current-source next234 {$key} is required");
                        }
                    }
