                    }
                    if ((int) $receipt['source_epoch'] !== $expectedSourceEpoch) {
                        $reasons[] = 'durable_handoff_source_epoch_mismatch';
                    }
                    if ((int) $receipt['next_source_epoch'] !== $expectedNextEpoch) {
                        $reasons[] = 'durable_handoff_next_source_epoch_mismatch';
                    }
