                    }
                    if ($duplicateNames !== []) {
                        $blockedReasons[] = 'duplicate_wal_sidecar_receipt';
                    }
                    if ($readerBlocks !== []) {
                        $blockedReasons[] = 'reader_pin_beyond_checkpoint_frame';
