                        'next_source_epoch' => (int) $sidecar['next_source_epoch'],
                        'checkpoint_frame' => (int) $sidecar['checkpoint_frame'],
                        'checkpoint_cookie' => (int) $sidecar['checkpoint_cookie'],
                        'schema_cookie' => (int) $sidecar['schema_cookie'],
