                        'database_digest' => (string) ($receipt['database_digest'] ?? ''),
                        'exclusive_lock_held' => ($receipt['exclusive_lock_held'] ?? false) === true,
                        'fsync_complete' => ($receipt['fsync_complete'] ?? false) === true,
                        'accepted' => $reasons === [],
