                        throw new \InvalidArgumentException('SQLite WAL hot-journal savepoint checkpoint current-source next244 requires reader acknowledgements');
                    }

                    $sourceToken = self::token($baselinePlan['source_token'] ?? null, 'source token');
                    $databaseDigest = self::digest($baselinePlan['database_digest'] ?? null, 'database digest');
                    $pageCacheDigest = self::digest($baselinePlan['page_cache_digest'] ?? null, 'page cache digest');
                    $schemaCookie = self::positiveInt($baselinePlan, 'schema_cookie');
                    $commitGeneration = self::positiveInt($baselinePlan, 'commit_generation');
                    $checkpointFrame = self::positiveInt($baselinePlan, 'checkpoint_frame');
                    $mxFrame = self::positiveInt($baselinePlan, 'wal_index_mx_frame');
                    $salt = self::walSalt($baselinePlan['wal_index_salt'] ?? null);
                    $expectedPages = self::intSet($baselinePlan['dirty_pages'] ?? null, 'dirty pages');
                    $expectedFrames = self::intSet($baselinePlan['commit_frames'] ?? null, 'commit frames');

                    $durableRows = [];
                    foreach ($durableReceipts as $receipt) {
                        $durableRows[] = self::durableRow($receipt, $sourceToken, $databaseDigest, $pageCacheDigest, $schemaCookie, $commitGeneration, $checkpointFrame, $mxFrame, $salt, $expectedPages, $expectedFrames);
                    }
                    $readerRows = [];
                    foreach ($readerAcks as $ack) {
                        $readerRows[] = self::readerRow($ack, $sourceToken, $databaseDigest, $schemaCookie, $commitGeneration, $checkpointFrame, $mxFrame, $salt);
                    }

                    $blockedDurableRows = array_values(array_filter($durableRows, static fn (array $row): bool => !$row['admitted']));
                    $blockedReaderRows = array_values(array_filter($readerRows, static fn (array $row): bool => !$row['admitted']));
                    $writtenPages = [];
                    $syncedFrames = [];
                    foreach ($durableRows as $row) {
                        if (!$row['admitted']) {
                            continue;
                        }
                        foreach ($row['database_pages_written'] as $pageNumber) {
                            $writtenPages[$pageNumber] = true;
                        }
                        foreach ($row['wal_frames_synced'] as $frameNumber) {
                            $syncedFrames[$frameNumber] = true;
                        }
                    }
                    ksort($writtenPages);
                    ksort($syncedFrames);
                    $missingPages = array_values(array_diff(array_keys($expectedPages), array_keys($writtenPages)));
                    $missingFrames = array_values(array_diff(array_keys($expectedFrames), array_keys($syncedFrames)));

                    $blockedReasons = self::blockedReasons($blockedDurableRows, $blockedReaderRows);
                    $guardRows = [
                        [
                            'name' => 'all_dirty_pages_durably_written',
                            'matched' => $missingPages === [],
                            'reason' => 'checkpoint publication must write every dirty page from the admitted next240 baseline',
                        ],
                        [
                            'name' => 'all_commit_frames_durably_synced',
                            'matched' => $missingFrames === [],
                            'reason' => 'checkpoint publication must sync every committed WAL frame before deleting or resetting sidecars',
                        ],
                        [
                            'name' => 'durable_receipts_match_current_source',
                            'matched' => $blockedDurableRows === [],
                            'reason' => 'durable receipts must match source token, digests, schema cookie, generation, checkpoint frame, mxFrame, salt, lock, and sync state',
                        ],
                        [
                            'name' => 'reader_acknowledgements_match_current_source',
                            'matched' => $blockedReaderRows === [],
                            'reason' => 'reader acknowledgements must be pinned to the same checkpoint generation before the hot journal and stale WAL are retired',
                        ],
                    ];
                    $blockedGuards = array_values(array_column(array_filter($guardRows, static fn (array $row): bool => !$row['matched']), 'name'));
                    $sealed = $blockedGuards === [];

                    return [
                        'status' => $sealed
                            ? 'wal-hot-journal-savepoint-checkpoint-current-source-next244'
                            : 'wal-hot-journal-savepoint-checkpoint-current-source-blocked-next244',
                        'reason' => $sealed
                            ? 'durable_current_source_sealed_after_hot_journal_savepoint_checkpoint'
                            : 'durable_current_source_held_after_hot_journal_savepoint_checkpoint',
                        'base_status' => $baselinePlan['status'],
                        'database_path' => $baselinePlan['database_path'] ?? null,
                        'journal_path' => $baselinePlan['journal_path'] ?? null,
                        'wal_path' => $baselinePlan['wal_path'] ?? null,
                        'source_token' => $sourceToken,
                        'schema_cookie' => $schemaCookie,
                        'commit_generation' => $commitGeneration,
                        'database_digest' => $databaseDigest,
                        'page_cache_digest' => $pageCacheDigest,
                        'wal_index_salt' => $salt,
                        'wal_index_mx_frame' => $mxFrame,
                        'checkpoint_frame' => $checkpointFrame,
                        'expected_dirty_pages' => array_keys($expectedPages),
                        'durably_written_pages' => array_keys($writtenPages),
                        'missing_dirty_pages' => $missingPages,
                        'expected_commit_frames' => array_keys($expectedFrames),
                        'durably_synced_frames' => array_keys($syncedFrames),
                        'missing_commit_frames' => $missingFrames,
                        'durable_rows' => $durableRows,
                        'reader_rows' => $readerRows,
                        'admitted_durable_names' => array_values(array_column(array_filter($durableRows, static fn (array $row): bool => $row['admitted']), 'name')),
                        'blocked_durable_names' => array_values(array_column($blockedDurableRows, 'name')),
                        'admitted_reader_names' => array_values(array_column(array_filter($readerRows, static fn (array $row): bool => $row['admitted']), 'name')),
                        'blocked_reader_names' => array_values(array_column($blockedReaderRows, 'name')),
                        'blocked_reasons' => $blockedReasons,
                        'sealed_current_source' => $sealed,
                        'hot_journal_action' => $sealed ? 'delete_hot_journal_after_durable_checkpoint' : 'retain_hot_journal_until_durable_receipts_match',
                        'wal_sidecar_action' => $sealed ? 'reset_or_truncate_wal_sidecar_after_reader_acknowledgements' : 'preserve_wal_sidecar_for_current_source_replay',
                        'reader_action' => $sealed ? 'advance_readers_to_commit_generation_' . $commitGeneration : 'hold_readers_on_prior_checkpoint_source',
                        'page_cache_action' => $sealed ? 'seal_clean_page_cache_digest_' . $pageCacheDigest : 'discard_unsealed_checkpoint_page_cache',
                        'guard_rows' => $guardRows,
                        'guard_names' => array_column($guardRows, 'name'),
                        'guard_matches' => array_column($guardRows, 'matched'),
                        'blocked_guard_names' => $blockedGuards,
                        'seal_digest' => hash('sha256', json_encode([$sourceToken, $commitGeneration, $salt, $durableRows, $readerRows, $missingPages, $missingFrames], JSON_THROW_ON_ERROR)),
                        'operation_names' => array_values(array_unique(array_merge(
                            is_array($baselinePlan['operation_names'] ?? null) ? $baselinePlan['operation_names'] : [],
                            [
                                'verify_durable_current_source_after_hot_journal_savepoint_checkpoint_next244',
                                $sealed ? 'seal_durable_current_source_next244' : 'hold_durable_current_source_next244',
                            ]
                        ))),
                        'dependencies' => array_values(array_unique(array_merge(
                            is_array($baselinePlan['dependencies'] ?? null) ? $baselinePlan['dependencies'] : [],
                            [
                                'sqlite-wal-hot-journal-savepoint-checkpoint-current-source-next244',
                                'sqlite-wal-checkpoint-durable-current-source-seal',
                                'wordpress-import-hot-journal-savepoint-checkpoint-durable-seal',
                            ]
                        ))),
                        'dependency_closure' => 'no new support component needed; reuses next240 WAL-index baseline metadata, VFS durable receipt evidence, reader acknowledgements, and page-cache digests',
                        'non_overlap' => 'next244 seals durable current-source publication after next240 autocheckpoint admission; it does not repeat next240 commit baseline admission, next236 finalizer release, checkpoint transaction planning, VFS savepoint rollback, rollback-journal commit/apply, WAL byte truncation, or WAL-index reopen verification',
                    ];
                }

                /**
                 * @param array<string,mixed> $receipt
                 * @param array<int,true> $expectedPages
                 * @param array<int,true> $expectedFrames
                 * @param list<string> $salt
                 * @return array<string,mixed>
                 */
                private static function durableRow(array $receipt, string $sourceToken, string $databaseDigest, string $pageCacheDigest, int $schemaCookie, int $commitGeneration, int $checkpointFrame, int $mxFrame, array $salt, array $expectedPages, array $expectedFrames): array
                {
                    $name = self::token($receipt['name'] ?? null, 'durable receipt name');
                    $pages = self::intList($receipt['database_pages_written'] ?? null, "{$name} database pages written");
                    $frames = self::intList($receipt['wal_frames_synced'] ?? null, "{$name} WAL frames synced");
                    $reasons = self::commonReasons($receipt, $sourceToken, $databaseDigest, $schemaCookie, $commitGeneration, $checkpointFrame, $mxFrame, $salt, $name);

                    if (!hash_equals($pageCacheDigest, self::digest($receipt['page_cache_digest'] ?? null, "{$name} page cache digest"))) {
                        $reasons[] = 'durable_page_cache_digest_mismatch';
                    }
                    foreach ($pages as $pageNumber) {
                        if (!isset($expectedPages[$pageNumber])) {
                            $reasons[] = 'durable_unexpected_database_page';
                            break;
                        }
                    }
                    foreach ($frames as $frameNumber) {
                        if (!isset($expectedFrames[$frameNumber])) {
                            $reasons[] = 'durable_unexpected_wal_frame';
                            break;
                        }
                    }
                    if (($receipt['exclusive_lock_held'] ?? false) !== true) {
                        $reasons[] = 'durable_exclusive_lock_missing';
                    }
                    if (($receipt['database_sync_done'] ?? false) !== true) {
                        $reasons[] = 'durable_database_sync_missing';
                    }
                    if (($receipt['wal_sync_done'] ?? false) !== true) {
                        $reasons[] = 'durable_wal_sync_missing';
                    }
                    if (($receipt['directory_sync_done'] ?? false) !== true) {
                        $reasons[] = 'durable_directory_sync_missing';
                    }
                    if (($receipt['hot_journal_deleted'] ?? false) !== true) {
                        $reasons[] = 'durable_hot_journal_not_deleted';
                    }
                    if (($receipt['stale_wal_preserved'] ?? false) === true) {
                        $reasons[] = 'durable_stale_wal_preserved';
                    }

                    $reasons = array_values(array_unique($reasons));

                    return [
                        'name' => $name,
                        'database_pages_written' => $pages,
                        'wal_frames_synced' => $frames,
                        'exclusive_lock_held' => ($receipt['exclusive_lock_held'] ?? false) === true,
                        'database_sync_done' => ($receipt['database_sync_done'] ?? false) === true,
                        'wal_sync_done' => ($receipt['wal_sync_done'] ?? false) === true,
                        'directory_sync_done' => ($receipt['directory_sync_done'] ?? false) === true,
                        'hot_journal_deleted' => ($receipt['hot_journal_deleted'] ?? false) === true,
                        'stale_wal_preserved' => ($receipt['stale_wal_preserved'] ?? false) === true,
                        'admitted' => $reasons === [],
                        'receipt_reason' => $reasons === [] ? 'durable_receipt_seals_checkpoint_current_source' : implode('|', $reasons),
                        'blocked_reasons' => $reasons,
                    ];
                }

                /**
                 * @param array<string,mixed> $ack
                 * @param list<string> $salt
                 * @return array<string,mixed>
                 */
                private static function readerRow(array $ack, string $sourceToken, string $databaseDigest, int $schemaCookie, int $commitGeneration, int $checkpointFrame, int $mxFrame, array $salt): array
                {
                    $name = self::token($ack['name'] ?? null, 'reader acknowledgement name');
                    $reasons = self::commonReasons($ack, $sourceToken, $databaseDigest, $schemaCookie, $commitGeneration, $checkpointFrame, $mxFrame, $salt, $name);

                    if (($ack['reader_generation'] ?? null) !== $commitGeneration) {
                        $reasons[] = 'reader_generation_mismatch';
                    }
                    if (($ack['snapshot_reopened'] ?? false) !== true) {
                        $reasons[] = 'reader_snapshot_not_reopened';
                    }
                    if (($ack['readmark_cleared'] ?? false) !== true) {
                        $reasons[] = 'reader_readmark_not_cleared';
                    }
                    if (($ack['hot_journal_seen'] ?? false) === true) {
                        $reasons[] = 'reader_hot_journal_still_visible';
                    }
                    if (($ack['stale_wal_seen'] ?? false) === true) {
                        $reasons[] = 'reader_stale_wal_still_visible';
                    }

                    $reasons = array_values(array_unique($reasons));

                    return [
                        'name' => $name,
                        'reader_generation' => $ack['reader_generation'] ?? null,
                        'snapshot_reopened' => ($ack['snapshot_reopened'] ?? false) === true,
                        'readmark_cleared' => ($ack['readmark_cleared'] ?? false) === true,
                        'hot_journal_seen' => ($ack['hot_journal_seen'] ?? false) === true,
                        'stale_wal_seen' => ($ack['stale_wal_seen'] ?? false) === true,
                        'admitted' => $reasons === [],
                        'reader_reason' => $reasons === [] ? 'reader_acknowledges_durable_checkpoint_current_source' : implode('|', $reasons),
                        'blocked_reasons' => $reasons,
                    ];
                }

                /**
                 * @param array<string,mixed> $row
                 * @param list<string> $salt
                 * @return list<string>
                 */
                private static function commonReasons(array $row, string $sourceToken, string $databaseDigest, int $schemaCookie, int $commitGeneration, int $checkpointFrame, int $mxFrame, array $salt, string $name): array
                {
                    $reasons = [];
                    if (self::token($row['source_token'] ?? null, "{$name} source token") !== $sourceToken) {
                        $reasons[] = 'source_token_mismatch';
                    }
                    if (self::positiveValue($row['schema_cookie'] ?? null, "{$name} schema cookie") !== $schemaCookie) {
                        $reasons[] = 'schema_cookie_mismatch';
                    }
                    if (self::positiveValue($row['commit_generation'] ?? null, "{$name} commit generation") !== $commitGeneration) {
                        $reasons[] = 'commit_generation_mismatch';
                    }
                    if (self::positiveValue($row['checkpoint_frame'] ?? null, "{$name} checkpoint frame") !== $checkpointFrame) {
                        $reasons[] = 'checkpoint_frame_mismatch';
                    }
                    if (self::positiveValue($row['wal_index_mx_frame'] ?? null, "{$name} wal index mx frame") !== $mxFrame) {
                        $reasons[] = 'wal_index_mx_frame_mismatch';
                    }
                    if (!hash_equals($databaseDigest, self::digest($row['database_digest'] ?? null, "{$name} database digest"))) {
                        $reasons[] = 'database_digest_mismatch';
                    }
                    if (self::walSalt($row['wal_index_salt'] ?? null) !== $salt) {
                        $reasons[] = 'wal_index_salt_mismatch';
                    }

                    return $reasons;
                }

                /**
                 * @param list<array<string,mixed>> $durableRows
                 * @param list<array<string,mixed>> $readerRows
                 * @return list<string>
                 */
                private static function blockedReasons(array $durableRows, array $readerRows): array
                {
                    $reasons = [];
                    foreach (array_merge($durableRows, $readerRows) as $row) {
                        foreach ($row['blocked_reasons'] as $reason) {
                            $reasons[$reason] = true;
                        }
                    }
                    ksort($reasons);

                    return array_keys($reasons);
                }

                /**
                 * @param array<string,mixed> $values
                 */
                private static function positiveInt(array $values, string $key): int
                {
                    return self::positiveValue($values[$key] ?? null, $key);
                }

                private static function positiveValue(mixed $value, string $label): int
                {
                    if (!is_int($value) || $value <= 0) {
                        throw new \InvalidArgumentException("SQLite WAL hot-journal savepoint checkpoint current-source next244 requires positive {$label}");
                    }

                    return $value;
                }

                private static function token(mixed $value, string $label): string
                {
                    if (!is_string($value) || !preg_match('/^[A-Za-z0-9_.:-]+$/', $value)) {
                        throw new \InvalidArgumentException("SQLite WAL hot-journal savepoint checkpoint current-source next244 {$label} is invalid");
                    }

                    return $value;
                }

                private static function digest(mixed $value, string $label): string
                {
                    if (!is_string($value) || !preg_match('/^[a-f0-9]{64}$/', $value)) {
                        throw new \InvalidArgumentException("SQLite WAL hot-journal savepoint checkpoint current-source next244 requires {$label}");
                    }

                    return $value;
                }

                /**
                 * @return list<string>
                 */
                private static function walSalt(mixed $value): array
                {
                    if (!is_array($value) || count($value) !== 2) {
                        throw new \InvalidArgumentException('SQLite WAL hot-journal savepoint checkpoint current-source next244 requires two WAL-index salt values');
                    }

                    $salt = array_values($value);
                    foreach ($salt as $part) {
                        self::token($part, 'WAL-index salt');
                    }

                    return $salt;
                }

                /**
                 * @return array<int,true>
                 */
                private static function intSet(mixed $value, string $label): array
                {
                    $list = self::intList($value, $label);
                    if ($list === []) {
                        throw new \InvalidArgumentException("SQLite WAL hot-journal savepoint checkpoint current-source next244 requires {$label}");
                    }

                    return array_fill_keys($list, true);
                }

                /**
                 * @return list<int>
                 */
                private static function intList(mixed $value, string $label): array
                {
                    if (!is_array($value)) {
                        throw new \InvalidArgumentException("SQLite WAL hot-journal savepoint checkpoint current-source next244 requires {$label}");
                    }

                    $values = [];
                    foreach ($value as $number) {
                        if (!is_int($number) || $number <= 0) {
                            throw new \InvalidArgumentException("SQLite WAL hot-journal savepoint checkpoint current-source next244 {$label} contains an invalid number");
                        }
                        $values[$number] = true;
                    }
                    ksort($values);

                    return array_keys($values);
                }
        };

        return $impl::sealDurableCurrentSource($baselinePlan, $durableReceipts, $readerAcks);
    }

    public static function next245AdmitReopenedReaders(array $commitPlan, array $readerReceipts): array
    {
        $impl = new class {
                /**
                 * @param array<string,mixed> $commitPlan
                 * @param list<array<string,mixed>> $readerReceipts
                 * @return array<string,mixed>
                 */
                public static function admitReopenedReaders(array $commitPlan, array $readerReceipts): array
                {
                    if (($commitPlan['status'] ?? null) !== 'wal-hot-journal-savepoint-checkpoint-current-source-next242'
                        || ($commitPlan['commit_admitted'] ?? null) !== true
                    ) {
                        throw new \InvalidArgumentException('SQLite WAL hot-journal savepoint checkpoint current-source next245 requires an admitted next242 commit plan');
                    }
                    if ($readerReceipts === []) {
                        throw new \InvalidArgumentException('SQLite WAL hot-journal savepoint checkpoint current-source next245 requires reopened reader receipts');
                    }

                    $databasePath = self::path($commitPlan['database_path'] ?? null, 'database path');
                    $walPath = self::path($commitPlan['wal_path'] ?? null, 'wal path');
                    $journalPath = self::path($commitPlan['journal_path'] ?? null, 'journal path');
                    $sourceToken = self::token($commitPlan['source_token'] ?? null, 'source token');
                    $writerGeneration = self::positiveInt($commitPlan['writer_generation'] ?? null, 'writer generation');
                    $nextSourceGeneration = self::positiveInt($commitPlan['next_source_generation'] ?? null, 'next source generation');
                    $databaseDigest = self::digest($commitPlan['database_digest'] ?? null, 'database digest');
                    $schemaCookie = self::positiveInt($commitPlan['expected_schema_cookie'] ?? null, 'schema cookie');
                    $walSalt = self::walSalt($commitPlan['expected_wal_salt'] ?? null);
                    $coveredPages = self::positiveIntList($commitPlan['covered_page_numbers'] ?? null, 'covered pages');

                    $rows = [];
                    foreach ($readerReceipts as $receipt) {
                        $rows[] = self::readerRow(
                            $receipt,
                            $databasePath,
                            $walPath,
                            $journalPath,
                            $sourceToken,
                            $writerGeneration,
                            $nextSourceGeneration,
                            $databaseDigest,
                            $schemaCookie,
                            $walSalt,
                            $coveredPages
                        );
                    }

                    $blockedRows = array_values(array_filter($rows, static fn (array $row): bool => !$row['accepted']));
                    $duplicateNames = self::duplicates(array_column($rows, 'name'));
                    $blockedReasons = [];
                    foreach ($blockedRows as $row) {
                        foreach ($row['blocked_reasons'] as $reason) {
                            $blockedReasons[] = $reason;
                        }
                    }
                    if ($duplicateNames !== []) {
                        $blockedReasons[] = 'reader_receipt_name_duplicate';
                    }
                    $blockedReasons = array_values(array_unique($blockedReasons));

                    $guards = [
                        'next242_commit_admitted' => true,
                        'reader_receipt_names_unique' => $duplicateNames === [],
                        'reader_generations_follow_committed_writer' => self::allRowsHave($rows, 'generation_safe'),
                        'reader_tokens_match_current_source' => self::allRowsHave($rows, 'source_token_match'),
                        'reader_snapshots_match_database_digest' => self::allRowsHave($rows, 'database_digest_match'),
                        'reader_wal_salt_and_frames_current' => self::allRowsHave($rows, 'wal_snapshot_current'),
                        'reader_page_cache_is_checkpoint_covered' => self::allRowsHave($rows, 'page_cache_covered'),
                        'hot_journal_and_savepoint_fences_clear' => self::allRowsHave($rows, 'fences_clear'),
                        'all_reopened_readers_current' => $blockedRows === [],
                    ];
                    $blockedGuards = array_keys(array_filter($guards, static fn (bool $matched): bool => !$matched));
                    $admitted = $blockedGuards === [];

                    return [
                        'status' => $admitted
                            ? 'wal-hot-journal-savepoint-checkpoint-current-source-next245'
                            : 'wal-hot-journal-savepoint-checkpoint-current-source-blocked-next245',
                        'reason' => $admitted
                            ? 'reopened_readers_are_bound_to_committed_checkpoint_source'
                            : 'reopened_readers_wait_for_committed_checkpoint_source',
                        'base_status' => $commitPlan['status'],
                        'database_path' => $databasePath,
                        'wal_path' => $walPath,
                        'journal_path' => $journalPath,
                        'source_token' => $sourceToken,
                        'writer_generation' => $writerGeneration,
                        'next_source_generation' => $nextSourceGeneration,
                        'database_digest' => $databaseDigest,
                        'expected_schema_cookie' => $schemaCookie,
                        'expected_wal_salt' => $walSalt,
                        'covered_page_numbers' => $coveredPages,
                        'reader_rows' => $rows,
                        'reader_names' => array_values(array_column($rows, 'name')),
                        'duplicate_reader_names' => $duplicateNames,
                        'accepted_reader_names' => array_values(array_column(array_filter($rows, static fn (array $row): bool => $row['accepted']), 'name')),
                        'blocked_reader_names' => array_values(array_column($blockedRows, 'name')),
                        'blocked_reasons' => $blockedReasons,
                        'guard_names' => array_keys($guards),
                        'guard_matches' => array_values($guards),
                        'blocked_guard_names' => $blockedGuards,
                        'readers_admitted' => $admitted,
                        'reader_action' => $admitted ? 'serve_reopened_readers_from_generation_' . $nextSourceGeneration : 'reopen_reader_snapshots_before_serving',
                        'wal_action' => $admitted ? 'retain_checkpoint_wal_until_reader_release' : 'preserve_wal_until_reader_snapshot_matches',
                        'journal_action' => $admitted ? 'hot_journal_delete_fence_satisfied' : 'hold_hot_journal_delete_fence',
                        'cache_action' => $admitted ? 'reuse_checkpoint_page_cache_for_reopened_readers' : 'discard_stale_reader_page_cache',
                        'reader_digest' => hash('sha256', json_encode([$sourceToken, $nextSourceGeneration, $rows, $guards], JSON_THROW_ON_ERROR)),
                        'operation_names' => array_values(array_unique(array_merge(
                            is_array($commitPlan['operation_names'] ?? null) ? $commitPlan['operation_names'] : [],
                            [
                                'verify_reopened_reader_cache_current_source_next245',
                                $admitted ? 'admit_reopened_reader_cache_current_source_next245' : 'block_reopened_reader_cache_current_source_next245',
                            ]
                        ))),
                        'dependencies' => array_values(array_unique(array_merge(
                            is_array($commitPlan['dependencies'] ?? null) ? $commitPlan['dependencies'] : [],
                            [
                                'sqlite-wal-hot-journal-savepoint-checkpoint-current-source-next245',
                                'sqlite-wal-reopened-reader-cache-current-source',
                                'wordpress-import-reopened-reader-after-checkpoint-commit',
                            ]
                        ))),
                        'dependency_closure' => 'no new support component needed; reuses next242 committed writer receipts with native PHP reopened-reader snapshot, page-cache, WAL salt, and hot-journal/savepoint fence metadata',
                        'non_overlap' => 'next245 admits reopened reader page-cache snapshots after the next242 committed writer source; it does not repeat writer commit receipt validation, durable sidecar publication, WAL byte truncation, VFS savepoint rollback apply, rollback-journal commit/apply, checkpoint transaction planning, or reader checkpoint snapshots',
                    ];
                }

                /**
                 * @param array<string,mixed> $receipt
                 * @param list<int> $coveredPages
                 * @return array<string,mixed>
                 */
                private static function readerRow(
                    array $receipt,
                    string $databasePath,
                    string $walPath,
                    string $journalPath,
                    string $sourceToken,
                    int $writerGeneration,
                    int $nextSourceGeneration,
                    string $databaseDigest,
                    int $schemaCookie,
                    string $walSalt,
                    array $coveredPages
                ): array {
                    $name = self::token($receipt['name'] ?? null, 'reader name');
                    $reasons = [];

                    if (self::path($receipt['database_path'] ?? null, "{$name} database path") !== $databasePath) {
                        $reasons[] = 'reader_database_path_mismatch';
                    }
                    if (self::path($receipt['wal_path'] ?? null, "{$name} wal path") !== $walPath) {
                        $reasons[] = 'reader_wal_path_mismatch';
                    }
                    if (self::path($receipt['journal_path'] ?? null, "{$name} journal path") !== $journalPath) {
                        $reasons[] = 'reader_journal_path_mismatch';
                    }
                    if (self::token($receipt['source_token'] ?? null, "{$name} source token") !== $sourceToken) {
                        $reasons[] = 'reader_source_token_mismatch';
                    }
                    if (self::positiveInt($receipt['writer_generation'] ?? null, "{$name} writer generation") !== $writerGeneration) {
                        $reasons[] = 'reader_writer_generation_mismatch';
                    }
                    if (self::positiveInt($receipt['reader_generation'] ?? null, "{$name} reader generation") < $nextSourceGeneration) {
                        $reasons[] = 'reader_generation_stale';
                    }
                    if (self::digest($receipt['database_digest'] ?? null, "{$name} database digest") !== $databaseDigest) {
                        $reasons[] = 'reader_database_digest_mismatch';
                    }
                    if (self::positiveInt($receipt['schema_cookie'] ?? null, "{$name} schema cookie") !== $schemaCookie) {
                        $reasons[] = 'reader_schema_cookie_mismatch';
                    }
                    if (self::walSalt($receipt['wal_salt'] ?? null) !== $walSalt) {
                        $reasons[] = 'reader_wal_salt_mismatch';
                    }

                    $readmarkFrame = self::nonNegativeInt($receipt['readmark_frame'] ?? null, "{$name} readmark frame");
                    $lastVisibleFrame = self::nonNegativeInt($receipt['last_visible_frame'] ?? null, "{$name} last visible frame");
                    if ($lastVisibleFrame < $readmarkFrame) {
                        $reasons[] = 'reader_visible_frame_before_readmark';
                    }
                    if ($lastVisibleFrame > $writerGeneration) {
                        $reasons[] = 'reader_visible_frame_past_writer_generation';
                    }

                    $pageNumbers = self::positiveIntList($receipt['page_numbers'] ?? null, "{$name} page numbers");
                    foreach ($pageNumbers as $pageNumber) {
                        if (!in_array($pageNumber, $coveredPages, true)) {
                            $reasons[] = 'reader_page_not_checkpoint_covered';
                        }
                    }

                    if (($receipt['page_cache_clean'] ?? false) !== true) {
                        $reasons[] = 'reader_page_cache_dirty';
                    }
                    if (($receipt['snapshot_open'] ?? false) !== true) {
                        $reasons[] = 'reader_snapshot_not_open';
                    }
                    if (($receipt['hot_journal_visible'] ?? false) === true) {
                        $reasons[] = 'reader_hot_journal_visible';
                    }
                    if (($receipt['savepoint_depth'] ?? 0) !== 0) {
                        $reasons[] = 'reader_savepoint_scope_open';
                    }
                    if (($receipt['reserved_lock_held'] ?? false) === true) {
                        $reasons[] = 'reader_reserved_lock_held';
                    }

                    $reasons = array_values(array_unique($reasons));

                    return [
                        'name' => $name,
                        'database_path' => (string) $receipt['database_path'],
                        'wal_path' => (string) $receipt['wal_path'],
                        'journal_path' => (string) $receipt['journal_path'],
                        'source_token' => (string) $receipt['source_token'],
                        'writer_generation' => (int) $receipt['writer_generation'],
                        'reader_generation' => (int) $receipt['reader_generation'],
                        'database_digest' => (string) $receipt['database_digest'],
                        'schema_cookie' => (int) $receipt['schema_cookie'],
                        'wal_salt' => (string) $receipt['wal_salt'],
                        'readmark_frame' => $readmarkFrame,
                        'last_visible_frame' => $lastVisibleFrame,
                        'page_numbers' => $pageNumbers,
                        'page_cache_clean' => ($receipt['page_cache_clean'] ?? false) === true,
                        'snapshot_open' => ($receipt['snapshot_open'] ?? false) === true,
                        'hot_journal_visible' => ($receipt['hot_journal_visible'] ?? false) === true,
                        'savepoint_depth' => (int) ($receipt['savepoint_depth'] ?? 0),
                        'reserved_lock_held' => ($receipt['reserved_lock_held'] ?? false) === true,
                        'generation_safe' => !in_array('reader_generation_stale', $reasons, true),
                        'source_token_match' => !in_array('reader_source_token_mismatch', $reasons, true),
                        'database_digest_match' => !in_array('reader_database_digest_mismatch', $reasons, true),
                        'wal_snapshot_current' => !in_array('reader_wal_salt_mismatch', $reasons, true)
                            && !in_array('reader_visible_frame_before_readmark', $reasons, true)
                            && !in_array('reader_visible_frame_past_writer_generation', $reasons, true),
                        'page_cache_covered' => !in_array('reader_page_not_checkpoint_covered', $reasons, true)
                            && !in_array('reader_page_cache_dirty', $reasons, true),
                        'fences_clear' => !in_array('reader_hot_journal_visible', $reasons, true)
                            && !in_array('reader_savepoint_scope_open', $reasons, true)
                            && !in_array('reader_reserved_lock_held', $reasons, true)
                            && !in_array('reader_snapshot_not_open', $reasons, true),
                        'accepted' => $reasons === [],
                        'receipt_reason' => $reasons === [] ? 'reader_receipt_current' : implode('|', $reasons),
                        'blocked_reasons' => $reasons,
                    ];
                }

                /** @param list<array<string,mixed>> $rows */
                private static function allRowsHave(array $rows, string $field): bool
                {
                    foreach ($rows as $row) {
                        if (($row[$field] ?? false) !== true) {
                            return false;
                        }
                    }

                    return $rows !== [];
                }

                private static function positiveInt(mixed $value, string $label): int
                {
                    if (!is_int($value) || $value <= 0) {
                        throw new \InvalidArgumentException("SQLite WAL hot-journal savepoint checkpoint current-source next245 {$label} must be positive");
                    }

                    return $value;
                }

                private static function nonNegativeInt(mixed $value, string $label): int
                {
                    if (!is_int($value) || $value < 0) {
                        throw new \InvalidArgumentException("SQLite WAL hot-journal savepoint checkpoint current-source next245 {$label} must be non-negative");
                    }

                    return $value;
                }

                private static function token(mixed $value, string $label): string
                {
                    if (!is_string($value) || !preg_match('/^[A-Za-z0-9_.:-]+$/', $value)) {
                        throw new \InvalidArgumentException("SQLite WAL hot-journal savepoint checkpoint current-source next245 {$label} is invalid");
                    }

                    return $value;
                }

                private static function path(mixed $value, string $label): string
                {
                    if (!is_string($value) || $value === '') {
                        throw new \InvalidArgumentException("SQLite WAL hot-journal savepoint checkpoint current-source next245 {$label} is required");
                    }

                    return $value;
                }

                private static function digest(mixed $value, string $label): string
                {
                    if (!is_string($value) || preg_match('/^[a-f0-9]{64}$/', $value) !== 1) {
                        throw new \InvalidArgumentException("SQLite WAL hot-journal savepoint checkpoint current-source next245 requires {$label}");
                    }

                    return $value;
                }

                private static function walSalt(mixed $value): string
                {
                    if (!is_string($value) || preg_match('/^[a-f0-9]{16}$/', $value) !== 1) {
                        throw new \InvalidArgumentException('SQLite WAL hot-journal savepoint checkpoint current-source next245 WAL salt is invalid');
                    }

                    return $value;
                }

                /**
                 * @param mixed $values
                 * @return list<int>
                 */
                private static function positiveIntList(mixed $values, string $label): array
                {
                    if (!is_array($values) || $values === []) {
                        throw new \InvalidArgumentException("SQLite WAL hot-journal savepoint checkpoint current-source next245 requires {$label}");
                    }
                    $out = [];
                    foreach ($values as $value) {
                        if (!is_int($value) || $value <= 0) {
                            throw new \InvalidArgumentException("SQLite WAL hot-journal savepoint checkpoint current-source next245 {$label} must contain positive integers");
                        }
                        $out[] = $value;
                    }
                    $out = array_values(array_unique($out));
                    sort($out);

                    return $out;
                }

                /**
                 * @param list<string> $values
                 * @return list<string>
                 */
                private static function duplicates(array $values): array
                {
                    $seen = [];
                    $dupes = [];
                    foreach ($values as $value) {
                        if (isset($seen[$value])) {
                            $dupes[$value] = true;
                        }
                        $seen[$value] = true;
                    }

                    return array_keys($dupes);
                }
        };

        return $impl::admitReopenedReaders($commitPlan, $readerReceipts);
    }

    public static function next246AdmitDurableCurrentSourceHandoff(array $readerPlan, array $writeReceipts): array
    {
        $impl = new class {
                /**
                 * @param array<string,mixed> $readerPlan
                 * @param list<array<string,mixed>> $writeReceipts
                 * @return array<string,mixed>
                 */
                public static function admitDurableCurrentSourceHandoff(array $readerPlan, array $writeReceipts): array
                {
                    if (($readerPlan['status'] ?? null) !== 'wal-hot-journal-savepoint-checkpoint-current-source-next243'
                        || ($readerPlan['reader_snapshot_admitted'] ?? null) !== true
                    ) {
                        throw new \InvalidArgumentException('SQLite WAL hot-journal savepoint checkpoint current-source next246 requires an admitted next243 reader snapshot plan');
                    }
                    if ($writeReceipts === []) {
                        throw new \InvalidArgumentException('SQLite WAL hot-journal savepoint checkpoint current-source next246 requires VFS write receipts');
                    }

                    $databasePath = self::path($readerPlan['database_path'] ?? null, 'database path');
                    $walPath = self::path($readerPlan['wal_path'] ?? null, 'wal path');
                    $journalPath = self::path($readerPlan['journal_path'] ?? null, 'journal path');
                    $sourceToken = self::token($readerPlan['source_token'] ?? null, 'source token');
                    $commitGeneration = self::positiveInt($readerPlan['commit_generation'] ?? null, 'commit generation');
                    $schemaCookie = self::positiveInt($readerPlan['schema_cookie'] ?? null, 'schema cookie');
                    $databaseDigest = self::digest($readerPlan['database_digest'] ?? null, 'database digest');
                    $pageCacheDigest = self::digest($readerPlan['page_cache_digest'] ?? null, 'page cache digest');
                    $checkpointFrame = self::nonNegativeInt($readerPlan['checkpoint_frame'] ?? null, 'checkpoint frame');
                    $dirtyPages = self::positiveIntSet($readerPlan['dirty_pages'] ?? null, 'dirty pages');
                    $commitFrames = self::positiveIntSet($readerPlan['commit_frames'] ?? null, 'commit frames');
                    $readerNames = self::tokenSet($readerPlan['accepted_reader_names'] ?? null, 'accepted reader names');

                    $rows = [];
                    foreach ($writeReceipts as $receipt) {
                        $rows[] = self::writeReceiptRow($receipt, $databasePath, $walPath, $journalPath, $sourceToken, $commitGeneration);
                    }

                    $receiptNames = array_column($rows, 'name');
                    $duplicateReceipts = self::duplicates($receiptNames);
                    $acceptedRows = array_values(array_filter($rows, static fn (array $row): bool => $row['accepted']));
                    $blockedRows = array_values(array_filter($rows, static fn (array $row): bool => !$row['accepted']));

                    $databasePageWrites = [];
                    $commitFrameWrites = [];
                    $syncTargets = [];
                    $deleteTargets = [];
                    $operationOrder = [];
                    foreach ($acceptedRows as $row) {
                        $operationOrder[] = $row['operation'] === 'sync' ? 'sync:' . $row['target'] : $row['operation'];
                        if ($row['operation'] === 'write_database_page') {
                            foreach ($row['pages'] as $page) {
                                $databasePageWrites[$page] = true;
                            }
                        }
                        if ($row['operation'] === 'mark_wal_commit_frame') {
                            foreach ($row['frames'] as $frame) {
                                $commitFrameWrites[$frame] = true;
                            }
                        }
                        if ($row['operation'] === 'sync') {
                            $syncTargets[$row['target']] = true;
                        }
                        if ($row['operation'] === 'delete') {
                            $deleteTargets[$row['target']] = true;
                        }
                    }

                    $writtenPages = array_map('intval', array_keys($databasePageWrites));
                    sort($writtenPages);
                    $writtenCommitFrames = array_map('intval', array_keys($commitFrameWrites));
                    sort($writtenCommitFrames);
                    $missingPages = array_values(array_diff($dirtyPages, $writtenPages));
                    $missingFrames = array_values(array_diff($commitFrames, $writtenCommitFrames));
                    $missingSyncTargets = array_values(array_diff(['database', 'wal', 'directory'], array_keys($syncTargets)));
                    $hotJournalDeleted = isset($deleteTargets['journal']);
                    $orderMatched = self::operationOrderIsSafe($operationOrder);

                    $blockedReasons = [];
                    foreach ($blockedRows as $row) {
                        foreach ($row['blocked_reasons'] as $reason) {
                            $blockedReasons[] = $reason;
                        }
                    }
                    if ($duplicateReceipts !== []) {
                        $blockedReasons[] = 'vfs_write_receipt_name_duplicate';
                    }
                    if ($missingPages !== []) {
                        $blockedReasons[] = 'checkpoint_database_page_write_missing';
                    }
                    if ($missingFrames !== []) {
                        $blockedReasons[] = 'checkpoint_commit_frame_mark_missing';
                    }
                    if ($missingSyncTargets !== []) {
                        $blockedReasons[] = 'checkpoint_sync_target_missing';
                    }
                    if (!$hotJournalDeleted) {
                        $blockedReasons[] = 'checkpoint_hot_journal_delete_missing';
                    }
                    if (!$orderMatched) {
                        $blockedReasons[] = 'checkpoint_current_source_write_order_unsafe';
                    }
                    $blockedReasons = array_values(array_unique($blockedReasons));

                    $guardRows = [
                        [
                            'name' => 'next243_reader_snapshot_admitted',
                            'matched' => true,
                            'reason' => 'reader snapshots already match the autocheckpoint current source',
                        ],
                        [
                            'name' => 'vfs_write_receipt_names_unique',
                            'matched' => $duplicateReceipts === [],
                            'reason' => 'each durable write receipt must be attributable exactly once',
                        ],
                        [
                            'name' => 'all_dirty_pages_written_to_database',
                            'matched' => $missingPages === [],
                            'reason' => 'checkpoint promotion must materialize every dirty page in the database image',
                        ],
                        [
                            'name' => 'all_commit_frames_marked',
                            'matched' => $missingFrames === [],
                            'reason' => 'the WAL commit frames that define the current source must remain attributable',
                        ],
                        [
                            'name' => 'database_wal_directory_synced',
                            'matched' => $missingSyncTargets === [],
                            'reason' => 'database bytes, WAL metadata, and directory entry changes must reach durable storage',
                        ],
                        [
                            'name' => 'hot_journal_deleted_after_sync',
                            'matched' => $hotJournalDeleted && $orderMatched,
                            'reason' => 'a hot journal may disappear only after checkpoint bytes and directory sync are durable',
                        ],
                        [
                            'name' => 'all_vfs_receipts_accepted',
                            'matched' => $blockedRows === [],
                            'reason' => 'receipt path, token, generation, lock, sync, savepoint, and error metadata must match',
                        ],
                    ];
                    $blockedGuards = array_values(array_column(
                        array_filter($guardRows, static fn (array $row): bool => !$row['matched']),
                        'name'
                    ));
                    $admitted = $blockedGuards === [];

                    return [
                        'status' => $admitted
                            ? 'wal-hot-journal-savepoint-checkpoint-current-source-next246'
                            : 'wal-hot-journal-savepoint-checkpoint-current-source-blocked-next246',
                        'reason' => $admitted
                            ? 'durable_vfs_handoff_promotes_checkpoint_current_source'
                            : 'durable_vfs_handoff_holds_checkpoint_current_source',
                        'base_status' => $readerPlan['status'],
                        'database_path' => $databasePath,
                        'wal_path' => $walPath,
                        'journal_path' => $journalPath,
                        'source_token' => $sourceToken,
                        'commit_generation' => $commitGeneration,
                        'schema_cookie' => $schemaCookie,
                        'database_digest' => $databaseDigest,
                        'page_cache_digest' => $pageCacheDigest,
                        'checkpoint_frame' => $checkpointFrame,
                        'dirty_pages' => $dirtyPages,
                        'commit_frames' => $commitFrames,
                        'accepted_reader_names' => $readerNames,
                        'write_rows' => $rows,
                        'write_receipt_names' => $receiptNames,
                        'accepted_write_receipt_names' => array_values(array_column($acceptedRows, 'name')),
                        'blocked_write_receipt_names' => array_values(array_column($blockedRows, 'name')),
                        'duplicate_write_receipt_names' => $duplicateReceipts,
                        'written_database_pages' => $writtenPages,
                        'missing_database_pages' => $missingPages,
                        'written_commit_frames' => $writtenCommitFrames,
                        'missing_commit_frames' => $missingFrames,
                        'sync_targets' => array_values(array_keys($syncTargets)),
                        'missing_sync_targets' => $missingSyncTargets,
                        'delete_targets' => array_values(array_keys($deleteTargets)),
                        'operation_order' => $operationOrder,
                        'write_order_safe' => $orderMatched,
                        'blocked_write_reasons' => $blockedReasons,
                        'durable_handoff_admitted' => $admitted,
                        'checkpoint_action' => $admitted ? 'publish_database_image_as_checkpoint_current_source' : 'retain_previous_current_source_until_vfs_handoff_is_durable',
                        'wal_action' => $admitted ? 'retain_committed_frames_until_reader_epoch_advances' : 'hold_wal_reset_and_restart',
                        'journal_action' => $admitted ? 'delete_hot_journal_after_directory_sync' : 'keep_hot_journal_recovery_visible',
                        'savepoint_action' => $admitted ? 'release_savepoint_after_vfs_handoff' : 'keep_savepoint_scope_replayable',
                        'guard_rows' => $guardRows,
                        'guard_names' => array_column($guardRows, 'name'),
                        'guard_matches' => array_column($guardRows, 'matched'),
                        'blocked_guard_names' => $blockedGuards,
                        'handoff_digest' => hash('sha256', json_encode([$sourceToken, $commitGeneration, $databaseDigest, $pageCacheDigest, $rows, $guardRows], JSON_THROW_ON_ERROR)),
                        'operation_names' => array_values(array_unique(array_merge(
                            is_array($readerPlan['operation_names'] ?? null) ? $readerPlan['operation_names'] : [],
                            [
                                'verify_durable_vfs_handoff_next246',
                                $admitted ? 'admit_durable_current_source_handoff_next246' : 'hold_durable_current_source_handoff_next246',
                            ]
                        ))),
                        'dependencies' => array_values(array_unique(array_merge(
                            is_array($readerPlan['dependencies'] ?? null) ? $readerPlan['dependencies'] : [],
                            [
                                'sqlite-wal-hot-journal-savepoint-checkpoint-current-source-next246',
                                'sqlite-vfs-durable-checkpoint-handoff',
                                'wordpress-import-hot-journal-checkpoint-current-source',
                            ]
                        ))),
                        'dependency_closure' => 'no new support component needed; reuses native PHP VFS write receipts, sync targets, WAL commit-frame metadata, hot-journal delete receipts, and next243 reader snapshot admission',
                        'non_overlap' => 'next246 validates durable VFS handoff ordering after next243 reader admission; it does not repeat reader snapshot matching, checkpoint transaction planning, WAL byte truncation, VFS savepoint rollback, rollback-journal apply/commit, VFS sync planning/apply, file locking, or SELECT/JSON/B-tree surfaces',
                    ];
                }

                /**
                 * @param array<string,mixed> $receipt
                 * @return array<string,mixed>
                 */
                private static function writeReceiptRow(array $receipt, string $databasePath, string $walPath, string $journalPath, string $sourceToken, int $commitGeneration): array
                {
                    $name = self::token($receipt['name'] ?? null, 'write receipt name');
                    $target = self::target($receipt['target'] ?? null, "{$name} target");
                    $operation = self::operation($receipt['operation'] ?? null, "{$name} operation");
                    $path = self::path($receipt['path'] ?? null, "{$name} path");
                    $pages = self::optionalPositiveIntSet($receipt['pages'] ?? null, "{$name} pages");
                    $frames = self::optionalPositiveIntSet($receipt['frames'] ?? null, "{$name} frames");
                    $sequence = self::positiveInt($receipt['sequence'] ?? null, "{$name} sequence");
                    $reasons = [];

                    $expectedPath = match ($target) {
                        'database' => $databasePath,
                        'wal' => $walPath,
                        'journal' => $journalPath,
                        'directory' => dirname($databasePath),
                    };
                    if ($path !== $expectedPath) {
                        $reasons[] = 'vfs_write_path_mismatch';
                    }
                    if (self::token($receipt['source_token'] ?? null, "{$name} source token") !== $sourceToken) {
                        $reasons[] = 'vfs_write_source_token_mismatch';
                    }
                    if (self::positiveInt($receipt['commit_generation'] ?? null, "{$name} commit generation") !== $commitGeneration) {
                        $reasons[] = 'vfs_write_commit_generation_mismatch';
                    }
                    if (($receipt['exclusive_lock_held'] ?? null) !== true) {
                        $reasons[] = 'vfs_write_exclusive_lock_missing';
                    }
                    if (($receipt['savepoint_replayable'] ?? null) !== true) {
                        $reasons[] = 'vfs_write_savepoint_not_replayable';
                    }
                    if (($receipt['io_error'] ?? null) !== null) {
                        $reasons[] = 'vfs_write_io_error';
                    }
                    if ($operation === 'write_database_page' && ($target !== 'database' || $pages === [])) {
                        $reasons[] = 'vfs_database_page_write_receipt_invalid';
                    }
                    if ($operation === 'mark_wal_commit_frame' && ($target !== 'wal' || $frames === [])) {
                        $reasons[] = 'vfs_wal_commit_frame_receipt_invalid';
                    }
                    if ($operation === 'sync' && !in_array($target, ['database', 'wal', 'directory'], true)) {
                        $reasons[] = 'vfs_sync_target_invalid';
                    }
                    if ($operation === 'delete' && $target !== 'journal') {
                        $reasons[] = 'vfs_delete_target_invalid';
                    }

                    return [
                        'name' => $name,
                        'target' => $target,
                        'operation' => $operation,
                        'path' => $path,
                        'sequence' => $sequence,
                        'pages' => $pages,
                        'frames' => $frames,
                        'source_token' => $receipt['source_token'],
                        'commit_generation' => $receipt['commit_generation'],
                        'exclusive_lock_held' => $receipt['exclusive_lock_held'] ?? null,
                        'savepoint_replayable' => $receipt['savepoint_replayable'] ?? null,
                        'io_error' => $receipt['io_error'] ?? null,
                        'accepted' => $reasons === [],
                        'blocked_reasons' => array_values(array_unique($reasons)),
                        'receipt_reason' => $reasons === [] ? 'vfs_write_receipt_matches_checkpoint_current_source' : 'vfs_write_receipt_blocks_checkpoint_current_source',
                    ];
                }

                /**
                 * @param list<string> $operations
                 */
                private static function operationOrderIsSafe(array $operations): bool
                {
                    $firstPage = array_search('write_database_page', $operations, true);
                    $firstFrame = array_search('mark_wal_commit_frame', $operations, true);
                    $databaseSync = array_search('sync:database', $operations, true);
                    $walSync = array_search('sync:wal', $operations, true);
                    $directorySync = array_search('sync:directory', $operations, true);
                    $delete = array_search('delete', $operations, true);

                    return $firstPage !== false
                        && $firstFrame !== false
                        && $databaseSync !== false
                        && $walSync !== false
                        && $directorySync !== false
                        && $delete !== false
                        && $firstPage < $databaseSync
                        && $firstFrame < $walSync
                        && $databaseSync < $directorySync
                        && $walSync < $directorySync
                        && $directorySync < $delete;
                }

                private static function path(mixed $value, string $label): string
                {
                    if (!is_string($value) || $value === '') {
                        throw new \InvalidArgumentException("Invalid {$label}");
                    }
                    return $value;
                }

                private static function token(mixed $value, string $label): string
                {
                    if (!is_string($value) || !preg_match('/^[a-z0-9][a-z0-9._:-]*$/i', $value)) {
                        throw new \InvalidArgumentException("Invalid {$label}");
                    }
                    return $value;
                }

                /** @return list<string> */
                private static function tokenSet(mixed $value, string $label): array
                {
                    if (!is_array($value) || $value === []) {
                        throw new \InvalidArgumentException("Invalid {$label}");
                    }
                    $tokens = [];
                    foreach ($value as $item) {
                        $tokens[] = self::token($item, $label);
                    }
                    return array_values(array_unique($tokens));
                }

                private static function target(mixed $value, string $label): string
                {
                    $target = self::token($value, $label);
                    if (!in_array($target, ['database', 'wal', 'journal', 'directory'], true)) {
                        throw new \InvalidArgumentException("Invalid {$label}");
                    }
                    return $target;
                }

                private static function operation(mixed $value, string $label): string
                {
                    $operation = self::token($value, $label);
                    if (!in_array($operation, ['write_database_page', 'mark_wal_commit_frame', 'sync', 'delete'], true)) {
                        throw new \InvalidArgumentException("Invalid {$label}");
                    }
                    return $operation;
                }

                private static function digest(mixed $value, string $label): string
                {
                    if (!is_string($value) || !preg_match('/^[a-f0-9]{64}$/', $value)) {
                        throw new \InvalidArgumentException("Invalid {$label}");
                    }
                    return $value;
                }

                private static function positiveInt(mixed $value, string $label): int
                {
                    if (!is_int($value) || $value < 1) {
                        throw new \InvalidArgumentException("Invalid {$label}");
                    }
                    return $value;
                }

                private static function nonNegativeInt(mixed $value, string $label): int
                {
                    if (!is_int($value) || $value < 0) {
