                private static function cleanupRow(
                    array $receipt,
                    string $databasePath,
                    string $walPath,
                    string $journalPath,
                    string $sourceToken,
                    int $commitGeneration,
                    int $schemaCookie,
                    string $databaseDigest,
                    string $pageCacheDigest,
                    array $walIndexSalt,
                    int $walIndexMxFrame,
                    int $checkpointFrame,
