                    foreach ($receiptFrames as $frameNumber) {
                        if (!in_array($frameNumber, $commitFrames, true)) {
                            $reasons[] = 'cleanup_frame_not_committed';
                        }
                    }
                    foreach ($receiptReaders as $readerName) {
