                    $receiptNames = array_values(array_column($rows, 'name'));
                    $duplicateNames = self::duplicates($receiptNames);
                    $missingReaderNames = array_values(array_diff($expectedReaderNames, $receiptNames));
                    sort($missingReaderNames);
                    $unexpectedReaderNames = array_values(array_diff($receiptNames, $expectedReaderNames));
                    sort($unexpectedReaderNames);

                    $blockedRows = array_values(array_filter($rows, static fn (array $row): bool => !$row['released']));
                    $blockedReasons = [];
                    foreach ($blockedRows as $row) {
                        foreach ($row['blocked_reasons'] as $reason) {
                            $blockedReasons[] = $reason;
                        }
                    }
                    foreach ($duplicateNames as $name) {
                        $blockedReasons[] = 'reader_release_name_duplicate:' . $name;
                    }
                    foreach ($missingReaderNames as $name) {
                        $blockedReasons[] = 'reader_release_missing:' . $name;
                    }
                    foreach ($unexpectedReaderNames as $name) {
                        $blockedReasons[] = 'reader_release_unexpected:' . $name;
                    }
                    $blockedReasons = array_values(array_unique($blockedReasons));

                    $guards = [
                        'next245_readers_admitted' => true,
                        'release_receipt_names_unique' => $duplicateNames === [],
                        'all_admitted_readers_released' => $missingReaderNames === [],
                        'no_unexpected_reader_release' => $unexpectedReaderNames === [],
                        'release_tokens_match_current_source' => self::allRowsHave($rows, 'source_token_match'),
                        'release_snapshots_match_database_digest' => self::allRowsHave($rows, 'database_digest_match'),
                        'release_generations_follow_committed_writer' => self::allRowsHave($rows, 'generation_safe'),
                        'release_page_cache_is_checkpoint_covered' => self::allRowsHave($rows, 'page_cache_covered'),
                        'release_locks_and_hot_journal_fences_clear' => self::allRowsHave($rows, 'fences_clear'),
                        'all_reader_releases_current' => $blockedRows === [],
                    ];
                    $blockedGuards = array_keys(array_filter($guards, static fn (bool $matched): bool => !$matched));
                    $canTruncate = $blockedGuards === [];

                    return [
                        'status' => $canTruncate
                            ? 'wal-hot-journal-savepoint-checkpoint-current-source-next248'
                            : 'wal-hot-journal-savepoint-checkpoint-current-source-blocked-next248',
                        'reason' => $canTruncate
                            ? 'checkpoint_wal_can_truncate_after_all_reopened_readers_release'
                            : 'checkpoint_wal_truncation_waits_for_reopened_reader_release',
                        'base_status' => $readerAdmissionPlan['status'],
                        'database_path' => $databasePath,
                        'wal_path' => $walPath,
                        'journal_path' => $journalPath,
                        'source_token' => $sourceToken,
                        'writer_generation' => $writerGeneration,
                        'next_source_generation' => $nextSourceGeneration,
                        'database_digest' => $databaseDigest,
                        'covered_page_numbers' => $coveredPages,
                        'expected_reader_names' => $expectedReaderNames,
                        'release_rows' => $rows,
                        'release_reader_names' => $receiptNames,
                        'duplicate_release_names' => $duplicateNames,
                        'missing_release_names' => $missingReaderNames,
                        'unexpected_release_names' => $unexpectedReaderNames,
                        'released_reader_names' => array_values(array_column(array_filter($rows, static fn (array $row): bool => $row['released']), 'name')),
                        'blocked_reader_names' => array_values(array_column($blockedRows, 'name')),
                        'blocked_reasons' => $blockedReasons,
                        'guard_names' => array_keys($guards),
                        'guard_matches' => array_values($guards),
                        'blocked_guard_names' => $blockedGuards,
                        'checkpoint_truncation_admitted' => $canTruncate,
                        'reader_action' => $canTruncate ? 'close_reopened_reader_generation_' . $nextSourceGeneration : 'wait_for_reopened_reader_release',
                        'wal_action' => $canTruncate ? 'truncate_checkpoint_wal_after_reader_release' : 'retain_checkpoint_wal_for_open_readers',
                        'journal_action' => $canTruncate ? 'delete_hot_journal_fence_after_release' : 'preserve_hot_journal_release_fence',
                        'cache_action' => $canTruncate ? 'evict_released_checkpoint_page_cache' : 'hold_checkpoint_page_cache_for_open_readers',
                        'release_digest' => hash('sha256', json_encode([$sourceToken, $nextSourceGeneration, $expectedReaderNames, $rows, $guards], JSON_THROW_ON_ERROR)),
                        'operation_names' => array_values(array_unique(array_merge(
                            is_array($readerAdmissionPlan['operation_names'] ?? null) ? $readerAdmissionPlan['operation_names'] : [],
                            [
                                'verify_reopened_reader_release_current_source_next248',
                                $canTruncate ? 'truncate_checkpoint_wal_current_source_next248' : 'block_checkpoint_wal_truncation_current_source_next248',
                            ]
                        ))),
                        'dependencies' => array_values(array_unique(array_merge(
                            is_array($readerAdmissionPlan['dependencies'] ?? null) ? $readerAdmissionPlan['dependencies'] : [],
                            [
                                'sqlite-wal-hot-journal-savepoint-checkpoint-current-source-next248',
                                'sqlite-wal-reopened-reader-release-current-source',
                                'wordpress-import-reader-release-before-wal-truncate',
                            ]
                        ))),
                        'dependency_closure' => 'no new support component needed; reuses next245 reopened-reader admission metadata with native PHP release receipts, page-cache coverage, WAL frame, lock, hot-journal, and savepoint fences',
                        'non_overlap' => 'next248 gates checkpoint WAL truncation after admitted reopened readers release; it does not repeat next245 reopened-reader admission, writer commit receipt validation, WAL byte truncation, VFS savepoint rollback apply, rollback-journal commit/apply, checkpoint transaction planning, or reader checkpoint snapshots',
                    ];
                }

                /**
                 * @param array<string,mixed> $receipt
                 * @param list<string> $expectedReaderNames
                 * @param list<int> $coveredPages
                 * @return array<string,mixed>
                 */
                private static function releaseRow(
                    array $receipt,
                    string $databasePath,
                    string $walPath,
                    string $journalPath,
                    string $sourceToken,
                    int $writerGeneration,
                    int $nextSourceGeneration,
                    string $databaseDigest,
                    array $expectedReaderNames,
                    array $coveredPages
                ): array {
                    $name = self::token($receipt['name'] ?? null, 'release reader name');
                    $reasons = [];

                    if (!in_array($name, $expectedReaderNames, true)) {
                        $reasons[] = 'reader_release_not_expected';
                    }
                    if (self::path($receipt['database_path'] ?? null, "{$name} database path") !== $databasePath) {
                        $reasons[] = 'reader_release_database_path_mismatch';
                    }
                    if (self::path($receipt['wal_path'] ?? null, "{$name} wal path") !== $walPath) {
                        $reasons[] = 'reader_release_wal_path_mismatch';
                    }
                    if (self::path($receipt['journal_path'] ?? null, "{$name} journal path") !== $journalPath) {
                        $reasons[] = 'reader_release_journal_path_mismatch';
                    }
                    if (self::token($receipt['source_token'] ?? null, "{$name} source token") !== $sourceToken) {
                        $reasons[] = 'reader_release_source_token_mismatch';
                    }
                    if (self::positiveInt($receipt['writer_generation'] ?? null, "{$name} writer generation") !== $writerGeneration) {
                        $reasons[] = 'reader_release_writer_generation_mismatch';
                    }
                    if (self::positiveInt($receipt['reader_generation'] ?? null, "{$name} reader generation") < $nextSourceGeneration) {
                        $reasons[] = 'reader_release_generation_stale';
                    }
                    if (self::digest($receipt['database_digest'] ?? null, "{$name} database digest") !== $databaseDigest) {
                        $reasons[] = 'reader_release_database_digest_mismatch';
                    }

                    $lastVisibleFrame = self::nonNegativeInt($receipt['last_visible_frame'] ?? null, "{$name} last visible frame");
                    $releaseFrame = self::nonNegativeInt($receipt['release_frame'] ?? null, "{$name} release frame");
                    if ($releaseFrame < $lastVisibleFrame) {
                        $reasons[] = 'reader_release_frame_before_visible_frame';
                    }
                    if ($releaseFrame > $writerGeneration) {
                        $reasons[] = 'reader_release_frame_past_writer_generation';
                    }

                    $pageNumbers = self::positiveIntList($receipt['page_numbers'] ?? null, "{$name} page numbers");
                    foreach ($pageNumbers as $pageNumber) {
                        if (!in_array($pageNumber, $coveredPages, true)) {
                            $reasons[] = 'reader_release_page_not_checkpoint_covered';
                        }
                    }

                    if (($receipt['snapshot_closed'] ?? false) !== true) {
                        $reasons[] = 'reader_release_snapshot_still_open';
                    }
                    if (($receipt['page_cache_clean'] ?? false) !== true) {
                        $reasons[] = 'reader_release_page_cache_dirty';
                    }
                    if (($receipt['shared_lock_released'] ?? false) !== true) {
                        $reasons[] = 'reader_release_shared_lock_held';
                    }
                    if (($receipt['reserved_lock_held'] ?? false) === true) {
                        $reasons[] = 'reader_release_reserved_lock_held';
                    }
                    if (($receipt['hot_journal_visible'] ?? false) === true) {
                        $reasons[] = 'reader_release_hot_journal_visible';
                    }
                    if (($receipt['savepoint_depth'] ?? 0) !== 0) {
                        $reasons[] = 'reader_release_savepoint_scope_open';
                    }

                    $reasons = array_values(array_unique($reasons));

                    return [
                        'name' => $name,
                        'database_path' => (string) $receipt['database_path'],
                        'wal_path' => (string) $receipt['wal_path'],
                        'journal_path' => (string) $receipt['journal_path'],
                        'source_token' => (string) $receipt['source_token'],
                        'writer_generation' => (int) $receipt['writer_generation'],
                        'reader_generation' => (int) $receipt['reader_generation'],
                        'database_digest' => (string) $receipt['database_digest'],
                        'last_visible_frame' => $lastVisibleFrame,
                        'release_frame' => $releaseFrame,
                        'page_numbers' => $pageNumbers,
                        'snapshot_closed' => ($receipt['snapshot_closed'] ?? false) === true,
                        'page_cache_clean' => ($receipt['page_cache_clean'] ?? false) === true,
                        'shared_lock_released' => ($receipt['shared_lock_released'] ?? false) === true,
                        'reserved_lock_held' => ($receipt['reserved_lock_held'] ?? false) === true,
                        'hot_journal_visible' => ($receipt['hot_journal_visible'] ?? false) === true,
                        'savepoint_depth' => (int) ($receipt['savepoint_depth'] ?? 0),
                        'source_token_match' => !in_array('reader_release_source_token_mismatch', $reasons, true),
                        'database_digest_match' => !in_array('reader_release_database_digest_mismatch', $reasons, true),
                        'generation_safe' => !in_array('reader_release_generation_stale', $reasons, true),
                        'page_cache_covered' => !in_array('reader_release_page_not_checkpoint_covered', $reasons, true)
                            && !in_array('reader_release_page_cache_dirty', $reasons, true),
                        'fences_clear' => !in_array('reader_release_snapshot_still_open', $reasons, true)
                            && !in_array('reader_release_shared_lock_held', $reasons, true)
                            && !in_array('reader_release_reserved_lock_held', $reasons, true)
                            && !in_array('reader_release_hot_journal_visible', $reasons, true)
                            && !in_array('reader_release_savepoint_scope_open', $reasons, true),
                        'released' => $reasons === [],
                        'release_reason' => $reasons === [] ? 'reader_release_current' : implode('|', $reasons),
                        'blocked_reasons' => $reasons,
                    ];
                }

                /** @param list<array<string,mixed>> $rows */
                private static function allRowsHave(array $rows, string $field): bool
                {
                    foreach ($rows as $row) {
                        if (($row[$field] ?? false) !== true) {
                            return false;
                        }
                    }

                    return $rows !== [];
                }

                private static function positiveInt(mixed $value, string $label): int
                {
                    if (!is_int($value) || $value <= 0) {
                        throw new \InvalidArgumentException("SQLite WAL hot-journal savepoint checkpoint current-source next248 {$label} must be positive");
                    }

                    return $value;
                }

                private static function nonNegativeInt(mixed $value, string $label): int
                {
                    if (!is_int($value) || $value < 0) {
                        throw new \InvalidArgumentException("SQLite WAL hot-journal savepoint checkpoint current-source next248 {$label} must be non-negative");
                    }

                    return $value;
                }

                private static function token(mixed $value, string $label): string
                {
                    if (!is_string($value) || !preg_match('/^[A-Za-z0-9_.:-]+$/', $value)) {
                        throw new \InvalidArgumentException("SQLite WAL hot-journal savepoint checkpoint current-source next248 {$label} is invalid");
                    }

                    return $value;
                }

                /**
                 * @param mixed $values
                 * @return list<string>
                 */
                private static function tokenList(mixed $values, string $label): array
                {
                    if (!is_array($values) || $values === []) {
                        throw new \InvalidArgumentException("SQLite WAL hot-journal savepoint checkpoint current-source next248 requires {$label}");
                    }
                    $out = [];
                    foreach ($values as $value) {
                        $out[] = self::token($value, $label);
                    }
                    $out = array_values(array_unique($out));
                    sort($out);

                    return $out;
                }

                private static function path(mixed $value, string $label): string
                {
                    if (!is_string($value) || $value === '') {
                        throw new \InvalidArgumentException("SQLite WAL hot-journal savepoint checkpoint current-source next248 {$label} is required");
                    }

                    return $value;
                }

                private static function digest(mixed $value, string $label): string
                {
                    if (!is_string($value) || preg_match('/^[a-f0-9]{64}$/', $value) !== 1) {
                        throw new \InvalidArgumentException("SQLite WAL hot-journal savepoint checkpoint current-source next248 requires {$label}");
                    }

                    return $value;
                }

                /**
                 * @param mixed $values
                 * @return list<int>
                 */
                private static function positiveIntList(mixed $values, string $label): array
                {
                    if (!is_array($values) || $values === []) {
                        throw new \InvalidArgumentException("SQLite WAL hot-journal savepoint checkpoint current-source next248 requires {$label}");
                    }
                    $out = [];
                    foreach ($values as $value) {
                        if (!is_int($value) || $value <= 0) {
                            throw new \InvalidArgumentException("SQLite WAL hot-journal savepoint checkpoint current-source next248 {$label} must contain positive integers");
                        }
                        $out[] = $value;
                    }
                    $out = array_values(array_unique($out));
                    sort($out);

                    return $out;
                }

                /**
                 * @param list<string> $values
                 * @return list<string>
                 */
                private static function duplicates(array $values): array
                {
                    $seen = [];
                    $dupes = [];
                    foreach ($values as $value) {
                        if (isset($seen[$value])) {
                            $dupes[$value] = true;
                        }
                        $seen[$value] = true;
                    }

                    return array_keys($dupes);
                }
        };

        return $impl::planCheckpointTruncation($readerAdmissionPlan, $releaseReceipts);
    }

    public static function next249VerifyReopenedCurrentSource(array $handoffPlan, array $reopenedState): array
    {
        $impl = new class {
                /**
                 * @param array<string,mixed> $handoffPlan
                 * @param array<string,mixed> $reopenedState
                 * @return array<string,mixed>
                 */
                public static function verifyReopenedCurrentSource(array $handoffPlan, array $reopenedState): array
                {
                    if (($handoffPlan['status'] ?? null) !== 'wal-hot-journal-savepoint-checkpoint-current-source-next246'
                        || ($handoffPlan['durable_handoff_admitted'] ?? null) !== true
                    ) {
                        throw new \InvalidArgumentException('SQLite WAL hot-journal savepoint checkpoint current-source next249 requires an admitted next246 durable handoff');
                    }

                    $databasePath = self::path($handoffPlan['database_path'] ?? null, 'database path');
                    $walPath = self::path($handoffPlan['wal_path'] ?? null, 'wal path');
                    $journalPath = self::path($handoffPlan['journal_path'] ?? null, 'journal path');
                    $sourceToken = self::token($handoffPlan['source_token'] ?? null, 'source token');
                    $commitGeneration = self::positiveInt($handoffPlan['commit_generation'] ?? null, 'commit generation');
                    $schemaCookie = self::positiveInt($handoffPlan['schema_cookie'] ?? null, 'schema cookie');
                    $databaseDigest = self::digest($handoffPlan['database_digest'] ?? null, 'database digest');
                    $pageCacheDigest = self::digest($handoffPlan['page_cache_digest'] ?? null, 'page cache digest');
                    $checkpointFrame = self::nonNegativeInt($handoffPlan['checkpoint_frame'] ?? null, 'checkpoint frame');
                    $dirtyPages = self::positiveIntSet($handoffPlan['dirty_pages'] ?? null, 'dirty pages');
                    $commitFrames = self::positiveIntSet($handoffPlan['commit_frames'] ?? null, 'commit frames');
                    $readerNames = self::tokenSet($handoffPlan['accepted_reader_names'] ?? null, 'accepted reader names');

                    $observedDatabaseDigest = self::digest($reopenedState['database_digest'] ?? null, 'reopened database digest');
                    $observedPageCacheDigest = self::digest($reopenedState['page_cache_digest'] ?? null, 'reopened page cache digest');
                    $observedCommitFrames = self::positiveIntSet($reopenedState['wal_commit_frames'] ?? null, 'reopened WAL commit frames');
                    $observedCleanPages = self::positiveIntSet($reopenedState['clean_page_numbers'] ?? null, 'reopened clean page numbers');
                    $readerRows = [];
                    foreach (self::readerStates($reopenedState['reader_states'] ?? null) as $readerState) {
                        $readerRows[] = self::readerRow($readerState, $readerNames, $sourceToken, $commitGeneration, $checkpointFrame);
                    }
                    $observedReaderNames = array_values(array_unique(array_column($readerRows, 'name')));
                    $missingReaderNames = array_values(array_diff($readerNames, $observedReaderNames));

                    $missingFrames = array_values(array_diff($commitFrames, $observedCommitFrames));
                    $extraFrames = array_values(array_diff($observedCommitFrames, $commitFrames));
                    $missingCleanPages = array_values(array_diff($dirtyPages, $observedCleanPages));
                    $blockedReaderRows = array_values(array_filter($readerRows, static fn (array $row): bool => !$row['admitted']));

                    $databaseMatches = hash_equals($databaseDigest, $observedDatabaseDigest);
                    $pageCacheMatches = hash_equals($pageCacheDigest, $observedPageCacheDigest);
                    $journalRetired = ($reopenedState['journal_exists'] ?? null) === false;
                    $walRetained = ($reopenedState['wal_exists'] ?? null) === true;
                    $schemaCookieMatches = ($reopenedState['schema_cookie'] ?? null) === $schemaCookie;
                    $generationMatches = ($reopenedState['commit_generation'] ?? null) === $commitGeneration;
                    $sourceMatches = self::token($reopenedState['source_token'] ?? null, 'reopened source token') === $sourceToken;
                    $pathsMatch = self::path($reopenedState['database_path'] ?? null, 'reopened database path') === $databasePath
                        && self::path($reopenedState['wal_path'] ?? null, 'reopened WAL path') === $walPath
                        && self::path($reopenedState['journal_path'] ?? null, 'reopened journal path') === $journalPath;

                    $guardRows = [
                        [
                            'name' => 'database_digest_matches_handoff',
                            'matched' => $databaseMatches,
                            'reason' => 'reopened database bytes must be the durable checkpoint image promoted by next246',
                        ],
                        [
                            'name' => 'page_cache_digest_matches_handoff',
                            'matched' => $pageCacheMatches,
                            'reason' => 'clean page cache must be derived from the same checkpoint image',
                        ],
                        [
                            'name' => 'wal_commit_frames_match_handoff',
                            'matched' => $missingFrames === [] && $extraFrames === [],
                            'reason' => 'the reopened WAL must expose exactly the committed frames kept for reader continuity',
                        ],
                        [
                            'name' => 'dirty_pages_clean_after_reopen',
                            'matched' => $missingCleanPages === [],
                            'reason' => 'every dirty page written by the checkpoint handoff must reopen as clean',
                        ],
                        [
                            'name' => 'hot_journal_retired_after_reopen',
                            'matched' => $journalRetired,
                            'reason' => 'the hot journal must be gone after checkpoint bytes and directory sync are durable',
                        ],
                        [
                            'name' => 'wal_sidecar_retained_for_reader_epoch',
                            'matched' => $walRetained,
                            'reason' => 'next246 retains committed WAL frames until reader epochs advance',
                        ],
                        [
                            'name' => 'schema_cookie_generation_and_source_match',
                            'matched' => $schemaCookieMatches && $generationMatches && $sourceMatches && $pathsMatch,
                            'reason' => 'reopened metadata must still point at the admitted current source',
                        ],
                        [
                            'name' => 'all_readers_reopened_on_current_source',
                            'matched' => $blockedReaderRows === [] && $missingReaderNames === [],
                            'reason' => 'reader snapshots must reopen on the same source token, generation, and checkpoint frame',
                        ],
                    ];
                    $blockedGuards = array_values(array_column(
                        array_filter($guardRows, static fn (array $row): bool => !$row['matched']),
                        'name'
                    ));
                    $admitted = $blockedGuards === [];

                    $blockedReasons = [];
                    if (!$databaseMatches) {
                        $blockedReasons[] = 'reopened_database_digest_mismatch';
                    }
                    if (!$pageCacheMatches) {
                        $blockedReasons[] = 'reopened_page_cache_digest_mismatch';
                    }
                    if ($missingFrames !== []) {
                        $blockedReasons[] = 'reopened_wal_commit_frame_missing';
                    }
                    if ($extraFrames !== []) {
                        $blockedReasons[] = 'reopened_wal_commit_frame_unexpected';
                    }
                    if ($missingCleanPages !== []) {
                        $blockedReasons[] = 'reopened_dirty_page_not_clean';
                    }
                    if (!$journalRetired) {
                        $blockedReasons[] = 'reopened_hot_journal_still_exists';
                    }
                    if (!$walRetained) {
                        $blockedReasons[] = 'reopened_wal_sidecar_missing';
                    }
                    if (!$schemaCookieMatches) {
                        $blockedReasons[] = 'reopened_schema_cookie_mismatch';
                    }
                    if (!$generationMatches) {
                        $blockedReasons[] = 'reopened_commit_generation_mismatch';
                    }
                    if (!$sourceMatches) {
                        $blockedReasons[] = 'reopened_source_token_mismatch';
                    }
                    if (!$pathsMatch) {
                        $blockedReasons[] = 'reopened_path_mismatch';
                    }
                    if ($missingReaderNames !== []) {
                        $blockedReasons[] = 'reopened_reader_missing';
                    }
                    foreach ($blockedReaderRows as $row) {
                        foreach ($row['blocked_reasons'] as $reason) {
                            $blockedReasons[] = $reason;
                        }
                    }
                    $blockedReasons = array_values(array_unique($blockedReasons));

                    return [
                        'status' => $admitted
                            ? 'wal-hot-journal-savepoint-checkpoint-current-source-next249'
                            : 'wal-hot-journal-savepoint-checkpoint-current-source-blocked-next249',
                        'reason' => $admitted
                            ? 'reopened_files_confirm_durable_checkpoint_current_source'
                            : 'reopened_files_hold_prior_checkpoint_current_source',
                        'base_status' => $handoffPlan['status'],
                        'database_path' => $databasePath,
                        'wal_path' => $walPath,
                        'journal_path' => $journalPath,
                        'source_token' => $sourceToken,
                        'commit_generation' => $commitGeneration,
                        'schema_cookie' => $schemaCookie,
                        'checkpoint_frame' => $checkpointFrame,
                        'database_digest' => $databaseDigest,
                        'page_cache_digest' => $pageCacheDigest,
                        'observed_database_digest' => $observedDatabaseDigest,
                        'observed_page_cache_digest' => $observedPageCacheDigest,
                        'dirty_pages' => $dirtyPages,
                        'clean_page_numbers' => $observedCleanPages,
                        'missing_clean_pages' => $missingCleanPages,
                        'expected_commit_frames' => $commitFrames,
                        'observed_commit_frames' => $observedCommitFrames,
                        'missing_commit_frames' => $missingFrames,
                        'unexpected_commit_frames' => $extraFrames,
                        'reader_rows' => $readerRows,
                        'expected_reader_names' => $readerNames,
                        'missing_reader_names' => $missingReaderNames,
                        'accepted_reader_names' => array_values(array_column(
                            array_filter($readerRows, static fn (array $row): bool => $row['admitted']),
                            'name'
                        )),
                        'blocked_reader_names' => array_values(array_column($blockedReaderRows, 'name')),
                        'journal_exists_after_reopen' => $reopenedState['journal_exists'],
                        'wal_exists_after_reopen' => $reopenedState['wal_exists'],
                        'blocked_reasons' => $blockedReasons,
                        'reopened_current_source_admitted' => $admitted,
                        'checkpoint_action' => $admitted ? 'serve_checkpoint_database_as_current_source' : 'retain_prior_current_source_until_reopen_matches',
                        'wal_action' => $admitted ? 'keep_wal_sidecar_until_reader_epoch_advances' : 'preserve_wal_for_recovery_replay',
                        'journal_action' => $admitted ? 'confirm_hot_journal_retired' : 'treat_hot_journal_as_recovery_blocker',
                        'reader_action' => $admitted ? 'serve_reopened_readers_from_generation_' . $commitGeneration : 'hold_readers_on_prior_generation',
                        'guard_rows' => $guardRows,
                        'guard_names' => array_column($guardRows, 'name'),
                        'guard_matches' => array_column($guardRows, 'matched'),
                        'blocked_guard_names' => $blockedGuards,
                        'reopen_digest' => hash('sha256', json_encode([$sourceToken, $commitGeneration, $databaseDigest, $pageCacheDigest, $observedCommitFrames, $observedCleanPages, $readerRows, $guardRows], JSON_THROW_ON_ERROR)),
                        'operation_names' => array_values(array_unique(array_merge(
                            is_array($handoffPlan['operation_names'] ?? null) ? $handoffPlan['operation_names'] : [],
                            [
                                'verify_reopened_current_source_after_durable_handoff_next249',
                                $admitted ? 'admit_reopened_current_source_next249' : 'hold_reopened_current_source_next249',
                            ]
                        ))),
                        'dependencies' => array_values(array_unique(array_merge(
                            is_array($handoffPlan['dependencies'] ?? null) ? $handoffPlan['dependencies'] : [],
                            [
                                'sqlite-wal-hot-journal-savepoint-checkpoint-current-source-next249',
                                'sqlite-wal-reopen-current-source-after-durable-handoff',
                                'wordpress-import-reopen-after-hot-journal-checkpoint',
                            ]
                        ))),
                        'dependency_closure' => 'no new support component needed; reuses next246 durable handoff metadata, reopened file digests, WAL commit-frame inventory, clean page-cache inventory, and reader epoch rows',
                        'non_overlap' => 'next249 verifies reopened current-source visibility after an accepted next246 durable handoff; it does not repeat VFS receipt ordering, checkpoint transaction planning, WAL byte truncation, savepoint rollback application, rollback-journal commit/apply, reader snapshot admission, JSON, SELECT, or B-tree behavior',
                    ];
                }

                /**
                 * @param list<string> $readerNames
                 * @return array<string,mixed>
                 */
                private static function readerRow(array $readerState, array $readerNames, string $sourceToken, int $commitGeneration, int $checkpointFrame): array
                {
                    $name = self::token($readerState['name'] ?? null, 'reader name');
                    $reasons = [];

                    if (!in_array($name, $readerNames, true)) {
                        $reasons[] = 'reopened_reader_unexpected';
                    }
                    if (self::token($readerState['source_token'] ?? null, "{$name} source token") !== $sourceToken) {
                        $reasons[] = 'reopened_reader_source_token_mismatch';
                    }
                    if (self::positiveInt($readerState['reader_generation'] ?? null, "{$name} reader generation") !== $commitGeneration) {
                        $reasons[] = 'reopened_reader_generation_mismatch';
                    }
                    if (self::nonNegativeInt($readerState['checkpoint_frame'] ?? null, "{$name} checkpoint frame") !== $checkpointFrame) {
                        $reasons[] = 'reopened_reader_checkpoint_frame_mismatch';
                    }
                    if (($readerState['snapshot_reopened'] ?? null) !== true) {
                        $reasons[] = 'reopened_reader_snapshot_not_reopened';
                    }
                    if (($readerState['readmark_cleared'] ?? null) !== true) {
                        $reasons[] = 'reopened_reader_readmark_not_cleared';
                    }

                    return [
                        'name' => $name,
                        'source_token' => $readerState['source_token'],
                        'reader_generation' => $readerState['reader_generation'],
                        'checkpoint_frame' => $readerState['checkpoint_frame'],
                        'snapshot_reopened' => $readerState['snapshot_reopened'] ?? null,
                        'readmark_cleared' => $readerState['readmark_cleared'] ?? null,
                        'admitted' => $reasons === [],
                        'blocked_reasons' => array_values(array_unique($reasons)),
                        'reader_reason' => $reasons === [] ? 'reader_reopened_on_checkpoint_current_source' : 'reader_blocks_reopened_checkpoint_current_source',
                    ];
                }

                private static function path(mixed $value, string $label): string
                {
                    if (!is_string($value) || $value === '') {
                        throw new \InvalidArgumentException("Invalid {$label}");
                    }
                    return $value;
                }

                private static function token(mixed $value, string $label): string
                {
                    if (!is_string($value) || !preg_match('/^[a-z0-9][a-z0-9._:-]*$/i', $value)) {
                        throw new \InvalidArgumentException("Invalid {$label}");
                    }
                    return $value;
                }

                /** @return list<string> */
                private static function tokenSet(mixed $value, string $label): array
                {
                    if (!is_array($value) || $value === []) {
                        throw new \InvalidArgumentException("Invalid {$label}");
                    }
                    $tokens = [];
                    foreach ($value as $item) {
                        $tokens[] = self::token($item, $label);
                    }
                    return array_values(array_unique($tokens));
                }

                private static function digest(mixed $value, string $label): string
                {
                    if (!is_string($value) || !preg_match('/^[a-f0-9]{64}$/', $value)) {
                        throw new \InvalidArgumentException("Invalid {$label}");
                    }
                    return $value;
                }

                private static function positiveInt(mixed $value, string $label): int
                {
                    if (!is_int($value) || $value < 1) {
                        throw new \InvalidArgumentException("Invalid {$label}");
                    }
                    return $value;
                }

                private static function nonNegativeInt(mixed $value, string $label): int
                {
                    if (!is_int($value) || $value < 0) {
                        throw new \InvalidArgumentException("Invalid {$label}");
                    }
                    return $value;
                }

                /** @return list<int> */
                private static function positiveIntSet(mixed $value, string $label): array
                {
                    if (!is_array($value) || $value === []) {
                        throw new \InvalidArgumentException("Invalid {$label}");
                    }
                    $set = [];
                    foreach ($value as $item) {
                        if (!is_int($item) || $item < 1) {
                            throw new \InvalidArgumentException("Invalid {$label}");
                        }
                        $set[$item] = true;
                    }
                    $values = array_map('intval', array_keys($set));
                    sort($values);
                    return $values;
                }

                /** @return list<array<string,mixed>> */
                private static function readerStates(mixed $value): array
                {
                    if (!is_array($value) || $value === []) {
                        throw new \InvalidArgumentException('Invalid reader states');
                    }
                    $rows = [];
                    foreach ($value as $row) {
                        if (!is_array($row)) {
                            throw new \InvalidArgumentException('Invalid reader states');
                        }
                        $rows[] = $row;
                    }
                    return $rows;
                }
        };

        return $impl::verifyReopenedCurrentSource($handoffPlan, $reopenedState);
    }

    public static function next250AdmitCacheInvalidation(array $cleanupPlan, array $cacheReceipts): array
    {
        $impl = new class {
                /**
                 * @param array<string,mixed> $cleanupPlan
                 * @param list<array<string,mixed>> $cacheReceipts
                 * @return array<string,mixed>
                 */
                public static function admitCacheInvalidation(array $cleanupPlan, array $cacheReceipts): array
                {
                    if (($cleanupPlan['status'] ?? null) !== 'wal-hot-journal-savepoint-checkpoint-current-source-next247'
                        || ($cleanupPlan['cleanup_admitted'] ?? null) !== true
                    ) {
                        throw new \InvalidArgumentException('SQLite WAL hot-journal savepoint checkpoint current-source next250 requires an admitted next247 cleanup plan');
                    }
                    if ($cacheReceipts === []) {
                        throw new \InvalidArgumentException('SQLite WAL hot-journal savepoint checkpoint current-source next250 requires cache invalidation receipts');
                    }

                    $databasePath = self::path($cleanupPlan['database_path'] ?? null, 'database path');
                    $walPath = self::path($cleanupPlan['wal_path'] ?? null, 'wal path');
                    $journalPath = self::path($cleanupPlan['journal_path'] ?? null, 'journal path');
                    $sourceToken = self::token($cleanupPlan['source_token'] ?? null, 'source token');
                    $commitGeneration = self::positiveInt($cleanupPlan['commit_generation'] ?? null, 'commit generation');
                    $schemaCookie = self::positiveInt($cleanupPlan['schema_cookie'] ?? null, 'schema cookie');
                    $databaseDigest = self::digest($cleanupPlan['database_digest'] ?? null, 'database digest');
                    $pageCacheDigest = self::digest($cleanupPlan['page_cache_digest'] ?? null, 'page cache digest');
                    $walIndexSalt = self::saltPair($cleanupPlan['wal_index_salt'] ?? null, 'wal index salt');
                    $walIndexMxFrame = self::nonNegativeInt($cleanupPlan['wal_index_mx_frame'] ?? null, 'wal index mx frame');
                    $checkpointFrame = self::nonNegativeInt($cleanupPlan['checkpoint_frame'] ?? null, 'checkpoint frame');
                    $dirtyPages = self::positiveIntSet($cleanupPlan['dirty_pages'] ?? null, 'dirty pages');
                    $commitFrames = self::positiveIntSet($cleanupPlan['commit_frames'] ?? null, 'commit frames');
                    $readerNames = self::tokenList($cleanupPlan['reader_names'] ?? null, 'reader names');

                    $rows = [];
                    foreach ($cacheReceipts as $receipt) {
                        $rows[] = self::cacheRow(
                            $receipt,
                            $databasePath,
                            $walPath,
                            $journalPath,
                            $sourceToken,
                            $commitGeneration,
                            $schemaCookie,
                            $databaseDigest,
                            $pageCacheDigest,
                            $walIndexSalt,
                            $walIndexMxFrame,
                            $checkpointFrame,
                            $dirtyPages,
                            $commitFrames,
                            $readerNames
                        );
                    }

                    $requiredKinds = ['cache-invalidate', 'readmark-clear', 'schema-cookie-refresh', 'wal-index-refresh'];
                    $kinds = array_values(array_unique(array_column($rows, 'kind')));
                    sort($kinds);
                    $missingKinds = array_values(array_diff($requiredKinds, $kinds));
                    $duplicateNames = self::duplicates(array_column($rows, 'name'));
                    $blockedRows = array_values(array_filter($rows, static fn (array $row): bool => !$row['accepted']));

                    $coveredReaders = [];
                    $coveredPages = [];
                    $coveredFrames = [];
                    foreach ($rows as $row) {
                        if (!$row['accepted']) {
                            continue;
                        }
                        foreach ($row['reader_names'] as $readerName) {
                            $coveredReaders[$readerName] = true;
                        }
                        foreach ($row['page_numbers'] as $pageNumber) {
                            $coveredPages[$pageNumber] = true;
                        }
                        foreach ($row['commit_frames'] as $frameNumber) {
                            $coveredFrames[$frameNumber] = true;
                        }
                    }
                    $coveredReaders = array_keys($coveredReaders);
                    sort($coveredReaders);
                    $coveredPages = array_map('intval', array_keys($coveredPages));
                    sort($coveredPages);
                    $coveredFrames = array_map('intval', array_keys($coveredFrames));
                    sort($coveredFrames);
                    $missingReaders = array_values(array_diff($readerNames, $coveredReaders));
                    $missingPages = array_values(array_diff($dirtyPages, $coveredPages));
                    $missingFrames = array_values(array_diff($commitFrames, $coveredFrames));

                    $blockedReasons = [];
                    foreach ($blockedRows as $row) {
                        foreach ($row['blocked_reasons'] as $reason) {
                            $blockedReasons[] = $reason;
                        }
                    }
                    if ($missingKinds !== []) {
                        $blockedReasons[] = 'cache_invalidation_kind_missing';
                    }
                    if ($duplicateNames !== []) {
                        $blockedReasons[] = 'cache_invalidation_name_duplicate';
                    }
                    if ($missingReaders !== []) {
                        $blockedReasons[] = 'cache_reader_invalidation_missing';
                    }
                    if ($missingPages !== []) {
                        $blockedReasons[] = 'cache_dirty_page_invalidation_missing';
                    }
                    if ($missingFrames !== []) {
                        $blockedReasons[] = 'cache_commit_frame_invalidation_missing';
                    }
                    $blockedReasons = array_values(array_unique($blockedReasons));

                    $guardRows = [
                        [
                            'name' => 'next247_cleanup_admitted',
                            'matched' => true,
                            'reason' => 'post-checkpoint hot-journal cleanup has already been admitted',
                        ],
                        [
                            'name' => 'cache_invalidation_receipt_names_unique',
                            'matched' => $duplicateNames === [],
                            'reason' => 'each cache invalidation receipt must be attributable once',
                        ],
                        [
                            'name' => 'required_cache_invalidation_kinds_present',
                            'matched' => $missingKinds === [],
                            'reason' => 'page-cache invalidation, readmark clear, schema-cookie refresh, and WAL-index refresh receipts are required',
                        ],
                        [
                            'name' => 'all_readers_reopened_after_cache_invalidation',
                            'matched' => $missingReaders === [],
                            'reason' => 'every admitted reader must reopen after stale cache and readmark state is cleared',
                        ],
                        [
                            'name' => 'all_dirty_pages_removed_from_stale_cache',
                            'matched' => $missingPages === [],
                            'reason' => 'every dirty checkpoint page must be removed from stale page-cache entries',
                        ],
                        [
                            'name' => 'all_commit_frames_removed_from_stale_readmarks',
                            'matched' => $missingFrames === [],
                            'reason' => 'every committed WAL frame must be covered by a readmark or WAL-index refresh receipt',
                        ],
                        [
                            'name' => 'all_cache_receipts_match_current_source',
                            'matched' => $blockedRows === [],
                            'reason' => 'cache receipts must match source token, generation, cookie, WAL-index, digests, closed savepoint state, and stale sidecar visibility',
                        ],
                    ];
                    $blockedGuards = array_values(array_column(
                        array_filter($guardRows, static fn (array $row): bool => !$row['matched']),
                        'name'
                    ));
                    $admitted = $blockedGuards === [];

                    return [
                        'status' => $admitted
                            ? 'wal-hot-journal-savepoint-checkpoint-current-source-next250'
                            : 'wal-hot-journal-savepoint-checkpoint-current-source-blocked-next250',
                        'reason' => $admitted
                            ? 'checkpoint_current_source_cache_invalidation_admitted'
                            : 'checkpoint_current_source_cache_invalidation_held',
                        'base_status' => $cleanupPlan['status'],
                        'database_path' => $databasePath,
                        'wal_path' => $walPath,
                        'journal_path' => $journalPath,
                        'source_token' => $sourceToken,
                        'commit_generation' => $commitGeneration,
                        'schema_cookie' => $schemaCookie,
                        'database_digest' => $databaseDigest,
                        'page_cache_digest' => $pageCacheDigest,
                        'wal_index_salt' => $walIndexSalt,
                        'wal_index_mx_frame' => $walIndexMxFrame,
                        'checkpoint_frame' => $checkpointFrame,
                        'dirty_pages' => $dirtyPages,
                        'commit_frames' => $commitFrames,
                        'reader_names' => $readerNames,
                        'receipt_rows' => $rows,
                        'receipt_names' => array_values(array_column($rows, 'name')),
                        'receipt_kinds' => $kinds,
                        'required_receipt_kinds' => $requiredKinds,
                        'missing_receipt_kinds' => $missingKinds,
                        'duplicate_receipt_names' => $duplicateNames,
                        'accepted_receipt_names' => array_values(array_column(array_filter($rows, static fn (array $row): bool => $row['accepted']), 'name')),
                        'blocked_receipt_names' => array_values(array_column($blockedRows, 'name')),
                        'covered_reader_names' => $coveredReaders,
                        'missing_reader_names' => $missingReaders,
                        'covered_dirty_pages' => $coveredPages,
                        'missing_dirty_pages' => $missingPages,
                        'covered_commit_frames' => $coveredFrames,
                        'missing_commit_frames' => $missingFrames,
                        'blocked_reasons' => $blockedReasons,
                        'guard_rows' => $guardRows,
                        'guard_names' => array_column($guardRows, 'name'),
                        'guard_matches' => array_column($guardRows, 'matched'),
                        'blocked_guard_names' => $blockedGuards,
                        'cache_invalidation_admitted' => $admitted,
                        'cache_action' => $admitted ? 'discard_stale_page_cache_before_current_source_read' : 'retain_prior_cache_until_invalidation_receipts_match',
                        'wal_index_action' => $admitted ? 'refresh_wal_index_header_for_checkpoint_current_source' : 'hold_wal_index_refresh_for_recheck',
                        'reader_action' => $admitted ? 'serve_reopened_readers_from_checkpoint_database_source' : 'force_readers_to_reopen_after_cache_fence',
                        'hot_journal_action' => $admitted ? 'keep_hot_journal_deleted_after_cache_fence' : 'preserve_hot_journal_recovery_until_cache_fence',
                        'cache_digest' => hash('sha256', json_encode([$sourceToken, $commitGeneration, $rows, $guardRows], JSON_THROW_ON_ERROR)),
                        'operation_names' => array_values(array_unique(array_merge(
                            is_array($cleanupPlan['operation_names'] ?? null) ? $cleanupPlan['operation_names'] : [],
                            [
                                'verify_checkpoint_cache_invalidation_next250',
                                $admitted ? 'admit_checkpoint_cache_invalidation_current_source_next250' : 'hold_checkpoint_cache_invalidation_current_source_next250',
                            ]
                        ))),
                        'dependencies' => array_values(array_unique(array_merge(
                            is_array($cleanupPlan['dependencies'] ?? null) ? $cleanupPlan['dependencies'] : [],
                            [
