                    $requiredKinds = ['database-header-cookie', 'reader-generation-reset', 'shm-generation-publish', 'wal-header-publish', 'writer-lock-release'];
                    $acceptedKinds = array_values(array_unique(array_column($acceptedRows, 'kind')));
