                        'exclusive_lock_held_until_release' => ($receipt['exclusive_lock_held_until_release'] ?? false) === true,
                        'writer_lock_released' => ($receipt['writer_lock_released'] ?? false) === true,
                        'durable' => ($receipt['durable'] ?? false) === true,
