        return $impl::admitWriterAfterPostTruncateSeal($sealedPlan, $writerReceipts);
    }

    public static function next260AdmitCurrentSource(array $handoffPlan, array $journalReceipts, array $savepointReceipts, array $checkpointReceipts, array $readerTokens): array
    {
        $impl = new class {
                /**
