                    $readerRows = array_map(
                        static fn (array $receipt): array => self::readerRow($receipt, $sourceToken, $databaseDigest, $pageCacheDigest, $commitGeneration, $schemaCookie, $checkpointFrame, $readerNames),
                        $readerTokens
