                    $guardRows = [
                        ['name' => 'next246_durable_handoff_admitted', 'matched' => true],
                        ['name' => 'hot_journal_deleted_from_current_source', 'matched' => $journalDeleted],
                        ['name' => 'savepoint_retained_prefix_matches_current_source', 'matched' => $missingRetainedFrames === [] && $savepointClosed],
                        ['name' => 'checkpoint_writes_cover_current_dirty_pages', 'matched' => $missingPages === []],
                        ['name' => 'checkpoint_frames_cover_retained_wal_prefix', 'matched' => $missingCheckpointFrames === []],
                        ['name' => 'checkpoint_and_wal_index_synced', 'matched' => $checkpointSynced],
                        ['name' => 'reader_tokens_reopened_on_current_source', 'matched' => $readersReopened],
                        ['name' => 'all_evidence_matches_current_source', 'matched' => $blockedReasons === []],
                    ];
                    $blockedGuards = array_values(array_column(array_filter($guardRows, static fn (array $row): bool => !$row['matched']), 'name'));
                    $admitted = $blockedGuards === [];

                    return [
                        'status' => $admitted
                            ? 'wal-hot-journal-savepoint-checkpoint-current-source-next260'
                            : 'wal-hot-journal-savepoint-checkpoint-current-source-blocked-next260',
                        'reason' => $admitted
                            ? 'hot_journal_savepoint_checkpoint_current_source_admitted'
                            : 'hot_journal_savepoint_checkpoint_current_source_held',
                        'base_status' => $handoffPlan['status'],
                        'database_path' => $handoffPlan['database_path'] ?? null,
                        'journal_path' => $handoffPlan['journal_path'] ?? null,
                        'wal_path' => $handoffPlan['wal_path'] ?? null,
                        'source_token' => $sourceToken,
                        'commit_generation' => $commitGeneration,
                        'schema_cookie' => $schemaCookie,
                        'checkpoint_frame' => $checkpointFrame,
                        'database_digest' => $databaseDigest,
                        'page_cache_digest' => $pageCacheDigest,
                        'dirty_pages' => array_keys($dirtyPages),
                        'commit_frames' => array_keys($commitFrames),
                        'accepted_reader_names' => array_keys($readerNames),
                        'journal_rows' => $journalRows,
                        'savepoint_rows' => $savepointRows,
                        'checkpoint_rows' => $checkpointRows,
                        'reader_rows' => $readerRows,
                        'admitted_journal_names' => self::names($journalRows, true),
                        'blocked_journal_names' => self::names($journalRows, false),
                        'admitted_savepoint_names' => self::names($savepointRows, true),
                        'blocked_savepoint_names' => self::names($savepointRows, false),
                        'admitted_checkpoint_names' => self::names($checkpointRows, true),
                        'blocked_checkpoint_names' => self::names($checkpointRows, false),
                        'admitted_reader_names' => self::names($readerRows, true),
                        'blocked_reader_names' => self::names($readerRows, false),
                        'covered_database_pages' => $coveredPages,
                        'missing_database_pages' => $missingPages,
                        'retained_wal_frames' => $coveredFrames,
                        'missing_retained_wal_frames' => $missingRetainedFrames,
                        'checkpointed_wal_frames' => $checkpointFrames,
                        'missing_checkpointed_wal_frames' => $missingCheckpointFrames,
                        'blocked_reasons' => $blockedReasons,
                        'guard_names' => array_column($guardRows, 'name'),
                        'guard_matches' => array_column($guardRows, 'matched'),
                        'blocked_guard_names' => $blockedGuards,
                        'current_source_admitted' => $admitted,
                        'journal_action' => $admitted ? 'retire_hot_journal_after_delete_receipt' : 'retain_hot_journal_replay_source',
                        'savepoint_action' => $admitted ? 'release_savepoint_prefix_for_checkpoint' : 'keep_savepoint_prefix_replayable',
                        'checkpoint_action' => $admitted ? 'publish_checkpoint_as_current_source' : 'hold_checkpoint_until_source_evidence_matches',
                        'reader_action' => $admitted ? 'advance_reopened_readers_to_generation_' . $commitGeneration : 'pin_readers_to_previous_current_source',
                        'admission_digest' => hash('sha256', json_encode([$sourceToken, $commitGeneration, $journalRows, $savepointRows, $checkpointRows, $readerRows, $blockedGuards], JSON_THROW_ON_ERROR)),
                        'operation_names' => array_values(array_unique(array_merge(
                            is_array($handoffPlan['operation_names'] ?? null) ? $handoffPlan['operation_names'] : [],
                            ['admit_hot_journal_savepoint_checkpoint_current_source_next260']
                        ))),
                        'dependencies' => array_values(array_unique(array_merge(
                            is_array($handoffPlan['dependencies'] ?? null) ? $handoffPlan['dependencies'] : [],
                            [
                                'sqlite-wal-hot-journal-savepoint-checkpoint-current-source-next260',
                                'sqlite-wal-hot-journal-savepoint-checkpoint-source-ordering',
                                'wordpress-import-hot-journal-savepoint-checkpoint-current-source',
                            ]
                        ))),
                        'dependency_closure' => 'no new support component needed; reuses lane-local rollback-journal receipt, savepoint WAL prefix, checkpoint durability, and reader-token evidence',
                        'non_overlap' => 'next260 adds post-next246 source-order admission across rollback-journal, savepoint WAL prefix, checkpoint, and reader tokens; it does not repeat next246 durable VFS handoff, checkpoint transaction planning, WAL byte truncation, rollback-journal commit/apply, or reader snapshot page-map helpers',
                    ];
                }

                /** @param array<string,mixed> $row @param array<int,true> $dirtyPages @return array<string,mixed> */
                private static function journalRow(array $row, string $sourceToken, string $databaseDigest, string $pageCacheDigest, int $commitGeneration, int $schemaCookie, array $dirtyPages): array
                {
                    $name = self::token($row['name'] ?? null, 'journal receipt name');
                    $pages = self::intList($row['recovered_pages'] ?? null, "{$name} recovered pages");
                    $reasons = self::commonReasons($row, $sourceToken, $databaseDigest, $pageCacheDigest, $commitGeneration, $schemaCookie, $name);
                    foreach ($pages as $page) {
                        if (!isset($dirtyPages[$page])) {
                            $reasons[] = 'journal_unexpected_recovered_page';
                            break;
                        }
                    }
                    if (($row['journal_checksum_valid'] ?? false) !== true) {
                        $reasons[] = 'journal_checksum_invalid';
                    }
                    if (($row['hot_journal_deleted'] ?? false) !== true) {
                        $reasons[] = 'hot_journal_delete_missing';
                    }
                    if (($row['directory_sync_done'] ?? false) !== true) {
                        $reasons[] = 'journal_directory_sync_missing';
                    }

                    return self::row($name, $reasons, [
                        'recovered_pages' => $pages,
                        'journal_checksum_valid' => ($row['journal_checksum_valid'] ?? false) === true,
                        'hot_journal_deleted' => ($row['hot_journal_deleted'] ?? false) === true,
                        'directory_sync_done' => ($row['directory_sync_done'] ?? false) === true,
                    ], 'journal_receipt_matches_current_source');
                }

                /** @param array<string,mixed> $row @param array<int,true> $commitFrames @return array<string,mixed> */
                private static function savepointRow(array $row, string $sourceToken, int $commitGeneration, int $checkpointFrame, array $commitFrames): array
                {
                    $name = self::token($row['name'] ?? null, 'savepoint receipt name');
                    $frames = self::intList($row['retained_wal_frames'] ?? null, "{$name} retained WAL frames");
                    $reasons = [];
                    if (!hash_equals($sourceToken, self::token($row['source_token'] ?? null, "{$name} source token"))) {
                        $reasons[] = 'savepoint_source_token_mismatch';
                    }
                    if (($row['commit_generation'] ?? null) !== $commitGeneration) {
                        $reasons[] = 'savepoint_commit_generation_mismatch';
                    }
                    if (($row['checkpoint_frame'] ?? null) !== $checkpointFrame) {
                        $reasons[] = 'savepoint_checkpoint_frame_mismatch';
                    }
                    foreach ($frames as $frame) {
                        if (!isset($commitFrames[$frame])) {
                            $reasons[] = 'savepoint_unexpected_wal_frame';
                            break;
                        }
                    }
                    if (($row['prefix_digest'] ?? '') !== self::prefixDigest(array_keys($commitFrames), $sourceToken, $commitGeneration)) {
                        $reasons[] = 'savepoint_prefix_digest_mismatch';
                    }
                    if (($row['savepoint_scope_closed'] ?? false) !== true) {
                        $reasons[] = 'savepoint_scope_still_open';
                    }

                    return self::row($name, $reasons, [
                        'retained_wal_frames' => $frames,
                        'savepoint_scope_closed' => ($row['savepoint_scope_closed'] ?? false) === true,
                    ], 'savepoint_prefix_matches_current_source');
                }

                /** @param array<string,mixed> $row @param array<int,true> $dirtyPages @param array<int,true> $commitFrames @return array<string,mixed> */
                private static function checkpointRow(array $row, string $sourceToken, string $databaseDigest, string $pageCacheDigest, int $commitGeneration, int $schemaCookie, int $checkpointFrame, array $dirtyPages, array $commitFrames): array
                {
                    $name = self::token($row['name'] ?? null, 'checkpoint receipt name');
                    $pages = self::intList($row['database_pages'] ?? null, "{$name} database pages");
                    $frames = self::intList($row['checkpointed_wal_frames'] ?? null, "{$name} checkpointed WAL frames");
                    $reasons = self::commonReasons($row, $sourceToken, $databaseDigest, $pageCacheDigest, $commitGeneration, $schemaCookie, $name);
                    if (($row['checkpoint_frame'] ?? null) !== $checkpointFrame) {
                        $reasons[] = 'checkpoint_frame_mismatch';
                    }
                    foreach ($pages as $page) {
                        if (!isset($dirtyPages[$page])) {
                            $reasons[] = 'checkpoint_unexpected_database_page';
                            break;
                        }
                    }
                    foreach ($frames as $frame) {
                        if (!isset($commitFrames[$frame])) {
                            $reasons[] = 'checkpoint_unexpected_wal_frame';
                            break;
                        }
                    }
                    if (($row['database_sync_done'] ?? false) !== true) {
                        $reasons[] = 'checkpoint_database_sync_missing';
                    }
                    if (($row['wal_index_sync_done'] ?? false) !== true) {
                        $reasons[] = 'checkpoint_wal_index_sync_missing';
                    }
                    if (($row['exclusive_lock_held'] ?? false) !== true) {
                        $reasons[] = 'checkpoint_exclusive_lock_missing';
                    }

                    return self::row($name, $reasons, [
                        'database_pages' => $pages,
                        'checkpointed_wal_frames' => $frames,
                        'database_sync_done' => ($row['database_sync_done'] ?? false) === true,
                        'wal_index_sync_done' => ($row['wal_index_sync_done'] ?? false) === true,
                        'exclusive_lock_held' => ($row['exclusive_lock_held'] ?? false) === true,
                    ], 'checkpoint_receipt_matches_current_source');
                }

                /** @param array<string,mixed> $row @param array<string,true> $readerNames @return array<string,mixed> */
                private static function readerRow(array $row, string $sourceToken, string $databaseDigest, string $pageCacheDigest, int $commitGeneration, int $schemaCookie, int $checkpointFrame, array $readerNames): array
                {
                    $name = self::token($row['name'] ?? null, 'reader token name');
                    $reasons = self::commonReasons($row, $sourceToken, $databaseDigest, $pageCacheDigest, $commitGeneration, $schemaCookie, $name);
                    if (!isset($readerNames[$name])) {
                        $reasons[] = 'reader_not_in_next246_admitted_set';
                    }
                    if (($row['checkpoint_frame'] ?? null) !== $checkpointFrame) {
                        $reasons[] = 'reader_checkpoint_frame_mismatch';
                    }
                    if (($row['snapshot_reopened'] ?? false) !== true) {
                        $reasons[] = 'reader_snapshot_not_reopened';
                    }
                    if (($row['hot_journal_seen'] ?? false) === true) {
                        $reasons[] = 'reader_still_sees_hot_journal';
                    }

                    return self::row($name, $reasons, [
                        'checkpoint_frame' => $row['checkpoint_frame'] ?? null,
                        'snapshot_reopened' => ($row['snapshot_reopened'] ?? false) === true,
                        'hot_journal_seen' => ($row['hot_journal_seen'] ?? false) === true,
                    ], 'reader_token_matches_current_source');
                }

                /** @param array<string,mixed> $row @return list<string> */
                private static function commonReasons(array $row, string $sourceToken, string $databaseDigest, string $pageCacheDigest, int $commitGeneration, int $schemaCookie, string $name): array
                {
                    $reasons = [];
                    if (!hash_equals($sourceToken, self::token($row['source_token'] ?? null, "{$name} source token"))) {
                        $reasons[] = 'source_token_mismatch';
                    }
                    if (($row['commit_generation'] ?? null) !== $commitGeneration) {
                        $reasons[] = 'commit_generation_mismatch';
                    }
                    if (($row['schema_cookie'] ?? null) !== $schemaCookie) {
                        $reasons[] = 'schema_cookie_mismatch';
                    }
                    if (!hash_equals($databaseDigest, self::digest($row['database_digest'] ?? null, "{$name} database digest"))) {
                        $reasons[] = 'database_digest_mismatch';
                    }
                    if (!hash_equals($pageCacheDigest, self::digest($row['page_cache_digest'] ?? null, "{$name} page cache digest"))) {
                        $reasons[] = 'page_cache_digest_mismatch';
                    }

                    return $reasons;
                }

                /** @param list<string> $reasons @param array<string,mixed> $extra @return array<string,mixed> */
                private static function row(string $name, array $reasons, array $extra, string $okReason): array
                {
                    $reasons = array_values(array_unique($reasons));

                    return array_merge([
                        'name' => $name,
                        'admitted' => $reasons === [],
                        'reason' => $reasons === [] ? $okReason : implode('|', $reasons),
                        'blocked_reasons' => $reasons,
                    ], $extra);
                }

                /** @param mixed $value */
                private static function token($value, string $label): string
                {
                    if (!is_string($value) || !preg_match('/^[A-Za-z0-9_.:-]+$/', $value)) {
                        throw new \InvalidArgumentException("Invalid {$label}");
                    }

                    return $value;
                }

                /** @param mixed $value */
                private static function digest($value, string $label): string
                {
                    if (!is_string($value) || !preg_match('/^[a-f0-9]{64}$/', $value)) {
                        throw new \InvalidArgumentException("Invalid {$label}");
                    }

                    return $value;
                }

                /** @param array<string,mixed> $row */
                private static function positiveInt(array $row, string $key): int
                {
                    if (!isset($row[$key]) || !is_int($row[$key]) || $row[$key] <= 0) {
                        throw new \InvalidArgumentException("Invalid {$key}");
                    }

                    return $row[$key];
                }

                /** @param mixed $value @return array<int,true> */
                private static function intSet($value, string $label): array
                {
                    $set = [];
                    foreach (self::intList($value, $label) as $int) {
                        $set[$int] = true;
                    }

                    return $set;
                }

                /** @param mixed $value @return list<int> */
                private static function intList($value, string $label): array
                {
                    if (!is_array($value) || $value === []) {
                        throw new \InvalidArgumentException("Invalid {$label}");
                    }
                    $list = [];
                    foreach ($value as $item) {
                        if (!is_int($item) || $item <= 0) {
                            throw new \InvalidArgumentException("Invalid {$label}");
                        }
                        $list[] = $item;
                    }
                    $list = array_values(array_unique($list));
                    sort($list);

                    return $list;
                }

                /** @param mixed $value @return array<string,true> */
                private static function tokenSet($value, string $label): array
                {
                    if (!is_array($value) || $value === []) {
                        throw new \InvalidArgumentException("Invalid {$label}");
                    }
                    $set = [];
                    foreach ($value as $item) {
                        $set[self::token($item, $label)] = true;
                    }

                    return $set;
                }

                /** @param list<int> $frames */
                private static function prefixDigest(array $frames, string $sourceToken, int $commitGeneration): string
                {
                    sort($frames);

                    return hash('sha256', json_encode([$sourceToken, $commitGeneration, $frames], JSON_THROW_ON_ERROR));
                }

                /** @param list<array<string,mixed>> $rows @return list<int> */
                private static function coveredInts(array $rows, string $key): array
                {
                    $covered = [];
                    foreach ($rows as $row) {
                        if (!$row['admitted']) {
                            continue;
                        }
                        foreach ($row[$key] as $int) {
                            $covered[$int] = true;
                        }
                    }
                    ksort($covered);

                    return array_keys($covered);
                }

                /** @param list<array<string,mixed>> $rows */
                private static function anyAdmitted(array $rows, string $key): bool
                {
                    foreach ($rows as $row) {
                        if ($row['admitted'] && ($row[$key] ?? false) === true) {
                            return true;
                        }
                    }

                    return false;
                }

                /** @param list<array<string,mixed>> $rows */
                private static function allAdmitted(array $rows): bool
                {
                    foreach ($rows as $row) {
                        if (!$row['admitted']) {
                            return false;
                        }
                    }

                    return true;
                }

                /** @param list<array<string,mixed>> $rows */
                private static function allBool(array $rows, string $key): bool
                {
                    foreach ($rows as $row) {
                        if (($row[$key] ?? false) !== true) {
                            return false;
                        }
                    }

                    return true;
                }

                /** @param list<array<string,mixed>> ...$groups @return list<string> */
                private static function blockedReasons(array ...$groups): array
                {
                    $reasons = [];
                    foreach ($groups as $rows) {
                        foreach ($rows as $row) {
                            foreach ($row['blocked_reasons'] as $reason) {
                                $reasons[$reason] = true;
                            }
                        }
                    }
                    ksort($reasons);

                    return array_keys($reasons);
                }

                /** @param list<array<string,mixed>> $rows @return list<string> */
                private static function names(array $rows, bool $admitted): array
                {
                    return array_values(array_column(array_filter($rows, static fn (array $row): bool => $row['admitted'] === $admitted), 'name'));
                }
        };

        return $impl::admitCurrentSource($handoffPlan, $journalReceipts, $savepointReceipts, $checkpointReceipts, $readerTokens);
    }

    public static function next261SealPublishedCurrentSource(array $writerPlan, array $publishReceipts): array
    {
        $impl = new class {
                /**
                 * @param array<string,mixed> $writerPlan
                 * @param list<array<string,mixed>> $publishReceipts
                 * @return array<string,mixed>
                 */
                public static function sealPublishedCurrentSource(array $writerPlan, array $publishReceipts): array
                {
                    if (($writerPlan['status'] ?? null) !== 'wal-hot-journal-savepoint-checkpoint-current-source-next258'
                        || ($writerPlan['post_restart_writer_admitted'] ?? null) !== true
                    ) {
                        throw new \InvalidArgumentException('SQLite WAL current-source next261 requires admitted next258 post-restart writer plan');
                    }
                    if ($publishReceipts === []) {
                        throw new \InvalidArgumentException('SQLite WAL current-source next261 requires publish receipts');
                    }

                    $databasePath = self::path($writerPlan['database_path'] ?? null, 'database path');
                    $walPath = self::path($writerPlan['wal_path'] ?? null, 'wal path');
                    $sourceToken = self::token($writerPlan['source_token'] ?? null, 'source token');
                    $generation = self::positiveInt($writerPlan['commit_generation'] ?? null, 'commit generation');
                    $publishGeneration = $generation + 1;
                    $checkpointFrame = self::nonNegativeInt($writerPlan['checkpoint_frame'] ?? null, 'checkpoint frame');
                    $databaseDigest = self::digest($writerPlan['database_digest'] ?? null, 'database digest');
                    $pageCacheDigest = self::digest($writerPlan['page_cache_digest'] ?? null, 'page cache digest');
                    $oldSalt = self::salt($writerPlan['restart_wal_salt'] ?? null, 'restart WAL salt');
                    $acceptedWriters = self::tokenSet($writerPlan['accepted_writer_receipt_names'] ?? null, 'accepted writer receipts');
                    $readmarkSlots = self::positiveIntSet($writerPlan['readmark_slots'] ?? null, 'readmark slots');
                    $readerNames = self::tokenSet($writerPlan['reopened_reader_names'] ?? null, 'reopened reader names');

                    $rows = [];
                    foreach ($publishReceipts as $receipt) {
                        $rows[] = self::publishRow(
                            $receipt,
                            $databasePath,
                            $walPath,
                            $sourceToken,
                            $publishGeneration,
                            $checkpointFrame,
                            $databaseDigest,
                            $pageCacheDigest,
                            $oldSalt,
                            $acceptedWriters,
                            $readmarkSlots,
                            $readerNames
                        );
                    }

                    $acceptedRows = array_values(array_filter($rows, static fn (array $row): bool => $row['accepted']));
                    $blockedRows = array_values(array_filter($rows, static fn (array $row): bool => !$row['accepted']));
                    $duplicateNames = self::duplicates(array_column($rows, 'name'));

                    $types = [];
                    $coveredWriters = [];
                    $coveredSlots = [];
                    $coveredReaders = [];
                    foreach ($acceptedRows as $row) {
                        $types[$row['receipt_type']] = true;
                        foreach ($row['writer_receipt_names'] as $name) {
                            $coveredWriters[$name] = true;
                        }
                        foreach ($row['readmark_slots'] as $slot) {
                            $coveredSlots[$slot] = true;
                        }
                        foreach ($row['reader_names'] as $readerName) {
                            $coveredReaders[$readerName] = true;
                        }
                    }

                    $requiredTypes = ['database-image', 'wal-frame', 'shm-index', 'readmark-fence', 'savepoint-release', 'sync'];
                    $missingTypes = array_values(array_diff($requiredTypes, array_keys($types)));
                    $missingWriters = array_values(array_diff($acceptedWriters, self::sortedStringKeys($coveredWriters)));
                    $missingSlots = array_values(array_diff($readmarkSlots, self::sortedIntKeys($coveredSlots)));
                    $missingReaders = array_values(array_diff($readerNames, self::sortedStringKeys($coveredReaders)));

                    $blockedReasons = [];
                    foreach ($blockedRows as $row) {
                        foreach ($row['blocked_reasons'] as $reason) {
                            $blockedReasons[] = $reason;
                        }
                    }
                    foreach ($duplicateNames as $name) {
                        $blockedReasons[] = 'current_source_publish_receipt_name_duplicate:' . $name;
                    }
                    if ($missingTypes !== []) {
                        $blockedReasons[] = 'current_source_publish_receipt_type_missing';
                    }
                    if ($missingWriters !== []) {
                        $blockedReasons[] = 'current_source_writer_receipt_coverage_missing';
                    }
                    if ($missingSlots !== []) {
                        $blockedReasons[] = 'current_source_readmark_coverage_missing';
                    }
                    if ($missingReaders !== []) {
                        $blockedReasons[] = 'current_source_reader_coverage_missing';
                    }
                    $blockedReasons = array_values(array_unique($blockedReasons));

                    $guardRows = [
                        ['name' => 'next258_writer_admitted', 'matched' => true, 'reason' => 'the first post-restart writer passed next258 reader-fence admission'],
                        ['name' => 'publish_receipt_names_unique', 'matched' => $duplicateNames === [], 'reason' => 'each source publication receipt must be unique'],
                        ['name' => 'all_publish_receipt_types_present', 'matched' => $missingTypes === [], 'reason' => 'database image, WAL frame, SHM, read-mark, savepoint, and sync receipts are required'],
                        ['name' => 'all_writer_receipts_covered', 'matched' => $missingWriters === [], 'reason' => 'all next258 writer receipts must be represented in the published source'],
                        ['name' => 'all_readmarks_fenced', 'matched' => $missingSlots === [], 'reason' => 'all restarted read-mark slots must point at the published generation'],
                        ['name' => 'all_reopened_readers_covered', 'matched' => $missingReaders === [], 'reason' => 'all reopened readers must observe the sealed source digest'],
                        ['name' => 'all_publish_receipts_current', 'matched' => $blockedRows === [], 'reason' => 'publish receipts must match generation, paths, digests, salt transition, locks, and sync state'],
                    ];
                    $blockedGuards = array_values(array_column(array_filter($guardRows, static fn (array $row): bool => !$row['matched']), 'name'));
                    $sealed = $blockedGuards === [];

                    return [
                        'status' => $sealed
                            ? 'wal-hot-journal-savepoint-checkpoint-current-source-next261'
                            : 'wal-hot-journal-savepoint-checkpoint-current-source-blocked-next261',
                        'reason' => $sealed ? 'current_source_sealed_after_post_restart_writer' : 'current_source_publish_waits_for_receipts',
                        'base_status' => $writerPlan['status'],
                        'database_path' => $databasePath,
                        'wal_path' => $walPath,
                        'source_token' => $sourceToken,
                        'commit_generation' => $generation,
                        'publish_generation' => $publishGeneration,
                        'checkpoint_frame' => $checkpointFrame,
                        'database_digest' => $databaseDigest,
                        'page_cache_digest' => $pageCacheDigest,
                        'restart_wal_salt' => $oldSalt,
                        'accepted_writer_receipt_names' => $acceptedWriters,
                        'reopened_reader_names' => $readerNames,
                        'readmark_slots' => $readmarkSlots,
                        'publish_rows' => $rows,
                        'publish_receipt_names' => array_column($rows, 'name'),
                        'accepted_publish_receipt_names' => array_values(array_column($acceptedRows, 'name')),
                        'blocked_publish_receipt_names' => array_values(array_column($blockedRows, 'name')),
                        'duplicate_publish_receipt_names' => $duplicateNames,
                        'publish_receipt_types' => array_values(array_keys($types)),
                        'missing_publish_receipt_types' => $missingTypes,
                        'covered_writer_receipt_names' => self::sortedStringKeys($coveredWriters),
                        'missing_writer_receipt_names' => $missingWriters,
                        'covered_readmark_slots' => self::sortedIntKeys($coveredSlots),
                        'missing_readmark_slots' => $missingSlots,
                        'covered_reader_names' => self::sortedStringKeys($coveredReaders),
                        'missing_reader_names' => $missingReaders,
                        'blocked_publish_reasons' => $blockedReasons,
                        'guard_rows' => $guardRows,
                        'guard_names' => array_column($guardRows, 'name'),
                        'guard_matches' => array_column($guardRows, 'matched'),
                        'blocked_guard_names' => $blockedGuards,
                        'current_source_sealed' => $sealed,
                        'writer_action' => $sealed ? 'publish_post_restart_writer_generation_' . $publishGeneration : 'hold_post_restart_writer_source_unpublished',
                        'wal_action' => $sealed ? 'seal_wal_frame_one_as_current_source' : 'preserve_restarted_wal_pending_publish',
                        'reader_action' => $sealed ? 'advance_reopened_readers_to_source_digest' : 'keep_reopened_readers_on_checkpoint_snapshot',
                        'savepoint_action' => $sealed ? 'release_post_restart_publish_savepoint' : 'keep_post_restart_publish_savepoint_replayable',
                        'sync_action' => $sealed ? 'fsync_database_wal_shm_before_reader_publish' : 'wait_for_database_wal_shm_sync',
                        'publication_digest' => hash('sha256', json_encode([$sourceToken, $publishGeneration, $rows, $guardRows], JSON_THROW_ON_ERROR)),
                        'operation_names' => array_values(array_unique(array_merge(
                            is_array($writerPlan['operation_names'] ?? null) ? $writerPlan['operation_names'] : [],
                            [
                                'verify_current_source_publish_receipts_next261',
                                $sealed ? 'seal_current_source_next261' : 'hold_current_source_next261',
                            ]
                        ))),
                        'dependencies' => array_values(array_unique(array_merge(
                            is_array($writerPlan['dependencies'] ?? null) ? $writerPlan['dependencies'] : [],
                            [
                                'sqlite-wal-hot-journal-savepoint-checkpoint-current-source-next261',
                                'sqlite-wal-current-source-publication-after-post-restart-writer',
                                'wordpress-import-wal-current-source-seal',
                            ]
                        ))),
                        'dependency_closure' => 'no new support component needed; reuses next258 writer admission metadata with native PHP database/WAL/SHM/read-mark/savepoint/sync publication receipts',
                        'non_overlap' => 'next261 seals the current-source publication after next258 writer admission; it does not repeat next258 writer admission, next255 reader restart admission, WAL byte truncation, VFS savepoint rollback, rollback-journal apply/commit, checkpoint transaction planning, JSON, SELECT, B-tree, or encoding surfaces',
                    ];
                }

                /**
                 * @param array<string,mixed> $receipt
                 * @param list<string> $oldSalt
                 * @param list<string> $acceptedWriters
                 * @param list<int> $readmarkSlots
                 * @param list<string> $readerNames
                 * @return array<string,mixed>
                 */
                private static function publishRow(array $receipt, string $databasePath, string $walPath, string $sourceToken, int $publishGeneration, int $checkpointFrame, string $databaseDigest, string $pageCacheDigest, array $oldSalt, array $acceptedWriters, array $readmarkSlots, array $readerNames): array
                {
                    $name = self::token($receipt['name'] ?? null, 'publish receipt name');
                    $type = self::receiptType($receipt['receipt_type'] ?? null);
                    $writers = self::tokenSet($receipt['writer_receipt_names'] ?? null, "{$name} writer receipts");
                    $slots = self::positiveIntSet($receipt['readmark_slots'] ?? null, "{$name} readmark slots");
                    $readers = self::tokenSet($receipt['reader_names'] ?? null, "{$name} reader names");
                    $newSalt = self::salt($receipt['published_wal_salt'] ?? null, "{$name} published WAL salt");
                    $reasons = [];

                    if (self::path($receipt['database_path'] ?? null, "{$name} database path") !== $databasePath) {
                        $reasons[] = 'current_source_publish_database_path_mismatch';
                    }
                    if (self::path($receipt['wal_path'] ?? null, "{$name} wal path") !== $walPath) {
                        $reasons[] = 'current_source_publish_wal_path_mismatch';
                    }
                    if (self::token($receipt['source_token'] ?? null, "{$name} source token") !== $sourceToken) {
                        $reasons[] = 'current_source_publish_source_token_mismatch';
                    }
                    if (self::positiveInt($receipt['publish_generation'] ?? null, "{$name} publish generation") !== $publishGeneration) {
                        $reasons[] = 'current_source_publish_generation_mismatch';
                    }
                    if (self::nonNegativeInt($receipt['checkpoint_frame'] ?? null, "{$name} checkpoint frame") !== $checkpointFrame) {
                        $reasons[] = 'current_source_publish_checkpoint_frame_mismatch';
                    }
                    if (self::digest($receipt['database_digest'] ?? null, "{$name} database digest") !== $databaseDigest) {
                        $reasons[] = 'current_source_publish_database_digest_mismatch';
                    }
                    if (self::digest($receipt['page_cache_digest'] ?? null, "{$name} page cache digest") !== $pageCacheDigest) {
                        $reasons[] = 'current_source_publish_page_cache_digest_mismatch';
                    }
                    if ($newSalt === $oldSalt) {
                        $reasons[] = 'current_source_publish_reused_restart_salt';
                    }
                    foreach ($writers as $writer) {
                        if (!in_array($writer, $acceptedWriters, true)) {
                            $reasons[] = 'current_source_publish_unknown_writer_receipt';
                        }
                    }
                    foreach ($slots as $slot) {
                        if (!in_array($slot, $readmarkSlots, true)) {
                            $reasons[] = 'current_source_publish_unknown_readmark_slot';
                        }
                    }
                    foreach ($readers as $reader) {
                        if (!in_array($reader, $readerNames, true)) {
                            $reasons[] = 'current_source_publish_unknown_reader';
                        }
                    }
                    if (self::positiveInt($receipt['mx_frame'] ?? null, "{$name} mxFrame") < 1) {
                        $reasons[] = 'current_source_publish_mxframe_invalid';
                    }
                    if (self::nonNegativeInt($receipt['savepoint_depth'] ?? null, "{$name} savepoint depth") !== 0) {
                        $reasons[] = 'current_source_publish_savepoint_scope_open';
                    }
                    if (($receipt['exclusive_lock_held'] ?? null) !== true) {
                        $reasons[] = 'current_source_publish_exclusive_lock_missing';
                    }
                    if (($receipt['hot_journal_visible'] ?? null) !== false) {
                        $reasons[] = 'current_source_publish_hot_journal_visible';
                    }
                    if (($receipt['database_synced'] ?? null) !== true) {
                        $reasons[] = 'current_source_publish_database_not_synced';
                    }
                    if (($receipt['wal_synced'] ?? null) !== true) {
                        $reasons[] = 'current_source_publish_wal_not_synced';
                    }
                    if (($receipt['shm_synced'] ?? null) !== true) {
                        $reasons[] = 'current_source_publish_shm_not_synced';
                    }
                    if (($receipt['io_error'] ?? null) !== null) {
                        $reasons[] = 'current_source_publish_io_error';
                    }

                    $reasons = array_values(array_unique($reasons));

                    return [
                        'name' => $name,
                        'receipt_type' => $type,
                        'database_path' => $receipt['database_path'],
                        'wal_path' => $receipt['wal_path'],
                        'source_token' => $receipt['source_token'],
                        'publish_generation' => $receipt['publish_generation'],
                        'checkpoint_frame' => $receipt['checkpoint_frame'],
                        'database_digest' => $receipt['database_digest'],
                        'page_cache_digest' => $receipt['page_cache_digest'],
                        'published_wal_salt' => $newSalt,
                        'writer_receipt_names' => $writers,
                        'readmark_slots' => $slots,
                        'reader_names' => $readers,
                        'mx_frame' => $receipt['mx_frame'],
                        'savepoint_depth' => $receipt['savepoint_depth'],
                        'exclusive_lock_held' => $receipt['exclusive_lock_held'] ?? null,
                        'hot_journal_visible' => $receipt['hot_journal_visible'] ?? null,
                        'database_synced' => $receipt['database_synced'] ?? null,
                        'wal_synced' => $receipt['wal_synced'] ?? null,
                        'shm_synced' => $receipt['shm_synced'] ?? null,
                        'io_error' => $receipt['io_error'] ?? null,
                        'accepted' => $reasons === [],
                        'blocked_reasons' => $reasons,
                        'receipt_reason' => $reasons === [] ? 'current_source_publish_receipt_matches' : 'current_source_publish_receipt_blocks',
                    ];
                }

                private static function receiptType(mixed $value): string
                {
                    if (!is_string($value) || !in_array($value, ['database-image', 'wal-frame', 'shm-index', 'readmark-fence', 'savepoint-release', 'sync'], true)) {
                        throw new \InvalidArgumentException('Invalid publish receipt type');
                    }
                    return $value;
                }

                private static function path(mixed $value, string $label): string
                {
                    if (!is_string($value) || $value === '') {
                        throw new \InvalidArgumentException("Invalid {$label}");
                    }
                    return $value;
                }

                private static function token(mixed $value, string $label): string
                {
                    if (!is_string($value) || !preg_match('/^[A-Za-z0-9_.:-]+$/', $value)) {
                        throw new \InvalidArgumentException("Invalid {$label}");
                    }
                    return $value;
                }

                private static function digest(mixed $value, string $label): string
                {
                    if (!is_string($value) || !preg_match('/^[a-f0-9]{64}$/', $value)) {
                        throw new \InvalidArgumentException("Invalid {$label}");
                    }
                    return $value;
                }

                /**
                 * @return list<string>
                 */
                private static function salt(mixed $value, string $label): array
                {
                    if (!is_array($value) || count($value) !== 2) {
                        throw new \InvalidArgumentException("Invalid {$label}");
                    }
                    $salt = array_values($value);
                    foreach ($salt as $part) {
                        if (!is_string($part) || !preg_match('/^[a-f0-9]{8}$/', $part)) {
                            throw new \InvalidArgumentException("Invalid {$label}");
                        }
                    }
                    return $salt;
                }

                /**
                 * @return list<string>
                 */
                private static function tokenSet(mixed $value, string $label): array
                {
                    if (!is_array($value) || $value === []) {
                        throw new \InvalidArgumentException("Invalid {$label}");
                    }
                    $items = [];
                    foreach ($value as $item) {
                        $items[] = self::token($item, $label);
                    }
                    $items = array_values(array_unique($items));
                    sort($items);
                    return $items;
                }

                /**
                 * @return list<int>
                 */
                private static function positiveIntSet(mixed $value, string $label): array
                {
                    if (!is_array($value) || $value === []) {
                        throw new \InvalidArgumentException("Invalid {$label}");
                    }
                    $items = [];
                    foreach ($value as $item) {
                        $items[] = self::positiveInt($item, $label);
                    }
                    $items = array_values(array_unique($items));
                    sort($items);
                    return $items;
                }

                private static function positiveInt(mixed $value, string $label): int
                {
                    if (!is_int($value) || $value < 1) {
                        throw new \InvalidArgumentException("Invalid {$label}");
                    }
                    return $value;
                }

                private static function nonNegativeInt(mixed $value, string $label): int
                {
                    if (!is_int($value) || $value < 0) {
                        throw new \InvalidArgumentException("Invalid {$label}");
                    }
                    return $value;
                }

                /**
                 * @param list<mixed> $values
                 * @return list<string>
                 */
                private static function duplicates(array $values): array
                {
                    $seen = [];
                    $duplicates = [];
                    foreach ($values as $value) {
                        if (!is_string($value)) {
                            continue;
                        }
                        if (isset($seen[$value])) {
                            $duplicates[$value] = true;
                        }
                        $seen[$value] = true;
                    }
                    $out = array_keys($duplicates);
                    sort($out);
                    return $out;
                }

                /**
                 * @param array<string,bool> $map
                 * @return list<string>
                 */
                private static function sortedStringKeys(array $map): array
                {
                    $keys = array_keys($map);
                    sort($keys);
                    return $keys;
                }

                /**
                 * @param array<int|string,bool> $map
                 * @return list<int>
                 */
                private static function sortedIntKeys(array $map): array
                {
                    $keys = array_map('intval', array_keys($map));
                    sort($keys);
                    return $keys;
                }
        };

        return $impl::sealPublishedCurrentSource($writerPlan, $publishReceipts);
    }

    public static function next262FenceReaderCache(array $currentSourcePlan, array $cacheEntries, array $retryReads): array
    {
        $impl = new class {
                /**
                 * @param array<string,mixed> $currentSourcePlan
                 * @param list<array<string,mixed>> $cacheEntries
                 * @param list<array<string,mixed>> $retryReads
                 * @return array<string,mixed>
                 */
                public static function fenceReaderCache(array $currentSourcePlan, array $cacheEntries, array $retryReads): array
                {
                    if (($currentSourcePlan['status'] ?? null) !== 'wal-hot-journal-savepoint-checkpoint-current-source-next260'
                        || ($currentSourcePlan['current_source_admitted'] ?? null) !== true
                    ) {
                        throw new \InvalidArgumentException('SQLite WAL hot-journal savepoint checkpoint current-source next262 requires an admitted next260 current source');
                    }
                    if ($cacheEntries === [] || $retryReads === []) {
                        throw new \InvalidArgumentException('SQLite WAL hot-journal savepoint checkpoint current-source next262 requires cache entries and retry reads');
                    }

                    $sourceToken = self::token($currentSourcePlan['source_token'] ?? null, 'source token');
                    $databaseDigest = self::digest($currentSourcePlan['database_digest'] ?? null, 'database digest');
                    $pageCacheDigest = self::digest($currentSourcePlan['page_cache_digest'] ?? null, 'page cache digest');
                    $commitGeneration = self::positiveInt($currentSourcePlan, 'commit_generation');
                    $schemaCookie = self::positiveInt($currentSourcePlan, 'schema_cookie');
                    $checkpointFrame = self::positiveInt($currentSourcePlan, 'checkpoint_frame');
                    $dirtyPages = self::intSet($currentSourcePlan['dirty_pages'] ?? null, 'dirty pages');
                    $readerNames = self::tokenSet($currentSourcePlan['accepted_reader_names'] ?? null, 'accepted reader names');

                    $cacheRows = [];
                    foreach ($cacheEntries as $entry) {
                        $cacheRows[] = self::cacheRow($entry, $sourceToken, $databaseDigest, $pageCacheDigest, $commitGeneration, $schemaCookie, $checkpointFrame, $dirtyPages, $readerNames);
                    }
                    $retryRows = [];
                    foreach ($retryReads as $read) {
                        $retryRows[] = self::retryRow($read, $sourceToken, $databaseDigest, $pageCacheDigest, $commitGeneration, $schemaCookie, $checkpointFrame, $dirtyPages, $readerNames);
                    }

                    $usablePages = [];
                    foreach ($cacheRows as $row) {
                        if ($row['usable']) {
                            $usablePages[$row['page_number']] = true;
                        }
                    }
                    ksort($usablePages);

                    $retryPages = self::coveredInts($retryRows, 'page_number');
                    $missingRetryPages = array_values(array_diff($retryPages, array_keys($usablePages)));
                    $blockedReasons = self::blockedReasons($cacheRows, $retryRows);
                    foreach ($missingRetryPages as $page) {
                        $blockedReasons[] = 'retry_page_missing_current_cache_entry_' . $page;
                    }
                    $blockedReasons = array_values(array_unique($blockedReasons));

                    $allRetryRowsAdmitted = self::allBool($retryRows, 'admitted');
                    $allRetryPagesCovered = $missingRetryPages === [];
                    $allCacheRowsUsableOrEvicted = self::allBool($cacheRows, 'safe');
                    $guardRows = [
                        ['name' => 'next260_current_source_admitted', 'matched' => true],
                        ['name' => 'cache_entries_match_current_source_epoch', 'matched' => $allCacheRowsUsableOrEvicted],
                        ['name' => 'retry_reads_match_current_source_epoch', 'matched' => $allRetryRowsAdmitted],
                        ['name' => 'retry_pages_have_current_cache_entries', 'matched' => $allRetryPagesCovered],
                        ['name' => 'stale_hot_journal_cache_entries_evicted', 'matched' => self::allBool($cacheRows, 'stale_evicted')],
                        ['name' => 'all_reader_cache_fences_match', 'matched' => $blockedReasons === []],
                    ];
                    $blockedGuards = array_values(array_column(array_filter($guardRows, static fn (array $row): bool => !$row['matched']), 'name'));
                    $admitted = $blockedGuards === [];

                    return [
                        'status' => $admitted
                            ? 'wal-hot-journal-savepoint-checkpoint-current-source-next262'
                            : 'wal-hot-journal-savepoint-checkpoint-current-source-blocked-next262',
                        'reason' => $admitted
                            ? 'reader_cache_retry_uses_checkpoint_current_source'
                            : 'reader_cache_retry_held_until_checkpoint_current_source_matches',
                        'base_status' => $currentSourcePlan['status'],
                        'database_path' => $currentSourcePlan['database_path'] ?? null,
                        'journal_path' => $currentSourcePlan['journal_path'] ?? null,
                        'wal_path' => $currentSourcePlan['wal_path'] ?? null,
                        'source_token' => $sourceToken,
                        'commit_generation' => $commitGeneration,
                        'schema_cookie' => $schemaCookie,
                        'checkpoint_frame' => $checkpointFrame,
                        'database_digest' => $databaseDigest,
                        'page_cache_digest' => $pageCacheDigest,
                        'dirty_pages' => array_keys($dirtyPages),
                        'accepted_reader_names' => array_keys($readerNames),
                        'cache_rows' => $cacheRows,
                        'retry_rows' => $retryRows,
                        'usable_cache_pages' => array_keys($usablePages),
                        'retry_pages' => $retryPages,
                        'missing_retry_pages' => $missingRetryPages,
                        'usable_cache_names' => self::names($cacheRows, 'usable', true),
                        'evicted_cache_names' => self::names($cacheRows, 'usable', false),
                        'admitted_retry_names' => self::names($retryRows, 'admitted', true),
                        'blocked_retry_names' => self::names($retryRows, 'admitted', false),
                        'blocked_reasons' => $blockedReasons,
                        'guard_names' => array_column($guardRows, 'name'),
                        'guard_matches' => array_column($guardRows, 'matched'),
                        'blocked_guard_names' => $blockedGuards,
                        'reader_cache_admitted' => $admitted,
                        'cache_action' => $admitted ? 'reuse_current_source_page_cache_for_retry_readers' : 'evict_or_reload_reader_page_cache_before_retry',
                        'retry_action' => $admitted ? 'retry_wordpress_import_readers_on_generation_' . $commitGeneration : 'pin_retry_readers_to_reopen_current_source',
                        'journal_action' => $admitted ? 'hot_journal_remains_retired_for_retry_readers' : 'retain_hot_journal_recovery_fence_for_retry_readers',
                        'fence_digest' => hash('sha256', json_encode([$sourceToken, $commitGeneration, $checkpointFrame, $cacheRows, $retryRows, $blockedGuards], JSON_THROW_ON_ERROR)),
                        'operation_names' => array_values(array_unique(array_merge(
                            is_array($currentSourcePlan['operation_names'] ?? null) ? $currentSourcePlan['operation_names'] : [],
                            ['fence_reader_cache_after_hot_journal_checkpoint_current_source_next262']
                        ))),
                        'dependencies' => array_values(array_unique(array_merge(
                            is_array($currentSourcePlan['dependencies'] ?? null) ? $currentSourcePlan['dependencies'] : [],
                            [
                                'sqlite-wal-hot-journal-savepoint-checkpoint-current-source-next262',
                                'sqlite-reader-cache-current-source-fence-after-hot-journal-checkpoint',
                                'wordpress-import-retry-reader-cache-current-source',
                            ]
                        ))),
                        'dependency_closure' => 'no new support component needed; reuses admitted next260 current-source metadata with lane-local reader cache and retry-read epoch receipts',
                        'non_overlap' => 'next262 fences reader cache reuse after next260 source admission; it does not repeat next260 rollback-journal/savepoint/checkpoint admission, next251 WAL sidecar reset, next246 durable VFS handoff, WAL byte truncation, rollback-journal apply/commit, VFS sync/apply, SQL, JSON, encoding, or B-tree behavior',
                    ];
                }

                /** @param array<string,mixed> $entry @param array<int,true> $dirtyPages @param array<string,true> $readerNames @return array<string,mixed> */
                private static function cacheRow(array $entry, string $sourceToken, string $databaseDigest, string $pageCacheDigest, int $commitGeneration, int $schemaCookie, int $checkpointFrame, array $dirtyPages, array $readerNames): array
                {
                    $name = self::token($entry['name'] ?? null, 'cache entry name');
                    $page = self::positiveInt($entry, 'page_number');
                    $reader = self::token($entry['reader_name'] ?? null, "{$name} reader name");
                    $reasons = self::commonReasons($entry, $sourceToken, $databaseDigest, $pageCacheDigest, $commitGeneration, $schemaCookie, $checkpointFrame, $name);
                    if (!isset($dirtyPages[$page])) {
                        $reasons[] = 'cache_page_not_in_checkpoint_dirty_set';
                    }
                    if (!isset($readerNames[$reader])) {
                        $reasons[] = 'cache_reader_not_admitted';
                    }
                    if (($entry['hot_journal_generation_seen'] ?? null) !== null) {
                        $reasons[] = 'cache_still_references_hot_journal_generation';
                    }
                    if (($entry['stale_wal_frame_seen'] ?? null) !== null) {
                        $reasons[] = 'cache_still_references_stale_wal_frame';
                    }
                    if (($entry['evicted'] ?? false) === true && $reasons === []) {
                        $reasons[] = 'cache_entry_evicted_despite_current_source_match';
                    }

                    $usable = $reasons === [] && ($entry['evicted'] ?? false) !== true;
                    $evictedCurrentMatch = $reasons === ['cache_entry_evicted_despite_current_source_match'];
                    $staleEvicted = $usable || (($entry['evicted'] ?? false) === true && $reasons !== []);

                    return self::row($name, $reasons, [
                        'reader_name' => $reader,
                        'page_number' => $page,
                        'evicted' => ($entry['evicted'] ?? false) === true,
                        'usable' => $usable,
                        'safe' => $usable || (($entry['evicted'] ?? false) === true),
                        'blocks_fence' => (!$usable && (($entry['evicted'] ?? false) !== true)) || $evictedCurrentMatch,
                        'stale_evicted' => $staleEvicted,
                    ], 'reader_cache_entry_matches_checkpoint_current_source');
                }

                /** @param array<string,mixed> $read @param array<int,true> $dirtyPages @param array<string,true> $readerNames @return array<string,mixed> */
                private static function retryRow(array $read, string $sourceToken, string $databaseDigest, string $pageCacheDigest, int $commitGeneration, int $schemaCookie, int $checkpointFrame, array $dirtyPages, array $readerNames): array
                {
                    $name = self::token($read['name'] ?? null, 'retry read name');
                    $page = self::positiveInt($read, 'page_number');
                    $reader = self::token($read['reader_name'] ?? null, "{$name} reader name");
                    $reasons = self::commonReasons($read, $sourceToken, $databaseDigest, $pageCacheDigest, $commitGeneration, $schemaCookie, $checkpointFrame, $name);
                    if (!isset($dirtyPages[$page])) {
                        $reasons[] = 'retry_page_not_in_checkpoint_dirty_set';
                    }
                    if (!isset($readerNames[$reader])) {
                        $reasons[] = 'retry_reader_not_admitted';
                    }
                    if (($read['snapshot_reopened'] ?? false) !== true) {
                        $reasons[] = 'retry_snapshot_not_reopened';
                    }
                    if (($read['hot_journal_visible'] ?? false) === true) {
                        $reasons[] = 'retry_hot_journal_visible';
                    }
                    if (($read['stale_wal_visible'] ?? false) === true) {
                        $reasons[] = 'retry_stale_wal_visible';
                    }

                    return self::row($name, $reasons, [
                        'reader_name' => $reader,
                        'page_number' => $page,
                        'blocks_fence' => $reasons !== [],
                        'snapshot_reopened' => ($read['snapshot_reopened'] ?? false) === true,
                        'hot_journal_visible' => ($read['hot_journal_visible'] ?? false) === true,
                        'stale_wal_visible' => ($read['stale_wal_visible'] ?? false) === true,
                    ], 'retry_read_matches_checkpoint_current_source');
                }

                /** @param array<string,mixed> $row @return list<string> */
                private static function commonReasons(array $row, string $sourceToken, string $databaseDigest, string $pageCacheDigest, int $commitGeneration, int $schemaCookie, int $checkpointFrame, string $name): array
                {
                    $reasons = [];
                    if (!hash_equals($sourceToken, self::token($row['source_token'] ?? null, "{$name} source token"))) {
                        $reasons[] = 'source_token_mismatch';
                    }
                    if (!hash_equals($databaseDigest, self::digest($row['database_digest'] ?? null, "{$name} database digest"))) {
                        $reasons[] = 'database_digest_mismatch';
                    }
                    if (!hash_equals($pageCacheDigest, self::digest($row['page_cache_digest'] ?? null, "{$name} page cache digest"))) {
                        $reasons[] = 'page_cache_digest_mismatch';
                    }
                    if (($row['commit_generation'] ?? null) !== $commitGeneration) {
                        $reasons[] = 'commit_generation_mismatch';
                    }
                    if (($row['schema_cookie'] ?? null) !== $schemaCookie) {
                        $reasons[] = 'schema_cookie_mismatch';
                    }
                    if (($row['checkpoint_frame'] ?? null) !== $checkpointFrame) {
                        $reasons[] = 'checkpoint_frame_mismatch';
                    }

                    return $reasons;
                }

                /** @param list<array<string,mixed>> $rows */
                private static function coveredInts(array $rows, string $key): array
                {
                    $values = [];
                    foreach ($rows as $row) {
                        if (($row['admitted'] ?? false) !== true) {
                            continue;
                        }
